window.COURSE = {"title":"零起点现代标准阿拉伯语 · 互动学习台","letters":{"letters":[{"n":1,"iso":"ا","ini":"ا","med":"ـا","fin":"ـا","name":"أَلِف","rom":"ʾalif","zh":"阿利夫","tip":"喉塞音，像「啊」前喉咙突然收紧；不向左连写","nonconn":true,"say":"أَلِف"},{"n":2,"iso":"ب","ini":"بـ","med":"ـبـ","fin":"ـب","name":"بَاء","rom":"bāʾ","zh":"巴","tip":"双唇音，同汉语 b（不送气）","nonconn":false,"say":"بَاء"},{"n":3,"iso":"ت","ini":"تـ","med":"ـتـ","fin":"ـت","name":"تَاء","rom":"tāʾ","zh":"塔","tip":"舌尖齿龈音，同汉语 t（送气弱）","nonconn":false,"say":"تَاء"},{"n":4,"iso":"ث","ini":"ثـ","med":"ـثـ","fin":"ـث","name":"ثَاء","rom":"thāʾ","zh":"萨（咬舌）","tip":"舌尖轻放上下齿之间发 s，像英语 think 的 th","nonconn":false,"say":"ثَاء"},{"n":5,"iso":"ج","ini":"جـ","med":"ـجـ","fin":"ـج","name":"جِيم","rom":"jīm","zh":"吉姆","tip":"同英语 j，像「鸡」但不卷舌","nonconn":false,"say":"جِيم"},{"n":6,"iso":"ح","ini":"حـ","med":"ـحـ","fin":"ـح","name":"حَاء","rom":"ḥāʾ","zh":"哈（喉）","tip":"喉音：从喉咙深处呼气摩擦，比汉语 h 用力","nonconn":false,"say":"حَاء"},{"n":7,"iso":"خ","ini":"خـ","med":"ـخـ","fin":"ـخ","name":"خَاء","rom":"khāʾ","zh":"赫","tip":"像「喝」的摩擦音，小舌部位，同德语 ch","nonconn":false,"say":"خَاء"},{"n":8,"iso":"د","ini":"د","med":"ـد","fin":"ـد","name":"دَال","rom":"dāl","zh":"达勒","tip":"舌尖齿龈音，同汉语 d；不向左连写","nonconn":true,"say":"دَال"},{"n":9,"iso":"ذ","ini":"ذ","med":"ـذ","fin":"ـذ","name":"ذَال","rom":"dhāl","zh":"扎勒（咬舌）","tip":"ث 的浊音，咬舌发 z；不向左连写","nonconn":true,"say":"ذَال"},{"n":10,"iso":"ر","ini":"ر","med":"ـر","fin":"ـر","name":"رَاء","rom":"rāʾ","zh":"拉","tip":"弹舌音，舌尖轻弹上齿龈；不向左连写","nonconn":true,"say":"رَاء"},{"n":11,"iso":"ز","ini":"ز","med":"ـز","fin":"ـز","name":"زَاي","rom":"zāy","zh":"扎伊","tip":"同汉语 z 的浊音；不向左连写","nonconn":true,"say":"زَاي"},{"n":12,"iso":"س","ini":"سـ","med":"ـسـ","fin":"ـس","name":"سِين","rom":"sīn","zh":"辛","tip":"同汉语 s，齿龈擦音","nonconn":false,"say":"سِين"},{"n":13,"iso":"ش","ini":"شـ","med":"ـشـ","fin":"ـش","name":"شِين","rom":"shīn","zh":"希恩","tip":"同汉语 sh，像「诗」","nonconn":false,"say":"شِين"},{"n":14,"iso":"ص","ini":"صـ","med":"ـصـ","fin":"ـص","name":"صَاد","rom":"ṣād","zh":"萨德","tip":"س 的强调音：舌根后缩、口腔后部抬起，声音发闷","nonconn":false,"say":"صَاد"},{"n":15,"iso":"ض","ini":"ضـ","med":"ـضـ","fin":"ـض","name":"ضَاد","rom":"ḍād","zh":"达德","tip":"د 的强调音，阿拉伯语独有的音，舌侧贴住上齿","nonconn":false,"say":"ضَاد"},{"n":16,"iso":"ط","ini":"طـ","med":"ـطـ","fin":"ـط","name":"طَاء","rom":"ṭāʾ","zh":"塔（重）","tip":"ت 的强调音，发音部位靠后，声音厚重","nonconn":false,"say":"طَاء"},{"n":17,"iso":"ظ","ini":"ظـ","med":"ـظـ","fin":"ـظ","name":"ظَاء","rom":"ẓāʾ","zh":"扎（重）","tip":"ذ 的强调音，咬舌 + 舌根后缩","nonconn":false,"say":"ظَاء"},{"n":18,"iso":"ع","ini":"عـ","med":"ـعـ","fin":"ـع","name":"عَيْن","rom":"ʿayn","zh":"阿因","tip":"咽音：喉咙中部收紧发声，中文没有对应音","nonconn":false,"say":"عَيْن"},{"n":19,"iso":"غ","ini":"غـ","med":"ـغـ","fin":"ـغ","name":"غَيْن","rom":"ghayn","zh":"加因","tip":"ع 的浊擦音，像法语 r 或漱口声","nonconn":false,"say":"غَيْن"},{"n":20,"iso":"ف","ini":"فـ","med":"ـفـ","fin":"ـف","name":"فَاء","rom":"fāʾ","zh":"法","tip":"唇齿音，同汉语 f","nonconn":false,"say":"فَاء"},{"n":21,"iso":"ق","ini":"قـ","med":"ـقـ","fin":"ـق","name":"قَاف","rom":"qāf","zh":"高夫","tip":"小舌音，比 k 靠后，从喉咙深处爆破","nonconn":false,"say":"قَاف"},{"n":22,"iso":"ك","ini":"كـ","med":"ـكـ","fin":"ـك","name":"كَاف","rom":"kāf","zh":"卡夫","tip":"同汉语 g/k 之间，舌根音","nonconn":false,"say":"كَاف"},{"n":23,"iso":"ل","ini":"لـ","med":"ـلـ","fin":"ـل","name":"لَام","rom":"lām","zh":"拉姆","tip":"同汉语 l","nonconn":false,"say":"لَام"},{"n":24,"iso":"م","ini":"مـ","med":"ـمـ","fin":"ـم","name":"مِيم","rom":"mīm","zh":"米姆","tip":"双唇鼻音，同汉语 m","nonconn":false,"say":"مِيم"},{"n":25,"iso":"ن","ini":"نـ","med":"ـنـ","fin":"ـن","name":"نُون","rom":"nūn","zh":"努恩","tip":"舌尖鼻音，同汉语 n","nonconn":false,"say":"نُون"},{"n":26,"iso":"ه","ini":"هـ","med":"ـهـ","fin":"ـه","name":"هَاء","rom":"hāʾ","zh":"哈","tip":"同汉语 h，比 ح 轻，声带不摩擦","nonconn":false,"say":"هَاء"},{"n":27,"iso":"و","ini":"و","med":"ـو","fin":"ـو","name":"وَاو","rom":"wāw","zh":"瓦乌","tip":"半元音 w；也作长元音 ū；不向左连写","nonconn":true,"say":"وَاو"},{"n":28,"iso":"ي","ini":"يـ","med":"ـيـ","fin":"ـي","name":"يَاء","rom":"yāʾ","zh":"亚","tip":"半元音 y；也作长元音 ī","nonconn":false,"say":"يَاء"}],"harakat":[{"ch":"َ","name":"فَتْحَة","rom":"fatha","zh":"开口符","say":"a","tip":"短 a，像「啊」但短促"},{"ch":"ِ","name":"كَسْرَة","rom":"kasra","zh":"齐齿符","say":"i","tip":"短 i，像「衣」但短促"},{"ch":"ُ","name":"ضَمَّة","rom":"damma","zh":"合口符","say":"u","tip":"短 u，像「乌」但短促"},{"ch":"ْ","name":"سُكُون","rom":"sukun","zh":"静符","say":"","tip":"该字母不带元音，直接接下一个音"},{"ch":"ّ","name":"شَدَّة","rom":"shadda","zh":"叠音符","say":"","tip":"同一字母读两遍，前一个停顿、后一个带元音"},{"ch":"ً","name":"تَنْوِين","rom":"-an","zh":"开口鼻音符","say":"an","tip":"词尾 -an，只用于泛指名词"},{"ch":"ٍ","name":"تَنْوِين","rom":"-in","zh":"齐齿鼻音符","say":"in","tip":"词尾 -in，只用于泛指名词"},{"ch":"ٌ","name":"تَنْوِين","rom":"-un","zh":"合口鼻音符","say":"un","tip":"词尾 -un，只用于泛指名词"}],"longvowels":[{"ch":"َا","rom":"ā","zh":"长开口音","tip":"ا 前面有 fatha 时读长 ā，拖两拍","say":"آ"},{"ch":"ُو","rom":"ū","zh":"长合口音","tip":"و 前面有 damma 时读长 ū","say":"و"},{"ch":"ِي","rom":"ī","zh":"长齐齿音","tip":"ي 前面有 kasra 时读长 ī","say":"ي"}],"tanwin":[{"ch":"ـًا","rom":"-an","zh":"宾格鼻音","tip":"泛指名词作宾语或谓语补足语时用","say":"an"},{"ch":"ـٍ","rom":"-in","zh":"属格鼻音","tip":"泛指名词在介词后时用","say":"in"},{"ch":"ـٌ","rom":"-un","zh":"主格鼻音","tip":"泛指名词作起语补语/谓语时用","say":"un"}]},"source":"自编 · 参照《零起点标准韩语入门》学习台结构","lang":"ar","rtl":true,"chapters":[{"title":"第一章 语音与字母","sections":[{"title":"第一节 阿拉伯语与 28 个字母","concepts":[{"title":"1. 这一节学完你能做什么","body":"学完这一节，你能用一句话说清阿拉伯语是一门什么样的语言，认得 28 个字母的名称、顺序和转写，知道它为什么从右往左写、为什么同一个字母会有四种样子，还能开口说出二十来句最常用的问候语。字母的具体写法这一节先不用背，混个脸熟就行。"},{"title":"2. 三亿人的母语，也是联合国的工作语言","body":"阿拉伯语（الْعَرَبِيَّةُ，al-ʿarabiyyatu，阿拉伯语）的母语使用者大约三亿，分布在从摩洛哥到伊拉克的二十多个国家，它也是联合国六种工作语言之一。\n阿拉伯语有一个别的语言不太常见的情况：**书面语只有一种，口语却各地不同**。报纸、新闻、正式讲话用的是统一的「现代标准阿拉伯语」（MSA，الْفُصْحَى，al-fuṣḥā，标准语）；而埃及人、叙利亚人、海湾人日常聊天各说各的方言，彼此不一定听得懂。**本课程教的是 MSA**：它通行于所有阿拉伯国家，学了它，书报能读、正式场合能说，走到哪儿都不算错。方言不在本课程范围内。"},{"title":"3. 从右往左写，字母「手拉手」","body":"阿拉伯语**从右往左**书写、阅读。打开一本书，第一页在右边，第一个字也在最右边。\n阿拉伯字母是连写的：同一个词里的字母像英文草书一样彼此相连。但**有 6 个字母只连右边、不连左边**——ا د ذ ر ز و。遇到它们，后面的字母就得另起一块，所以一个词看起来可能是一整串，也可能断成几截。\n除这 6 个以外，每个字母都有 **4 种形态**：独立（单独写时）、词首（在词开头）、词中（在词中间）、词末（在词末尾）。形态不同，骨架是同一个。以 ب 为例：独立形就是字母表里那个样子；词首形出现在 بَيْتٌ（baytun，房子）的开头；词中形出现在 خُبْزٌ（khubzun，面包）的中间；词末形出现在 كِتَابٌ（kitābun，书）的末尾。学字母时不要一个形状一个形状地死记，要记住「它怎么跟左右两边打交道」。"},{"title":"4. 只写「辅音骨架」，元音靠符号","body":"阿拉伯语是「辅音 + 元音符号」的文字。日常书写时，人们**只写辅音和长元音**，短元音和叠音一概省略，读者靠上下文和语法去补。同一副骨架 كتب  可以读成 kataba（他写了）、kutub（书，复数）、kutiba（被写了），意思全靠上下文定。\n零基础阶段这样学是不行的，所以**本课程所有阿拉伯语都标满符号**（这套符号叫 تَشْكِيلٌ，tashkīlun，标音符号）：短元音 a、i、u，鼻音 -n，叠音，一个不漏。等你读顺了，再去看不带符号的原文，会发现那些「没有元音」的词其实一眼就能认出来。"},{"title":"5. 28 个字母的顺序","body":"28 个字母按阿拉伯语课本和词典通用的顺序排列如下（下一节的词汇表就是它们的名称和转写）：\nأ ب ت ث ج ح خ د ذ ر ز س ش ص ض ط ظ ع غ ف ق ك ل م ن ه و ي\n按这个顺序数：第一个是 أ，第十个是 ذ，第二十个是 ف，第二十八个是 ي。背顺序的用处很实际——阿拉伯语词典就是按这个顺序排的，顺序熟了查词才快。"},{"title":"6. 先整块背：问候语是「固定说法」","body":"阿拉伯语的问候语几乎都是**固定的整块**，不能按字面拆开重造。比如 مَرْحَبًا（marḥaban，你好）字面上是「欢迎」，但你只要会说这一句就够了，不必去分析它的语法。\n学这些句子的正确方法是：**整句背下来，连同使用场合**。什么时候说、对谁说、对方怎么回，比语法分析重要得多。下面例句表里的二十来句，就是你的第一批「口语存货」，先会背，再慢慢理解。"}],"vocab":[{"ar":"أَلِفٌ","rom":"alifun","zh":"字母 أ，名称「阿利夫」","a":"896eae8d4f03"},{"ar":"بَاءٌ","rom":"bāʾun","zh":"字母 ب，名称「巴」","a":"443b69e75fed"},{"ar":"تَاءٌ","rom":"tāʾun","zh":"字母 ت，名称「塔」","a":"746f7c990f99"},{"ar":"ثَاءٌ","rom":"thāʾun","zh":"字母 ث，名称「萨」（咬舌）","a":"6e96ef2ab0f4"},{"ar":"جِيمٌ","rom":"jīmun","zh":"字母 ج，名称「吉姆」","a":"8caed3d918c7"},{"ar":"حَاءٌ","rom":"ḥāʾun","zh":"字母 ح，名称「哈」（喉壁）","a":"b0d0730a6520"},{"ar":"خَاءٌ","rom":"khāʾun","zh":"字母 خ，名称「哈」（软腭）","a":"7dfeee9c183e"},{"ar":"دَالٌ","rom":"dālun","zh":"字母 د，名称「达勒」","a":"17356c8eaab2"},{"ar":"ذَالٌ","rom":"dhālun","zh":"字母 ذ，名称「扎勒」","a":"74017650f3d8"},{"ar":"رَاءٌ","rom":"rāʾun","zh":"字母 ر，名称「拉」","a":"d43d7fe087e9"},{"ar":"زَايٌ","rom":"zāyun","zh":"字母 ز，名称「扎伊」","a":"75351479fc5f"},{"ar":"سِينٌ","rom":"sīnun","zh":"字母 س，名称「辛」","a":"77227da68cbb"},{"ar":"شِينٌ","rom":"shīnun","zh":"字母 ش，名称「希恩」","a":"0417e896cc59"},{"ar":"صَادٌ","rom":"ṣādun","zh":"字母 ص，名称「萨德」","a":"d3367304fcbe"},{"ar":"ضَادٌ","rom":"ḍādun","zh":"字母 ض，名称「达德」","a":"6e457b41c021"},{"ar":"طَاءٌ","rom":"ṭāʾun","zh":"字母 ط，名称「塔」（重）","a":"be1c5b402549"},{"ar":"ظَاءٌ","rom":"ẓāʾun","zh":"字母 ظ，名称「扎」（重）","a":"0dabbf001a8e"},{"ar":"عَيْنٌ","rom":"ʿaynun","zh":"字母 ع，名称「阿因」","a":"b07db83c3950"},{"ar":"غَيْنٌ","rom":"ghaynun","zh":"字母 غ，名称「盖因」","a":"0a735aca9247"},{"ar":"فَاءٌ","rom":"fāʾun","zh":"字母 ف，名称「法」","a":"71a547d92f34"},{"ar":"قَافٌ","rom":"qāfun","zh":"字母 ق，名称「嘎夫」","a":"130e790cf0a1"},{"ar":"كَافٌ","rom":"kāfun","zh":"字母 ك，名称「卡夫」","a":"aec25080fa64"},{"ar":"لَامٌ","rom":"lāmun","zh":"字母 ل，名称「拉姆」","a":"72474f93d5bd"},{"ar":"مِيمٌ","rom":"mīmun","zh":"字母 م，名称「米姆」","a":"328cd006e8b8"},{"ar":"نُونٌ","rom":"nūnun","zh":"字母 ن，名称「努恩」","a":"3d305c4e5f96"},{"ar":"هَاءٌ","rom":"hāʾun","zh":"字母 ه，名称「哈」（轻）","a":"0e4bc4fda48d"},{"ar":"وَاوٌ","rom":"wāwun","zh":"字母 و，名称「瓦乌」","a":"f9750865feb7"},{"ar":"يَاءٌ","rom":"yāʾun","zh":"字母 ي，名称「亚」","a":"751f3fd6e110"}],"examples":[{"ar":"مَرْحَبًا.","rom":"marḥaban","zh":"你好！","note":"固定问候语，字面是「欢迎」，整块记","a":"3ee282b224b8"},{"ar":"أَهْلًا وَسَهْلًا.","rom":"ahlan wa-sahlan","zh":"欢迎！","note":"两个宾格名词的固定搭配，不拆开用","a":"81eac1393a12"},{"ar":"أَهْلًا بِكَ.","rom":"ahlan bika","zh":"欢迎你！","note":"بِ 加代词后缀 كَ 表示「你」","a":"8150d470e229"},{"ar":"السَّلَامُ عَلَيْكُمْ.","rom":"as-salāmu ʿalaykum","zh":"你们好！","note":"名词句，省略谓语；عَلَى 加代词后缀 كُمْ","a":"438187d99b0e"},{"ar":"وَعَلَيْكُمُ السَّلَامُ.","rom":"wa-ʿalaykumu as-salāmu","zh":"也祝你们平安！","note":"对上一句的固定回答，语序倒过来","a":"a1405b6cf06d"},{"ar":"صَبَاحُ الْخَيْرِ.","rom":"ṣabāḥu al-khayri","zh":"早上好！","note":"正偏组合，字面是「好事的早晨」","a":"581b6c0f6511"},{"ar":"صَبَاحُ النُّورِ.","rom":"ṣabāḥu an-nūri","zh":"早上好！这是回答别人的说法。","note":"固定回答，把 خَيْرٌ 换成 نُورٌ","a":"cf4a6217c40a"},{"ar":"مَسَاءُ الْخَيْرِ.","rom":"masāʾu al-khayri","zh":"晚上好！","note":"同上，把 صَبَاحٌ 换成 مَسَاءٌ","a":"48128387d342"},{"ar":"مَسَاءُ النُّورِ.","rom":"masāʾu an-nūri","zh":"晚上好！这是回答别人的说法。","note":"固定回答，与 صَبَاحُ النُّورِ 同构","a":"e519ffe7f1ed"},{"ar":"مَعَ السَّلَامَةِ.","rom":"maʿa as-salāmati","zh":"再见！","note":"介词短语，字面是「带着平安」","a":"24e61092bdd2"},{"ar":"إِلَى اللِّقَاءِ.","rom":"ilā al-liqāʾi","zh":"再见！","note":"介词短语，字面是「到相见时」","a":"c3a87f332cc1"},{"ar":"إِلَى الْغَدِ.","rom":"ilā al-ghadi","zh":"明天见！","note":"同上，الْغَدُ 是「明天」","a":"3b8e3f81c27b"},{"ar":"شُكْرًا.","rom":"shukran","zh":"谢谢！","note":"宾格绝对宾语，固定用法，不加主语","a":"ad9c41b545c1"},{"ar":"عَفْوًا.","rom":"ʿafwan","zh":"不客气！也可表示「对不起」。","note":"同一个词两用，看场合判断","a":"f16d3560d8e4"},{"ar":"نَعَمْ.","rom":"naʿam","zh":"是。","note":"应答词，表示肯定","a":"6b1f25b26010"},{"ar":"لَا.","rom":"lā","zh":"不。","note":"否定词，也可以单独成句","a":"5de5d19f19ec"},{"ar":"مِنْ فَضْلِكَ.","rom":"min faḍlika","zh":"请。劳驾。","note":"介词短语，字面是「出于你的恩惠」","a":"f536c40f548c"},{"ar":"كَيْفَ حَالُكَ؟","rom":"kayfa ḥāluka","zh":"你好吗？","note":"كَيْفَ 疑问词 + 正偏组合 حَالُكَ","a":"0605021321aa"},{"ar":"أَنَا بِخَيْرٍ.","rom":"anā bi-khayrin","zh":"我很好。","note":"名词句，谓语是介词短语 بِخَيْرٍ","a":"60bdd380153d"},{"ar":"مَا اسْمُكَ؟","rom":"mā ismuka","zh":"你叫什么名字？","note":"مَا 疑问代词 + اسْمٌ 加代词后缀","a":"73ae15973f10"},{"ar":"اِسْمِي مُحَمَّدٌ.","rom":"ismī muḥammadun","zh":"我叫穆罕默德。","note":"名词句，اِسْمِي 是起语，مُحَمَّدٌ 是谓语","a":"a53eaacb40f6"},{"ar":"تَشَرَّفْنَا.","rom":"tasharrafnā","zh":"幸会。","note":"过去式加 ـنَا「我们」，固定客套话","a":"99bb8a6e7996"},{"ar":"لَيْلَةً سَعِيدَةً.","rom":"laylatan saʿīdatan","zh":"晚安。","note":"两个宾格形容词，固定祝愿语","a":"8ee2474fd4df"}],"drills":[{"q":"阿拉伯语书写和阅读的方向是？","a":"从右往左"},{"q":"哪 6 个字母不向左连写？","a":"ا د ذ ر ز و"},{"q":"一个普通字母有几种形态？分别叫什么？","a":"4 种：独立、词首、词中、词末"},{"q":"第 5 个字母的名称和转写是什么？","a":"جِيمٌ（jīmun）"},{"q":"第 20 个字母的名称和转写是什么？","a":"فَاءٌ（fāʾun）"},{"q":"第 28 个字母的名称和转写是什么？","a":"يَاءٌ（yāʾun）"},{"q":"「你好」怎么说？","a":"مَرْحَبًا"},{"q":"「谢谢」怎么说？","a":"شُكْرًا"},{"q":"「早上好」怎么说？","a":"صَبَاحُ الْخَيْرِ"},{"q":"「再见」怎么说？","a":"مَعَ السَّلَامَةِ"},{"q":"「请」怎么说？","a":"مِنْ فَضْلِكَ"},{"q":"阿拉伯语日常书写时，短元音符号一般写不写？","a":"不写，只写辅音和长元音"}],"tips":["从右往左写，写完检查第一个字母是不是落在最右边，别把词序写反。","ا د ذ ر ز و 这 6 个字母只连右边，遇到它们一个词会「断开」，这是正常现象，不是写错。","冠词 الْ 单独念 al-，遇到太阳字母（ت ث د ذ ر ز س ش ص ض ط ظ ل ن）时，ل 同化成后面那个字母并读成叠音，如 الشَّمْس 念 ash-shams。","这二十来句问候语都是固定说法，整句背、连同场合一起背，别按字面拆开重造。","阿拉伯语日常书写不标短元音，本课程全程标出，是为了让你先读得出来；以后看原文时，靠词形和上下文补元音。","不要把阿拉伯语的 ب 读成汉语拼音的 p，它是不送气的 b；也不要拿方言说法代替例句里的 MSA。"],"id":"ch1-s1"},{"title":"第二节 字母（一）：ا ب ت ث ن ي","concepts":[{"title":"1. 这一节学完你能做什么","body":"学完这一节，你能读出、写出 ا ب ت ث ن ي 这 6 个字母，会给任何一个辅音配上 a、i、u 三个短元音，还能用「这 + 名词」造出第一批阿拉伯语句子。这一节真正的重点是那四个小符号，字母本身反倒简单。"},{"title":"2. 六个字母，六个发音位置","body":"- **ا（أَلِفٌ，ʾalifun，阿利夫）**：喉塞音。发音时声门先闭一下再打开，像汉语「啊」前面那个轻轻的顿。它自己不携带短元音，多数时候是长元音 ā 的「座位」。\n- **ب（بَاءٌ，bāʾun，巴）**：双唇闭合再放开，和汉语「爸」的 b 一样，**不送气**，别读成汉语拼音的 p。\n- **ت（تَاءٌ，tāʾun，塔）**：舌尖抵住上齿背再放开，发不送气的 t，比汉语「他」的 t 少一股气，部位也更靠前，是贴着牙齿发的。\n- **ث（ثَاءٌ，thāʾun，萨）**：**咬舌音**。舌尖轻轻放在上下门牙之间，让气流从舌尖和牙齿的缝里擦出来，像英语 think 的 th。\n- **ن（نُونٌ，nūnun，努恩）**：鼻音，和汉语的 n 基本一样，舌尖抵上齿背，气流从鼻子出。\n- **ي（يَاءٌ，yāʾun，亚）**：硬腭半元音，和汉语「衣」的起头一样；在词尾常常拉长成 ī。\n这六个字母里，ا 是不向左连写的，其余五个都正常连写。"},{"title":"3. 四个符号，决定一个字母怎么读","body":"阿拉伯语的辅音本身不带元音，要靠在它上下的「小符号」来定音。零基础阶段先认这四个，它们是全书的地基：\n- **فَتْحَةٌ（fatḥatun，开口符）**：一小斜杠写在字母**上方**，读 a。بَ 就是 ba。\n- **كَسْرَةٌ（kasratun，齐齿符）**：一小斜杠写在字母**下方**，读 i。بِ 就是 bi。\n- **ضَمَّةٌ（ḍammatun，合口符）**：一个像小 و 的符号写在字母**上方**，读 u。بُ 就是 bu。\n- **سُكُونٌ（sukūnun，静符）**：一个小圆圈写在字母**上方**，表示这个辅音**不带元音**，直接跟前面的音连读。بْ 就是 b。\n记位置的口诀：**上方两个、下方一个、圆圈也在上**。فَتْحَةٌ 和 ضَمَّةٌ 在上方，كَسْرَةٌ 在下方——这是最容易写错的地方，写反了意思就变了。\n还有一条硬规则：**每个辅音后面最多跟一个短元音**，要么 a、要么 i、要么 u、要么没有（سُكُونٌ）。不会出现 بَِ 这种叠两个元音符号的写法。\n读的时候，把一个词的符号从右往左依次读出来就行。以 بَابٌ（bābun，门）为例：ب 带 فَتْحَةٌ 读 ba，接着的 ا 把 a 拉长成 ā，最后一个 ب 带鼻音符 -un 读 bun，连起来就是 bā-bun。三个音，三块符号，一一对应，没有例外。"},{"title":"4. 短元音加 ا و ي，就成了长元音","body":"短元音后面跟上 ا、و、ي，音就拉长，变成 ā、ī、ū：\n- بَ + ا → بَا，读 bā，如 بَابٌ（bābun，门）\n- تِ + ي → تِي，读 tī，如 تِينٌ（tīnun，无花果）\n- نُ + و → نُو，读 nū，如 نُورٌ（nūrun，光）\n要注意的是：**长元音的字母本身不标元音符号**。写 بَا 的时候，ا 上什么都不写，它的任务只是把前面的 a 拉长。初学者常犯的错是给 ا 也加一个 فَتْحَةٌ，那就变成两个音了。"},{"title":"5. 鼻音符和叠音符，先认样子","body":"- **تَنْوِينٌ（tanwīnun，鼻音符）**：把 فَتْحَةٌ、كَسْرَةٌ、ضَمَّةٌ 写成双份，分别表示 -an、-in、-un。比如 بَيْتٌ（baytun，房子）末尾的 ـٌ 就是 -un。名词作谓语、表示「泛指」时经常带它。\n- **شَدَّةٌ（shaddatun，叠音符）**：像一个小写的 w 写在字母上方，表示这个辅音**读两遍**：前一遍不带元音，后一遍带元音。比如 أُمٌّ（ummun，母亲）的 م 上有 شَدَّةٌ，读 um-m。\n这两个符号这一节只要认得出来、知道它表示什么就行，后面每一节都会反复出现，见多了自然会用。"},{"title":"6. 「这 + 名词」就是一句话","body":"阿拉伯语最简单的句子没有「是」：هَذَا（hādhā，这，指阳性）加一个带鼻音符的名词，就成句了——هَذَا بَابٌ（hādhā bābun，这是一扇门）。\n指阴性名词要换成 هَذِهِ（hādhihi，这，指阴性），比如 هَذِهِ يَدٌ（hādhihi yadun，这是一只手）。为什么 يَدٌ 是阴性？这类「成对的身体部位」在阿拉伯语里大多算阴性。判断阴阳性的完整规则在第二章讲，这一节先记两条：带 ة 的词是阴性，يَدٌ 这类成对部位也是阴性。"}],"vocab":[{"ar":"أَبٌ","rom":"abun","zh":"父亲","a":"2c07cb543d73"},{"ar":"أُمٌّ","rom":"ummun","zh":"母亲","a":"33ccd5682798"},{"ar":"أَخٌ","rom":"akhun","zh":"哥哥、弟弟","a":"ea297f87a8a5"},{"ar":"أُخْتٌ","rom":"ukhtun","zh":"姐姐、妹妹","a":"2adfcda1c372"},{"ar":"اِبْنٌ","rom":"ibnun","zh":"儿子","a":"5fd11d42f6ef"},{"ar":"بِنْتٌ","rom":"bintun","zh":"女儿","a":"db9e49cfe2a2"},{"ar":"بَابٌ","rom":"bābun","zh":"门","a":"b7831c1d1303"},{"ar":"بَيْتٌ","rom":"baytun","zh":"房子","a":"f681630e99e8"},{"ar":"بَحْرٌ","rom":"baḥrun","zh":"大海","a":"e600489f311d"},{"ar":"بَقَرَةٌ","rom":"baqaratun","zh":"牛","a":"273ee6517ef6"},{"ar":"بَطَّةٌ","rom":"baṭṭatun","zh":"鸭子","a":"971d93456a35"},{"ar":"تَمْرٌ","rom":"tamrun","zh":"椰枣","a":"e3cc90fa8e19"},{"ar":"تُفَّاحٌ","rom":"tuffāḥun","zh":"苹果","a":"00e77058bd2b"},{"ar":"تَاجٌ","rom":"tājun","zh":"王冠","a":"66febf897638"},{"ar":"تِينٌ","rom":"tīnun","zh":"无花果","a":"cb7852b01964"},{"ar":"تِلْمِيذٌ","rom":"tilmīdhun","zh":"学生（中小学）","a":"3fabc23347d2"},{"ar":"تَارِيخٌ","rom":"tārīkhun","zh":"历史","a":"31ed12e7a788"},{"ar":"ثَوْبٌ","rom":"thawbun","zh":"衣服","a":"a0a6866249a3"},{"ar":"ثَلْجٌ","rom":"thaljun","zh":"雪","a":"761e505e2deb"},{"ar":"ثَمَرٌ","rom":"thamarun","zh":"水果","a":"4f425794f046"},{"ar":"ثَلَاثَةٌ","rom":"thalāthatun","zh":"三","a":"8811b3146c16"},{"ar":"نَارٌ","rom":"nārun","zh":"火","a":"9316a364dd74"},{"ar":"نَهْرٌ","rom":"nahrun","zh":"河","a":"e00592d0e0f2"},{"ar":"نُورٌ","rom":"nūrun","zh":"光","a":"6f670ffb7f68"},{"ar":"نَافِذَةٌ","rom":"nāfidhatun","zh":"窗户","a":"a09b57379a2d"},{"ar":"نَوْمٌ","rom":"nawmun","zh":"睡眠","a":"03c1a13da95a"},{"ar":"يَدٌ","rom":"yadun","zh":"手","a":"d5c37467bea0"},{"ar":"يَوْمٌ","rom":"yawmun","zh":"日子、天","a":"031c241145e1"},{"ar":"يَمِينٌ","rom":"yamīnun","zh":"右边","a":"61459aae2d90"},{"ar":"يَاسَمِينٌ","rom":"yāsamīnun","zh":"茉莉花","a":"5269205c7219"}],"examples":[{"ar":"هَذَا بَابٌ.","rom":"hādhā bābun","zh":"这是一扇门。","note":"هَذَا 起语 + 泛指谓语","a":"6090ab44b350"},{"ar":"هَذَا بَيْتٌ.","rom":"hādhā baytun","zh":"这是一栋房子。","note":"同上，بَيْتٌ 带鼻音符 -un","a":"11d79ed5b496"},{"ar":"هَذِهِ يَدٌ.","rom":"hādhihi yadun","zh":"这是一只手。","note":"يَدٌ 是阴性，用 هَذِهِ","a":"91179c5dfea3"},{"ar":"هَذَا تَمْرٌ.","rom":"hādhā tamrun","zh":"这是椰枣。","note":"تَمْرٌ 是集合名词，不分单复数","a":"f74087db3d38"},{"ar":"هَذَا ثَوْبٌ.","rom":"hādhā thawbun","zh":"这是一件衣服。","note":"ث 是咬舌音，别读成 s","a":"7206cc5dda03"},{"ar":"هَذِهِ نَارٌ.","rom":"hādhihi nārun","zh":"这是火。","note":"نَارٌ 是阴性，用 هَذِهِ","a":"5af6a8411bac"},{"ar":"هَذَا نَهْرٌ.","rom":"hādhā nahrun","zh":"这是一条河。","note":"نَهْرٌ 是阳性","a":"a56f4bdc848d"},{"ar":"هَذِهِ بِنْتٌ.","rom":"hādhihi bintun","zh":"这是个女孩。","note":"بِنْتٌ 是阴性","a":"978f3e2df335"},{"ar":"هَذَا ابْنٌ.","rom":"hādhā ibnun","zh":"这是儿子。","note":"اِبْنٌ 的 ا 是连接哈姆扎，单独念时读 i","a":"953c7f8b59d3"},{"ar":"أَنَا أَبٌ.","rom":"anā abun","zh":"我是父亲。","note":"代词作起语，谓语带鼻音符","a":"b9c6811395d1"},{"ar":"أَنْتَ أَخٌ.","rom":"anta akhun","zh":"你是兄弟。","note":"أَنْتَ 指男性","a":"fc9aa99df7c9"},{"ar":"هُوَ تَاجِرٌ.","rom":"huwa tājirun","zh":"他是商人。","note":"هُوَ 指男性","a":"3ad425b7d4cd"},{"ar":"هِيَ أُمٌّ.","rom":"hiya ummun","zh":"她是母亲。","note":"هِيَ 指女性，أُمٌّ 的 م 带 شَدَّةٌ","a":"23a8afef12b4"},{"ar":"الْبَيْتُ كَبِيرٌ.","rom":"al-baytu kabīrun","zh":"这房子很大。","note":"确指起语 + 泛指谓语","a":"2d4085b6dfa6"},{"ar":"الْبَابُ مَفْتُوحٌ.","rom":"al-bābu maftūḥun","zh":"门开着。","note":"同上，谓语是形容词","a":"c1303668c61f"},{"ar":"الْيَدُ صَغِيرَةٌ.","rom":"al-yadu ṣaghīratun","zh":"手很小。","note":"阴性起语配阴性谓语 ة","a":"81ba98c3ef57"},{"ar":"الْبِنْتُ صَغِيرَةٌ.","rom":"al-bintu ṣaghīratun","zh":"这女孩很小。","note":"同上，主语换成 بِنْتٌ","a":"f0aa2592511e"},{"ar":"النَّارُ حَارَّةٌ.","rom":"an-nāru ḥārratun","zh":"火是热的。","note":"太阳字母 ن，冠词同化成 an-","a":"9d1a3c9c7387"},{"ar":"النُّورُ جَمِيلٌ.","rom":"an-nūru jamīlun","zh":"光很美。","note":"同上，نُورٌ 是阳性","a":"31b06264da2a"},{"ar":"التُّفَّاحُ حُلْوٌ.","rom":"at-tuffāḥu ḥulwun","zh":"苹果很甜。","note":"太阳字母 ت，冠词同化成 at-","a":"7c8f85c8a40c"},{"ar":"الثَّلْجُ بَارِدٌ.","rom":"ath-thalju bāridun","zh":"雪是冷的。","note":"太阳字母 ث，冠词同化成 ath-","a":"58a943b2574f"},{"ar":"يَدِي كَبِيرَةٌ.","rom":"yadī kabīratun","zh":"我的手很大。","note":"يَدٌ 加 ـِي 表示「我的」","a":"ad19751b4c69"},{"ar":"الْبَحْرُ وَاسِعٌ.","rom":"al-baḥru wāsiʿun","zh":"大海很辽阔。","note":"ح 是喉壁音，别读成汉语 h","a":"6129ed1195b0"},{"ar":"هَذَا يَوْمٌ جَمِيلٌ.","rom":"hādhā yawmun jamīlun","zh":"这是美好的一天。","note":"名词 + 形容词，两处都带 -un","a":"eba6ccd80f98"}],"drills":[{"q":"字母 ب 的名称和转写是什么？","a":"بَاءٌ（bāʾun）"},{"q":"字母 ث 的名称和转写是什么？","a":"ثَاءٌ（thāʾun）"},{"q":"ب 加 فَتْحَةٌ 怎么读？","a":"بَ（ba）"},{"q":"ب 加 كَسْرَةٌ 怎么写？","a":"بِ"},{"q":"ب 加 ضَمَّةٌ 怎么读？","a":"بُ（bu）"},{"q":"سُكُونٌ 表示什么？","a":"这个辅音不带元音，直接跟前面的音连读"},{"q":"「门」用阿拉伯语怎么说？","a":"بَابٌ"},{"q":"「房子」用阿拉伯语怎么说？","a":"بَيْتٌ"},{"q":"「手」用阿拉伯语怎么说？","a":"يَدٌ"},{"q":"「雪」用阿拉伯语怎么说？","a":"ثَلْجٌ"},{"q":"「这是房子」怎么说？","a":"هَذَا بَيْتٌ"},{"q":"「这是一只手」怎么说？","a":"هَذِهِ يَدٌ"}],"tips":["فَتْحَةٌ 和 ضَمَّةٌ 写在字母上方，كَسْرَةٌ 写在下方，写错位置是最常见的错误。","ث 一定要咬舌，舌尖放在上下门牙之间，读成 s 就变成另一个字母了。","ب 和 ت 都不送气，别读成汉语拼音的 p 和 t（这两个是送气的）。","一个辅音只能带一个短元音，بَِ 这种写法不存在。","长元音是「短元音 + ا 或 و 或 ي」，那个字母一定要写出来：bā 写成 بَا，不是 بَ。","名词作谓语要带鼻音符 -un，写成 بَابٌ，漏了 ـٌ 句子在语法上就不完整。"],"id":"ch1-s2"},{"title":"第三节 字母（二）：ج ح خ د ذ ر ز","concepts":[{"title":"1. 这一节学完你能做什么","body":"学完这一节，你能读出 ج ح خ د ذ ر ز 这 7 个字母，弄懂「不向左连写」这条贯穿全书的规则，还能分清三对中国学习者最容易混的音：ج 和 ح 和 خ、ث 和 ذ、س 和 ز。这一节的难点不在字母形状，在发音部位。"},{"title":"2. 不向左连写的六个字母","body":"28 个字母里，只有 6 个**只连右边、不连左边**：ا د ذ ر ز و。这一节学其中的 د ذ ر ز，ا 上一节学过，و 后面学。\n实际写出来是什么效果？看 دَرْسٌ（darsun，课）：د 不往左连，后面的 ر 只好另起一块；ر 也不往左连，س 又另起一块。整个词看上去断成三截。\n再对比 بَيْتٌ（baytun，房子）：ب、ي、ت 都能左右连，所以写出来是一整串，中间没有断口。\n所以这 6 个字母只有 **2 种形态**，不是 4 种：词首形和词中形长得一样（都只连右边），词末形和独立形长得一样（都不往左连）。别的字母要记 4 个形状，它们只要记 2 个，算是省事。\n**判断方法**：写完一个词，如果发现中间有「断口」，先别怀疑写错了，回头看看是不是碰上了这 6 个字母。"},{"title":"3. ج ح خ：一副骨架，三个点","body":"这三个字母骨架完全相同，全靠「点」区分：\n- **ج（جِيمٌ，jīmun，吉姆）**：点在**肚子里**，读 j。舌面抬向硬腭，是浊音，比汉语的 j 更靠后、更「厚」一些。\n- **ح（حَاءٌ，ḥāʾun，哈）**：**没有点**，读 ḥ。这是汉语里没有的音：气流从喉咙深处（咽壁）擦出来，像用力呵气，但声带不振动，比汉语的 h 更靠里、更紧。\n- **خ（خَاءٌ，khāʾun，哈）**：点在**头上**，读 kh。小舌或软腭摩擦，像汉语「喝」的 h 但更用力，接近德语 Bach 里的 ch。\n口诀：**点在下、点在上的、没点的**——依次是 ج、خ、ح。这三个字母在阿拉伯语里出现频率极高，认错一个点，词就变了。"},{"title":"4. ذ 是 ث 的浊音，ز 是 س 的浊音","body":"汉语的辅音基本只有「送气」和「不送气」的对立，没有「清音」和「浊音」的对立，所以这两对要专门练。判断标准只有一个：**摸喉结，振动的是浊音**。\n- **ث 和 ذ**：都是**齿间音**，舌尖放在上下门牙之间。ث 是清音，声带不振动，像英语 think 的 th；ذ 是浊音，声带振动，像英语 this 的 th。\n- **س 和 ز**：都是齿龈咝音。س 是清音 s；ز 是浊音 z，像英语 zoo 开头的那个音。\n一句话记住：**同一发音部位，清浊成对**。ث 和 ذ 一对，س 和 ز 一对，学的时候成对记，别单独记一个。"},{"title":"5. ر：弹舌音","body":"ر（رَاءٌ，rāʾun，拉）是**舌尖颤音**：舌尖轻抵上齿龈，让气流把它弹一下（或者连弹几下）。西班牙语、意大利语的 r 就是这个音。\n中国人最容易犯的错，是用汉语的 r（如「日」）去代替它——那是卷舌近音，舌头卷起来但不弹。**汉语的 r 不弹舌，阿拉伯语的 r 要弹**。\n练法：先快速连说「d-d-d」，让舌尖放松地拍上齿龈，再加上声带振动，就能找到弹的感觉。弹一下也算对，不必像西班牙语那样连弹很多下。"},{"title":"6. هَذَا 还是 هَذِهِ：先认阴性","body":"前面学的 هَذَا 只能指阳性名词，指阴性名词要换成 هَذِهِ（hādhihi，这，指阴性）。哪些词是阴性？最明显的标志是词尾的 ة：زَهْرَةٌ（zahratun，花）就是阴性。\n但也有一批词不带 ة 却是阴性，比如 دَارٌ（dārun，房子）。这类词没有外形标志，只能一个一个记，好在数量不算多。\n所以：هَذَا دَرْسٌ（hādhā darsun，这是一节课），但 هَذِهِ دَارٌ（hādhihi dārun，这是一栋房子）。看到 ة 就用 هَذِهِ，基本不会错；剩下的靠积累。"}],"vocab":[{"ar":"جَمَلٌ","rom":"jamalun","zh":"骆驼","a":"8e17efc8e25c"},{"ar":"جَبَلٌ","rom":"jabalun","zh":"山","a":"92e814215c7a"},{"ar":"جَمِيلٌ","rom":"jamīlun","zh":"美丽的","a":"edc5aa96b508"},{"ar":"جَدِيدٌ","rom":"jadīdun","zh":"新的","a":"bc60168bb745"},{"ar":"جَامِعَةٌ","rom":"jāmiʿatun","zh":"大学","a":"4e7c3f025186"},{"ar":"جَوَابٌ","rom":"jawābun","zh":"回答","a":"499366d4785d"},{"ar":"حَجَرٌ","rom":"ḥajarun","zh":"石头","a":"326113d809b1"},{"ar":"حَلِيبٌ","rom":"ḥalībun","zh":"牛奶","a":"f9a794056d46"},{"ar":"حَارٌّ","rom":"ḥārrun","zh":"热的","a":"cc2178c63d75"},{"ar":"حَقِيبَةٌ","rom":"ḥaqībatun","zh":"手提包","a":"b003ecf6acba"},{"ar":"حَيَاةٌ","rom":"ḥayātun","zh":"生活","a":"16c378532c33"},{"ar":"خُبْزٌ","rom":"khubzun","zh":"面包","a":"96ab68e09cee"},{"ar":"خَيْرٌ","rom":"khayrun","zh":"好、善","a":"426addbfd3f0"},{"ar":"خَبَرٌ","rom":"khabarun","zh":"消息","a":"f8ee8713c055"},{"ar":"خَرِيطَةٌ","rom":"kharīṭatun","zh":"地图","a":"5ad1a81cc44a"},{"ar":"دَارٌ","rom":"dārun","zh":"房子、家","a":"d88ed34b2e4a"},{"ar":"دَرْسٌ","rom":"darsun","zh":"课","a":"d13ac4ee73ac"},{"ar":"دَجَاجٌ","rom":"dajājun","zh":"鸡","a":"98f3d9e24e13"},{"ar":"دُكَّانٌ","rom":"dukkānun","zh":"商店","a":"632f1576a647"},{"ar":"ذَهَبٌ","rom":"dhahabun","zh":"金子","a":"162a2b860e52"},{"ar":"ذُبَابٌ","rom":"dhubābun","zh":"苍蝇","a":"175530c6c3eb"},{"ar":"ذِرَاعٌ","rom":"dhirāʿun","zh":"手臂","a":"cb3554ed9fc4"},{"ar":"رَجُلٌ","rom":"rajulun","zh":"男人","a":"44767a34bc25"},{"ar":"رَأْسٌ","rom":"raʾsun","zh":"头","a":"6f76fc7c4728"},{"ar":"رَخِيصٌ","rom":"rakhīṣun","zh":"便宜的","a":"085510d514f2"},{"ar":"زَيْتٌ","rom":"zaytun","zh":"油","a":"915e4d9e6d51"},{"ar":"زَهْرَةٌ","rom":"zahratun","zh":"花","a":"46c178387533"},{"ar":"زَمَنٌ","rom":"zamanun","zh":"时间","a":"4b7d61dcfd9a"},{"ar":"زُجَاجٌ","rom":"zujājun","zh":"玻璃","a":"eec2e7c83e6f"},{"ar":"زَيْتُونٌ","rom":"zaytūnun","zh":"橄榄","a":"1c61b47cb00e"}],"examples":[{"ar":"هَذَا جَمَلٌ.","rom":"hādhā jamalun","zh":"这是骆驼。","note":"هَذَا 起语 + 泛指谓语","a":"0e0c699febd2"},{"ar":"هَذَا جَبَلٌ.","rom":"hādhā jabalun","zh":"这是山。","note":"ج 读浊音 j，点在肚子里","a":"d2a3e8a63f68"},{"ar":"الْجَبَلُ كَبِيرٌ.","rom":"al-jabalu kabīrun","zh":"山很大。","note":"确指起语 + 泛指谓语","a":"d15b96a77f31"},{"ar":"هَذَا حَجَرٌ.","rom":"hādhā ḥajarun","zh":"这是石头。","note":"ح 是喉壁音，别读成汉语 h","a":"a0948abaf444"},{"ar":"الْحَجَرُ صَغِيرٌ.","rom":"al-ḥajaru ṣaghīrun","zh":"石头很小。","note":"ح 是月亮字母，冠词读 al-","a":"5e28a22fb9c5"},{"ar":"هَذَا حَلِيبٌ.","rom":"hādhā ḥalībun","zh":"这是牛奶。","note":"名词带鼻音符 -un","a":"2fc200c93a55"},{"ar":"الْحَلِيبُ بَارِدٌ.","rom":"al-ḥalību bāridun","zh":"牛奶是凉的。","note":"起语确指、谓语泛指","a":"e9f641dc9f5e"},{"ar":"هَذَا خُبْزٌ.","rom":"hādhā khubzun","zh":"这是面包。","note":"خ 是软腭音，气流从口腔后部出","a":"7a04c0a08ac4"},{"ar":"الْخُبْزُ لَذِيذٌ.","rom":"al-khubzu ladhīdhun","zh":"面包很好吃。","note":"خ 是月亮字母，冠词读 al-","a":"4e11f95e15e8"},{"ar":"هَذَا دَرْسٌ جَدِيدٌ.","rom":"hādhā darsun jadīdun","zh":"这是新课。","note":"د 不往左连，دَرْسٌ 断开成几块","a":"bba82af3cf15"},{"ar":"الدَّرْسُ سَهْلٌ.","rom":"ad-darsu sahlun","zh":"这课很容易。","note":"太阳字母 د，冠词同化成 ad-","a":"b0fedd6953e9"},{"ar":"هَذِهِ دَارٌ.","rom":"hādhihi dārun","zh":"这是一栋房子。","note":"دَارٌ 不带 ة，但是阴性","a":"f7b5f7924c70"},{"ar":"الدَّارُ جَمِيلَةٌ.","rom":"ad-dāru jamīlatun","zh":"这房子很漂亮。","note":"阴性起语配阴性谓语","a":"f979a603737e"},{"ar":"هَذَا ذَهَبٌ.","rom":"hādhā dhahabun","zh":"这是金子。","note":"ذ 是浊音，读的时候摸喉结","a":"d7d72557dd19"},{"ar":"هَذَا خَاتَمٌ مِنْ ذَهَبٍ.","rom":"hādhā khātamun min dhahabin","zh":"这是一枚金戒指。","note":"مِنْ 后面的名词用属格 -in","a":"0f68b2293835"},{"ar":"هَذَا رَجُلٌ.","rom":"hādhā rajulun","zh":"这是个男人。","note":"ر 要弹舌","a":"072e1bc833ee"},{"ar":"الرَّجُلُ طَوِيلٌ.","rom":"ar-rajulu ṭawīlun","zh":"这个男人很高。","note":"太阳字母 ر，冠词同化成 ar-","a":"b6fcbc4f220b"},{"ar":"هَذَا رَأْسٌ.","rom":"hādhā raʾsun","zh":"这是头。","note":"رَأْسٌ 中间是 ء，起首的 ر 带 فَتْحَةٌ","a":"bfd8e5d0585d"},{"ar":"هَذَا زَيْتٌ.","rom":"hādhā zaytun","zh":"这是油。","note":"ز 是浊音 z，不是汉语的 z","a":"7195997905fb"},{"ar":"الزَّيْتُ جَدِيدٌ.","rom":"az-zaytu jadīdun","zh":"这油是新的。","note":"太阳字母 ز，冠词同化成 az-","a":"7c7705c92a68"},{"ar":"هَذِهِ زَهْرَةٌ جَمِيلَةٌ.","rom":"hādhihi zahratun jamīlatun","zh":"这是一朵美丽的花。","note":"ة 结尾是阴性，形容词也跟着带 ة","a":"4337ada468d9"},{"ar":"هَذَا جَوَابٌ صَحِيحٌ.","rom":"hādhā jawābun ṣaḥīḥun","zh":"这是正确答案。","note":"名词 + 形容词，两处都带 -un","a":"e8e1f486ca1a"},{"ar":"الْجَامِعَةُ قَرِيبَةٌ.","rom":"al-jāmiʿatu qarībatun","zh":"大学很近。","note":"ج 是月亮字母，冠词读 al-","a":"49dfcaf3a78d"},{"ar":"الدَّجَاجُ لَذِيذٌ.","rom":"ad-dajāju ladhīdhun","zh":"鸡肉很好吃。","note":"太阳字母 د，冠词同化成 ad-","a":"eda32ff32dcd"},{"ar":"هَذَا زَمَنٌ جَمِيلٌ.","rom":"hādhā zamanun jamīlun","zh":"这是美好的时光。","note":"同上，名词加形容词","a":"761c3888ba53"}],"drills":[{"q":"不向左连写的 6 个字母是哪 6 个？","a":"ا د ذ ر ز و"},{"q":"د 和 ذ 在连写上有什么共同点？","a":"都只连右边，不向左连写"},{"q":"这 6 个字母有几种形态？","a":"2 种：词首形与词中形一样，词末形与独立形一样"},{"q":"ج 和 خ 靠什么区分？","a":"点的位置：ج 的点在肚子里，خ 的点在头上，ح 没有点"},{"q":"ث 和 ذ 是什么关系？","a":"同一部位清浊成对，ث 清音、ذ 浊音"},{"q":"س 和 ز 是什么关系？","a":"同一部位清浊成对，س 清音、ز 浊音"},{"q":"「石头」用阿拉伯语怎么说？","a":"حَجَرٌ"},{"q":"「面包」用阿拉伯语怎么说？","a":"خُبْزٌ"},{"q":"「课」用阿拉伯语怎么说？","a":"دَرْسٌ"},{"q":"「男人」用阿拉伯语怎么说？","a":"رَجُلٌ"},{"q":"「油」用阿拉伯语怎么说？","a":"زَيْتٌ"},{"q":"「这是新课」怎么说？","a":"هَذَا دَرْسٌ جَدِيدٌ"}],"tips":["د ذ ر ز 只连右边，一个词写出来「断成几截」是正常的，别硬把它们连上。","ج 的点在肚子里，خ 的点在头上，ح 没点；三个骨架一模一样，只靠点认，看错一个点词就变了。","ح 不是汉语的 h，发的时候喉咙要收紧，气流从咽壁擦出来，别从口腔送气。","ذ 和 ز 都是浊音，读的时候摸喉结要有振动；汉语母语者容易顺手读成清音 ث 和 س。","ر 要弹舌，别用汉语「日」的 r 代替；弹一下也算对，不必连弹很多下。","ة 结尾的名词一般是阴性，用 هَذِهِ 指代；像 دَارٌ 这样不带 ة 的阴性词要单独记。"],"id":"ch1-s3"},{"title":"第四节 字母（三）：س ش ص ض ط ظ","concepts":[{"title":"1. 学完这一节你能做什么","body":"这一节学完，你就能读带 س ش ص ض ط ظ 的词，并且第一次分清阿拉伯语里最让外国人头疼的一组对立：普通音和强调音。ط 和 ظ 分别是 ت、ذ 的强调版，ص 是 س 的强调版，这三组都是「同部位、不同口腔状态」的关系。所以这一节真正的新概念只有一个——**强调音**。抓住它，六个字母其实只有三个发音部位。"},{"title":"2. س 和 ش：一对省力的音","body":"س（s）就是汉语「思」的声母 s：舌尖靠近上齿背，气流从窄缝里摩擦出来，声带不振动。它不送气，别读成英语 see 那样带一股气冲出来。\nش（sh）像汉语「诗」的 sh，但有两处要调：舌位比汉语略靠前（汉语 sh 是卷舌音，阿拉伯语的 ش 不卷舌），嘴唇要稍稍收圆、往前突一点。听起来介于「诗」和「希」之间，就对了。阿拉伯语里 ش 出现频率很高，شَمْسٌ（shamsun，太阳）、شَجَرَةٌ（shajaratun，树）都以它开头。"},{"title":"3. ص 和 ض：口腔后部抬起来","body":"ص（ṣ）不是新音，它是 س 的**强调版**。发音部位和 س 完全一样，区别只在一点：发 s 的同时，把舌根往后压、往软腭方向抬起来，咽腔跟着收紧。这样出来的 s 会变「闷」、变「暗」，像隔着一层东西。找感觉的办法是先发一个拖长的「哦」，记住喉咙往后缩的状态，再在这个状态下发 s。\nض（ḍ）是阿拉伯语的**标志音**，全世界只有阿拉伯语把它当作独立的音位，所以阿拉伯人常自称「ض 的语言」：لُغَةُ الضَّادِ（lughatu ḍ-ḍādi，ض 的语言）。它的发音部位与 د 相同（舌尖抵上齿龈），同时舌根后缩、咽腔收紧。古典语音学把它描写成「舌侧音」，现代标准阿拉伯语实际读起来更接近一个被压暗的 d。初学者最常见的错是把它读成普通的 d 或 z，那样 ضَوْءٌ（ḍawʾun，光）就和别的词混在一起了。"},{"title":"4. ط 和 ظ：清浊成对的强调音","body":"ط（ṭ）是 ت 的强调版：清音、不送气，舌尖抵住上齿龈，同时舌根后缩。它读起来像汉语「打」的 d 突然放开那一下，不是「他」那样喷气。阿拉伯语的 ط 一律不送气，这一点和汉语的 t 正好相反。\nظ（ẓ）是 ذ 的强调版：浊音，舌尖轻轻碰一下上齿边缘（像英语 this 的 th），同时舌根后缩。它是本章最「重」的音之一，听起来像把 th 闷在嘴里发出来。ظِلٌّ（ẓillun，影子）、ظَهْرٌ（ẓahrun，背）都是常用词。"},{"title":"5. 强调音（الْحُرُوفُ الْمُفَخَّمَةُ）与三组对比词","body":"阿拉伯语把辅音分成「细」和「粗」两套。粗音就是强调音，阿拉伯语叫 الْحُرُوفُ الْمُفَخَّمَةُ（al-ḥurūfu l-mufakhkhamatu，被加粗的字母）；语音学上又叫「升音字母」，因为发这些音时舌根是抬起来的。本节的 ص ض ط ظ 四个全是强调音，第五节的 ق خ غ 属于同一家族，一共七个。\n强调音的关键不只是辅音本身变闷，它还会**把后面的 a 拉低**：صَبَاحٌ（ṣabāḥun，早晨）里的 a 听起来更接近「ɑ」而不是「æ」，طَالِبٌ（ṭālibun，学生）也一样。所以判断自己有没有发对，听元音够不够「暗」，往往比听辅音更准。\n三组对比词请成对练：先读细音，再读粗音，专门体会舌根那一下动作。\n- س / ص：سَارَ（sāra，走）对 صَارَ（ṣāra，变成）；سَيْفٌ（sayfun，剑）对 صَيْفٌ（ṣayfun，夏天）\n- ت / ط：تَابَ（tāba，悔过）对 طَابَ（ṭāba，变好、可口）；تِينٌ（tīnun，无花果）对 طِينٌ（ṭīnun，泥）\n- ذ / ظ：ذَلَّ（dhalla，变得卑微）对 ظَلَّ（ẓalla，停留、一直）"},{"title":"6. 三个最容易犯的错","body":"第一，把 ص 读成普通的 s。汉语没有强调音，舌头会自动偷懒，一定要刻意把舌根往后收，宁可夸张一点。\n第二，给 ط 送气。汉语的 t 是送气音，阿拉伯语的 ط 不送气。练的时候在嘴前放一张纸，读 ط 时纸不该被吹动。\n第三，把 ض 读成 z。ض 是舌尖抵齿龈的音，不是平舌摩擦音，嘴形和 د 一样，只是「暗」了一档。"}],"vocab":[{"ar":"سَمَاءٌ","rom":"samāʾun","zh":"天空","a":"7f723751abd3"},{"ar":"سُوقٌ","rom":"sūqun","zh":"市场","a":"aa5a6fe6a100"},{"ar":"سَاعَةٌ","rom":"sāʿatun","zh":"钟；小时","a":"ac9b3059e0fc"},{"ar":"سَيْفٌ","rom":"sayfun","zh":"剑","a":"28c0ebc6482c"},{"ar":"سَارَ","rom":"sāra","zh":"走（过去式）","a":"7b8c7a223eaf"},{"ar":"شَمْسٌ","rom":"shamsun","zh":"太阳","a":"90fac5bf0987"},{"ar":"شَجَرَةٌ","rom":"shajaratun","zh":"树","a":"935958a504ce"},{"ar":"شَاطِئٌ","rom":"shāṭiʾun","zh":"海岸；海滩","a":"4d753b258300"},{"ar":"شَابٌّ","rom":"shābbun","zh":"年轻人（男）","a":"95bf7fd79f7d"},{"ar":"شُكْرًا","rom":"shukran","zh":"谢谢","a":"85934d9777f8"},{"ar":"صَبَاحٌ","rom":"ṣabāḥun","zh":"早晨","a":"8e5c395e6860"},{"ar":"صَدِيقٌ","rom":"ṣadīqun","zh":"朋友（男）","a":"204b61c6d156"},{"ar":"صَيْفٌ","rom":"ṣayfun","zh":"夏天","a":"7b077fe4335b"},{"ar":"صَغِيرٌ","rom":"ṣaghīrun","zh":"小的","a":"2353820d7b0e"},{"ar":"صَحِيحٌ","rom":"ṣaḥīḥun","zh":"正确的","a":"2716c485047e"},{"ar":"صَارَ","rom":"ṣāra","zh":"变成（过去式）","a":"7b27e3141577"},{"ar":"صُورَةٌ","rom":"ṣūratun","zh":"照片；图画","a":"7625a86f5b09"},{"ar":"ضَوْءٌ","rom":"ḍawʾun","zh":"光","a":"538601d779b2"},{"ar":"ضَحِكَ","rom":"ḍaḥika","zh":"笑（过去式）","a":"433f96a84105"},{"ar":"ضَابِطٌ","rom":"ḍābiṭun","zh":"军官","a":"9b42c9c753eb"},{"ar":"أَرْضٌ","rom":"arḍun","zh":"土地","a":"16825e86d45a"},{"ar":"طَالِبٌ","rom":"ṭālibun","zh":"学生（男）","a":"bea7c61ac7f5"},{"ar":"طَعَامٌ","rom":"ṭaʿāmun","zh":"食物","a":"c0c6dea5f5c8"},{"ar":"طَرِيقٌ","rom":"ṭarīqun","zh":"路","a":"ba6f825ddd71"},{"ar":"طَاوِلَةٌ","rom":"ṭāwilatun","zh":"桌子","a":"6676a860f540"},{"ar":"طِينٌ","rom":"ṭīnun","zh":"泥","a":"7d33df0d399b"},{"ar":"ظِلٌّ","rom":"ẓillun","zh":"影子；阴凉","a":"4fb0beae01a2"},{"ar":"ظَهْرٌ","rom":"ẓahrun","zh":"背；背面","a":"0d7593cc4e0e"},{"ar":"ظَلَّ","rom":"ẓalla","zh":"停留；一直（过去式）","a":"154f5aaa17f9"},{"ar":"تِينٌ","rom":"tīnun","zh":"无花果","a":"cb7852b01964"},{"ar":"ذَلَّ","rom":"dhalla","zh":"变得卑微（过去式）","a":"40a0b5836e99"},{"ar":"مَشْهُورٌ","rom":"mashhūrun","zh":"有名的","a":"2500a5064324"}],"examples":[{"ar":"الشَّمْسُ قَوِيَّةٌ.","rom":"ash-shamsu qawiyyatun","zh":"太阳很烈。","note":"名词句；ش 是太阳字母，الْ 同化","a":"1634de378eb9"},{"ar":"السَّمَاءُ صَافِيَةٌ.","rom":"as-samāʾu ṣāfiyatun","zh":"天空晴朗。","note":"س 是太阳字母，الْ 读 as-","a":"c007dfb573f3"},{"ar":"هَذَا صَدِيقِي.","rom":"hādhā ṣadīqī","zh":"这是我的朋友。","note":"代词后缀 ـي 表示「我的」","a":"7d782d5e1731"},{"ar":"أَنَا طَالِبٌ.","rom":"anā ṭālibun","zh":"我是学生。","note":"人称代词作起语，谓语带 -un","a":"089a5f92b79f"},{"ar":"هُوَ ضَابِطٌ.","rom":"huwa ḍābiṭun","zh":"他是军官。","note":"ض 是强调音，后面的 a 变暗","a":"c757bb23f00f"},{"ar":"هَذَا طَعَامٌ لَذِيذٌ.","rom":"hādhā ṭaʿāmun ladhīdhun","zh":"这食物很好吃。","note":"名词 + 形容词，形容词后置","a":"db0ea070c214"},{"ar":"الطَّالِبُ فِي الْمَدْرَسَةِ.","rom":"aṭ-ṭālibu fī l-madrasati","zh":"学生在学校里。","note":"介词短语作谓语；ط 同化","a":"08c55abea8f6"},{"ar":"الشَّجَرَةُ فِي الْحَدِيقَةِ.","rom":"ash-shajaratu fī l-ḥadīqati","zh":"树在花园里。","note":"同上；الْ 后接 ش 要同化","a":"3b710fe0a45d"},{"ar":"صَبَاحُ الْخَيْرِ.","rom":"ṣabāḥu l-khayri","zh":"早上好。","note":"正偏组合，偏次用属格","a":"581b6c0f6511"},{"ar":"ضَوْءُ الشَّمْسِ قَوِيٌّ.","rom":"ḍawʾu sh-shamsi qawiyyun","zh":"阳光很强。","note":"正偏组合作起语","a":"e9d704f35eef"},{"ar":"ظِلُّ الشَّجَرَةِ بَارِدٌ.","rom":"ẓillu sh-shajarati bāridun","zh":"树荫很凉。","note":"正偏组合 + 形容词谓语","a":"c12e8a7301a5"},{"ar":"صُورَةُ الشَّمْسِ جَمِيلَةٌ.","rom":"ṣūratu sh-shamsi jamīlatun","zh":"太阳的照片很美。","note":"正偏组合作起语，谓语配合阴性","a":"359e4c23dfce"},{"ar":"ذَهَبَ إِلَى السُّوقِ.","rom":"dhahaba ilā s-sūqi","zh":"他去了市场。","note":"动词句；إِلَى 后接属格","a":"8a106fdea282"},{"ar":"ضَحِكَ الطَّالِبُ.","rom":"ḍaḥika ṭ-ṭālibu","zh":"学生笑了。","note":"动词 + 主语，主语用主格","a":"5ee8b128f198"},{"ar":"ظَلَّ فِي الْبَيْتِ.","rom":"ẓalla fī l-bayti","zh":"他留在了家里。","note":"ظَلَّ 表「一直、仍然」","a":"13c1a721d89e"},{"ar":"صَارَ الطَّالِبُ مُعَلِّمًا.","rom":"ṣāra ṭ-ṭālibu muʿalliman","zh":"学生成了老师。","note":"صَارَ 后面的谓语用宾格 -an","a":"a53381ca0647"},{"ar":"سَارَ عَلَى الطَّرِيقِ.","rom":"sāra ʿalā ṭ-ṭarīqi","zh":"他走在路上。","note":"عَلَى 后接属格","a":"1e12be8d506e"},{"ar":"الصَّيْفُ حَارٌّ.","rom":"aṣ-ṣayfu ḥārrun","zh":"夏天很热。","note":"ص 同化；حَارٌّ 带叠音","a":"d063323a17ae"},{"ar":"هَذِهِ سَاعَةٌ صَغِيرَةٌ.","rom":"hādhihi sāʿatun ṣaghīratun","zh":"这是一只小钟。","note":"هَذِهِ 用于阴性名词","a":"dd1e41369a4d"},{"ar":"كَلَامُكَ صَحِيحٌ.","rom":"kalāmuka ṣaḥīḥun","zh":"你说的话是对的。","note":"代词后缀 ـكَ 表「你的」","a":"1cac2b5b0c4a"},{"ar":"أَرْضُ الْعَرَبِ وَاسِعَةٌ.","rom":"arḍu l-ʿarabi wāsiʿatun","zh":"阿拉伯的土地辽阔。","note":"正偏组合作起语","a":"66a818278988"},{"ar":"شُكْرًا يَا صَدِيقِي.","rom":"shukran yā ṣadīqī","zh":"谢谢，我的朋友。","note":"يَا 是呼语虚词","a":"03dae602528e"}],"drills":[{"q":"「太阳」用阿拉伯语怎么说？","a":"شَمْسٌ"},{"q":"「影子」用阿拉伯语怎么说？","a":"ظِلٌّ"},{"q":"ص 是哪个字母的强调音？","a":"س"},{"q":"ظ 是哪个字母的强调音？","a":"ذ"},{"q":"ط 送气吗？","a":"不送气"},{"q":"给「天空」加上冠词 الْ","a":"السَّمَاءُ"},{"q":"سَيْفٌ 和 صَيْفٌ 分别是什么意思？","a":"剑 / 夏天"},{"q":"「这 + 学生」连成名词句","a":"هَذَا طَالِبٌ"},{"q":"「他是军官」怎么说？","a":"هُوَ ضَابِطٌ"},{"q":"「早上好」怎么说？","a":"صَبَاحُ الْخَيْرِ"},{"q":"「树荫很凉」怎么说？","a":"ظِلُّ الشَّجَرَةِ بَارِدٌ"}],"tips":["ص 和 س 的舌位完全一样，区别只在舌根；先发「哦」，记住喉咙后缩的感觉再发 s。","ض 不要读成 z，它是舌尖抵齿龈的 d，只是被压暗了一档。","强调音会把后面的 a 拉成「ɑ」，元音够暗，辅音基本就对了。","汉语的 t 送气，ط 不送气；把手放在嘴前，纸不动才对。","记词要成对记：سَيْفٌ（剑）对 صَيْفٌ（夏天）、تَابَ（悔过）对 طَابَ（可口），比单记牢得多。"],"id":"ch1-s4"},{"title":"第五节 字母（四）：ع غ ف ق ك ل م ه و","concepts":[{"title":"1. 学完这一节你能做什么","body":"这一节学完，28 个字母就全部过完了。你会遇到阿拉伯语里最难的一个音 ع，也会遇到和汉语几乎一样的 ف ك ل م ه。这一节的重点不是数量，而是把「喉咙一带」的几个音分开：ع 和 غ 是一对，ق 和 ك 是一对，ه 单独一个。混了这几对，词义就会变。"},{"title":"2. ع：阿拉伯语的「喉咙音」","body":"ع（ʿ）是阿拉伯语最有特色的音，语音学上叫咽擦音。发音方法分三步：先发汉语的「啊」，注意这时候喉咙是松的；保持口型不变，把舌根往喉咙深处压，咽部肌肉收紧；让声音从收紧的地方挤出来。你会听到一个带「挤压感」的浊音，这就是 ع。可以想象被人轻轻掐住脖子时发出的那声「啊」，或者打嗝前喉咙突然一紧的那一下。\n练的时候这样找位置：连续发「a-a-a」，然后在两个 a 之间把喉咙收一下，那个收紧的地方就是 ع 的发音部位。先把这个「收紧」练熟，再加上声音，比一上来就硬憋容易。\n**发不出来怎么办**：完全正常，汉语里没有这个音，不用急。实在找不到时，用一个「喉部收紧的 a」代替——把元音 a 发得又紧又闷、位置靠后，听起来接近 ع，母语者能听懂，也就够用了。千万不要用 ء（hamza，喉塞音）或 غ 顶替：ء 是喉咙「一顿」，غ 是「摩擦的咕噜」，两者都不是 ع。"},{"title":"3. غ：ع 的浊擦音，像法语 r","body":"غ（gh）和 ع 部位接近，但方法不同：ع 是咽部收紧、气流从窄缝里挤；غ 是舌根靠近软腭，让气流在那里摩擦，声带振动。它听起来像法语 Paris 里的那个小舌 r，也像漱口时喉咙里「咕噜」的那一声。\n区分 ع 和 غ 最简单的办法：ع 更靠下、更紧，像从喉咙深处挤出来；غ 更靠上、更松，像在口腔后部摩擦。غَدًا（ghadan，明天）、غُرْفَةٌ（ghurfatun，房间）都以 غ 开头。"},{"title":"4. ق 和 ك：一对「前后」","body":"ك（k）和汉语拼音的 g 几乎一样：舌根抵住软腭，憋住气再放开，不送气。注意不是汉语的 k——汉语的 k 是送气音，阿拉伯语的 ك 不送气。\nق（q）比 ك 靠后得多，是**小舌音**：舌根要一直退到小舌附近，抵住那里再放开。发 ك 时舌头在「前面一点」，发 ق 时要明显往后缩，声音也更空、更沉。很多中国学生把 ق 读成 ك，结果 قَلْبٌ（qalbun，心）听起来像 كَلْبٌ（kalbun，狗），这是很尴尬的错误，一定要分清。"},{"title":"5. ف ل م ه：四个省力的音","body":"ف（f）和汉语的 f 一样：上齿轻触下唇，气流从缝里出来，送气要弱，别像吹蜡烛。\nل（l）和汉语的 l 一样：舌尖抵上齿龈，声音清亮。阿拉伯语的 ل 一般不发「暗 l」，只有一个例外（安拉之名），初学不用管。\nم（m）和汉语的 m 一样：双唇闭合，气流从鼻腔出来。\nه（h）比汉语的「喝」轻得多：汉语的 h 是舌根摩擦，阿拉伯语的 ه 气流直接从喉咙出来，几乎不带摩擦，更像叹气时的「哈」。هُوَ（huwa，他）、هِيَ（hiya，她）里的 ه 都很轻。\n前面已经学过的 ن（n）这一节只做复习，不再单独讲。"},{"title":"6. و：一个字母，两种身份","body":"و（w）在这一节有两个身份，看它有没有元音符号就能判断：\n- 作辅音时读 w，像英语 water 的 w：وَلَدٌ（waladun，男孩）、وَاحِدٌ（wāḥidun，一）。\n- 作长元音时读 ū，前提是它前面有一个带 ضَمَّة（damma，合口符）的字母、而它自己光秃秃不带任何符号：نُورٌ（nūrun，光）、يَقُولُ（yaqūlu，他说）。\n一句话记住：و 上带短元音（وَ وُ وِ وْ）就是辅音 w；紧跟在一个 ضَمَّة 后面、自己没有符号，就是长元音 ū。这个规则对 ي 完全一样，第六节会正式讲长元音。"}],"vocab":[{"ar":"عَيْنٌ","rom":"ʿaynun","zh":"眼睛","a":"b07db83c3950"},{"ar":"عِلْمٌ","rom":"ʿilmun","zh":"知识","a":"ae08ec1b9909"},{"ar":"عَرَبِيٌّ","rom":"ʿarabiyyun","zh":"阿拉伯的","a":"120d95aa30f1"},{"ar":"عَائِلَةٌ","rom":"ʿāʾilatun","zh":"家庭","a":"e63ab91a7148"},{"ar":"عِنَبٌ","rom":"ʿinabun","zh":"葡萄","a":"16507742322c"},{"ar":"غَدًا","rom":"ghadan","zh":"明天","a":"7268f632e353"},{"ar":"غُرْفَةٌ","rom":"ghurfatun","zh":"房间","a":"56cee0873c82"},{"ar":"غَنِيٌّ","rom":"ghaniyyun","zh":"富有的","a":"c9ba9aba933a"},{"ar":"غُرَابٌ","rom":"ghurābun","zh":"乌鸦","a":"10aecaec6342"},{"ar":"فَمٌ","rom":"famun","zh":"嘴","a":"8906b81d381a"},{"ar":"فِيلٌ","rom":"fīlun","zh":"大象","a":"94d5c87f3a10"},{"ar":"فَقِيرٌ","rom":"faqīrun","zh":"贫穷的","a":"30c0e3e7e091"},{"ar":"فُنْدُقٌ","rom":"funduqun","zh":"旅馆","a":"a4cfa534d966"},{"ar":"قَلَمٌ","rom":"qalamun","zh":"笔","a":"c5cd3bad9c06"},{"ar":"قَلْبٌ","rom":"qalbun","zh":"心；心脏","a":"5bf7f07886ca"},{"ar":"قَدِيمٌ","rom":"qadīmun","zh":"旧的","a":"47a6413615d8"},{"ar":"قَهْوَةٌ","rom":"qahwatun","zh":"咖啡","a":"3eb55ad84bbd"},{"ar":"قِطٌّ","rom":"qiṭṭun","zh":"猫","a":"39b506244144"},{"ar":"كِتَابٌ","rom":"kitābun","zh":"书","a":"edbacf7ab47c"},{"ar":"كَلْبٌ","rom":"kalbun","zh":"狗","a":"d375e861ea2b"},{"ar":"كَبِيرٌ","rom":"kabīrun","zh":"大的","a":"1fabde614f66"},{"ar":"كُرْسِيٌّ","rom":"kursiyyun","zh":"椅子","a":"f8c06dec5141"},{"ar":"لَيْلٌ","rom":"laylun","zh":"夜晚","a":"f3e2f8cd86d9"},{"ar":"لُغَةٌ","rom":"lughatun","zh":"语言","a":"a5689680ac79"},{"ar":"مَاءٌ","rom":"māʾun","zh":"水","a":"8bc24c13a697"},{"ar":"مَدْرَسَةٌ","rom":"madrasatun","zh":"学校","a":"5d4aca09dd41"},{"ar":"مُعَلِّمٌ","rom":"muʿallimun","zh":"老师（男）","a":"d3c46805be2a"},{"ar":"هُوَ","rom":"huwa","zh":"他","a":"f080a220a33d"},{"ar":"هِيَ","rom":"hiya","zh":"她","a":"662ee0fd3425"},{"ar":"هَاتِفٌ","rom":"hātifun","zh":"电话","a":"049971f0fef1"},{"ar":"وَاحِدٌ","rom":"wāḥidun","zh":"一","a":"3cdce2f89a8f"},{"ar":"وَلَدٌ","rom":"waladun","zh":"男孩","a":"ef7a497be3d4"},{"ar":"مِصْرُ","rom":"miṣru","zh":"埃及","a":"549f8b4f1424"},{"ar":"نُورٌ","rom":"nūrun","zh":"光","a":"6f670ffb7f68"}],"examples":[{"ar":"هُوَ مُعَلِّمٌ.","rom":"huwa muʿallimun","zh":"他是老师。","note":"名词句，谓语带 -un","a":"89104c38dde0"},{"ar":"هِيَ طَالِبَةٌ.","rom":"hiya ṭālibatun","zh":"她是学生。","note":"هِيَ 用于阴性","a":"c132fc6402de"},{"ar":"هَذَا فِيلٌ.","rom":"hādhā fīlun","zh":"这是大象。","note":"هَذَا + 泛指名词作谓语","a":"72df9e2e662b"},{"ar":"هَذَا قَلَمٌ جَدِيدٌ.","rom":"hādhā qalamun jadīdun","zh":"这是一支新笔。","note":"形容词后置修饰名词","a":"7e5f40015887"},{"ar":"ذَلِكَ كَلْبٌ صَغِيرٌ.","rom":"dhālika kalbun ṣaghīrun","zh":"那是一只小狗。","note":"ذَلِكَ 指远处","a":"8f629950a967"},{"ar":"هَذِهِ غُرْفَةٌ كَبِيرَةٌ.","rom":"hādhihi ghurfatun kabīratun","zh":"这是一个大房间。","note":"هَذِهِ + 阴性名词","a":"71901a677d91"},{"ar":"الْكِتَابُ عَلَى الطَّاوِلَةِ.","rom":"al-kitābu ʿalā ṭ-ṭāwilati","zh":"书在桌子上。","note":"ك 是月亮字母，ل 要读出来","a":"7c2e1237ba82"},{"ar":"الْمَاءُ بَارِدٌ.","rom":"al-māʾu bāridun","zh":"水是凉的。","note":"冠词 + 名词句","a":"91d8970b8f91"},{"ar":"اللَّيْلُ طَوِيلٌ.","rom":"al-laylu ṭawīlun","zh":"夜很长。","note":"ل 是太阳字母，الْ 读 al- 并叠音","a":"359153d852d9"},{"ar":"الْقَهْوَةُ سَاخِنَةٌ.","rom":"al-qahwatu sākhinatun","zh":"咖啡是热的。","note":"ق 是月亮字母，l 读出","a":"89a1795fd70f"},{"ar":"هُوَ فِي الْغُرْفَةِ.","rom":"huwa fī l-ghurfati","zh":"他在房间里。","note":"فِي 后接属格","a":"467c07f3322e"},{"ar":"هِيَ فِي الْمَدْرَسَةِ.","rom":"hiya fī l-madrasati","zh":"她在学校里。","note":"同上，م 是月亮字母","a":"c0e952e1686a"},{"ar":"أَنَا مِنْ مِصْرَ.","rom":"anā min miṣra","zh":"我来自埃及。","note":"مِنْ 后接属格","a":"9592f8970687"},{"ar":"فِي الْغُرْفَةِ كُرْسِيٌّ.","rom":"fī l-ghurfati kursiyyun","zh":"房间里有一把椅子。","note":"前置介词短语 + 后置主语","a":"f0c80647a0aa"},{"ar":"الْمُعَلِّمُ فِي الْفَصْلِ.","rom":"al-muʿallimu fī l-faṣli","zh":"老师在教室里。","note":"ع 的咽音要发出来","a":"49502984f5d7"},{"ar":"هَذَا عِلْمٌ نَافِعٌ.","rom":"hādhā ʿilmun nāfiʿun","zh":"这是有用的知识。","note":"名词 + 形容词","a":"306e321fabea"},{"ar":"الْعَرَبِيَّةُ لُغَةٌ جَمِيلَةٌ.","rom":"al-ʿarabiyyatu lughatun jamīlatun","zh":"阿拉伯语是一门美丽的语言。","note":"谓语是「名词 + 形容词」","a":"a4009419a147"},{"ar":"عَائِلَتِي كَبِيرَةٌ.","rom":"ʿāʾilatī kabīratun","zh":"我的家庭很大。","note":"hamza 写在 ي 上；ـي 表所属","a":"6de508078bda"},{"ar":"هُوَ غَنِيٌّ وَأَنَا فَقِيرٌ.","rom":"huwa ghaniyyun wa-anā faqīrun","zh":"他富有，我贫穷。","note":"وَ 连接两个名词句","a":"0a3b4a441359"},{"ar":"هَذَا هَاتِفٌ جَدِيدٌ.","rom":"hādhā hātifun jadīdun","zh":"这是一部新电话。","note":"ه 很轻，不要发成汉语的 h","a":"11240cd64333"},{"ar":"فِي الْحَدِيقَةِ شَجَرَةٌ كَبِيرَةٌ.","rom":"fī l-ḥadīqati shajaratun kabīratun","zh":"花园里有一棵大树。","note":"同上，主语在介词短语之后","a":"fe2bd05b5e84"},{"ar":"أَرَاكَ غَدًا.","rom":"arāka ghadan","zh":"明天见。","note":"宾语后缀 ـكَ + 时间副词","a":"d7815ce62120"}],"drills":[{"q":"ع 的发音部位在哪里？","a":"咽部，舌根后压、喉咙收紧"},{"q":"ع 实在发不出来时可以用什么代替？","a":"喉部收紧的 a"},{"q":"غ 像哪种语言里的 r？","a":"法语的小舌 r"},{"q":"ق 和 ك 哪个更靠后？","a":"ق"},{"q":"قَلْبٌ 和 كَلْبٌ 分别是什么意思？","a":"心 / 狗"},{"q":"「书」用阿拉伯语怎么说？","a":"كِتَابٌ"},{"q":"「水」用阿拉伯语怎么说？","a":"مَاءٌ"},{"q":"و 什么时候读长元音 ū？","a":"前面是 ضَمَّة、自己不带元音符号时"},{"q":"「他」和「她」分别是哪个词？","a":"هُوَ / هِيَ"},{"q":"把「这 + 房间」连成名词句","a":"هَذِهِ غُرْفَةٌ"},{"q":"「一」用阿拉伯语怎么说？","a":"وَاحِدٌ"},{"q":"「明天见」怎么说？","a":"أَرَاكَ غَدًا"}],"tips":["ع 别用 ء 代替：ء 是喉咙「一顿」，ع 是喉咙「一紧」，一顿一紧完全是两回事。","找 ع 的位置：连发 a-a-a，中间收紧的那一下就是它，先练收紧再加声音。","ق 往后缩，ك 往前放；قَلْبٌ（心）读成 كَلْبٌ 就变成「狗」了。","汉语的 k 送气，ك 不送气，它更接近拼音的 g。","و 上有元音符号就是辅音 w，光秃秃跟在 ضَمَّة 后面就是长元音 ū。","ه 比汉语的「喝」轻，气流直接从喉咙出来，几乎不带摩擦。"],"id":"ch1-s5"},{"title":"第六节 长元音、叠音与冠词","concepts":[{"title":"1. 学完这一节你能做什么","body":"这一节是第一章的收口。学完它，你手上就有了拼读任何标音阿拉伯语词的全部工具：28 个字母、短元音、长元音、叠音、鼻音符、冠词、hamza 和 ة。换句话说，只要给你标好音的词，你都能读出来，也能说出它大致是确指还是泛指、是阳性还是阴性。这就是第一章的全部目标。"},{"title":"2. 长元音：ā ī ū 与长短对立","body":"阿拉伯语有三个长元音，它们不是新字母，而是由 ا و ي 三个字母兼职：\n- ا 前面是 fatha（短音 a）→ 读 ā：بَابٌ（bābun，门）、كَاتِبٌ（kātibun，作家）\n- و 前面是 damma（短音 u）→ 读 ū：نُورٌ（nūrun，光）、يَقُولُ（yaqūlu，他说）\n- ي 前面是 kasra（短音 i）→ 读 ī：فِيلٌ（fīlun，大象）、كَبِيرٌ（kabīrun，大的）\n长短元音是**区分词义**的，不是随便拖长：كَتَبَ（kataba，他写了）、كَاتِبٌ（kātibun，作家）、كِتَابٌ（kitābun，书），同一个词根 k-t-b，靠元音的长短和位置变出三个不同的词。读的时候长元音要真的拉长，大约是一个短元音的两倍；短元音则要短促收住，不能拖。中国学生最常见的毛病是把短元音拖长，于是 كَتَبَ 听起来像 كَاتِبٌ。"},{"title":"3. 叠音（شَدَّةٌ）与鼻音符（تَنْوِينٌ）","body":"**叠音**：字母上多写一个小符号，叫 شَدَّة（shaddatun，叠音符）。它表示这个辅音要读两遍——前一半收住上一个音节，后一半起下一个音节，听起来像中间停了一下再重读。مُحَمَّدٌ（muḥammadun，穆罕默德）里的 م 要停一下再重读，دَرَّسَ（darrasa，他教）里的 ر 也一样。带叠音的音节要读得比其他音节更「实」、更长一点。\n**鼻音符**：写在词尾的三个符号，表示词尾加一个 n。三个符号按格分：\n- ـٌ = -un（主格）：كِتَابٌ（kitābun，书）\n- ـٍ = -in（属格）：كِتَابٍ（kitābin，书）\n- ـً = -an（宾格）：كِتَابًا（kitāban，书）\n鼻音符只加在**泛指名词**（和修饰它的形容词）上。确指名词已经带了 الْ，就不能再带鼻音符：الْكِتَابُ 对，الْكِتَابٌ 错。写 ـً 的时候通常要在后面补一个 ا，写成 ـًا；但词尾是 ة 或 ء 时不补：مَدْرَسَةً（madrasatan，一所学校）、مَاءً（māʾan，水）。"},{"title":"4. 冠词 الْ：太阳字母与月亮字母","body":"الْ（al-）相当于汉语「这/那」加英语 the 的合力，作用是**确指**：把泛指变确指。كِتَابٌ 是「一本书」，الْكِتَابُ 是「那本书」。它是阿拉伯语里出现频率最高的词形，必须一次学扎实。\n关键在于：الْ 的 ل 读不读，取决于后面第一个字母属于哪一类。\n- **月亮字母**（14 个）：أ ب ج ح خ ع غ ف ق ك م ه و ي。遇到它们，ل 照读，带 sukun：الْقَمَرُ（al-qamaru，月亮）、الْكِتَابُ（al-kitābu，书）、الْمَاءُ（al-māʾu，水）。\n- **太阳字母**（14 个）：ت ث د ذ ر ز س ش ص ض ط ظ ل ن。遇到它们，ل **不读**，后面那个字母要**叠起来读**：الشَّمْسُ 读 ash-shamsu（不是 al-shamsu），الدَّرْسُ 读 ad-darsu（功课），السَّمَاءُ 读 as-samāʾu（天空），الطَّالِبُ 读 aṭ-ṭālibu（学生）。\n写法上，太阳字母前的 الْ 照样写出来，只是要在后面那个字母上加 شَدَّة。所以看到一个词以 الْ 开头、紧跟的字母带叠音，就知道是太阳字母同化。名字的由来是：阿拉伯人觉得这些字母把 l 的声音「吞掉」了，像太阳把星星的光盖住。"},{"title":"5. هَمْزَةٌ 的四种写法与 ة（تَاءٌ مَرْبُوطَةٌ）","body":"**هَمْزَةٌ（hamza，ء）** 是喉塞音，像汉语「啊」前面突然一顿。它有四种写法，选哪个由它前后元音的「强弱」决定，强弱顺序是：kasra（i）最强，其次 damma（u），再次 fatha（a）。\n- أ：写在 alif 上，词首最常见：أَنَا（anā，我）、أَبٌ（abun，父亲）、أُمٌّ（ummun，母亲）\n- إ：写在 alif 下，只用于词首读 i 的时候：إِلَى（ilā，到）、إِبْنٌ（ibnun，儿子）\n- ؤ：写在 waw 上，前后有 u 的时候：سُؤَالٌ（suʾālun，问题）、مَسْؤُولٌ（masʾūlun，负责人）\n- ئ：写在 ya 上，前后有 i 的时候：عَائِلَةٌ（ʿāʾilatun，家庭）、بِئْرٌ（biʾrun，井）\n初学不用背得太细，先记三条：词首一律写 أ 或 إ（读 a、u 用 أ，读 i 用 إ）；词中谁「强」就写在谁上面；拿不准就查词典，标准拼写是固定的，不能自己造。\n**ة（تَاءٌ مَرْبُوطَةٌ，「连着的 t」）**：只出现在词尾，形状是 ه 加两点。它有两种读法：\n- 停顿（读到这里就停）时读 a：مَدْرَسَةٌ 读 madrasatun，末尾那个 ة 读 a。\n- 后面接别的词（正偏组合、代词后缀）时读 t：مَدْرَسَةُ الْوَلَدِ（madrasatu l-waladi，男孩的学校）。\n它绝大多数表阴性，是最可靠的性别线索：طَالِبٌ（男学生）对 طَالِبَةٌ（女学生），مُعَلِّمٌ（男老师）对 مُعَلِّمَةٌ（女老师）。"}],"vocab":[{"ar":"كَتَبَ","rom":"kataba","zh":"写（过去式）","a":"1a31c3cbb834"},{"ar":"كَاتِبٌ","rom":"kātibun","zh":"作家","a":"c4de9789ace7"},{"ar":"كِتَابٌ","rom":"kitābun","zh":"书","a":"edbacf7ab47c"},{"ar":"كِتَابًا","rom":"kitāban","zh":"书（宾格，带 -an）","a":"9e10f0206c40"},{"ar":"دَرَسَ","rom":"darasa","zh":"学习（过去式）","a":"a534bf110d1a"},{"ar":"دَرَّسَ","rom":"darrasa","zh":"教（过去式）","a":"b99a4e41f864"},{"ar":"مُحَمَّدٌ","rom":"muḥammadun","zh":"穆罕默德（人名）","a":"6c8dc358ebb7"},{"ar":"شَمْسٌ","rom":"shamsun","zh":"太阳","a":"90fac5bf0987"},{"ar":"الشَّمْسُ","rom":"ash-shamsu","zh":"太阳（确指）","a":"c39784db0341"},{"ar":"قَمَرٌ","rom":"qamarun","zh":"月亮","a":"d1bb9ee87802"},{"ar":"الْقَمَرُ","rom":"al-qamaru","zh":"月亮（确指）","a":"d50c85896444"},{"ar":"بَيْتٌ","rom":"baytun","zh":"房子","a":"f681630e99e8"},{"ar":"الْبَيْتُ","rom":"al-baytu","zh":"房子（确指）","a":"b8cca83ab210"},{"ar":"وَلَدٌ","rom":"waladun","zh":"男孩","a":"ef7a497be3d4"},{"ar":"الْوَلَدُ","rom":"al-waladu","zh":"那个男孩","a":"07d337982afa"},{"ar":"مَدْرَسَةٌ","rom":"madrasatun","zh":"学校","a":"5d4aca09dd41"},{"ar":"الْمَدْرَسَةُ","rom":"al-madrasatu","zh":"那所学校","a":"6ee4932a0614"},{"ar":"طَالِبَةٌ","rom":"ṭālibatun","zh":"女学生","a":"f69923af1ab2"},{"ar":"مُعَلِّمَةٌ","rom":"muʿallimatun","zh":"女老师","a":"dccf4a2c8f7c"},{"ar":"أَبٌ","rom":"abun","zh":"父亲","a":"2c07cb543d73"},{"ar":"أُمٌّ","rom":"ummun","zh":"母亲","a":"33ccd5682798"},{"ar":"إِبْنٌ","rom":"ibnun","zh":"儿子","a":"800ab74fbe51"},{"ar":"بِنْتٌ","rom":"bintun","zh":"女儿","a":"db9e49cfe2a2"},{"ar":"أُخْتٌ","rom":"ukhtun","zh":"姐妹","a":"2adfcda1c372"},{"ar":"سُؤَالٌ","rom":"suʾālun","zh":"问题","a":"ae22ad648daf"},{"ar":"مَسْؤُولٌ","rom":"masʾūlun","zh":"负责人","a":"d81a11228483"},{"ar":"بِئْرٌ","rom":"biʾrun","zh":"井","a":"3b4272d154f2"},{"ar":"شَيْءٌ","rom":"shayʾun","zh":"东西","a":"faa12087e330"},{"ar":"مَاءٌ","rom":"māʾun","zh":"水","a":"8bc24c13a697"},{"ar":"نُورٌ","rom":"nūrun","zh":"光","a":"6f670ffb7f68"},{"ar":"يَقُولُ","rom":"yaqūlu","zh":"他说（现在式）","a":"69a4ff02ce91"},{"ar":"جَدِيدٌ","rom":"jadīdun","zh":"新的","a":"bc60168bb745"},{"ar":"قَدِيمٌ","rom":"qadīmun","zh":"旧的","a":"47a6413615d8"},{"ar":"مُجْتَهِدٌ","rom":"mujtahidun","zh":"用功的","a":"10a9e9bd54f1"}],"examples":[{"ar":"مُحَمَّدٌ طَالِبٌ.","rom":"muḥammadun ṭālibun","zh":"穆罕默德是学生。","note":"两个泛指名词构成名词句","a":"9fc3f6898157"},{"ar":"أَنَا كَاتِبٌ.","rom":"anā kātibun","zh":"我是作家。","note":"ā 与短 a 的对立","a":"dc1e7cfbc661"},{"ar":"الْكِتَابُ جَدِيدٌ.","rom":"al-kitābu jadīdun","zh":"这本书是新的。","note":"الْ 确指 + 形容词谓语","a":"234f3c14dc49"},{"ar":"الشَّمْسُ فِي السَّمَاءِ.","rom":"ash-shamsu fī s-samāʾi","zh":"太阳在天上。","note":"ش 和 س 都是太阳字母，两处同化","a":"31f41d68069c"},{"ar":"الْقَمَرُ جَمِيلٌ.","rom":"al-qamaru jamīlun","zh":"月亮很美。","note":"ق 是月亮字母，l 要读出","a":"1641d637870d"},{"ar":"هَذَا الْبَيْتُ كَبِيرٌ.","rom":"hādhā l-baytu kabīrun","zh":"这栋房子很大。","note":"指示词 + 确指名词作起语","a":"4a79fba118c6"},{"ar":"الْمَدْرَسَةُ قَرِيبَةٌ.","rom":"al-madrasatu qarībatun","zh":"学校很近。","note":"ة 在停顿处读 a","a":"a1bda2716d68"},{"ar":"الْوَلَدُ فِي الْبَيْتِ.","rom":"al-waladu fī l-bayti","zh":"男孩在家里。","note":"介词短语作谓语","a":"c66534c42b33"},{"ar":"دَرَّسَ الْمُعَلِّمُ الْعَرَبِيَّةَ.","rom":"darrasa l-muʿallimu l-ʿarabiyyata","zh":"老师教阿拉伯语。","note":"ر 带叠音，要读两拍","a":"8675ac72d349"},{"ar":"كَتَبَ الْوَلَدُ الدَّرْسَ.","rom":"kataba l-waladu d-darsa","zh":"男孩写了功课。","note":"د 是太阳字母，الْ 读 ad-","a":"030bfa451d14"},{"ar":"كَتَبَ كِتَابًا.","rom":"kataba kitāban","zh":"他写了一本书。","note":"宾格鼻音符 -an","a":"0d945a5b8644"},{"ar":"فِي الْبَيْتِ وَلَدٌ.","rom":"fī l-bayti waladun","zh":"家里有一个男孩。","note":"主格鼻音符 -un","a":"17880e1e8a3d"},{"ar":"هَذَا سُؤَالٌ صَعْبٌ.","rom":"hādhā suʾālun ṣaʿbun","zh":"这是一个难题。","note":"hamza 写在 waw 上","a":"777cfddc6c72"},{"ar":"هُوَ مَسْؤُولٌ.","rom":"huwa masʾūlun","zh":"他是负责人。","note":"hamza 在 waw 上，读 -ū-","a":"8a003db89d5b"},{"ar":"عَائِلَتِي كَبِيرَةٌ.","rom":"ʿāʾilatī kabīratun","zh":"我的家庭很大。","note":"hamza 写在 ya 上；ـي 表所属","a":"6de508078bda"},{"ar":"أَبِي مُعَلِّمٌ.","rom":"abī muʿallimun","zh":"我父亲是老师。","note":"长元音 ī 在词尾","a":"1b39a2f5a9b8"},{"ar":"أُخْتِي طَالِبَةٌ مُجْتَهِدَةٌ.","rom":"ukhtī ṭālibatun mujtahidatun","zh":"我妹妹是个用功的学生。","note":"ة 两次出现，都表阴性","a":"f70f56787b4f"},{"ar":"هَذِهِ طَالِبَةٌ.","rom":"hādhihi ṭālibatun","zh":"这是一位女学生。","note":"هَذِهِ 用于阴性名词","a":"ed5509fdff2d"},{"ar":"هَذَا شَيْءٌ جَمِيلٌ.","rom":"hādhā shayʾun jamīlun","zh":"这是一件美好的东西。","note":"hamza 单独站在词尾","a":"731c05daa532"},{"ar":"هُوَ يَقُولُ الْحَقَّ.","rom":"huwa yaqūlu l-ḥaqqa","zh":"他说真话。","note":"现在式 + 宾格；ū 是长元音","a":"53eadcaf17f2"},{"ar":"الْمُعَلِّمَةُ فِي الْمَدْرَسَةِ.","rom":"al-muʿallimatu fī l-madrasati","zh":"女老师在学校里。","note":"两处 الْ 都不同化","a":"74d26f3c73ef"},{"ar":"بِنْتُ الْمُعَلِّمِ طَالِبَةٌ.","rom":"bintu l-muʿallimi ṭālibatun","zh":"老师的女儿是学生。","note":"正偏组合，偏次用属格","a":"de104f939a83"}],"drills":[{"q":"كَتَبَ 和 كَاتِبٌ 和 كِتَابٌ 三个词哪里不同？","a":"元音的长短和位置不同"},{"q":"مُحَمَّدٌ 里的 شَدَّةٌ 怎么读？","a":"同一个字母读两遍，先停住再重读"},{"q":"-an 的鼻音符写成什么符号？","a":"ـً，例如 كِتَابًا"},{"q":"الْقَمَرُ 里的 ل 读不读？","a":"读，因为 ق 是月亮字母"},{"q":"الشَّمْسُ 怎么读？","a":"ash-shamsu"},{"q":"太阳字母和月亮字母各有多少个？","a":"各 14 个"},{"q":"سُؤَالٌ 里的 hamza 为什么写在 و 上？","a":"前面是 ضَمَّة（u），u 比 a 强"},{"q":"ة 在词尾停顿时读什么？","a":"a"},{"q":"「女学生」用阿拉伯语怎么说？","a":"طَالِبَةٌ"},{"q":"「老师的女儿」怎么说？","a":"بِنْتُ الْمُعَلِّمِ"},{"q":"给 كِتَابٌ 加上 الْ 并写出转写","a":"الْكِتَابُ，al-kitābu"},{"q":"مَدْرَسَةٌ 加宾格鼻音符怎么写？","a":"مَدْرَسَةً"}],"tips":["四步法第一步：先找有没有 الْ，看后面第一个字母是太阳字母还是月亮字母，决定 ل 读不读。","四步法第二步：再看 ا و ي 前面有没有同符短元音，有就拉长成 ā ī ū。","四步法第三步：找带 شَدَّةٌ 的字母，读两拍，前一半停住、后一半重读。","四步法第四步：看词尾有没有 ـٌ ـٍ ـً，有就加 n，而且只有泛指名词才加。","长元音要拉到短元音的两倍，短元音不能拖，否则 كَتَبَ 会变成 كَاتِبٌ。","الْ 和鼻音符不能同时出现：有了 الْ 就不会再有 ـٌ ـٍ ـً。"],"id":"ch1-s6"}],"id":"ch1"},{"title":"第二章 名词与名词句","sections":[{"title":"第七节 名词句：起语与谓语","concepts":[{"title":"1. 阿拉伯语只有两大类句子","body":"这一节学完，你能用「起语 + 谓语」造出「这是一本书」「房子很大」这类最基本的句子，也会知道哪个词上必须带鼻音符。阿拉伯语的句子只有两大类：名词句（الْجُمْلَةُ الِاسْمِيَّةُ，al-jumlatu al-ismiyyatu）和动词句（الْجُمْلَةُ الْفِعْلِيَّةُ，al-jumlatu al-fiʿliyyatu）。判断方法很简单，看第一个词：第一个词是名词或代词的叫名词句，第一个词是动词的叫动词句。本节只讲名词句。"},{"title":"2. 名词句 = 起语 + 谓语，中间没有「是」","body":"名词句由两部分组成：起语（مُبْتَدَأٌ，mubtadaʾun，句子里被说明的那个人或东西）和谓语（خَبَرٌ，khabarun，用来说明起语的部分）。两部分之间不加任何系动词，阿拉伯语里没有相当于英语 is 的词。\n想说「这是一本书」，就是把「这」和「书」并排放在一起：هَذَا كِتَابٌ（hādhā kitābun，这是一本书）。初学阶段不要加 هُوَ，两块并排就是句子。"},{"title":"3. 谓语是泛指名词，要带鼻音符 -un","body":"谓语如果是一个泛指名词（不确定的「一本书」），词尾要加 -un 的鼻音符（تَنْوِينٌ，tanwīnun），写在最后一个字母上。所以「书」在谓语位置上要写 كِتَابٌ（kitābun），不能写 كِتَاب。\n这是初学者最容易漏的一条：漏了鼻音符，句子在语法上就不完整。"},{"title":"4. 语序原则：确指在前，泛指在后","body":"起语一般是确指的（مَعْرِفَةٌ，maʿrifatun），也就是听话人已经知道指的是谁、什么；谓语一般是泛指的（نَكِرَةٌ，nakiratun），是你告诉对方的新信息。\n所以正常语序是「确指 + 泛指」：الْبَيْتُ كَبِيرٌ（al-baytu kabīrun，这栋房子很大）。反过来写成 بَيْتٌ كَبِيرٌ（baytun kabīrun），它就不是句子，而是短语「一栋大房子」——这是名词加形容词，不是起语加谓语。"},{"title":"5. 起语常见的三种形式","body":"起语要确指，最常用的有三种。一是指示代词，如 هَذَا（hādhā，这，阳性）、هَذِهِ（hādhihi，这，阴性）；二是带 الْ 的名词，如 الْكِتَابُ（al-kitābu，这本书）；三是人称代词，如 هُوَ（huwa，他）、هِيَ（hiya，她）、أَنَا（ʾanā，我）。三种都能直接放在句首作起语。"},{"title":"6. 三个常见错误","body":"第一，在起语和谓语之间硬加「是」；第二，谓语忘了鼻音符，写成 هَذَا كِتَاب；第三，用 هَذَا 去指阴性名词，说成 هَذَا مَدْرَسَةٌ。记住：名词句是两块并排，不是「主 + 系 + 表」。"}],"vocab":[{"ar":"كِتَابٌ","rom":"kitābun","zh":"书","a":"edbacf7ab47c"},{"ar":"قَلَمٌ","rom":"qalamun","zh":"笔","a":"c5cd3bad9c06"},{"ar":"دَفْتَرٌ","rom":"daftarun","zh":"笔记本","a":"cf38915bbf53"},{"ar":"مَكْتَبٌ","rom":"maktabun","zh":"书桌；办公室","a":"9b5fb3903fdf"},{"ar":"كُرْسِيٌّ","rom":"kursiyyun","zh":"椅子","a":"f8c06dec5141"},{"ar":"بَابٌ","rom":"bābun","zh":"门","a":"b7831c1d1303"},{"ar":"نَافِذَةٌ","rom":"nāfidhatun","zh":"窗户","a":"a09b57379a2d"},{"ar":"بَيْتٌ","rom":"baytun","zh":"房子","a":"f681630e99e8"},{"ar":"غُرْفَةٌ","rom":"ghurfatun","zh":"房间","a":"56cee0873c82"},{"ar":"مَدْرَسَةٌ","rom":"madrasatun","zh":"学校","a":"5d4aca09dd41"},{"ar":"جَامِعَةٌ","rom":"jāmiʿatun","zh":"大学","a":"4e7c3f025186"},{"ar":"مَسْجِدٌ","rom":"masjidun","zh":"清真寺","a":"f5e111bd990d"},{"ar":"مَطْعَمٌ","rom":"maṭʿamun","zh":"餐厅","a":"dad00cffec5c"},{"ar":"حَدِيقَةٌ","rom":"ḥadīqatun","zh":"花园","a":"0b6587e313c8"},{"ar":"شَارِعٌ","rom":"shāriʿun","zh":"街道","a":"34c115324fd0"},{"ar":"مَدِينَةٌ","rom":"madīnatun","zh":"城市","a":"e91c192a8eaf"},{"ar":"قَرْيَةٌ","rom":"qaryatun","zh":"村庄","a":"55330b89cc77"},{"ar":"بِنَايَةٌ","rom":"bināyatun","zh":"楼房","a":"ff76c338f819"},{"ar":"سَيَّارَةٌ","rom":"sayyāratun","zh":"汽车","a":"e5f13dbd9c85"},{"ar":"مِفْتَاحٌ","rom":"miftāḥun","zh":"钥匙","a":"deb53ab6c662"},{"ar":"هَاتِفٌ","rom":"hātifun","zh":"电话","a":"049971f0fef1"},{"ar":"مَاءٌ","rom":"māʾun","zh":"水","a":"8bc24c13a697"},{"ar":"خُبْزٌ","rom":"khubzun","zh":"面包","a":"96ab68e09cee"},{"ar":"قَهْوَةٌ","rom":"qahwatun","zh":"咖啡","a":"3eb55ad84bbd"},{"ar":"شَايٌ","rom":"shāyun","zh":"茶","a":"4076b47ec209"},{"ar":"طَالِبٌ","rom":"ṭālibun","zh":"学生（男）","a":"bea7c61ac7f5"},{"ar":"مُعَلِّمٌ","rom":"muʿallimun","zh":"老师（男）","a":"d3c46805be2a"},{"ar":"أُسْتَاذٌ","rom":"ustādhun","zh":"老师；教授","a":"5a4d46413b66"},{"ar":"طَبِيبٌ","rom":"ṭabībun","zh":"医生","a":"0695f0f3810f"},{"ar":"مُهَنْدِسٌ","rom":"muhandisun","zh":"工程师","a":"b2a995823af6"},{"ar":"صَدِيقٌ","rom":"ṣadīqun","zh":"朋友（男）","a":"204b61c6d156"},{"ar":"وَلَدٌ","rom":"waladun","zh":"男孩","a":"ef7a497be3d4"},{"ar":"بِنْتٌ","rom":"bintun","zh":"女孩","a":"db9e49cfe2a2"},{"ar":"رَجُلٌ","rom":"rajulun","zh":"男人","a":"44767a34bc25"},{"ar":"اِمْرَأَةٌ","rom":"imraʾatun","zh":"女人","a":"9615543e5098"}],"examples":[{"ar":"هَذَا كِتَابٌ.","rom":"hādhā kitābun","zh":"这是一本书。","note":"هَذَا 起语 + 泛指谓语","a":"63c73a325011"},{"ar":"ذَلِكَ بَيْتٌ.","rom":"dhālika baytun","zh":"那是一栋房子。","note":"ذَلِكَ 指远处","a":"e387c40f8d9a"},{"ar":"هَذِهِ مَدْرَسَةٌ.","rom":"hādhihi madrasatun","zh":"这是一所学校。","note":"هَذِهِ 配阴性名词","a":"ecf187627e77"},{"ar":"هَذَا طَالِبٌ.","rom":"hādhā ṭālibun","zh":"这是一名学生。","note":"起语 + 泛指谓语","a":"7988a683546c"},{"ar":"هَذِهِ بِنْتٌ.","rom":"hādhihi bintun","zh":"这是一个女孩。","note":"بِنْتٌ 是阴性名词","a":"978f3e2df335"},{"ar":"هَذَا وَلَدٌ.","rom":"hādhā waladun","zh":"这是一个男孩。","note":"وَلَدٌ 是阳性名词","a":"975c78cad0d5"},{"ar":"ذَلِكَ رَجُلٌ.","rom":"dhālika rajulun","zh":"那是一个男人。","note":"远指阳性","a":"dd49ffb6f8a1"},{"ar":"هَذِهِ اِمْرَأَةٌ.","rom":"hādhihi imraʾatun","zh":"这是一位女人。","note":"اِمْرَأَةٌ 是阴性","a":"73b8911971d9"},{"ar":"هَذِهِ سَيَّارَةٌ.","rom":"hādhihi sayyāratun","zh":"这是一辆汽车。","note":"阴性名词配 هَذِهِ","a":"444838cb5d9c"},{"ar":"هَذَا بَابٌ.","rom":"hādhā bābun","zh":"这是一扇门。","note":"谓语带 -un","a":"6090ab44b350"},{"ar":"هَذِهِ نَافِذَةٌ.","rom":"hādhihi nāfidhatun","zh":"这是一扇窗户。","note":"谓语带 -un","a":"35687f77b327"},{"ar":"هَذَا مَكْتَبٌ.","rom":"hādhā maktabun","zh":"这是一张书桌。","note":"谓语带 -un","a":"2914e446660c"},{"ar":"هَذَا كُرْسِيٌّ.","rom":"hādhā kursiyyun","zh":"这是一把椅子。","note":"词尾叠音 + 鼻音符","a":"c4aaad647bb2"},{"ar":"هَذَا قَلَمٌ.","rom":"hādhā qalamun","zh":"这是一支笔。","note":"谓语带 -un","a":"40533bcf2d20"},{"ar":"ذَلِكَ دَفْتَرٌ.","rom":"dhālika daftarun","zh":"那是一个笔记本。","note":"远指 + 泛指谓语","a":"27008f9b606f"},{"ar":"هَذَا مِفْتَاحٌ.","rom":"hādhā miftāḥun","zh":"这是一把钥匙。","note":"谓语带 -un","a":"b87ce76163df"},{"ar":"هَذَا هَاتِفٌ.","rom":"hādhā hātifun","zh":"这是一部电话。","note":"谓语带 -un","a":"11636ce7cff0"},{"ar":"ذَلِكَ مُعَلِّمٌ.","rom":"dhālika muʿallimun","zh":"那位是老师。","note":"远指 + 泛指谓语","a":"63117c631347"},{"ar":"هُوَ طَالِبٌ.","rom":"huwa ṭālibun","zh":"他是学生。","note":"人称代词作起语","a":"f59d45693267"},{"ar":"هِيَ مُعَلِّمَةٌ.","rom":"hiya muʿallimatun","zh":"她是老师。","note":"谓语随起语变阴性","a":"e8dbb992007c"},{"ar":"أَنَا طَالِبٌ.","rom":"anā ṭālibun","zh":"我是学生。","note":"代词作起语","a":"089a5f92b79f"},{"ar":"الْبَيْتُ كَبِيرٌ.","rom":"al-baytu kabīrun","zh":"这栋房子很大。","note":"起语带 الْ 确指，谓语泛指","a":"2d4085b6dfa6"},{"ar":"الْكِتَابُ جَدِيدٌ.","rom":"al-kitābu jadīdun","zh":"这本书是新的。","note":"确指在前、泛指在后","a":"234f3c14dc49"},{"ar":"الْمَدْرَسَةُ قَرِيبَةٌ.","rom":"al-madrasatu qarībatun","zh":"学校很近。","note":"阴性起语配阴性谓语","a":"a1bda2716d68"},{"ar":"بَيْتٌ كَبِيرٌ.","rom":"baytun kabīrun","zh":"一栋大房子（短语）。","note":"名词 + 形容词，不是名词句","a":"688b2b19ed71"}],"drills":[{"q":"名词句由哪两部分组成？","a":"起语（مُبْتَدَأٌ）+ 谓语（خَبَرٌ）"},{"q":"「书」用阿拉伯语怎么说？","a":"كِتَابٌ"},{"q":"「房子」用阿拉伯语怎么说？","a":"بَيْتٌ"},{"q":"把「这 + 书」连成名词句","a":"هَذَا كِتَابٌ"},{"q":"「这是一所学校」怎么说？","a":"هَذِهِ مَدْرَسَةٌ"},{"q":"「那是一栋房子」怎么说？","a":"ذَلِكَ بَيْتٌ"},{"q":"「他是学生」怎么说？","a":"هُوَ طَالِبٌ"},{"q":"「她是老师」怎么说？","a":"هِيَ مُعَلِّمَةٌ"},{"q":"改错：هَذَا كِتَاب","a":"هَذَا كِتَابٌ（谓语要带鼻音符）"},{"q":"「这栋房子很大」怎么说？","a":"الْبَيْتُ كَبِيرٌ"},{"q":"بَيْتٌ كَبِيرٌ 是句子还是短语？","a":"短语，意思是「一栋大房子」"}],"tips":["名词句没有「是」，别在起语和谓语之间硬加动词。","谓语的 -un 一定要写出来：كِتَابٌ，不是 كِتَاب。","起语要确指：كِتَابٌ كَبِيرٌ 不是句子，是「一本大书」这个短语。","هَذَا 配阳性，هَذِهِ 配阴性，说 هَذَا مَدْرَسَةٌ 就错了。","阿拉伯语从右往左写，句子的第一个词在最右边。","书写时谓语一律写 -un；朗读到句末停顿时这个 -un 不发音，属正常现象，别以为写错了。"],"id":"ch2-s1"},{"title":"第八节 性与指示代词","concepts":[{"title":"1. 名词分阴阳两性","body":"这一节学完，你能判断一个名词是阳性还是阴性，也能选对「这」「那」这些指示代词。阿拉伯语每个名词都有语法性别：阳性（مُذَكَّرٌ，mudhakkarun）和阴性（مُؤَنَّثٌ，muʾannathun）。中文说「桌子」「椅子」不分性别，阿拉伯语里每个词都得记一个性别，这一点只能靠背。"},{"title":"2. 默认阳性，标记阴性：以 ة 结尾","body":"规则很简单：没有阴性标记的词，一律按阳性处理；最常见的阴性标记是词尾的 ة，读 -a。所以 طَالِبٌ（ṭālibun，男学生）是阳性，加上 ة 变成 طَالِبَةٌ（ṭālibatun，女学生）就是阴性。绝大多数以 ة 结尾的名词都是阴性。"},{"title":"3. 两种例外","body":"第一种：以 ة 结尾却指男性的词，如 خَلِيفَةٌ（khalīfatun，哈里发、继任者）、عَلَّامَةٌ（ʿallāmatun，大学者），它们是阳性。这类词不多，见到记一下就行。\n第二种：不带 ة 却是阴性的常见词，如 أُمٌّ（ʾummun，母亲）、شَمْسٌ（shamsun，太阳）、يَدٌ（yadun，手）、عَيْنٌ（ʿaynun，眼睛）、نَارٌ（nārun，火）、دَارٌ（dārun，家）、حَرْبٌ（ḥarbun，战争）、أَرْضٌ（ʾarḍun，大地）、رِيحٌ（rīḥun，风）。这些没有标记可看，要单独背。"},{"title":"4. 指示代词：近指与远指","body":"近指「这」：هَذَا（hādhā，阳性单数）、هَذِهِ（hādhihi，阴性单数）、هَؤُلَاءِ（hāʾulāʾi，这些）。\n远指「那」：ذَلِكَ（dhālika，阳性单数）、تِلْكَ（tilka，阴性单数）、أُولَئِكَ（ʾulāʾika，那些）。\n规律：配阳性名词用 هَذَا 和 ذَلِكَ，配阴性名词用 هَذِهِ 和 تِلْكَ；指人时用 هَؤُلَاءِ 和 أُولَئِكَ，不分男女。"},{"title":"5. 指示代词作起语","body":"指示代词本身就能当起语：هَذَا طَالِبٌ（hādhā ṭālibun，这是一名男学生）。它也可以直接修饰后面的名词，这时名词要带 الْ：هَذِهِ الْمَدِينَةُ كَبِيرَةٌ（hādhihi al-madīnatu kabīratun，这座城市很大）。后一种结构里，指示代词和名词一起当起语，谓语形容词要跟名词的阴阳性一致。"},{"title":"6. 常见错误","body":"最常见的错误是指代不一致：说 هَذَا مَدْرَسَةٌ，学校是阴性，应该说 هَذِهِ مَدْرَسَةٌ。第二个错误是形容词不跟着变：هَذِهِ الْمَدِينَةُ كَبِيرٌ 应改成 كَبِيرَةٌ。第三个错误是把 هَؤُلَاءِ 只用于女性，其实它男女通用。"}],"vocab":[{"ar":"طَالِبٌ","rom":"ṭālibun","zh":"学生（男）","a":"bea7c61ac7f5"},{"ar":"طَالِبَةٌ","rom":"ṭālibatun","zh":"学生（女）","a":"f69923af1ab2"},{"ar":"مُعَلِّمٌ","rom":"muʿallimun","zh":"老师（男）","a":"d3c46805be2a"},{"ar":"مُعَلِّمَةٌ","rom":"muʿallimatun","zh":"老师（女）","a":"dccf4a2c8f7c"},{"ar":"مُسْلِمٌ","rom":"muslimun","zh":"穆斯林（男）","a":"0640fde1e376"},{"ar":"مُسْلِمَةٌ","rom":"muslimatun","zh":"穆斯林（女）","a":"e2e29218cb65"},{"ar":"مُهَنْدِسٌ","rom":"muhandisun","zh":"工程师（男）","a":"b2a995823af6"},{"ar":"مُهَنْدِسَةٌ","rom":"muhandisatun","zh":"工程师（女）","a":"9fb2d7ac796c"},{"ar":"طَبِيبٌ","rom":"ṭabībun","zh":"医生（男）","a":"0695f0f3810f"},{"ar":"طَبِيبَةٌ","rom":"ṭabībatun","zh":"医生（女）","a":"a11eb08be38d"},{"ar":"صَدِيقٌ","rom":"ṣadīqun","zh":"朋友（男）","a":"204b61c6d156"},{"ar":"صَدِيقَةٌ","rom":"ṣadīqatun","zh":"朋友（女）","a":"2388f2f63b68"},{"ar":"وَلَدٌ","rom":"waladun","zh":"男孩","a":"ef7a497be3d4"},{"ar":"بِنْتٌ","rom":"bintun","zh":"女孩","a":"db9e49cfe2a2"},{"ar":"رَجُلٌ","rom":"rajulun","zh":"男人","a":"44767a34bc25"},{"ar":"اِمْرَأَةٌ","rom":"imraʾatun","zh":"女人","a":"9615543e5098"},{"ar":"أَبٌ","rom":"abun","zh":"父亲","a":"2c07cb543d73"},{"ar":"أُمٌّ","rom":"ummun","zh":"母亲","a":"33ccd5682798"},{"ar":"أَخٌ","rom":"akhun","zh":"兄弟","a":"ea297f87a8a5"},{"ar":"أُخْتٌ","rom":"ukhtun","zh":"姐妹","a":"2adfcda1c372"},{"ar":"جَدٌّ","rom":"jaddun","zh":"祖父","a":"7d7c9320b882"},{"ar":"جَدَّةٌ","rom":"jaddatun","zh":"祖母","a":"fe582deac1e1"},{"ar":"شَمْسٌ","rom":"shamsun","zh":"太阳","a":"90fac5bf0987"},{"ar":"يَدٌ","rom":"yadun","zh":"手","a":"d5c37467bea0"},{"ar":"عَيْنٌ","rom":"ʿaynun","zh":"眼睛","a":"b07db83c3950"},{"ar":"نَارٌ","rom":"nārun","zh":"火","a":"9316a364dd74"},{"ar":"دَارٌ","rom":"dārun","zh":"家；房子","a":"d88ed34b2e4a"},{"ar":"حَرْبٌ","rom":"ḥarbun","zh":"战争","a":"4624dfb22267"},{"ar":"أَرْضٌ","rom":"arḍun","zh":"大地","a":"16825e86d45a"},{"ar":"رِيحٌ","rom":"rīḥun","zh":"风","a":"a2c9c7ae18c2"},{"ar":"مَدِينَةٌ","rom":"madīnatun","zh":"城市","a":"e91c192a8eaf"},{"ar":"قَرْيَةٌ","rom":"qaryatun","zh":"村庄","a":"55330b89cc77"},{"ar":"غُرْفَةٌ","rom":"ghurfatun","zh":"房间","a":"56cee0873c82"},{"ar":"سَيَّارَةٌ","rom":"sayyāratun","zh":"汽车","a":"e5f13dbd9c85"},{"ar":"حَدِيقَةٌ","rom":"ḥadīqatun","zh":"花园","a":"0b6587e313c8"},{"ar":"بِنَايَةٌ","rom":"bināyatun","zh":"楼房","a":"ff76c338f819"},{"ar":"خَلِيفَةٌ","rom":"khalīfatun","zh":"哈里发；继任者","a":"941800b4fed3"},{"ar":"عَلَّامَةٌ","rom":"ʿallāmatun","zh":"大学者","a":"c92a8156bf07"}],"examples":[{"ar":"هَذَا طَالِبٌ.","rom":"hādhā ṭālibun","zh":"这是一名男学生。","note":"هَذَا + 阳性名词","a":"7988a683546c"},{"ar":"هَذِهِ طَالِبَةٌ.","rom":"hādhihi ṭālibatun","zh":"这是一名女学生。","note":"هَذِهِ + 阴性名词","a":"ed5509fdff2d"},{"ar":"هَذَا مُعَلِّمٌ.","rom":"hādhā muʿallimun","zh":"这位是男老师。","note":"指示代词作起语","a":"c162aa384086"},{"ar":"هَذِهِ مُعَلِّمَةٌ.","rom":"hādhihi muʿallimatun","zh":"这位是女老师。","note":"谓语随名词变阴性","a":"70cf3da2d846"},{"ar":"ذَلِكَ وَلَدٌ.","rom":"dhālika waladun","zh":"那个是男孩。","note":"远指阳性","a":"ee563955c307"},{"ar":"تِلْكَ بِنْتٌ.","rom":"tilka bintun","zh":"那个是女孩。","note":"远指阴性","a":"f685026d7229"},{"ar":"هَذَا رَجُلٌ.","rom":"hādhā rajulun","zh":"这是一个男人。","note":"阳性名词","a":"072e1bc833ee"},{"ar":"هَذِهِ اِمْرَأَةٌ.","rom":"hādhihi imraʾatun","zh":"这是一位女人。","note":"阴性名词","a":"73b8911971d9"},{"ar":"هَذَا طَبِيبٌ.","rom":"hādhā ṭabībun","zh":"这是一位男医生。","note":"阳性名词","a":"f74aa774ed3e"},{"ar":"هَذِهِ طَبِيبَةٌ.","rom":"hādhihi ṭabībatun","zh":"这是一位女医生。","note":"ة 表示阴性","a":"b706af435f35"},{"ar":"هَذَا صَدِيقٌ.","rom":"hādhā ṣadīqun","zh":"这是一位男性朋友。","note":"阳性名词","a":"2278da228424"},{"ar":"هَذِهِ صَدِيقَةٌ.","rom":"hādhihi ṣadīqatun","zh":"这是一位女性朋友。","note":"阴性名词","a":"7d3d2c98ddb9"},{"ar":"هَذِهِ يَدٌ.","rom":"hādhihi yadun","zh":"这是一只手。","note":"يَدٌ 不带 ة 但是阴性","a":"91179c5dfea3"},{"ar":"هَذِهِ دَارٌ.","rom":"hādhihi dārun","zh":"这是一座房子。","note":"دَارٌ 是阴性","a":"f7b5f7924c70"},{"ar":"هَذِهِ نَارٌ.","rom":"hādhihi nārun","zh":"这是一堆火。","note":"نَارٌ 是阴性","a":"5af6a8411bac"},{"ar":"الشَّمْسُ حَارَّةٌ.","rom":"ash-shamsu ḥārratun","zh":"太阳很热。","note":"شَمْسٌ 阴性，谓语用 حَارَّةٌ","a":"b9d4c2fc7f61"},{"ar":"هَؤُلَاءِ طُلَّابٌ.","rom":"hāʾulāʾi ṭullābun","zh":"这些是学生。","note":"هَؤُلَاءِ 指人，复数","a":"70dbde627adb"},{"ar":"هَؤُلَاءِ طَالِبَاتٌ.","rom":"hāʾulāʾi ṭālibātun","zh":"这些是女学生。","note":"复数不分阴阳，都用 هَؤُلَاءِ","a":"0cda7122fd43"},{"ar":"أُولَئِكَ رِجَالٌ.","rom":"ulāʾika rijālun","zh":"那些是男人。","note":"أُولَئِكَ 指远处的人","a":"50f74f89d4e8"},{"ar":"تِلْكَ مَدْرَسَةٌ.","rom":"tilka madrasatun","zh":"那是一所学校。","note":"远指阴性","a":"9632433edf78"},{"ar":"تِلْكَ حَدِيقَةٌ.","rom":"tilka ḥadīqatun","zh":"那是一座花园。","note":"远指阴性","a":"830f43366e8c"},{"ar":"ذَلِكَ كُرْسِيٌّ.","rom":"dhālika kursiyyun","zh":"那是一把椅子。","note":"远指阳性","a":"015f27d5c20b"},{"ar":"هَذِهِ الْمَدِينَةُ كَبِيرَةٌ.","rom":"hādhihi al-madīnatu kabīratun","zh":"这座城市很大。","note":"指示代词 + 确指名词作起语","a":"c9aabd93939c"},{"ar":"هَذَا الْكُرْسِيُّ جَدِيدٌ.","rom":"hādhā al-kursiyyu jadīdun","zh":"这把椅子是新的。","note":"阳性名词配阳性形容词","a":"09d6a9641171"}],"drills":[{"q":"「女学生」怎么说？","a":"طَالِبَةٌ"},{"q":"「男老师」怎么说？","a":"مُعَلِّمٌ"},{"q":"把 طَالِبٌ 变成阴性形式","a":"طَالِبَةٌ"},{"q":"「这」（阳性单数）怎么说？","a":"هَذَا"},{"q":"「这」（阴性单数）怎么说？","a":"هَذِهِ"},{"q":"「那些」怎么说？","a":"أُولَئِكَ"},{"q":"「太阳」是阳性还是阴性？","a":"阴性，شَمْسٌ"},{"q":"「书」是阳性还是阴性？","a":"阳性，كِتَابٌ"},{"q":"「这是一名女学生」怎么说？","a":"هَذِهِ طَالِبَةٌ"},{"q":"「那些是男人」怎么说？","a":"أُولَئِكَ رِجَالٌ"},{"q":"「这座城市很大」怎么说？","a":"هَذِهِ الْمَدِينَةُ كَبِيرَةٌ"}],"tips":["看到 ة 先按阴性处理，除非它指男性。","شَمْسٌ、يَدٌ、عَيْنٌ、نَارٌ、دَارٌ 没有 ة 也是阴性，要单独背。","هَذَا 和 هَذِهِ 的选择看名词阴阳性，不看说话人性别。","هَؤُلَاءِ 和 أُولَئِكَ 只用于人；指物时用 هَذِهِ 和 تِلْكَ。","形容词也要跟着名词变：كَبِيرٌ 配阳性，كَبِيرَةٌ 配阴性。"],"id":"ch2-s2"},{"title":"第九节 确指与泛指：冠词 الْ","concepts":[{"title":"1. 泛指与确指","body":"这一节学完，你能说出一个名词是泛指还是确指，也能按太阳字母、月亮字母把 الْ 读对。阿拉伯语名词按「听话人知不知道指哪个」分成两类：泛指（نَكِرَةٌ，nakiratun）是「某一个、不确定的」；确指（مَعْرِفَةٌ，maʿrifatun）是「特定的那个」。中文靠「一个」「这个」来区分，阿拉伯语靠词尾的鼻音符和词首的 الْ。"},{"title":"2. 泛指靠鼻音符，确指靠 الْ","body":"泛指：词尾带鼻音符 -un（主格），如 كِتَابٌ（kitābun，一本书）。\n确指：加冠词 الْ，鼻音符消失，如 الْكِتَابُ（al-kitābu，这本书）。加 الْ 以后，词尾只剩下普通的短元音 -u（主格），不再是 -un。这是最容易写错的地方。"},{"title":"3. 月亮字母：读 al-","body":"الْ 遇到月亮字母（الْحُرُوفُ الْقَمَرِيَّةُ，al-ḥurūfu al-qamariyyatu）时，ل 正常发音，读 al-。月亮字母有 14 个：ء ب ج ح خ ع غ ف ق ك م ه و ي。\n例：الْكِتَابُ（al-kitābu，这本书）、الْبَيْتُ（al-baytu，这栋房子）、الْقَلَمُ（al-qalamu，这支笔）。"},{"title":"4. 太阳字母：同化，读成叠音","body":"الْ 遇到太阳字母（الْحُرُوفُ الشَّمْسِيَّةُ，al-ḥurūfu ash-shamsiyyatu）时，ل 不发音，后面的字母读成叠音，要标 شَدَّةٌ（shaddatun）。冠词的转写也跟着变，写成 ash-、aṣ-、at- 等。太阳字母 14 个：ت ث د ذ ر ز س ش ص ض ط ظ ل ن。\n例：الشَّمْسُ（ash-shamsu，太阳）、الصَّدِيقُ（aṣ-ṣadīqu，朋友）、الدَّرْسُ（ad-darsu，课）、النَّهْرُ（an-nahru，河）。\n注意：ل 在拼写上仍然写出来，只是不读。"},{"title":"5. 指示代词 + 确指名词","body":"指示代词后面的名词如果带 الْ，就是「这、那 + 特定的东西」：هَذَا الْكِتَابُ（hādhā al-kitābu，这本书）、هَذِهِ الْمَدْرَسَةُ（hādhihi al-madrasatu，这所学校）。这种结构可以单独作起语，后面再接谓语：هَذَا الْكِتَابُ جَدِيدٌ（hādhā al-kitābu jadīdun，这本书是新的）。"},{"title":"6. 常见错误","body":"第一，加了 الْ 还留着鼻音符，写成 الْكِتَابٌ；第二，太阳字母前硬读成 al-，把 الشَّمْسُ 读成 al-shamsu；第三，把 الْ 和名词分开写。记住：الْ 是名词的一部分，永远连写。"}],"vocab":[{"ar":"كِتَابٌ / الْكِتَابُ","rom":"kitābun / al-kitābu","zh":"书","a":"15bbcaa698d2"},{"ar":"بَيْتٌ / الْبَيْتُ","rom":"baytun / al-baytu","zh":"房子","a":"50d06bc96c25"},{"ar":"قَلَمٌ / الْقَلَمُ","rom":"qalamun / al-qalamu","zh":"笔","a":"afdc4ef3e346"},{"ar":"بَابٌ / الْبَابُ","rom":"bābun / al-bābu","zh":"门","a":"51ce06fe6988"},{"ar":"وَلَدٌ / الْوَلَدُ","rom":"waladun / al-waladu","zh":"男孩","a":"6450970c8191"},{"ar":"طَالِبٌ / الطَّالِبُ","rom":"ṭālibun / aṭ-ṭālibu","zh":"学生（男）","a":"83d5e0634bf6"},{"ar":"مُعَلِّمٌ / الْمُعَلِّمُ","rom":"muʿallimun / al-muʿallimu","zh":"老师（男）","a":"efb01e484433"},{"ar":"كُرْسِيٌّ / الْكُرْسِيُّ","rom":"kursiyyun / al-kursiyyu","zh":"椅子","a":"56ead310bc48"},{"ar":"مَكْتَبٌ / الْمَكْتَبُ","rom":"maktabun / al-maktabu","zh":"书桌","a":"1831fbf87a54"},{"ar":"مِفْتَاحٌ / الْمِفْتَاحُ","rom":"miftāḥun / al-miftāḥu","zh":"钥匙","a":"b540b93803bf"},{"ar":"هَاتِفٌ / الْهَاتِفُ","rom":"hātifun / al-hātifu","zh":"电话","a":"7e24110afda9"},{"ar":"دَفْتَرٌ / الدَّفْتَرُ","rom":"daftarun / ad-daftaru","zh":"笔记本","a":"31afb55fd6b7"},{"ar":"شَمْسٌ / الشَّمْسُ","rom":"shamsun / ash-shamsu","zh":"太阳","a":"9d10885a71e7"},{"ar":"بِنْتٌ / الْبِنْتُ","rom":"bintun / al-bintu","zh":"女孩","a":"dc4519067a97"},{"ar":"مَدْرَسَةٌ / الْمَدْرَسَةُ","rom":"madrasatun / al-madrasatu","zh":"学校","a":"78b5ed2c67fe"},{"ar":"سَيَّارَةٌ / السَّيَّارَةُ","rom":"sayyāratun / as-sayyāratu","zh":"汽车","a":"51c8aae4612b"},{"ar":"نَافِذَةٌ / النَّافِذَةُ","rom":"nāfidhatun / an-nāfidhatu","zh":"窗户","a":"1b0d5ddff791"},{"ar":"غُرْفَةٌ / الْغُرْفَةُ","rom":"ghurfatun / al-ghurfatu","zh":"房间","a":"74aa8005a95c"},{"ar":"حَدِيقَةٌ / الْحَدِيقَةُ","rom":"ḥadīqatun / al-ḥadīqatu","zh":"花园","a":"1e7f63c00f22"},{"ar":"مَدِينَةٌ / الْمَدِينَةُ","rom":"madīnatun / al-madīnatu","zh":"城市","a":"28a33c342e39"},{"ar":"طَبِيبٌ / الطَّبِيبُ","rom":"ṭabībun / aṭ-ṭabību","zh":"医生","a":"f7b4f908721e"},{"ar":"صَدِيقٌ / الصَّدِيقُ","rom":"ṣadīqun / aṣ-ṣadīqu","zh":"朋友","a":"97baa62ab38c"},{"ar":"رَجُلٌ / الرَّجُلُ","rom":"rajulun / ar-rajulu","zh":"男人","a":"ff06d58194d6"},{"ar":"زَهْرَةٌ / الزَّهْرَةُ","rom":"zahratun / az-zahratu","zh":"花","a":"b82b8e9757d5"},{"ar":"تَاجِرٌ / التَّاجِرُ","rom":"tājirun / at-tājiru","zh":"商人","a":"2d597ed993fa"},{"ar":"ثَوْبٌ / الثَّوْبُ","rom":"thawbun / ath-thawbu","zh":"衣服","a":"07d53f04bc50"},{"ar":"ذَهَبٌ / الذَّهَبُ","rom":"dhahabun / adh-dhahabu","zh":"金子","a":"e7ca4b21afde"},{"ar":"رَأْسٌ / الرَّأْسُ","rom":"raʾsun / ar-raʾsu","zh":"头","a":"bb4f06371a27"},{"ar":"دَرْسٌ / الدَّرْسُ","rom":"darsun / ad-darsu","zh":"课","a":"5ddc0c57840c"},{"ar":"سُوقٌ / السُّوقُ","rom":"sūqun / as-sūqu","zh":"市场","a":"93897b5e9256"},{"ar":"صَبَاحٌ / الصَّبَاحُ","rom":"ṣabāḥun / aṣ-ṣabāḥu","zh":"早晨","a":"3109252ecf5b"},{"ar":"ضَوْءٌ / الضَّوْءُ","rom":"ḍawʾun / aḍ-ḍawʾu","zh":"光","a":"490d861585b0"},{"ar":"طَالِبَةٌ / الطَّالِبَةُ","rom":"ṭālibatun / aṭ-ṭālibatu","zh":"学生（女）","a":"0dffa03bc9ec"},{"ar":"لَيْلٌ / اللَّيْلُ","rom":"laylun / al-laylu","zh":"夜晚","a":"f2a8cd1eddd8"},{"ar":"نَهْرٌ / النَّهْرُ","rom":"nahrun / an-nahru","zh":"河","a":"03ebfb77a426"},{"ar":"ظِلٌّ / الظِّلُّ","rom":"ẓillun / aẓ-ẓillu","zh":"影子","a":"05aab9eafaee"},{"ar":"يَدٌ / الْيَدُ","rom":"yadun / al-yadu","zh":"手","a":"360a4a651c22"},{"ar":"مَاءٌ / الْمَاءُ","rom":"māʾun / al-māʾu","zh":"水","a":"3b18dae81ac0"},{"ar":"عَيْنٌ / الْعَيْنُ","rom":"ʿaynun / al-ʿaynu","zh":"眼睛","a":"9c4755345c82"},{"ar":"قَهْوَةٌ / الْقَهْوَةُ","rom":"qahwatun / al-qahwatu","zh":"咖啡","a":"f69c6e432aa5"}],"examples":[{"ar":"هَذَا كِتَابٌ.","rom":"hādhā kitābun","zh":"这是一本书。","note":"泛指谓语带鼻音符","a":"63c73a325011"},{"ar":"الْكِتَابُ جَدِيدٌ.","rom":"al-kitābu jadīdun","zh":"这本书是新的。","note":"起语带 الْ 确指","a":"234f3c14dc49"},{"ar":"الْبَيْتُ كَبِيرٌ.","rom":"al-baytu kabīrun","zh":"这栋房子很大。","note":"确指起语 + 泛指谓语","a":"2d4085b6dfa6"},{"ar":"بَيْتٌ كَبِيرٌ.","rom":"baytun kabīrun","zh":"一栋大房子（短语）。","note":"泛指名词 + 形容词，不是句子","a":"688b2b19ed71"},{"ar":"الشَّمْسُ حَارَّةٌ.","rom":"ash-shamsu ḥārratun","zh":"太阳很热。","note":"太阳字母 ش，冠词读 ash-","a":"b9d4c2fc7f61"},{"ar":"الطَّالِبُ مُجْتَهِدٌ.","rom":"aṭ-ṭālibu mujtahidun","zh":"这名男学生很用功。","note":"太阳字母 ط","a":"45d9f98977d4"},{"ar":"الدَّرْسُ سَهْلٌ.","rom":"ad-darsu sahlun","zh":"这一课很容易。","note":"太阳字母 د","a":"b0fedd6953e9"},{"ar":"الْبَابُ مَفْتُوحٌ.","rom":"al-bābu maftūḥun","zh":"门开着。","note":"月亮字母 ب，读 al-","a":"c1303668c61f"},{"ar":"الْمَاءُ بَارِدٌ.","rom":"al-māʾu bāridun","zh":"水是凉的。","note":"月亮字母 م","a":"91d8970b8f91"},{"ar":"الصَّبَاحُ جَمِيلٌ.","rom":"aṣ-ṣabāḥu jamīlun","zh":"早晨很美。","note":"太阳字母 ص","a":"a0b8e9ceb4c7"},{"ar":"اللَّيْلُ طَوِيلٌ.","rom":"al-laylu ṭawīlun","zh":"夜晚很长。","note":"太阳字母 ل，读成叠音","a":"359153d852d9"},{"ar":"النَّهْرُ وَاسِعٌ.","rom":"an-nahru wāsiʿun","zh":"这条河很宽。","note":"太阳字母 ن","a":"b938d90f7ed8"},{"ar":"الظِّلُّ بَارِدٌ.","rom":"aẓ-ẓillu bāridun","zh":"阴凉处很凉。","note":"太阳字母 ظ","a":"8af13fa56d8f"},{"ar":"الثَّوْبُ نَظِيفٌ.","rom":"ath-thawbu naẓīfun","zh":"这件衣服很干净。","note":"太阳字母 ث","a":"efe0e46a769c"},{"ar":"الذَّهَبُ ثَقِيلٌ.","rom":"adh-dhahabu thaqīlun","zh":"金子很重。","note":"太阳字母 ذ","a":"c9963cd0e74e"},{"ar":"الضَّوْءُ قَوِيٌّ.","rom":"aḍ-ḍawʾu qawiyyun","zh":"光很强。","note":"太阳字母 ض","a":"eaa426eb0efb"},{"ar":"الرَّجُلُ طَبِيبٌ.","rom":"ar-rajulu ṭabībun","zh":"这个男人是医生。","note":"太阳字母 ر","a":"fd0f24543190"},{"ar":"الطَّالِبَةُ مُجْتَهِدَةٌ.","rom":"aṭ-ṭālibatu mujtahidatun","zh":"这名女学生很用功。","note":"阴性谓语","a":"7a2fc405b8de"},{"ar":"السَّيَّارَةُ جَدِيدَةٌ.","rom":"as-sayyāratu jadīdatun","zh":"这辆汽车是新的。","note":"太阳字母 س","a":"d564b3775f93"},{"ar":"النَّافِذَةُ مَفْتُوحَةٌ.","rom":"an-nāfidhatu maftūḥatun","zh":"窗户开着。","note":"太阳字母 ن","a":"8a651af7dd0e"},{"ar":"الْقَهْوَةُ سَاخِنَةٌ.","rom":"al-qahwatu sākhinatun","zh":"咖啡是热的。","note":"月亮字母 ق","a":"89a1795fd70f"},{"ar":"هَذَا الْكِتَابُ.","rom":"hādhā al-kitābu","zh":"这本书（短语）。","note":"指示代词 + 确指名词","a":"16c62fada8cd"},{"ar":"هَذِهِ الْمَدْرَسَةُ.","rom":"hādhihi al-madrasatu","zh":"这所学校（短语）。","note":"指示代词 + 确指名词","a":"f32484c6dda8"},{"ar":"هَذَا الْكِتَابُ جَدِيدٌ.","rom":"hādhā al-kitābu jadīdun","zh":"这本书是新的。","note":"指示代词 + 确指名词作起语","a":"87ee23579c8a"},{"ar":"ذَلِكَ الرَّجُلُ طَبِيبٌ.","rom":"dhālika ar-rajulu ṭabībun","zh":"那个男人是医生。","note":"远指 + 确指名词","a":"857007f3b7bb"}],"drills":[{"q":"كِتَابٌ 的确指形式是什么？","a":"الْكِتَابُ"},{"q":"شَمْسٌ 的确指形式是什么？","a":"الشَّمْسُ"},{"q":"بَيْتٌ 的确指形式是什么？","a":"الْبَيْتُ"},{"q":"نَافِذَةٌ 的确指形式是什么？","a":"النَّافِذَةُ"},{"q":"الْ 遇到太阳字母怎么读？","a":"同化，ل 不发音，后面的字母读叠音"},{"q":"举出 5 个太阳字母","a":"ت ث د ذ ر（任意 5 个即可）"},{"q":"举出 5 个月亮字母","a":"ب ج ح خ ع（任意 5 个即可）"},{"q":"الشَّمْسُ 里的 ل 要读出来吗？","a":"不读，ل 只写不读"},{"q":"「这本书」怎么说？","a":"هَذَا الْكِتَابُ"},{"q":"「这所学校」怎么说？","a":"هَذِهِ الْمَدْرَسَةُ"},{"q":"泛指名词靠什么标记？","a":"鼻音符 -un / -an / -in"}],"tips":["الْ 的 ا 是连接 Hamza（هَمْزَةُ الْوَصْلِ，hamzatu al-waṣli），前面有元音时连读不发音；本课表格一律按停顿读法标 al-。","太阳字母前，ل 只写不读，后面那个字母要加 شَدَّةٌ（shaddatun）。","加了 الْ 就没有鼻音符：كِتَابٌ 变成 الْكِتَابُ，不是 الْكِتَابٌ。","الْ 永远和名词连写，中间不能断开。","28 个字母里正好 14 个太阳字母、14 个月亮字母，把太阳字母表背熟，看到词就能读准。"],"id":"ch2-s3"},{"title":"第十节 人称代词与所有格后缀","concepts":[{"title":"1. 这一节学完你能做什么","body":"学完这一节，你能说出「我是学生」「他是老师」这样的句子，也能把「我的书」「你的家」「他的名字」这类「某人的某物」说清楚。这两件事看起来不一样，其实靠的是同一套东西：人称代词。阿拉伯语的人称代词有两种样子，一种能单独站着，叫独立人称代词；一种只能粘在别的词后面，叫代词后缀。"},{"title":"2. 独立人称代词一共 12 个","body":"阿拉伯语的人称除了单数、复数，还有「双数」——正好两个人。汉语和英语都没有双数，这是第一个要适应的点。\n单数五个：أَنَا（anā，我）、أَنْتَ（anta，你，男）、أَنْتِ（anti，你，女）、هُوَ（huwa，他）、هِيَ（hiya，她）。\n双数两个：أَنْتُمَا（antumā，你们俩）、هُمَا（humā，他俩、她俩）。\n复数五个：نَحْنُ（naḥnu，我们）、أَنْتُمْ（antum，你们，男）、أَنْتُنَّ（antunna，你们，女）、هُمْ（hum，他们）、هُنَّ（hunna，她们）。\n背的时候按「我—你—他」竖着成组记，比横着念一遍有效：أَنَا / أَنْتَ / هُوَ 是一组，نَحْنُ / أَنْتُمْ / هُمْ 是同一组的复数，剩下的只是在阳性和阴性之间换尾巴。"},{"title":"3. 代词放在起语的位置","body":"名词句是「起语 + 谓语」，中间不加「是」。把代词放在起语的位置，就成了「我是…」「他是…」：أَنَا طَالِبٌ（anā ṭālibun，我是学生）、هُوَ مُعَلِّمٌ（huwa muʿallimun，他是老师）。\n谓语照样要带鼻音符 -un，这一点和上一节完全一样，不能因为前面是代词就省掉。另外要提醒一句：阿拉伯语的动词句里主语常常省掉（动词本身就告诉你是谁），但名词句里的代词起语一般要写出来，因为 هُوَ 和 هِيَ 只差一个字母，省了就分不清说的是男是女。"},{"title":"4. 所有格后缀：把「我的」粘在名词后面","body":"汉语说「我的书」，是两个词；阿拉伯语不用独立的「我的」，而是把「我的」压成一个后缀，直接粘在名词尾巴上：كِتَابٌ（kitābun，书）→ كِتَابِي（kitābī，我的书）。\n12 个后缀和 12 个独立代词一一对应。单数：ـِي（-ī，我的）、ـكَ（-ka，你的，男）、ـكِ（-ki，你的，女）、ـهُ（-hu，他的）、ـهَا（-hā，她的）。双数：ـكُمَا（-kumā，你们俩的）、ـهُمَا（-humā，他俩的）。复数：ـنَا（-nā，我们的）、ـكُمْ（-kum，你们的，男）、ـكُنَّ（-kunna，你们的，女）、ـهُمْ（-hum，他们的）、ـهُنَّ（-hunna，她们的）。\n后缀不能单独成词，写的时候要紧贴前面的名词，中间不能空格。比如「你的书」是 كِتَابُكَ 一个词，不能断开写成 كِتَابُ كَ。"},{"title":"5. 加了后缀，鼻音符就消失","body":"كِتَابٌ 读 kitābun，加上「我的」以后写成 كِتَابِي，读 kitābī，不是 kitābunī。道理不复杂：-n 这个鼻音是「泛指」的标志，表示「随便一本书、某一本书」，而「我的书」已经确指了，自然不需要再标泛指。\n要小心的是词尾的格元音还在：كِتَابُهُ 读 kitābuhu，中间那个是 -u-，不能写成 كِتَابَهُ。名词在起语位置上是主格 -u，加了后缀仍然保持 -u。\n还有一个变化要记住：以 ة 结尾的名词，接了后缀要把 ة 写成 ت，مَدْرَسَةٌ（madrasatun，学校）变成 مَدْرَسَتِي（madrasatī，我的学校）。"},{"title":"6. 介词后面也用同一套后缀","body":"介词不能单独跟人称，也得靠后缀：مَعَ（maʿa，和…一起）→ مَعِي（maʿī，和我一起）；عِنْدَ（ʿinda，在…那里）→ عِنْدِي（ʿindī，我这儿有）；لِـ（li-，属于）→ لِي（lī，我的）；بِـ（bi-，用、凭）→ بِي（bī，用我、凭我）。\n这几个组合出现频率极高。عِنْدِي كِتَابٌ（ʿindī kitābun）字面是「我这儿有一本书」，意思就是「我有一本书」；هَذَا الْكِتَابُ لِي（hādhā al-kitābu lī）字面是「这本书属于我」，意思就是「这本书是我的」。"}],"vocab":[{"ar":"أَنَا","rom":"anā","zh":"我","a":"77317e275347"},{"ar":"أَنْتَ","rom":"anta","zh":"你（男）","a":"3165396e2054"},{"ar":"أَنْتِ","rom":"anti","zh":"你（女）","a":"89bf7482e69b"},{"ar":"هُوَ","rom":"huwa","zh":"他","a":"f080a220a33d"},{"ar":"هِيَ","rom":"hiya","zh":"她","a":"662ee0fd3425"},{"ar":"أَنْتُمَا","rom":"antumā","zh":"你们俩","a":"d839a3355963"},{"ar":"هُمَا","rom":"humā","zh":"他俩、她俩","a":"15c0d5539d73"},{"ar":"نَحْنُ","rom":"naḥnu","zh":"我们","a":"11205f9e7353"},{"ar":"أَنْتُمْ","rom":"antum","zh":"你们（男）","a":"dd0df8586969"},{"ar":"أَنْتُنَّ","rom":"antunna","zh":"你们（女）","a":"5eb2c4d3af32"},{"ar":"هُمْ","rom":"hum","zh":"他们","a":"a33f0f61e805"},{"ar":"هُنَّ","rom":"hunna","zh":"她们","a":"b497d106488e"},{"ar":"كِتَابٌ","rom":"kitābun","zh":"书","a":"edbacf7ab47c"},{"ar":"كِتَابِي","rom":"kitābī","zh":"我的书","a":"6d8efa6270a2"},{"ar":"كِتَابُكَ","rom":"kitābuka","zh":"你的书（男）","a":"319244ccb1d6"},{"ar":"كِتَابُكِ","rom":"kitābuki","zh":"你的书（女）","a":"4ac5fbee477b"},{"ar":"كِتَابُهُ","rom":"kitābuhu","zh":"他的书","a":"c0d097c2fb62"},{"ar":"كِتَابُهَا","rom":"kitābuhā","zh":"她的书","a":"ec1df221888b"},{"ar":"كِتَابُنَا","rom":"kitābunā","zh":"我们的书","a":"88de85487df4"},{"ar":"كِتَابُكُمْ","rom":"kitābukum","zh":"你们的书（男）","a":"213b68754947"},{"ar":"كِتَابُهُمْ","rom":"kitābuhum","zh":"他们的书","a":"1c44ad3ee968"},{"ar":"بَيْتِي","rom":"baytī","zh":"我的家","a":"907afe814edb"},{"ar":"مَدْرَسَتِي","rom":"madrasatī","zh":"我的学校","a":"03c63f57c358"},{"ar":"أُخْتِي","rom":"ukhtī","zh":"我的姐妹","a":"5180eea28122"},{"ar":"صَدِيقِي","rom":"ṣadīqī","zh":"我的朋友（男）","a":"c0320fe5b57e"},{"ar":"مَعِي","rom":"maʿī","zh":"和我一起","a":"04f3384e2485"},{"ar":"عِنْدِي","rom":"ʿindī","zh":"我这儿有、我有","a":"02d2dd403278"},{"ar":"لِي","rom":"lī","zh":"我的、属于我的","a":"ac9970b05c68"},{"ar":"بِي","rom":"bī","zh":"用我、凭我","a":"d0adcb8baad4"},{"ar":"مَعَكَ","rom":"maʿaka","zh":"和你一起（男）","a":"9cff21d56082"},{"ar":"عِنْدَهُ","rom":"ʿindahu","zh":"他这儿有","a":"cd63918bd8e8"},{"ar":"لَنَا","rom":"lanā","zh":"我们的","a":"5ead46960985"}],"examples":[{"ar":"أَنَا طَالِبٌ.","rom":"anā ṭālibun","zh":"我是学生。","note":"代词作起语，谓语带鼻音符","a":"089a5f92b79f"},{"ar":"أَنْتَ طَالِبٌ.","rom":"anta ṭālibun","zh":"你是学生。","note":"أَنْتَ 指男性","a":"0c7a1effbb20"},{"ar":"أَنْتِ طَالِبَةٌ.","rom":"anti ṭālibatun","zh":"你是学生。（对女性说）","note":"阴性谓语加 ة","a":"bb16bc0f39c2"},{"ar":"هُوَ مُعَلِّمٌ.","rom":"huwa muʿallimun","zh":"他是老师。","note":"هُوَ 指男性","a":"89104c38dde0"},{"ar":"هِيَ مُعَلِّمَةٌ.","rom":"hiya muʿallimatun","zh":"她是老师。","note":"هِيَ 指女性","a":"e8dbb992007c"},{"ar":"نَحْنُ طُلَّابٌ.","rom":"naḥnu ṭullābun","zh":"我们是学生。","note":"طُلَّاب 是 طَالِب 的复数","a":"bc8601a448c9"},{"ar":"هُمْ طُلَّابٌ.","rom":"hum ṭullābun","zh":"他们是学生。","note":"هُمْ 指三人以上男性","a":"fb1d7b7c6929"},{"ar":"هُنَّ طَالِبَاتٌ.","rom":"hunna ṭālibātun","zh":"她们是学生。","note":"阴性复数词尾 ـَات","a":"0e4ce0d6a87c"},{"ar":"أَنْتُمْ مُعَلِّمُونَ.","rom":"antum muʿallimūna","zh":"你们是老师。","note":"阳性复数谓语用 ـُونَ","a":"08ded314e985"},{"ar":"هُمَا طَالِبَانِ.","rom":"humā ṭālibāni","zh":"他俩是学生。","note":"双数谓语用 ـَانِ","a":"287f8aeed016"},{"ar":"هَذَا كِتَابِي.","rom":"hādhā kitābī","zh":"这是我的书。","note":"带后缀后不再有鼻音符","a":"5f83156c0683"},{"ar":"هَذَا كِتَابُكَ.","rom":"hādhā kitābuka","zh":"这是你的书。","note":"ـكَ 紧贴名词","a":"73c13cb19bc6"},{"ar":"هَذَا كِتَابُهُ.","rom":"hādhā kitābuhu","zh":"这是他的书。","note":"词尾保持主格 -u","a":"8a6418fa1ee1"},{"ar":"هَذِهِ مَدْرَسَتِي.","rom":"hādhihi madrasatī","zh":"这是我的学校。","note":"ة 接后缀要写成 ت","a":"6c672fdc5687"},{"ar":"هَذَا بَيْتُنَا.","rom":"hādhā baytunā","zh":"这是我们的家。","note":"ـنَا 表示我们的","a":"ea37a4c82b13"},{"ar":"كِتَابِي جَدِيدٌ.","rom":"kitābī jadīdun","zh":"我的书是新的。","note":"带后缀的名词作起语","a":"19533d44dcfe"},{"ar":"بَيْتُهُمْ كَبِيرٌ.","rom":"baytuhum kabīrun","zh":"他们的家很大。","note":"ـهُمْ 表示他们的","a":"8ba41470007a"},{"ar":"أُخْتِي طَالِبَةٌ.","rom":"ukhtī ṭālibatun","zh":"我姐妹是学生。","note":"أُخْت 加 ـِي","a":"bc5c1ec0c30f"},{"ar":"صَدِيقُهُ مُعَلِّمٌ.","rom":"ṣadīquhu muʿallimun","zh":"他的朋友是老师。","note":"صَدِيق 加 ـهُ","a":"61075198d4c5"},{"ar":"عِنْدِي كِتَابٌ.","rom":"ʿindī kitābun","zh":"我有一本书。","note":"عِنْدِي 表示我这儿有","a":"0e3d7c59b01a"},{"ar":"عِنْدَهُ بَيْتٌ.","rom":"ʿindahu baytun","zh":"他有一栋房子。","note":"عِنْدَ 加 ـهُ","a":"2e01f7d895dc"},{"ar":"مَعِي صَدِيقِي.","rom":"maʿī ṣadīqī","zh":"我的朋友和我在一起。","note":"مَعِي 表示和我一起","a":"507ff3a2caf4"},{"ar":"هَذَا الْكِتَابُ لِي.","rom":"hādhā al-kitābu lī","zh":"这本书是我的。","note":"لِي 表示属于我","a":"b4879873f8c7"},{"ar":"نَحْنُ فِي الْبَيْتِ.","rom":"naḥnu fī al-bayti","zh":"我们在家里。","note":"فِي 后面名词用属格","a":"f1c6bf65d260"}],"drills":[{"q":"「我」用阿拉伯语怎么说？","a":"أَنَا"},{"q":"「你（女）」用阿拉伯语怎么说？","a":"أَنْتِ"},{"q":"「他们」用阿拉伯语怎么说？","a":"هُمْ"},{"q":"「我的书」怎么写？","a":"كِتَابِي"},{"q":"「他的书」怎么写？","a":"كِتَابُهُ"},{"q":"كِتَابٌ 加上「我们的」后缀怎么写？","a":"كِتَابُنَا"},{"q":"「我有一本书」怎么说？","a":"عِنْدِي كِتَابٌ"},{"q":"「她是老师」怎么说？","a":"هِيَ مُعَلِّمَةٌ"},{"q":"「和我一起」怎么说？","a":"مَعِي"},{"q":"مَدْرَسَةٌ 接 ـِي 之后，ة 要写成什么？","a":"ت，写成 مَدْرَسَتِي"}],"tips":["双数是阿拉伯语的「第三个数」，汉语里没有，看到 ـَانِ 或 ـَيْنِ 就是「两个」。","代词后缀不能单独成词，必须紧贴名词或介词，中间不能空格。","加了后缀就没有鼻音符：كِتَابٌ（kitābun）要变成 كِتَابِي（kitābī），不能读成 kitābunī。","名词带后缀时词尾仍是 -u（主格），别写成 كِتَابَهُ。","ة 接后缀一律写成 ت：مَدْرَسَةٌ 变 مَدْرَسَتِي，读音也跟着从 -tun 变成 -tī。"],"id":"ch2-s4"},{"title":"第十一节 疑问句与疑问词","concepts":[{"title":"1. 这一节学完你能做什么","body":"学完这一节，你能用阿拉伯语问「你是学生吗」「这是什么」「书在哪儿」「你从哪儿来」，也能听懂别人用疑问词问你的问题。阿拉伯语的疑问句比汉语还简单：句子本身一个词都不用改，只要在句首加一个疑问词或疑问助词，句末换个问号就行。"},{"title":"2. 一般疑问句：句首加 هَلْ","body":"汉语用「吗」，阿拉伯语用疑问助词 هَلْ（hal，吗），放在句子最前面，句末用阿拉伯语的问号 ؟。\nأَنْتَ طَالِبٌ（anta ṭālibun，你是学生）加上 هَلْ，就成了 هَلْ أَنْتَ طَالِبٌ؟（hal anta ṭālibun，你是学生吗）。只加了一个词，语序、词尾、标音全都不动，这一点比英语省事得多。\n回答用 نَعَمْ（naʿam，是、对）或者 لَا（lā，不、不是）。要完整回答也可以重复一遍：نَعَمْ، أَنَا طَالِبٌ（naʿam, anā ṭālibun，是的，我是学生）。"},{"title":"3. 否定疑问：أَلَيْسَ","body":"把否定词 لَيْسَ（laysa，不是）前面加一个 أَ，就成了「难道不…吗」：أَلَيْسَ هَذَا كِتَابًا؟（alaysa hādhā kitāban，这不是一本书吗）。\n这里有个坑要特别注意：لَيْسَ 后面的谓语要用宾格，也就是读 -an，写成 كِتَابًا，不能写成 كِتَابٌ。لَيْسَ 是少数几个「让后面的词变宾格」的词，先记住这个搭配就行。\nأَلَيْسَ 还会跟着人称变：对「你（男）」说就是 أَلَسْتَ（alasta，你难道不…），例如 أَلَسْتَ طَالِبًا؟（alasta ṭāliban，你难道不是学生吗）。\n还有一个 أَلَا（alā，难道不），语气更书面，多用于反问，后面常接动词句，本节先认得它的意思就可以，动词句在下一章细讲。"},{"title":"4. 八个疑问词，各管一类问题","body":"问东西用 مَا（mā，什么），问人用 مَنْ（man，谁），问地方用 أَيْنَ（ayna，哪里），问状态用 كَيْفَ（kayfa，怎么样），问时间用 مَتَى（matā，什么时候），问原因用 لِمَاذَا（limādhā，为什么），问数量用 كَمْ（kam，多少），问「哪一个」用 أَيُّ（ayyu，哪个）。\n另外两个是「介词 + 疑问词」的组合：مِنْ أَيْنَ（min ayna，从哪里）和 إِلَى أَيْنَ（ilā ayna，到哪里）。它们写出来是两个词，中间有空格，别连成一个词。"},{"title":"5. 疑问词必须站在句首","body":"这是和汉语最大的不同。汉语可以把疑问词留在它原来的位置（「书在哪儿？」「你在哪儿？」），阿拉伯语不行，疑问词一律提到最前面：أَيْنَ الْكِتَابُ؟（ayna al-kitābu，书在哪儿）。不能说 الْكِتَابُ أَيْنَ。\n语序是「疑问词（谓语）+ 起语」：أَيْنَ 本身就是谓语（问「在哪里」），الْكِتَابُ 是起语。所以这句话里没有别的谓语，也不用加「是」。\n再体会一组对比：مَنْ أَنْتَ؟（man anta，你是谁）里，مَنْ 是谓语，أَنْتَ 是起语；汉语说「你是谁」，语序碰巧一样，但问地点、问时间的时候就不一样了，所以从一开始就养成「疑问词放最前」的习惯。"},{"title":"6. 三个高频固定问法","body":"كَيْفَ حَالُكَ؟（kayfa ḥāluka，你好吗）直译是「你的状况怎么样」，حَال 是「状况」，ـكَ 是「你的」，正好用上上一节的后缀。\nكَمْ عُمْرُكَ؟（kam ʿumruka，你多大了）直译是「你的年龄多少」。\nكَمْ كِتَابًا عِنْدَكَ؟（kam kitāban ʿindaka，你有几本书）注意 كَمْ 后面的名词要用宾格单数，读 -an，所以是 كِتَابًا，不是复数 كُتُبٌ。"}],"vocab":[{"ar":"مَا","rom":"mā","zh":"什么","a":"cf093c097b3b"},{"ar":"مَنْ","rom":"man","zh":"谁","a":"2348694c3c16"},{"ar":"أَيْنَ","rom":"ayna","zh":"哪里","a":"cfcbb8a7574d"},{"ar":"كَيْفَ","rom":"kayfa","zh":"怎么样","a":"602fa47d0e96"},{"ar":"مَتَى","rom":"matā","zh":"什么时候","a":"c7d7cb8280b6"},{"ar":"لِمَاذَا","rom":"limādhā","zh":"为什么","a":"b73af4897847"},{"ar":"كَمْ","rom":"kam","zh":"多少","a":"8da01b1313b1"},{"ar":"أَيُّ","rom":"ayyu","zh":"哪个","a":"4766c308ff34"},{"ar":"مِنْ أَيْنَ","rom":"min ayna","zh":"从哪里","a":"ef1e65ac8419"},{"ar":"إِلَى أَيْنَ","rom":"ilā ayna","zh":"到哪里","a":"cff4eb13ebf0"},{"ar":"هَلْ","rom":"hal","zh":"吗（疑问助词）","a":"41f596368e3d"},{"ar":"أَلَيْسَ","rom":"alaysa","zh":"难道不…吗","a":"1fe9376f4a6b"},{"ar":"أَلَسْتَ","rom":"alasta","zh":"你难道不…吗（对男性）","a":"92ae97ffa9b1"},{"ar":"لَيْسَ","rom":"laysa","zh":"不是","a":"855fa25c17aa"},{"ar":"أَلَا","rom":"alā","zh":"难道不（反问语气）","a":"f5cdf37ad656"},{"ar":"نَعَمْ","rom":"naʿam","zh":"是、对","a":"f7443118d6d8"},{"ar":"لَا","rom":"lā","zh":"不、不是","a":"2e27e0c97265"},{"ar":"هُنَا","rom":"hunā","zh":"这里","a":"cc7d2511fa46"},{"ar":"هُنَاكَ","rom":"hunāka","zh":"那里","a":"cd7d7405d0d7"},{"ar":"بَابٌ","rom":"bābun","zh":"门","a":"b7831c1d1303"},{"ar":"مِفْتَاحٌ","rom":"miftāḥun","zh":"钥匙","a":"deb53ab6c662"},{"ar":"قَلَمٌ","rom":"qalamun","zh":"笔","a":"c5cd3bad9c06"},{"ar":"حَالٌ","rom":"ḥālun","zh":"状况","a":"6d9c2b6affc3"},{"ar":"عُمْرٌ","rom":"ʿumrun","zh":"年龄","a":"212bba69c990"},{"ar":"يَوْمٌ","rom":"yawmun","zh":"天、日子","a":"031c241145e1"},{"ar":"طَقْسٌ","rom":"ṭaqsun","zh":"天气","a":"e8803934f337"},{"ar":"مَطَارٌ","rom":"maṭārun","zh":"机场","a":"242b2c06b41b"},{"ar":"قِطَارٌ","rom":"qiṭārun","zh":"火车","a":"be6cf6f81e72"},{"ar":"صَدِيقٌ","rom":"ṣadīqun","zh":"朋友（男）","a":"204b61c6d156"},{"ar":"مَدِينَةٌ","rom":"madīnatun","zh":"城市","a":"e91c192a8eaf"}],"examples":[{"ar":"مَا هَذَا؟","rom":"mā hādhā","zh":"这是什么？","note":"مَا 问事物，放句首","a":"c99a592a6664"},{"ar":"مَنْ أَنْتَ؟","rom":"man anta","zh":"你是谁？","note":"مَنْ 问人","a":"12d2ed7a07d8"},{"ar":"أَيْنَ أَنْتَ؟","rom":"ayna anta","zh":"你在哪儿？","note":"疑问词 + 代词起语","a":"33d20204c7a1"},{"ar":"هَلْ أَنْتَ طَالِبٌ؟","rom":"hal anta ṭālibun","zh":"你是学生吗？","note":"هَلْ 加句首，语序不变","a":"72ff8474d360"},{"ar":"هَلْ هُوَ مُعَلِّمٌ؟","rom":"hal huwa muʿallimun","zh":"他是老师吗？","note":"代词起语照常","a":"21c36f741c70"},{"ar":"هَلْ هَذَا كِتَابٌ؟","rom":"hal hādhā kitābun","zh":"这是一本书吗？","note":"هَلْ 只管疑问，不改词尾","a":"e3d9080a5d12"},{"ar":"أَيْنَ الْكِتَابُ؟","rom":"ayna al-kitābu","zh":"书在哪儿？","note":"疑问词必须在句首","a":"229da59560f8"},{"ar":"مَنْ هَذَا؟","rom":"man hādhā","zh":"这是谁？","note":"مَنْ 作谓语","a":"04a530a11be4"},{"ar":"كَيْفَ حَالُكَ؟","rom":"kayfa ḥāluka","zh":"你好吗？","note":"固定问候，حَال 加 ـكَ","a":"0605021321aa"},{"ar":"مَتَى الدَّرْسُ؟","rom":"matā ad-darsu","zh":"什么时候上课？","note":"مَتَى 问时间","a":"f05eb72d2bcf"},{"ar":"مَتَى السَّفَرُ؟","rom":"matā as-safaru","zh":"什么时候出发？","note":"冠词遇到太阳字母同化为 as-","a":"1d16d08bc4e9"},{"ar":"لِمَاذَا هُوَ هُنَاكَ؟","rom":"limādhā huwa hunāka","zh":"他为什么在那儿？","note":"لِمَاذَا 问原因","a":"945b8abdc25f"},{"ar":"كَمْ عُمْرُكَ؟","rom":"kam ʿumruka","zh":"你多大了？","note":"كَمْ 加正偏组合","a":"c99a9d282fa1"},{"ar":"أَيُّ كِتَابٍ هَذَا؟","rom":"ayyu kitābin hādhā","zh":"这是哪本书？","note":"أَيُّ 后面的名词用属格 -in","a":"88a4868cac3a"},{"ar":"هَلْ عِنْدَكَ قَلَمٌ؟","rom":"hal ʿindaka qalamun","zh":"你有笔吗？","note":"هَلْ 加介词短语谓语","a":"3897b04f8e9c"},{"ar":"مَا لَوْنُ الْبَابِ؟","rom":"mā lawnu al-bābi","zh":"门是什么颜色的？","note":"مَا 加正偏组合","a":"a966a8b2c3fc"},{"ar":"كَيْفَ الطَّقْسُ الْيَوْمَ؟","rom":"kayfa aṭ-ṭaqsu al-yawma","zh":"今天天气怎么样？","note":"冠词遇到太阳字母同化为 aṭ-","a":"92c578b281b7"},{"ar":"مِنْ أَيْنَ أَنْتَ؟","rom":"min ayna anta","zh":"你是哪儿人？","note":"介词 + 疑问词，两个词","a":"ad82da916da2"},{"ar":"إِلَى أَيْنَ الْقِطَارُ؟","rom":"ilā ayna al-qiṭāru","zh":"这列火车开往哪里？","note":"إِلَى 加疑问词 أَيْنَ","a":"d69b5ca87e85"},{"ar":"أَلَيْسَ هَذَا كِتَابًا؟","rom":"alaysa hādhā kitāban","zh":"这不是一本书吗？","note":"لَيْسَ 后面谓语用宾格 -an","a":"3582c580cdb4"},{"ar":"أَلَسْتَ طَالِبًا؟","rom":"alasta ṭāliban","zh":"你难道不是学生吗？","note":"أَلَيْسَ 随人称变成 أَلَسْتَ","a":"732b24f80125"},{"ar":"كَمْ كِتَابًا عِنْدَكَ؟","rom":"kam kitāban ʿindaka","zh":"你有几本书？","note":"كَمْ 后面用宾格单数","a":"f26e543b8f7d"},{"ar":"أَيُّ مَدِينَةٍ هَذِهِ؟","rom":"ayyu madīnatin hādhihi","zh":"这是哪座城市？","note":"阴性用 هَذِهِ","a":"4bc59490ac43"},{"ar":"مِنْ أَيْنَ هَذَا؟","rom":"min ayna hādhā","zh":"这是从哪儿来的？","note":"مِنْ أَيْنَ 问来源","a":"e342be489b13"},{"ar":"إِلَى أَيْنَ أَنْتَ ذَاهِبٌ؟","rom":"ilā ayna anta dhāhibun","zh":"你要去哪儿？","note":"ذَاهِبٌ 是主动分词，作谓语","a":"fdf845f07032"},{"ar":"لِمَاذَا أَنْتَ هُنَا؟","rom":"limādhā anta hunā","zh":"你为什么在这儿？","note":"疑问词 + 起语 + 谓语","a":"4f6990bd6ae1"}],"drills":[{"q":"「你是学生吗？」怎么说？","a":"هَلْ أَنْتَ طَالِبٌ؟"},{"q":"「这是什么？」怎么说？","a":"مَا هَذَا؟"},{"q":"「书在哪儿？」怎么说？","a":"أَيْنَ الْكِتَابُ؟"},{"q":"「谁」用阿拉伯语怎么说？","a":"مَنْ"},{"q":"「什么时候」用阿拉伯语怎么说？","a":"مَتَى"},{"q":"「为什么」用阿拉伯语怎么说？","a":"لِمَاذَا"},{"q":"「你有几本书？」怎么说？","a":"كَمْ كِتَابًا عِنْدَكَ؟"},{"q":"「你是哪儿人？」怎么说？","a":"مِنْ أَيْنَ أَنْتَ؟"},{"q":"肯定回答「是、对」用哪个词？","a":"نَعَمْ"},{"q":"疑问词在阿拉伯语句子里必须放在什么位置？","a":"句首"}],"tips":["疑问词一律放句首，不能像汉语那样留在原来的位置。","هَلْ 只负责「吗」，加了它语序一个词都不用动。","阿拉伯语问号是 ؟，不是半角的 ?。","كَمْ 后面的名词用宾格单数（كِتَابًا），不要用复数。","لَيْسَ 后面的谓语要读 -an（كِتَابًا），别写成 كِتَابٌ。"],"id":"ch2-s5"}],"id":"ch2"},{"title":"第三章 格、介词与正偏组合","sections":[{"title":"第十二节 三个格与三种鼻音符","concepts":[{"title":"1. 这一节学完你能做什么","body":"学完这一节，你能说出「这本书是新的」「我读了这本书」「我在学校里」这三类句子，并且知道每个名词的词尾为什么长成那个样子。前面几节你已经反复见过 -un 这个小尾巴，这一节把它背后的整套系统讲清楚：阿拉伯语的名词有三个格，格只体现在词尾那一个短元音上。\n这是全书第一个真正「汉语里没有」的语法点。它不是背单词能解决的问题，得靠理解句子成分的位置来判断。好消息是：规则只有三条，而且判断的时候看的是「这个词在句子里干什么」，不是看它前面是什么词。"},{"title":"2. 汉语的名词不变，阿拉伯语的名词会变","body":"汉语的名词没有格。不管「书」在句子里担任什么角色，「书」这个字永远不变：书是新的、我读了书、在书里，三个「书」一模一样。阿拉伯语不行，同一个名词在句子里担任不同的角色，词尾要换一个短元音。\n三个格各有名字：رَفْعٌ（rafʿun，主格）、نَصْبٌ（naṣbun，宾格）、جَرٌّ（jarrun，属格）。名字先记不住没关系，先记住它们的「长相」：主格收 -u，宾格收 -a，属格收 -i。\n格不是靠加词、换词序来表达的，只靠词尾一个符号。所以阿拉伯语的书面上，这个小符号是必须写出来的，漏了就等于没说清楚这个名词在句子里干什么。"},{"title":"3. 格怎么写出来：短元音与鼻音符","body":"带 الْ 的确指名词只用三个短元音收尾：-u 是主格，-a 是宾格，-i 是属格。看 الْكِتَابُ（al-kitābu，这本书）、الْكِتَابَ（al-kitāba，这本书，宾格）、الْكِتَابِ（al-kitābi，这本书，属格）：三个词的字母完全一样，只有最后那个符号不同。\n泛指名词（不带 الْ，表示「某一个、随便一个」的）要在这三个短元音后面再加一个 -n。这个 -n 写出来就是鼻音符，阿拉伯语叫 تَنْوِينٌ（tanwīnun，鼻音符）：-un 写作 ـٌ，-an 写作 ـً，-in 写作 ـٍ。所以 كِتَابٌ 读 kitābun，كِتَابًا 读 kitāban，كِتَابٍ 读 kitābin。\n一句话记住：带 الْ 的看短元音，泛指的看鼻音符。短元音三个、鼻音符三个，一共六个尾巴，这就是一个名词能有的全部格形式。反过来也成立：看到一个名词以 ـٌ 结尾，它一定是主格，不可能是宾格或属格。"},{"title":"4. 什么时候用哪个格","body":"主格：起语（句子的主题）用主格，名词句的谓语也用主格。الْكِتَابُ جَدِيدٌ（al-kitābu jadīdun，这本书是新的）里，الْكِتَابُ 是起语，جَدِيدٌ 是谓语，两个都是主格。\n宾格：动词的宾语用宾格。قَرَأْتُ الْكِتَابَ（qaraʾtu al-kitāba，我读了这本书）里，الْكِتَابَ 是宾语，所以读 -a，不能读 -u。\n属格：介词后面的名词用属格；正偏组合里的偏次也用属格（第十四节细讲）。فِي الْمَدْرَسَةِ（fī al-madrasati，在学校里）里，الْمَدْرَسَةِ 跟在介词 فِي 后面，所以读 -i。\n把这几条压成一句口诀：起语谓语主格走，动词宾语用宾格，介词偏次属格收。判断的时候先问「这个词在句子里干什么」，答案出来，格就出来了。"},{"title":"5. 同一个词的六种形式","body":"把 كِتَاب（书）摊开看，六种形式一目了然。横着看是「确指 / 泛指」的差别，竖着看是三个格的差别：\n这张表要能默写。默写的诀窍不是死记六行，而是记住两个开关：第一个开关是「有没有 الْ」，决定要不要加 -n；第二个开关是「这个词在句子里干什么」，决定用 -u、-a 还是 -i。两个开关一组合，六种形式自然就出来了。\n任何规则名词都套得进这张表，只要把 كِتَاب 换成 بَيْتٌ（baytun，房子）、قَلَمٌ（qalamun，笔）、مَدْرَسَةٌ（madrasatun，学校）都行。先把 كِتَاب 这一张背熟，剩下的都是复制粘贴。","tables":[{"header":["格","确指（带 الْ）","泛指（带鼻音符）"],"rows":[["主格 رَفْع","الْكِتَابُ（al-kitābu）","كِتَابٌ（kitābun）"],["宾格 نَصْب","الْكِتَابَ（al-kitāba）","كِتَابًا（kitāban）"],["属格 جَرّ","الْكِتَابِ（al-kitābi）","كِتَابٍ（kitābin）"]]}]},{"title":"6. 双数和复数先放一放","body":"双数和复数的格变化本节只提一句：规则阳性复数的主格是 ـُونَ（-ūna），属格和宾格都是 ـِينَ（-īna），所以 مُعَلِّمُونَ（muʿallimūna，老师们，主格）和 مُعَلِّمِينَ（muʿallimīna，老师们，属格、宾格）其实是同一个词的两个格形式，只差一个字母。\n这就是为什么第十六节要专门讲复数：复数的格不靠短元音区分，而是靠词尾的 -ūna / -īna 区分，规则不一样。现在只要建立一个印象——「复数的格也在词尾上，只是尾巴长得不同」——就够了，先别急着背。"}],"vocab":[{"ar":"الْكِتَابُ","rom":"al-kitābu","zh":"这本书（主格）","a":"fc164be6be8a"},{"ar":"كِتَابٌ","rom":"kitābun","zh":"一本书（主格）","a":"edbacf7ab47c"},{"ar":"الطَّالِبُ","rom":"aṭ-ṭālibu","zh":"这个学生（主格）","a":"18f56a9d9d0a"},{"ar":"طَالِبٌ","rom":"ṭālibun","zh":"一个学生（主格）","a":"bea7c61ac7f5"},{"ar":"الْبَيْتُ","rom":"al-baytu","zh":"这栋房子（主格）","a":"b8cca83ab210"},{"ar":"بَيْتٌ","rom":"baytun","zh":"一栋房子（主格）","a":"f681630e99e8"},{"ar":"الْمُعَلِّمُ","rom":"al-muʿallimu","zh":"这位老师（主格）","a":"af64603861f2"},{"ar":"مُعَلِّمٌ","rom":"muʿallimun","zh":"一位老师（主格）","a":"d3c46805be2a"},{"ar":"الْقَلَمُ","rom":"al-qalamu","zh":"这支笔（主格）","a":"f7e9c84d2391"},{"ar":"قَلَمٌ","rom":"qalamun","zh":"一支笔（主格）","a":"c5cd3bad9c06"},{"ar":"الْكِتَابَ","rom":"al-kitāba","zh":"这本书（宾格）","a":"cf5c474f5df7"},{"ar":"كِتَابًا","rom":"kitāban","zh":"一本书（宾格）","a":"9e10f0206c40"},{"ar":"الطَّالِبَ","rom":"aṭ-ṭāliba","zh":"这个学生（宾格）","a":"1ad9ea0d13ac"},{"ar":"طَالِبًا","rom":"ṭāliban","zh":"一个学生（宾格）","a":"3344fd7195cc"},{"ar":"الْبَيْتَ","rom":"al-bayta","zh":"这栋房子（宾格）","a":"0a4e04550718"},{"ar":"بَيْتًا","rom":"baytan","zh":"一栋房子（宾格）","a":"72528919315f"},{"ar":"الطَّاوِلَةَ","rom":"aṭ-ṭāwilata","zh":"这张桌子（宾格）","a":"aa1c594b0856"},{"ar":"طَاوِلَةً","rom":"ṭāwilatan","zh":"一张桌子（宾格）","a":"fe18db6449bb"},{"ar":"الْمَدْرَسَةَ","rom":"al-madrasata","zh":"这所学校（宾格）","a":"a79f2923c35f"},{"ar":"مَدْرَسَةً","rom":"madrasatan","zh":"一所学校（宾格）","a":"c325328094e7"},{"ar":"الْكِتَابِ","rom":"al-kitābi","zh":"这本书（属格）","a":"1c24fab31374"},{"ar":"كِتَابٍ","rom":"kitābin","zh":"一本书（属格）","a":"e7ec432bf619"},{"ar":"الْبَيْتِ","rom":"al-bayti","zh":"这栋房子（属格）","a":"75adb1e6cca4"},{"ar":"بَيْتٍ","rom":"baytin","zh":"一栋房子（属格）","a":"997476b4bb5a"},{"ar":"الطَّاوِلَةِ","rom":"aṭ-ṭāwilati","zh":"这张桌子（属格）","a":"8877ee680c92"},{"ar":"طَاوِلَةٍ","rom":"ṭāwilatin","zh":"一张桌子（属格）","a":"0924ecd995aa"},{"ar":"الْمَدْرَسَةِ","rom":"al-madrasati","zh":"这所学校（属格）","a":"2a86afbc8e6a"},{"ar":"مَدْرَسَةٍ","rom":"madrasatin","zh":"一所学校（属格）","a":"026ad02634d8"},{"ar":"الْقَلَمِ","rom":"al-qalami","zh":"这支笔（属格）","a":"1bec2f4e7e9b"},{"ar":"قَلَمٍ","rom":"qalamin","zh":"一支笔（属格）","a":"2ce3569495cc"},{"ar":"رَفْعٌ","rom":"rafʿun","zh":"主格","a":"78bc4e8f8eb1"},{"ar":"نَصْبٌ","rom":"naṣbun","zh":"宾格","a":"5d81469d5941"},{"ar":"جَرٌّ","rom":"jarrun","zh":"属格","a":"cd94593a14a1"},{"ar":"تَنْوِينٌ","rom":"tanwīnun","zh":"鼻音符","a":"71491276e8ad"},{"ar":"مَعْرِفَةٌ","rom":"maʿrifatun","zh":"确指","a":"00d9a3cab7c6"},{"ar":"نَكِرَةٌ","rom":"nakiratun","zh":"泛指","a":"1ca65e035edd"}],"examples":[{"ar":"الْكِتَابُ جَدِيدٌ.","rom":"al-kitābu jadīdun","zh":"这本书是新的。","note":"起语用主格 -u，谓语也主格","a":"234f3c14dc49"},{"ar":"هَذَا كِتَابٌ.","rom":"hādhā kitābun","zh":"这是一本书。","note":"谓语泛指，用主格鼻音 -un","a":"63c73a325011"},{"ar":"أَنَا طَالِبٌ.","rom":"anā ṭālibun","zh":"我是学生。","note":"代词起语不变，谓语主格 -un","a":"089a5f92b79f"},{"ar":"الْبَيْتُ كَبِيرٌ.","rom":"al-baytu kabīrun","zh":"这栋房子很大。","note":"起语谓语都用主格","a":"2d4085b6dfa6"},{"ar":"الطَّالِبُ فِي الْمَدْرَسَةِ.","rom":"aṭ-ṭālibu fī al-madrasati","zh":"这个学生在学校里。","note":"起语主格，介词后属格","a":"08c55abea8f6"},{"ar":"الْمُعَلِّمُ فِي الْفَصْلِ.","rom":"al-muʿallimu fī al-faṣli","zh":"老师在教室里。","note":"主格 + 属格，一句话两个格","a":"49502984f5d7"},{"ar":"الْقَلَمُ عَلَى الطَّاوِلَةِ.","rom":"al-qalamu ʿalā aṭ-ṭāwilati","zh":"笔在桌子上。","note":"介词短语作谓语","a":"112a3ceae6fe"},{"ar":"قَرَأْتُ الْكِتَابَ.","rom":"qaraʾtu al-kitāba","zh":"我读了这本书。","note":"宾语用宾格 -a","a":"7f8ce82e083d"},{"ar":"قَرَأَ الطَّالِبُ كِتَابًا.","rom":"qaraʾa aṭ-ṭālibu kitāban","zh":"这个学生读了一本书。","note":"主语主格，泛指宾语用 -an","a":"ed30d39697c8"},{"ar":"رَأَيْتُ الطَّالِبَ.","rom":"raʾaytu aṭ-ṭāliba","zh":"我看见了那个学生。","note":"宾语确指用宾格 -a","a":"f1e907aea623"},{"ar":"أَكَلَ الْوَلَدُ تُفَّاحَةً.","rom":"akala al-waladu tuffāḥatan","zh":"男孩吃了一个苹果。","note":"宾语泛指宾格 -an","a":"7a4f924b4184"},{"ar":"فَتَحَ الْمُعَلِّمُ الْبَابَ.","rom":"fataḥa al-muʿallimu al-bāba","zh":"老师开了门。","note":"主语主格、宾语宾格","a":"e3bf3d58a824"},{"ar":"لَا أَعْرِفُ هَذَا الْكِتَابَ.","rom":"lā aʿrifu hādhā al-kitāba","zh":"我不认识这本书。","note":"هَذَا 不变，后面的名词用宾格","a":"ac779bf107fa"},{"ar":"أَحْبَبْتُ هَذِهِ الْمَدْرَسَةَ.","rom":"aḥbabtu hādhihi al-madrasata","zh":"我喜欢这所学校。","note":"هَذِهِ 不变，名词随成分用宾格","a":"361afd9ebb07"},{"ar":"زُرْتُ مَدِينَةً جَمِيلَةً.","rom":"zurtu madīnatan jamīlatan","zh":"我参观了一座美丽的城市。","note":"名词和形容词一起用 -an","a":"1970ffd6beb8"},{"ar":"أُحِبُّ الْقِرَاءَةَ.","rom":"uḥibbu al-qirāʾata","zh":"我喜欢阅读。","note":"动名词作宾语也用宾格","a":"fcdd6e73adef"},{"ar":"ذَهَبْتُ إِلَى الْمَدْرَسَةِ.","rom":"dhahabtu ilā al-madrasati","zh":"我去了学校。","note":"إِلَى 后面用属格 -i","a":"e74677054c0f"},{"ar":"أَنَا مِنَ الْيَابَانِ.","rom":"anā mina al-yābāni","zh":"我来自日本。","note":"مِنْ 遇 الْ 写成 مِنَ，后面属格","a":"8aeeadedbd58"},{"ar":"الْكِتَابُ فِي الْحَقِيبَةِ.","rom":"al-kitābu fī al-ḥaqībati","zh":"书在包里。","note":"介词宾语用属格","a":"ba3416146b31"},{"ar":"الْمَدْرَسَةُ قَرِيبَةٌ مِنَ الْبَيْتِ.","rom":"al-madrasatu qarībatun mina al-bayti","zh":"学校离家很近。","note":"起语主格，介词宾语属格","a":"95924e237418"},{"ar":"هَذَا بَيْتُ الطَّالِبِ.","rom":"hādhā baytu aṭ-ṭālibi","zh":"这是学生的家。","note":"偏次用属格 -i","a":"f7dbb87cd53e"},{"ar":"بَابُ الْبَيْتِ مَفْتُوحٌ.","rom":"bābu al-bayti maftūḥun","zh":"房子的门开着。","note":"正次主格，偏次属格","a":"40cf70b5dde4"},{"ar":"كِتَابُ الطَّالِبِ جَدِيدٌ.","rom":"kitābu aṭ-ṭālibi jadīdun","zh":"学生的书是新的。","note":"整个正偏组合作起语，仍用主格","a":"aafeb86d2a42"},{"ar":"هَذَا كِتَابُ مُعَلِّمٍ.","rom":"hādhā kitābu muʿallimin","zh":"这是一位老师的书。","note":"泛指偏次用属格鼻音 -in","a":"10920dcccc2b"},{"ar":"هَذِهِ مَدْرَسَةٌ كَبِيرَةٌ.","rom":"hādhihi madrasatun kabīratun","zh":"这是一所大学校。","note":"名词和形容词两个都主格","a":"8376656d8a07"},{"ar":"أَيْنَ كِتَابُكَ؟","rom":"ayna kitābuka","zh":"你的书在哪儿？","note":"带后缀的名词仍按成分定格","a":"b9d4093ef1aa"}],"drills":[{"q":"「主格」的阿拉伯语怎么说？","a":"رَفْعٌ"},{"q":"「属格」的阿拉伯语怎么说？","a":"جَرٌّ"},{"q":"كِتَابٌ 是哪个格、确指还是泛指？","a":"主格、泛指"},{"q":"「一本书（宾格）」怎么写？","a":"كِتَابًا"},{"q":"「这本书（属格）」怎么写？","a":"الْكِتَابِ"},{"q":"泛指名词的三个鼻音符分别是什么？","a":"ـٌ ـً ـٍ"},{"q":"「我读了这本书」怎么说？","a":"قَرَأْتُ الْكِتَابَ"},{"q":"「书在包里」怎么说？","a":"الْكِتَابُ فِي الْحَقِيبَةِ"},{"q":"介词后面的名词用什么格？","a":"属格"},{"q":"名词句的谓语用什么格？","a":"主格"}],"tips":["格只体现在词尾一个符号上，写的时候别漏，漏了读者就判断不出句子成分。","三个鼻音符按位置记：ـٌ 主格、ـً 宾格、ـٍ 属格，别和确指的 -u/-a/-i 混。","人名是确指的，却照样带鼻音符，比如 حَسَنٌ（ḥasanun，哈桑），别拿「确指不带 -n」去套专有名词。","泛指宾格的 ـًا 要写成 alif 加鼻音符，是 kitāban 不是 kitābun。","هَذَا、هَذِهِ 这类指示词自己不变格，变格的是它后面那个名词。","判断格先问「这个词是起语、宾语，还是跟在介词后面」，别从词形倒推。"],"id":"ch3-s1"},{"title":"第十三节 常用介词","concepts":[{"title":"1. 这一节学完你能做什么","body":"学完这一节，你能说「书在桌子上」「我从家里来」「他有一辆车」「这个礼物是给你的」这类句子，也能读懂大部分日常句子里那个「属格」是怎么来的。上一节讲的三个格还只是规则，这一节给你一个几乎不会出错的判断法：看介词。\n阿拉伯语的介词不多，常用的十来个，但出现频率高得惊人。一句话里只要有个介词，后面的名词就一定是属格——记住这一条，你已经能判断一半的格了。"},{"title":"2. 介词后面一定接属格","body":"介词（حُرُوفُ الْجَرِّ，ḥurūfu al-jarri，介词）在阿拉伯语里又叫「جَرّ 的词」——字面意思就是「让后面变属格的词」。名字已经把规则说尽了：介词后面的名词，一律属格，没有例外。\n看三个例子：فِي الْبَيْتِ（fī al-bayti，在家里）、مِنَ الْمَدْرَسَةِ（mina al-madrasati，从学校）、إِلَى السُّوقِ（ilā as-sūqi，到市场去）。三个名词分别以 -i 收尾，因为前面都是介词。\n还有一个细节：介词后面的名词如果是泛指的，同样用属格，只是尾巴变成 -in。بِقَلَمٍ（bi-qalamin，用一支笔）里，قَلَمٍ 读 qalamin，不能读成 qalamun。确指用 -i、泛指用 -in，这是上一节那张表在介词位置上的直接应用。"},{"title":"3. 表示位置的四个：فِي、عَلَى、عِنْدَ、مَعَ","body":"فِي（fī，在…里）表示在某个范围之内：فِي الْفَصْلِ（fī al-faṣli，在教室里）、فِي الْحَقِيبَةِ（fī al-ḥaqībati，在包里）。它是最常用的介词，没有之一。\nعَلَى（ʿalā，在…上）表示接触着某个表面：عَلَى الطَّاوِلَةِ（ʿalā aṭ-ṭāwilati，在桌子上）。注意 عَلَى 的最后一个字母是 ى，不带两点，写的时候别写成 عَلَي。\nعِنْدَ（ʿinda，在…那里、有）表示「在某人身边」。阿拉伯语用它表示「有」：عِنْدِي كِتَابٌ（ʿindī kitābun，我有一本书）。字面是「在我这儿有一本书」，汉语的「我有」在阿拉伯语里不说「我」，而说「我这儿」。\nمَعَ（maʿa，和…一起）表示伴随：مَعَ صَدِيقِي（maʿa ṣadīqī，和我朋友一起）。它和 عِنْدَ 一样，接代词后缀时拼写会变，变成 مَعِي、مَعَهُ，下一段细说。"},{"title":"4. 表示方向与来源的四个：مِنْ、إِلَى、حَتَّى、عَنْ","body":"مِنْ（min，从…）表示起点或来源：مِنَ الْبَيْتِ（mina al-bayti，从家里）。它后面遇到 الْ 时要写成 مِنَ，多一个短元音，读 mina，不能读成 min al-bayti。\nإِلَى（ilā，到…、向…）表示终点：إِلَى الْمَطَارِ（ilā al-maṭāri，到机场）。إِلَى 单用或接名词时以 ى 结尾（إِلَى الْمَطَارِ），接代词后缀时写成 ي：إِلَيْهِ、إِلَيْكَ、إِلَيَّ。\nحَتَّى（ḥattā，直到…）表示界限：حَتَّى الصَّبَاحِ（ḥattā aṣ-ṣabāḥi，直到早上）。它后面的名词照样属格。\nعَنْ（ʿan，关于…、离开…）有两个意思，一个是「谈论某事」，一个是「离开某地」：أَتَكَلَّمُ عَنْ كِتَابٍ جَدِيدٍ（atakallamu ʿan kitābin jadīdin，我在谈一本新书）、بَحَثْتُ عَنْ مِفْتَاحِي（baḥathtu ʿan miftāḥī，我找我的钥匙）。第二个意思汉语常译成「找」，其实是「从…那儿寻找」。另外 مِنْ … إِلَى …（min … ilā …，从…到…）是一对固定搭配，两个介词后面都用属格：مِنَ الْبَيْتِ إِلَى الْمَدْرَسَةِ（mina al-bayti ilā al-madrasati，从家到学校）。"},{"title":"5. 表示关系与工具的：لِ、بِ、كَ","body":"لِ（li-，属于、为了）和 بِ（bi-，用、凭借）都以短元音结尾，所以写出来必须和后面的词连在一起，中间不空格。لِ + الطَّالِبِ = لِلطَّالِبِ（liṭ-ṭālibi，属于那个学生的），بِ + الْقَلَمِ = بِالْقَلَمِ（bi-al-qalami，用这支笔）。\n接代词后缀时，这两个介词都要和后面的词连写成一个词：لِ + ـِي = لِي（lī，我的、属于我的），بِ + ـِي = بِي（bī，用我）；لِ + ـهُ = لَهُ（lahu，他的），بِ + ـهُ = بِهِ（bihi，用它）。要特别记住的是：لِ 后面接后缀时，原来的 -i 要变成 -a，所以是 لَكَ（laka，你的）、لَنَا（lanā，我们的），绝不能写成 لِكَ；而 بِ 的 -i 保持不动，是 بِكَ（bika，用你）、بِكُمْ（bikum，用你们）。只有接 ـِي 的时候两个都写成 لِي、بِي。\nكَ（ka-，像…一样）也一样要连写：كَ + أَخِي = كَأَخِي（ka-akhī，像我的兄弟）。كَ 后面的名词同样属格。"},{"title":"6. 介词短语在句子里的两种身份","body":"介词短语在句子里有两个主要工作。第一是当谓语：الْكِتَابُ عَلَى الطَّاوِلَةِ（al-kitābu ʿalā aṭ-ṭāwilati，书在桌子上），起语是 الْكِتَابُ，谓语就是 عَلَى الطَّاوِلَةِ。阿拉伯语名词句的谓语不一定是名词，介词短语完全可以，这正好对应汉语的「书在桌子上」。\n第二是当定语，修饰前面的名词：رَأَيْتُ كِتَابًا عَلَى الطَّاوِلَةِ（raʾaytu kitāban ʿalā aṭ-ṭāwilati，我看见桌子上的一本书）。这时候介词短语紧跟在被修饰的名词后面，作用相当于一个形容词。被修饰的名词是确指的时候，中间还要加关系代词 الَّذِي，这个后面再讲，现在先只用泛指的形式。\n要提醒一句：这种定语不改变被修饰名词的格。كِتَابًا 仍然是宾格，因为它是 رَأَيْتُ 的宾语，介词短语只是贴上去补充说明「哪一本书」。"}],"vocab":[{"ar":"فِي","rom":"fī","zh":"在…里","a":"eca34af797c4"},{"ar":"مِنْ","rom":"min","zh":"从…、来自…","a":"45ece67b1666"},{"ar":"إِلَى","rom":"ilā","zh":"到…、向…","a":"66010396fe12"},{"ar":"عَلَى","rom":"ʿalā","zh":"在…上","a":"452a5d58c427"},{"ar":"عَنْ","rom":"ʿan","zh":"关于…、离开…","a":"883beb6f61c3"},{"ar":"مَعَ","rom":"maʿa","zh":"和…一起","a":"dfc64fe1dccb"},{"ar":"عِنْدَ","rom":"ʿinda","zh":"在…那里、有","a":"7e2f9771fde6"},{"ar":"لِـ","rom":"li-","zh":"属于…、为了…","a":"cfc0da33ba54"},{"ar":"بِـ","rom":"bi-","zh":"用…、凭借…","a":"caa7d9bf4b50"},{"ar":"كَـ","rom":"ka-","zh":"像…一样","a":"62b546554dde"},{"ar":"حَتَّى","rom":"ḥattā","zh":"直到…","a":"3eb8a960231f"},{"ar":"لِي","rom":"lī","zh":"我的、属于我的","a":"ac9970b05c68"},{"ar":"بِي","rom":"bī","zh":"用我","a":"d0adcb8baad4"},{"ar":"لَهُ","rom":"lahu","zh":"他的","a":"f4843dc0bfb3"},{"ar":"بِهِ","rom":"bihi","zh":"用它","a":"2157bc595c57"},{"ar":"لَنَا","rom":"lanā","zh":"我们的","a":"5ead46960985"},{"ar":"بِكُمْ","rom":"bikum","zh":"用你们","a":"5faa7c8c672d"},{"ar":"فِيهِ","rom":"fīhi","zh":"在它里面","a":"17b03fcb42d2"},{"ar":"مِنْهُ","rom":"minhu","zh":"从他那里","a":"d5ccea13fd31"},{"ar":"إِلَيْهِ","rom":"ilayhi","zh":"到他那里","a":"287b984b78ce"},{"ar":"عَلَيْهِ","rom":"ʿalayhi","zh":"在他身上","a":"6030672eb83a"},{"ar":"عَنْهُ","rom":"ʿanhu","zh":"关于他","a":"3c58047b725d"},{"ar":"مَعَهُ","rom":"maʿahu","zh":"和他一起","a":"7cbfc7a7eef5"},{"ar":"عِنْدَهَا","rom":"ʿindahā","zh":"她那儿有","a":"212a4f414c57"},{"ar":"الْفَصْلُ","rom":"al-faṣlu","zh":"教室","a":"9200cdf0ba8b"},{"ar":"الطَّاوِلَةُ","rom":"aṭ-ṭāwilatu","zh":"桌子","a":"43f426b47ef7"},{"ar":"الْحَقِيبَةُ","rom":"al-ḥaqībatu","zh":"包","a":"54f75f683755"},{"ar":"السُّوقُ","rom":"as-sūqu","zh":"市场","a":"b14f8c7024d4"},{"ar":"الْبَابُ","rom":"al-bābu","zh":"门","a":"f497e0e40739"},{"ar":"النَّافِذَةُ","rom":"an-nāfidhatu","zh":"窗户","a":"e93cb7860f0a"},{"ar":"الْيَابَانُ","rom":"al-yābānu","zh":"日本","a":"2f4dc88cb791"},{"ar":"الصِّينُ","rom":"aṣ-ṣīnu","zh":"中国","a":"fb85465919f2"},{"ar":"الْقِطَارُ","rom":"al-qiṭāru","zh":"火车","a":"6df3346a8ad8"},{"ar":"الْمَطَارُ","rom":"al-maṭāru","zh":"机场","a":"9a3078cfdee9"},{"ar":"الْعَائِلَةُ","rom":"al-ʿāʾilatu","zh":"家庭","a":"3ab08e5ea170"},{"ar":"الصَّبَاحُ","rom":"aṣ-ṣabāḥu","zh":"早上","a":"aedff93e2415"}],"examples":[{"ar":"الْكِتَابُ عَلَى الطَّاوِلَةِ.","rom":"al-kitābu ʿalā aṭ-ṭāwilati","zh":"书在桌子上。","note":"介词短语作谓语","a":"7c2e1237ba82"},{"ar":"أَنَا فِي الْفَصْلِ.","rom":"anā fī al-faṣli","zh":"我在教室里。","note":"فِي 后面用属格 -i","a":"a2c8e554ac9a"},{"ar":"هُوَ مِنَ الْيَابَانِ.","rom":"huwa mina al-yābāni","zh":"他是日本人。","note":"مِنْ 遇 الْ 写成 مِنَ","a":"8f650fcb62cc"},{"ar":"ذَهَبْتُ إِلَى السُّوقِ.","rom":"dhahabtu ilā as-sūqi","zh":"我去了市场。","note":"إِلَى 后面用属格","a":"e503f7734522"},{"ar":"الْقَلَمُ فِي الْحَقِيبَةِ.","rom":"al-qalamu fī al-ḥaqībati","zh":"笔在包里。","note":"起语主格，介词宾语属格","a":"de2ed1f40782"},{"ar":"عِنْدِي كِتَابٌ.","rom":"ʿindī kitābun","zh":"我有一本书。","note":"عِنْدَ 加 ـِي 表示「有」","a":"0e3d7c59b01a"},{"ar":"عِنْدَهُ بَيْتٌ كَبِيرٌ.","rom":"ʿindahu baytun kabīrun","zh":"他有一栋大房子。","note":"عِنْدَ 加 ـهُ","a":"a344cdc4aeec"},{"ar":"مَعِي صَدِيقِي.","rom":"maʿī ṣadīqī","zh":"我的朋友和我在一起。","note":"مَعَ 加 ـِي","a":"507ff3a2caf4"},{"ar":"هَذَا الْكِتَابُ لِلطَّالِبِ.","rom":"hādhā al-kitābu liṭ-ṭālibi","zh":"这本书是那个学生的。","note":"لِ + الْ 写成 لِلْ","a":"df186645d625"},{"ar":"أَكْتُبُ بِالْقَلَمِ.","rom":"aktubu bi-al-qalami","zh":"我用笔写。","note":"بِ + الْ 写成 بِالْ","a":"6dff31fc58ef"},{"ar":"أَنْتَ كَأَخِي.","rom":"anta ka-akhī","zh":"你就像我的兄弟。","note":"كَ 连写，后面属格","a":"41abaff4adbb"},{"ar":"سَافَرْتُ مِنَ الْبَيْتِ إِلَى الْمَدْرَسَةِ.","rom":"sāfartu mina al-bayti ilā al-madrasati","zh":"我从家出发去了学校。","note":"مِنْ … إِلَى … 两头都是属格","a":"2847f5a07643"},{"ar":"أَتَكَلَّمُ عَنْ كِتَابٍ جَدِيدٍ.","rom":"atakallamu ʿan kitābin jadīdin","zh":"我在谈一本新书。","note":"عَنْ 后面泛指属格 -in","a":"59525b4efcbb"},{"ar":"بَحَثْتُ عَنْ مِفْتَاحِي.","rom":"baḥathtu ʿan miftāḥī","zh":"我在找我的钥匙。","note":"عَنْ 后面接代词后缀","a":"6d2adb32bc9a"},{"ar":"تَكَلَّمَ الْمُعَلِّمُ عَنِ الدَّرْسِ.","rom":"takallama al-muʿallimu ʿani ad-darsi","zh":"老师讲了这一课。","note":"عَنْ 遇 الْ 写成 عَنِ","a":"8197333f8e1c"},{"ar":"الْمَدْرَسَةُ قَرِيبَةٌ مِنَ الْبَيْتِ.","rom":"al-madrasatu qarībatun mina al-bayti","zh":"学校离家很近。","note":"مِنْ 后面用属格","a":"95924e237418"},{"ar":"هَذَا الْبَابُ مِنَ الْخَشَبِ.","rom":"hādhā al-bābu mina al-khashabi","zh":"这扇门是木头做的。","note":"مِنْ 表示材质","a":"d472bfa04206"},{"ar":"أَجْلِسُ مَعَ صَدِيقِي.","rom":"ajlisu maʿa ṣadīqī","zh":"我和朋友坐在一起。","note":"مَعَ 后面用属格","a":"87c236c435eb"},{"ar":"نَذْهَبُ إِلَى الْمَطَارِ مَعًا.","rom":"nadhhabu ilā al-maṭāri maʿan","zh":"我们一起去机场。","note":"مَعًا 是副词，意思是「一起」","a":"df0798971c8e"},{"ar":"هَذِهِ الْهَدِيَّةُ لَكَ.","rom":"hādhihi al-hadiyyatu laka","zh":"这个礼物是给你的。","note":"لِ + ـكَ 写成 لَكَ","a":"fab9029348d4"},{"ar":"كَتَبْتُ بِهِ رِسَالَةً.","rom":"katabtu bihi risālatan","zh":"我用它写了一封信。","note":"بِ + ـهُ 写成 بِهِ","a":"87cc355ca0b3"},{"ar":"لِي أَخٌ وَأُخْتٌ.","rom":"lī akhun wa-ukhtun","zh":"我有一个哥哥和一个妹妹。","note":"لِي 表示「属于我」","a":"aedf316fd2ad"},{"ar":"ذَهَبْتُ إِلَيْهِ.","rom":"dhahabtu ilayhi","zh":"我去了他那儿。","note":"إِلَى + ـهُ 写成 إِلَيْهِ","a":"8eb3ae32edd7"},{"ar":"عِنْدَهَا كِتَابٌ جَدِيدٌ.","rom":"ʿindahā kitābun jadīdun","zh":"她有一本新书。","note":"عِنْدَ 加 ـهَا","a":"61c31d0ea7f5"},{"ar":"الْفَصْلُ كَبِيرٌ وَفِيهِ نَافِذَاتٌ كَثِيرَةٌ.","rom":"al-faṣlu kabīrun wa-fīhi nāfidhātun kathīratun","zh":"教室很大，里面有很多窗户。","note":"وَ + فِيهِ 连读，后面属格","a":"1d216dd643d6"},{"ar":"نَجْلِسُ فِي الْفَصْلِ حَتَّى الصَّبَاحِ.","rom":"najlisu fī al-faṣli ḥattā aṣ-ṣabāḥi","zh":"我们在教室里待到早上。","note":"حَتَّى 后面用属格","a":"82757bc02ab4"}],"drills":[{"q":"「在…里」用哪个介词？","a":"فِي"},{"q":"「从…到…」怎么说？","a":"مِنْ … إِلَى …"},{"q":"「我有一本书」怎么说？","a":"عِنْدِي كِتَابٌ"},{"q":"「书在桌子上」怎么说？","a":"الْكِتَابُ عَلَى الطَّاوِلَةِ"},{"q":"「用笔」怎么说？","a":"بِالْقَلَمِ"},{"q":"「这个礼物是给你的」怎么说？","a":"هَذِهِ الْهَدِيَّةُ لَكَ"},{"q":"لِ 加 ـِي 变成什么？","a":"لِي"},{"q":"بِ 加 ـهُ 变成什么？","a":"بِهِ"},{"q":"إِلَى 加 ـهُ 变成什么？","a":"إِلَيْهِ"},{"q":"介词后面的名词用什么格？","a":"属格"}],"tips":["介词后面一律属格，这是判断格最省力的办法，先看有没有介词。","مِنْ 和 عَنْ 遇到 الْ 要写成 مِنَ、عَنِ，多一个短元音。","إِلَى 和 عَلَى 单用或接名词时以 ى 结尾，接代词后缀时改成 ي：إِلَيْهِ、عَلَيْهِ。","لِ 接代词后缀时 -i 要换成 -a：لَكَ、لَهُ、لَنَا，不是 لِكَ。","介词短语可以直接当谓语，不用另加「是」或动词。"],"id":"ch3-s2"},{"title":"第十四节 正偏组合 الْإِضَافَة","concepts":[{"title":"1. 这一节学完你能做什么","body":"学完这一节，你能把「学生的书」「我朋友的家」「车钥匙」「女子学校」这类「A 的 B」说清楚，也能把一个正偏组合塞进句子的任何位置——当起语、当宾语、跟在介词后面。这是阿拉伯语里出现频率最高的结构，几乎每句话都会碰到，学会它，你的句子长度立刻上一个台阶。"},{"title":"2. 顺序和汉语正好相反","body":"汉语说「学生的书」，修饰语在前，被修饰语在后。阿拉伯语反过来：先说被修饰的东西，再说修饰它的东西。كِتَابُ الطَّالِبِ（kitābu aṭ-ṭālibi，学生的书）——字面顺序是「书 学生」。这个结构阿拉伯语叫 الْإِضَافَةُ（al-iḍāfatu，正偏组合），汉语教材里就译作「正偏组合」。\n两个成员各有名字：前面那个被修饰的词叫正次（مُضَافٌ，muḍāfun，正次），后面那个修饰它的词叫偏次（مُضَافٌ إِلَيْهِ，muḍāfun ilayhi，偏次）。مُضَافٌ إِلَيْهِ 的字面意思是「被加到它上面的」，也就是「依附于它的词」。\n汉语那个「的」在阿拉伯语里没有对应的词，全靠顺序和词尾来表达。所以你写正偏组合的时候，脑子里要先把汉语的「A 的 B」翻成「B A」，再去处理词尾。翻译方向反了，句子就完全不成话。"},{"title":"3. 三条铁律","body":"第一条：正次不带 الْ。الْكِتَابُ 是「这本书」，但要说「学生的书」，正次必须光着：كِتَابُ الطَّالِبِ，不能写成 الْكِتَابُ الطَّالِبِ。道理不难理解：正次一旦带了 الْ 就变成确指，而正偏组合的确指性由偏次决定，两个都带 الْ 就冲突了。\n第二条：正次不带鼻音符 -n。كِتَابٌ 读 kitābun，进了正偏组合就读 kitābu，写成 كِتَابُ。原因是那个 -n 是泛指的标志，而正偏组合已经靠偏次确定了所指，不再需要它。同理，双数的 ـَانِ 要变成 ـَا，规则复数的 ـُونَ 要变成 ـُو。\n第三条：偏次永远属格。الطَّالِبِ 读 aṭ-ṭālibi，不管是确指还是泛指，不管是单数还是复数，只要它在偏次的位置上，就是属格。泛指偏次则用 -in：كِتَابُ طَالِبٍ（kitābu ṭālibin，一个学生的书）。\n三条铁律可以缩成六个字：正次光、偏次格。写完一个正偏组合，回头检查这两件事，基本不会错。"},{"title":"4. 偏次的四种类型","body":"第一种是专有名词或带 الْ 的确指名词：كِتَابُ الطَّالِبِ（kitābu aṭ-ṭālibi，学生的书）、بَابُ الْمَدْرَسَةِ（bābu al-madrasati，学校的门）。这类最常见，也最好认，因为偏次身上有 الْ。\n第二种是泛指名词，用属格鼻音 -in：بَابُ مَدْرَسَةٍ（bābu madrasatin，一所学校的门）、كِتَابُ طَالِبٍ（kitābu ṭālibin，一个学生的书）。注意这时候正次仍然是「光」的，不能带 الْ。\n第三种是代词后缀，直接粘在正次上：كِتَابِي（kitābī，我的书）、كِتَابُهُ（kitābuhu，他的书）、بَيْتُنَا（baytunā，我们的家）。这一类最省事，因为根本没有独立的偏次词，也就没有属格符号要标。\n第四种是另一个正偏组合，一层套一层：كِتَابُ صَدِيقِ أَخِي（kitābu ṣadīqi akhī，我哥哥的朋友的书）。拆开看是 كِتَابُ（正次）加 صَدِيقِ أَخِي（偏次），而 صَدِيقِ أَخِي 本身又是一个正偏组合，صَدِيقِ 是它的正次，أَخِي 是它的偏次。层层叠加时，每一层都遵守同样三条铁律。"},{"title":"5. 正次自己也能变形","body":"正次本身可以是双数、规则复数，或者带代词后缀，变形时都要记住「-n 脱落」这一条。双数：كِتَابَانِ（kitābāni，两本书）变成 كِتَابَا الطَّالِبِ（kitābā aṭ-ṭālibi，学生的两本书），ـَانِ 脱落成 ـَا。\n规则阳性复数：مُعَلِّمُونَ（muʿallimūna，老师们）变成 مُعَلِّمُو الْفَصْلِ（muʿallimū al-faṣli，班级的老师们），ـُونَ 脱落成 ـُو。\n阴性复数的词尾是 ـَات，进入正偏组合时只掉鼻音符（-un → -u）：طَالِبَاتٌ → طَالِبَاتُ الْفَصْلِ，ـَات 这个复数标记本身不变：طَالِبَاتٌ（ṭālibātun，女学生们）变成 طَالِبَاتُ الْفَصْلِ（ṭālibātu al-faṣli，班级的女学生们）。\n正次带代词后缀的情况，其实就是「偏次是后缀」：كِتَابِي 里 ـِي 是偏次，前面的 كِتَابِ 是正次——注意这里读 kitābi-，因为 ي 前面必须是 -i-。这时候正次照样不带 الْ、不带 -n，和普通正偏组合一模一样。"},{"title":"6. 整个组合在句子里当什么成分","body":"整个正偏组合是一个名词短语，它在句子里当什么成分，就按什么格变——变的只是正次那个词，偏次永远是属格，一动不动。\n作起语或谓语，正次用主格 -u：كِتَابُ الطَّالِبِ جَدِيدٌ（kitābu aṭ-ṭālibi jadīdun，学生的书是新的）、هَذَا كِتَابُ الطَّالِبِ（hādhā kitābu aṭ-ṭālibi，这是学生的书）。\n作宾语，正次用宾格 -a；作介词宾语，正次用属格 -i：قَرَأْتُ كِتَابَ الطَّالِبِ（qaraʾtu kitāba aṭ-ṭālibi，我读了学生的书）、ذَهَبْتُ إِلَى بَيْتِ صَدِيقِي（dhahabtu ilā bayti ṣadīqī，我去了我朋友家）。\n记住一个判断顺序：先看整个组合在句子里是什么成分，定下正次的格；再确认偏次是属格。两步都过了，这个组合就写对了。"}],"vocab":[{"ar":"كِتَابُ الطَّالِبِ","rom":"kitābu aṭ-ṭālibi","zh":"学生的书","a":"6f162e9f3345"},{"ar":"كِتَابُ الطَّالِبَةِ","rom":"kitābu aṭ-ṭālibati","zh":"女学生的书","a":"1d2795058919"},{"ar":"بَابُ الْبَيْتِ","rom":"bābu al-bayti","zh":"房子的门","a":"de53c2c146e2"},{"ar":"مِفْتَاحُ السَّيَّارَةِ","rom":"miftāḥu as-sayyārati","zh":"车钥匙","a":"9a0255a6cf04"},{"ar":"غُرْفَةُ النَّوْمِ","rom":"ghurfatu an-nawmi","zh":"卧室","a":"ff40676e900e"},{"ar":"قَلَمُ الْمُعَلِّمِ","rom":"qalamu al-muʿallimi","zh":"老师的笔","a":"774050243f4f"},{"ar":"كِتَابِي","rom":"kitābī","zh":"我的书","a":"6d8efa6270a2"},{"ar":"كِتَابُهُ","rom":"kitābuhu","zh":"他的书","a":"c0d097c2fb62"},{"ar":"بَيْتُنَا","rom":"baytunā","zh":"我们的家","a":"2b6c96344a5d"},{"ar":"مُعَلِّمُ الْفَصْلِ","rom":"muʿallimu al-faṣli","zh":"班级的老师","a":"899bfe6b056f"},{"ar":"صَدِيقُ أَخِي","rom":"ṣadīqu akhī","zh":"我哥哥的朋友","a":"0144df8e05b2"},{"ar":"كِتَابُ صَدِيقِي","rom":"kitābu ṣadīqī","zh":"我朋友的书","a":"5901a37a6fd6"},{"ar":"بَابُ مَدْرَسَةٍ","rom":"bābu madrasatin","zh":"一所学校的门","a":"411629e479ad"},{"ar":"كِتَابُ طَالِبٍ","rom":"kitābu ṭālibin","zh":"一个学生的书","a":"96049b01061b"},{"ar":"مَدْرَسَةُ الْبَنَاتِ","rom":"madrasatu al-banāti","zh":"女子学校","a":"8c647efd4e9a"},{"ar":"مُدِيرُ الْمَدْرَسَةِ","rom":"mudīru al-madrasati","zh":"校长","a":"56be46f8d4b7"},{"ar":"اسْمُ الطَّالِبِ","rom":"ismu aṭ-ṭālibi","zh":"学生的名字","a":"792629a3f11d"},{"ar":"لَوْنُ الْبَابِ","rom":"lawnu al-bābi","zh":"门的颜色","a":"016dc9991333"},{"ar":"عُمْرُ الطَّالِبِ","rom":"ʿumru aṭ-ṭālibi","zh":"学生的年龄","a":"b3359559924b"},{"ar":"وَالِدُ الطَّالِبِ","rom":"wālidu aṭ-ṭālibi","zh":"学生的父亲","a":"9392dfc93c83"},{"ar":"بَيْتُ الطَّالِبَتَيْنِ","rom":"baytu aṭ-ṭālibatayni","zh":"两个女学生的家","a":"c9a55423afd2"},{"ar":"كِتَابُ الطُّلَّابِ","rom":"kitābu aṭ-ṭullābi","zh":"学生们的书","a":"011455cfff9a"},{"ar":"مُعَلِّمُو الْفَصْلِ","rom":"muʿallimū al-faṣli","zh":"班级的老师们","a":"7de1c8c15f0d"},{"ar":"غُرْفَةُ الْأُسْتَاذِ","rom":"ghurfatu al-ustādhi","zh":"教授的办公室","a":"687b1b1263d6"},{"ar":"نَافِذَةُ الْغُرْفَةِ","rom":"nāfidhatu al-ghurfati","zh":"房间的窗户","a":"c35713a5e809"},{"ar":"مِفْتَاحُ الْبَابِ","rom":"miftāḥu al-bābi","zh":"门的钥匙","a":"a61afa0cfa78"},{"ar":"غُرْفَةُ الْمُعَلِّمِينَ","rom":"ghurfatu al-muʿallimīna","zh":"老师们的房间","a":"4f46714dbdf9"},{"ar":"الْإِضَافَةُ","rom":"al-iḍāfatu","zh":"正偏组合","a":"21ede3a4f40e"},{"ar":"مُضَافٌ","rom":"muḍāfun","zh":"正次","a":"b39ad1505bc4"},{"ar":"مُضَافٌ إِلَيْهِ","rom":"muḍāfun ilayhi","zh":"偏次","a":"5612ccf4f5a9"},{"ar":"غُرْفَةٌ","rom":"ghurfatun","zh":"房间","a":"56cee0873c82"},{"ar":"مِفْتَاحٌ","rom":"miftāḥun","zh":"钥匙","a":"deb53ab6c662"},{"ar":"لَوْنٌ","rom":"lawnun","zh":"颜色","a":"c011e7b08297"},{"ar":"اسْمٌ","rom":"ismun","zh":"名字","a":"f44a34d2e01f"}],"examples":[{"ar":"كِتَابُ الطَّالِبِ جَدِيدٌ.","rom":"kitābu aṭ-ṭālibi jadīdun","zh":"学生的书是新的。","note":"正偏组合作起语，正次主格","a":"aafeb86d2a42"},{"ar":"هَذَا كِتَابُ الطَّالِبِ.","rom":"hādhā kitābu aṭ-ṭālibi","zh":"这是学生的书。","note":"正偏组合作谓语，正次主格","a":"17305e143eb8"},{"ar":"بَابُ الْبَيْتِ مَفْتُوحٌ.","rom":"bābu al-bayti maftūḥun","zh":"房子的门开着。","note":"正次主格，偏次属格","a":"40cf70b5dde4"},{"ar":"قَرَأْتُ كِتَابَ الطَّالِبِ.","rom":"qaraʾtu kitāba aṭ-ṭālibi","zh":"我读了学生的书。","note":"正次作宾语，用宾格 -a","a":"b75c8d824b16"},{"ar":"ذَهَبْتُ إِلَى بَيْتِ صَدِيقِي.","rom":"dhahabtu ilā bayti ṣadīqī","zh":"我去了我朋友家。","note":"正次在介词后用属格","a":"87298bd3d681"},{"ar":"كِتَابِي عَلَى الطَّاوِلَةِ.","rom":"kitābī ʿalā aṭ-ṭāwilati","zh":"我的书在桌子上。","note":"偏次是代词后缀","a":"2703ff2a4bdc"},{"ar":"غُرْفَةُ النَّوْمِ كَبِيرَةٌ.","rom":"ghurfatu an-nawmi kabīratun","zh":"卧室很大。","note":"正次主格，偏次属格","a":"a9f19d6ae763"},{"ar":"لَوْنُ الْبَابِ جَمِيلٌ.","rom":"lawnu al-bābi jamīlun","zh":"门的颜色很漂亮。","note":"正次主格，偏次属格","a":"0b34fb00f52d"},{"ar":"اسْمُ الطَّالِبِ حَسَنٌ.","rom":"ismu aṭ-ṭālibi ḥasanun","zh":"学生的名字是哈桑。","note":"谓语是专有名词，照常带鼻音符","a":"0a64942132f7"},{"ar":"مِفْتَاحُ السَّيَّارَةِ فِي الْحَقِيبَةِ.","rom":"miftāḥu as-sayyārati fī al-ḥaqībati","zh":"车钥匙在包里。","note":"介词短语作谓语","a":"3716201ab816"},{"ar":"هَذَا بَابُ مَدْرَسَةٍ.","rom":"hādhā bābu madrasatin","zh":"这是一所学校的门。","note":"泛指偏次用属格 -in","a":"0cc16dae3880"},{"ar":"كِتَابُ صَدِيقِي جَدِيدٌ.","rom":"kitābu ṣadīqī jadīdun","zh":"我朋友的书是新的。","note":"偏次是后缀，不再标属格","a":"a1eb693e0393"},{"ar":"بَيْتُ أَخِي كَبِيرٌ.","rom":"baytu akhī kabīrun","zh":"我哥哥的家很大。","note":"偏次是后缀，正次仍主格","a":"7ce9bad226e5"},{"ar":"مُدِيرُ الْمَدْرَسَةِ رَجُلٌ طَيِّبٌ.","rom":"mudīru al-madrasati rajulun ṭayyibun","zh":"校长是个好人。","note":"起语和谓语都用主格","a":"2e03a59eac57"},{"ar":"كِتَابُ الطُّلَّابِ فِي الْفَصْلِ.","rom":"kitābu aṭ-ṭullābi fī al-faṣli","zh":"学生们的书在教室里。","note":"偏次是复数，用属格 -i","a":"94395db32a03"},{"ar":"هَؤُلَاءِ مُعَلِّمُو الْفَصْلِ.","rom":"hāʾulāʾi muʿallimū al-faṣli","zh":"这些是班级的老师。","note":"正次复数，ـُونَ 的 -n 脱落","a":"589128da1e88"},{"ar":"نَافِذَةُ الْغُرْفَةِ مَفْتُوحَةٌ.","rom":"nāfidhatu al-ghurfati maftūḥatun","zh":"房间的窗户开着。","note":"正次主格，偏次属格","a":"d6eaddcba83a"},{"ar":"أُحِبُّ غُرْفَةَ النَّوْمِ.","rom":"uḥibbu ghurfata an-nawmi","zh":"我喜欢卧室。","note":"正次作宾语，用宾格 -a","a":"182a38fdccb9"},{"ar":"هَذَا كِتَابُ طَالِبٍ جَدِيدٍ.","rom":"hādhā kitābu ṭālibin jadīdin","zh":"这是一个新学生的书。","note":"偏次和它的形容词都用属格","a":"5934c0360cdd"},{"ar":"بَيْتُ الطَّالِبَتَيْنِ قَرِيبٌ.","rom":"baytu aṭ-ṭālibatayni qarībun","zh":"两个女学生的家很近。","note":"偏次是双数，用属格 -ayni","a":"5e43dab001ba"},{"ar":"مَدْرَسَةُ الْبَنَاتِ كَبِيرَةٌ.","rom":"madrasatu al-banāti kabīratun","zh":"女子学校很大。","note":"偏次是复数属格","a":"96bdfb093904"},{"ar":"قَلَمُ الْمُعَلِّمِ عَلَى الطَّاوِلَةِ.","rom":"qalamu al-muʿallimi ʿalā aṭ-ṭāwilati","zh":"老师的笔在桌子上。","note":"正次主格，偏次属格","a":"489edd1c1552"},{"ar":"هَذَا مِفْتَاحُ بَيْتِنَا.","rom":"hādhā miftāḥu baytinā","zh":"这是我们家的钥匙。","note":"偏次本身又带代词后缀","a":"55cbf20db386"},{"ar":"أَخَذْتُ كِتَابَ أَخِي.","rom":"akhadhtu kitāba akhī","zh":"我拿了我哥哥的书。","note":"正次作宾语，用宾格 -a","a":"0158a4aa2743"},{"ar":"غُرْفَةُ الْمُعَلِّمِينَ كَبِيرَةٌ.","rom":"ghurfatu al-muʿallimīna kabīratun","zh":"老师们的房间很大。","note":"偏次复数，用属格 -īna","a":"fffabf3ca6c5"}],"drills":[{"q":"「正偏组合」的阿拉伯语怎么说？","a":"الْإِضَافَةُ"},{"q":"「偏次」的阿拉伯语怎么说？","a":"مُضَافٌ إِلَيْهِ"},{"q":"「学生的书」怎么说？","a":"كِتَابُ الطَّالِبِ"},{"q":"「我哥哥的朋友」怎么说？","a":"صَدِيقُ أَخِي"},{"q":"正次能不能带 الْ？","a":"不能"},{"q":"正次能不能带鼻音符 -n？","a":"不能"},{"q":"偏次用什么格？","a":"属格"},{"q":"「一所学校的门」怎么写？","a":"بَابُ مَدْرَسَةٍ"},{"q":"كِتَابُ الطَّالِبِ 里的正次是哪个词？","a":"كِتَابُ"},{"q":"「我读了学生的书」怎么说？","a":"قَرَأْتُ كِتَابَ الطَّالِبِ"}],"tips":["语序是「被修饰语 + 修饰语」，和汉语的「A 的 B」正好相反，先翻译顺序再翻词。","正次一旦带了 الْ 或 -n，这个正偏组合就写错了，回头检查这两个地方。","偏次的属格和它是不是确指无关，确指用 -i，泛指用 -in。","正次是规则阳性复数时，ـُونَ 的 -n 要脱落，写成 مُعَلِّمُو الْفَصْلِ。","正偏组合的确指与否看偏次，偏次确指整个组合就确指，正次自己不加 الْ。"],"id":"ch3-s3"},{"title":"第十五节 形容词与一致","concepts":[{"title":"1. 这一节学完你能做什么","body":"学完这一节，你能把「一本新书」说成 كِتَابٌ جَدِيدٌ（kitābun jadīdun），把「这本新书」说成 الْكِتَابُ الْجَدِيدُ（al-kitābu al-jadīdu），也能一眼分清「这本书是新的」和「这本新书」为什么只差一个 الْ。形容词（نَعْتٌ，naʿtun，定语）在阿拉伯语里位置固定、条件严格，四条一致规则记熟，这一类短语基本不会错。\n先交代两个术语，后面会一直用：被形容词修饰的那个名词叫被修饰语（مَنْعُوتٌ，manʿūtun）；跟在它后面、说明它「什么样的」那个词叫形容词（نَعْتٌ，naʿtun）。汉语语法里叫「定语」，阿拉伯语语法里叫 نَعْتٌ，本课两种叫法混着用，指的是同一件事。"},{"title":"2. 形容词永远站在名词后面","body":"汉语说「新书」，形容词在前；英语说 new book，也在前。阿拉伯语反过来：名词先出场，形容词跟在后面，像影子一样贴着走。كِتَابٌ（kitābun，书）加上 جَدِيدٌ（jadīdun，新的），就是 كِتَابٌ جَدِيدٌ（kitābun jadīdun，一本新书）。\n这个顺序不能倒。把顺序反过来，听的人会先以为你在说「新的……」，然后等你把名词补上，句子才落地。初学阶段养成一个习惯：先说「东西」，再说「什么样的东西」，说完就停，不要回头改。\n形容词在后还有个连带效果：修饰语越长，句子重心越靠前。الْبَيْتُ الْكَبِيرُ الْقَدِيمُ（al-baytu al-kabīru al-qadīmu，那栋又大又旧的房子）里三个词层层往后叠，中心词 الْبَيْتُ 始终站在最前面，后面的词都只是它的补充说明。"},{"title":"3. 四项一致：性、数、格、确指","body":"形容词必须跟被修饰的名词在四个方面保持一致：性、数、格、确指。这四项是本节的核心，缺一项就算错。前三项下面逐条说，第四项放到下一小节专门讲。\n第一是性：阳性名词配阳性形容词，阴性名词配阴性形容词。الطَّالِبُ مُجْتَهِدٌ（aṭ-ṭālibu mujtahidun，这名男学生很用功）对 الطَّالِبَةُ مُجْتَهِدَةٌ（aṭ-ṭālibatu mujtahidatun，这名女学生很用功），差别只在词尾那个 ة。\n第二是数：单数配单数，双数配双数，复数配复数。طَالِبٌ جَدِيدٌ（ṭālibun jadīdun，一个新学生）、طَالِبَانِ جَدِيدَانِ（ṭālibāni jadīdāni，两个新学生）、الطُّلَّابُ الْمُجْتَهِدُونَ（aṭ-ṭullābu al-mujtahidūna，这些用功的学生）。复数的细节下一节专门讲，这里只要记住「数要对上」。\n第三是格：名词在主格，形容词也主格；名词在属格，形容词也属格；名词在宾格，形容词也宾格。同一个「新书」，三种格三种尾巴：الْكِتَابُ الْجَدِيدُ（al-kitābu al-jadīdu，主格，两个词都读 -u）、فِي الْكِتَابِ الْجَدِيدِ（fī al-kitābi al-jadīdi，属格，两个词都读 -i）、قَرَأْتُ الْكِتَابَ الْجَدِيدَ（qaraʾtu al-kitāba al-jadīda，宾格，两个词都读 -a）。这里 قَرَأْتُ（qaraʾtu，我读了）是动词，先不用管它怎么变，只看名词和形容词的尾巴是不是一起动。"},{"title":"4. 确指要一起确指，泛指要一起泛指","body":"确指名词配确指形容词：الْكِتَابُ الْجَدِيدُ（al-kitābu al-jadīdu，这本新书）。两个词都带 الْ，两个词都不带鼻音符。\n泛指名词配泛指形容词：كِتَابٌ جَدِيدٌ（kitābun jadīdun，一本新书）。两个词都不带 الْ，两个词都带鼻音符 -un。注意是「两个都」，不能只给一个。\n最常见的错法是「一有一无」。名词带 الْ、形容词不带，句子就变了性质：الْكِتَابُ جَدِيدٌ（al-kitābu jadīdun，这本书是新的）不是短语，而是一个完整的名词句；反过来，名词不带 الْ、形容词带 الْ，则根本不通。阿拉伯语靠 الْ 的有无来区分定语和谓语，这一点和汉语、英语都不一样，只能当硬规则记下来。"},{"title":"5. 形容词作谓语：还是不用「是」","body":"形容词除了修饰名词，还能直接当谓语，句子照样不加系动词：الْكِتَابُ جَدِيدٌ（al-kitābu jadīdun，这本书是新的）。起语 الْكِتَابُ 带 الْ，谓语 جَدِيدٌ 不带——谓语提供的是新信息，新信息不能确指。\n对比下面三句，词形几乎一样，只差 الْ 的有无：\n- هَذَا كِتَابٌ جَدِيدٌ（hādhā kitābun jadīdun，这是一本新书）——كِتَابٌ 是谓语，جَدِيدٌ 修饰它\n- هَذَا الْكِتَابُ جَدِيدٌ（hādhā al-kitābu jadīdun，这本书是新的）——جَدِيدٌ 是谓语\n- هَذَا الْكِتَابُ الْجَدِيدُ（hādhā al-kitābu al-jadīdu，这本新书）——只是短语，后面还缺谓语\n判断口诀：形容词带 الْ，就是定语，跟着名词走；形容词不带 الْ，又找不到名词可修饰，它就是谓语。定语让短语变长，谓语让短语变成句子，这是两种完全不同的活儿。"},{"title":"6. 阴性怎么变，颜色词怎么变","body":"大多数形容词变阴性就是加 ة：كَبِيرٌ（kabīrun，大的）变成 كَبِيرَةٌ（kabīratun），صَغِيرٌ（ṣaghīrun，小的）变成 صَغِيرَةٌ（ṣaghīratun），جَدِيدٌ（jadīdun，新的）变成 جَدِيدَةٌ（jadīdatun）。加了 ة 之后，词尾从 -un 变成 -atun，写出来是 ـَةٌ，鼻音符落在 ة 上面，别写成 ـَةً。\n表示颜色和生理缺陷的形容词走另一套：阳性是 أَفْعَل 型，阴性是 فَعْلَاء 型。أَحْمَرُ（aḥmaru，红的）的阴性是 حَمْرَاءُ（ḥamrāʾu，红的），أَبْيَضُ（abyaḍu，白的）的阴性是 بَيْضَاءُ（bayḍāʾu，白的）。这一组还有个特点：它们不带鼻音符，阳性就是 أَحْمَرُ（aḥmaru），不会出现 -un 那样的尾巴。\n最后一个位置问题：形容词跟在正偏组合（「A 的 B」那种结构）后面时，通常修饰最后一个词，也就是偏次。بَابُ الْبَيْتِ الْجَدِيدِ（bābu al-bayti al-jadīdi）字面是「新房子之门」，意思是「新房子的门」，不是「门里新的那部分」。初学阶段记住一句话：形容词紧贴谁，就修饰谁。"}],"vocab":[{"ar":"كَبِيرٌ / كَبِيرَةٌ","rom":"kabīrun / kabīratun","zh":"大的","a":"efd2027a5437"},{"ar":"صَغِيرٌ / صَغِيرَةٌ","rom":"ṣaghīrun / ṣaghīratun","zh":"小的","a":"bb3c244e8d45"},{"ar":"جَدِيدٌ / جَدِيدَةٌ","rom":"jadīdun / jadīdatun","zh":"新的","a":"e4e1c953b619"},{"ar":"قَدِيمٌ / قَدِيمَةٌ","rom":"qadīmun / qadīmatun","zh":"旧的、古老的","a":"df0d0e0f5d3c"},{"ar":"جَمِيلٌ / جَمِيلَةٌ","rom":"jamīlun / jamīlatun","zh":"美的、漂亮的","a":"39c77365d2a6"},{"ar":"طَوِيلٌ / طَوِيلَةٌ","rom":"ṭawīlun / ṭawīlatun","zh":"长的、高的","a":"b2fe720ef553"},{"ar":"قَصِيرٌ / قَصِيرَةٌ","rom":"qaṣīrun / qaṣīratun","zh":"短的、矮的","a":"7f10e6ef74f6"},{"ar":"سَهْلٌ / سَهْلَةٌ","rom":"sahlun / sahlatun","zh":"容易的","a":"ffa13295151f"},{"ar":"صَعْبٌ / صَعْبَةٌ","rom":"ṣaʿbun / ṣaʿbatun","zh":"难的","a":"65b9a11d835b"},{"ar":"نَظِيفٌ / نَظِيفَةٌ","rom":"naẓīfun / naẓīfatun","zh":"干净的","a":"0d019d0cc13d"},{"ar":"وَسِخٌ / وَسِخَةٌ","rom":"wasikhun / wasikhatun","zh":"脏的","a":"4a59f0974a40"},{"ar":"حَارٌّ / حَارَّةٌ","rom":"ḥārrun / ḥārratun","zh":"热的（天气）","a":"5b6e42242d3e"},{"ar":"بَارِدٌ / بَارِدَةٌ","rom":"bāridun / bāridatun","zh":"冷的","a":"788c4c4750e7"},{"ar":"سَاخِنٌ / سَاخِنَةٌ","rom":"sākhinun / sākhinatun","zh":"热的（饮品、食物）","a":"0bf3970ad0c2"},{"ar":"لَذِيذٌ / لَذِيذَةٌ","rom":"ladhīdhun / ladhīdhatun","zh":"好吃的","a":"d3f489a9e86b"},{"ar":"مُجْتَهِدٌ / مُجْتَهِدَةٌ","rom":"mujtahidun / mujtahidatun","zh":"用功的","a":"8ceaa4113547"},{"ar":"ذَكِيٌّ / ذَكِيَّةٌ","rom":"dhakiyyun / dhakiyyatun","zh":"聪明的","a":"adef7618082a"},{"ar":"قَوِيٌّ / قَوِيَّةٌ","rom":"qawiyyun / qawiyyatun","zh":"强的","a":"09b398211945"},{"ar":"مَرِيضٌ / مَرِيضَةٌ","rom":"marīḍun / marīḍatun","zh":"生病的","a":"b90b3ddedfa5"},{"ar":"أَحْمَرُ / حَمْرَاءُ","rom":"aḥmaru / ḥamrāʾu","zh":"红的","a":"57b3fcaa1117"},{"ar":"أَبْيَضُ / بَيْضَاءُ","rom":"abyaḍu / bayḍāʾu","zh":"白的","a":"06adf8993eba"},{"ar":"كِتَابٌ","rom":"kitābun","zh":"书","a":"edbacf7ab47c"},{"ar":"بَيْتٌ","rom":"baytun","zh":"房子","a":"f681630e99e8"},{"ar":"وَلَدٌ","rom":"waladun","zh":"男孩","a":"ef7a497be3d4"},{"ar":"بِنْتٌ","rom":"bintun","zh":"女孩","a":"db9e49cfe2a2"},{"ar":"مَدْرَسَةٌ","rom":"madrasatun","zh":"学校","a":"5d4aca09dd41"},{"ar":"سَيَّارَةٌ","rom":"sayyāratun","zh":"汽车","a":"e5f13dbd9c85"},{"ar":"غُرْفَةٌ","rom":"ghurfatun","zh":"房间","a":"56cee0873c82"},{"ar":"طَالِبٌ / طَالِبَةٌ","rom":"ṭālibun / ṭālibatun","zh":"学生（男／女）","a":"c88361346da6"},{"ar":"طُلَّابٌ","rom":"ṭullābun","zh":"学生们","a":"28fd9a2ac273"},{"ar":"دَرْسٌ","rom":"darsun","zh":"课","a":"d13ac4ee73ac"},{"ar":"حَدِيقَةٌ","rom":"ḥadīqatun","zh":"花园","a":"0b6587e313c8"},{"ar":"طَعَامٌ","rom":"ṭaʿāmun","zh":"食物","a":"c0c6dea5f5c8"},{"ar":"نَعْتٌ","rom":"naʿtun","zh":"形容词、定语（语法术语）","a":"80849d977bc7"},{"ar":"مَنْعُوتٌ","rom":"manʿūtun","zh":"被修饰语（语法术语）","a":"bd6bbfcc41b0"}],"examples":[{"ar":"كِتَابٌ جَدِيدٌ.","rom":"kitābun jadīdun","zh":"一本新书（短语）。","note":"形容词后置，两个词都带 -un","a":"5b2d865f90c6"},{"ar":"بَيْتٌ كَبِيرٌ.","rom":"baytun kabīrun","zh":"一栋大房子（短语）。","note":"泛指名词 + 泛指形容词","a":"688b2b19ed71"},{"ar":"الْكِتَابُ الْجَدِيدُ.","rom":"al-kitābu al-jadīdu","zh":"这本新书（短语）。","note":"两个词都带 الْ，都不带鼻音符","a":"5bfdd04bf694"},{"ar":"الْبَيْتُ الْكَبِيرُ.","rom":"al-baytu al-kabīru","zh":"这栋大房子（短语）。","note":"确指名词 + 确指形容词","a":"939fd6025374"},{"ar":"هَذَا كِتَابٌ جَدِيدٌ.","rom":"hādhā kitābun jadīdun","zh":"这是一本新书。","note":"كِتَابٌ 作谓语，جَدِيدٌ 修饰它","a":"74619a6b7171"},{"ar":"هَذَا الْكِتَابُ جَدِيدٌ.","rom":"hādhā al-kitābu jadīdun","zh":"这本书是新的。","note":"谓语位形容词不带 الْ","a":"87ee23579c8a"},{"ar":"هَذَا الْكِتَابُ الْجَدِيدُ.","rom":"hādhā al-kitābu al-jadīdu","zh":"这本新书（短语）。","note":"定语位形容词带 الْ","a":"dce0ad545094"},{"ar":"الطَّالِبُ مُجْتَهِدٌ.","rom":"aṭ-ṭālibu mujtahidun","zh":"这名男学生很用功。","note":"阳性单数一致","a":"45d9f98977d4"},{"ar":"الطَّالِبَةُ مُجْتَهِدَةٌ.","rom":"aṭ-ṭālibatu mujtahidatun","zh":"这名女学生很用功。","note":"阴性形容词加 ة","a":"7a2fc405b8de"},{"ar":"طَالِبَةٌ مُجْتَهِدَةٌ.","rom":"ṭālibatun mujtahidatun","zh":"一个用功的女学生（短语）。","note":"泛指阴性一致","a":"b5fcba49d744"},{"ar":"الْوَلَدُ الصَّغِيرُ.","rom":"al-waladu aṣ-ṣaghīru","zh":"这个小男孩（短语）。","note":"ص 是太阳字母，冠词读 aṣ-","a":"7c7e7ee29cf2"},{"ar":"الْبِنْتُ الصَّغِيرَةُ.","rom":"al-bintu aṣ-ṣaghīratu","zh":"这个小女孩（短语）。","note":"阴性 + 确指 + 主格","a":"7a0559b8331b"},{"ar":"طَالِبَانِ مُجْتَهِدَانِ.","rom":"ṭālibāni mujtahidāni","zh":"两个用功的学生（短语）。","note":"双数：名词 -āni，形容词也 -āni","a":"7ab1188357e7"},{"ar":"الطُّلَّابُ الْمُجْتَهِدُونَ.","rom":"aṭ-ṭullābu al-mujtahidūna","zh":"这些用功的学生（短语）。","note":"阳性复数：两个词都用 ـُونَ","a":"124b6b722b37"},{"ar":"فِي الْبَيْتِ الْقَدِيمِ.","rom":"fī al-bayti al-qadīmi","zh":"在旧房子里（短语）。","note":"属格：两个词都读 -i","a":"305650344ef1"},{"ar":"فِي الْغُرْفَةِ الْكَبِيرَةِ.","rom":"fī al-ghurfati al-kabīrati","zh":"在大房间里（短语）。","note":"属格阴性一致","a":"4cc03c58f914"},{"ar":"قَرَأْتُ الْكِتَابَ الْجَدِيدَ.","rom":"qaraʾtu al-kitāba al-jadīda","zh":"我读了这本新书。","note":"宾格：两个词都读 -a","a":"6b3891af40b6"},{"ar":"أُرِيدُ كِتَابًا جَدِيدًا.","rom":"urīdu kitāban jadīdan","zh":"我想要一本新书。","note":"泛指宾格，两个词都带 -an","a":"ce0134f139f9"},{"ar":"الْغُرْفَةُ الْجَدِيدَةُ كَبِيرَةٌ.","rom":"al-ghurfatu al-jadīdatu kabīratun","zh":"这个新房间很大。","note":"起语带定语 + 谓语形容词","a":"3600b4322f1d"},{"ar":"الْمَدْرَسَةُ الْقَدِيمَةُ جَمِيلَةٌ.","rom":"al-madrasatu al-qadīmatu jamīlatun","zh":"这所古老的学校很美。","note":"起语 + 定语 + 谓语","a":"8f01028351ab"},{"ar":"الْقَهْوَةُ سَاخِنَةٌ.","rom":"al-qahwatu sākhinatun","zh":"咖啡是热的。","note":"阴性谓语形容词","a":"89a1795fd70f"},{"ar":"الطَّعَامُ لَذِيذٌ.","rom":"aṭ-ṭaʿāmu ladhīdhun","zh":"这食物很好吃。","note":"阳性谓语形容词","a":"4a7a558fb165"},{"ar":"الْبَابُ الْأَحْمَرُ.","rom":"al-bābu al-aḥmaru","zh":"这扇红色的门（短语）。","note":"颜色词 أَفْعَل 型，不带鼻音符","a":"6b8addd506af"},{"ar":"السَّيَّارَةُ الْبَيْضَاءُ جَدِيدَةٌ.","rom":"as-sayyāratu al-bayḍāʾu jadīdatun","zh":"这辆白色的汽车是新的。","note":"颜色词阴性 بَيْضَاءُ，仍与名词一致","a":"68f64982a83d"},{"ar":"الطَّالِبُ الذَّكِيُّ مُجْتَهِدٌ.","rom":"aṭ-ṭālibu adh-dhakiyyu mujtahidun","zh":"这名聪明的学生很用功。","note":"定语 + 谓语，两个形容词位置不同","a":"95f0fed395a8"},{"ar":"بَابُ الْبَيْتِ الْجَدِيدِ.","rom":"bābu al-bayti al-jadīdi","zh":"新房子的门（短语）。","note":"形容词紧贴偏次，修饰偏次","a":"12983ee33c5e"}],"drills":[{"q":"形容词在阿拉伯语里放在名词的哪一边？","a":"后面"},{"q":"形容词要和被修饰名词在哪四项上一致？","a":"性、数、格、确指"},{"q":"「一本新书」怎么说？","a":"كِتَابٌ جَدِيدٌ"},{"q":"「这本新书」怎么说？","a":"الْكِتَابُ الْجَدِيدُ"},{"q":"「这本书是新的」怎么说？","a":"الْكِتَابُ جَدِيدٌ"},{"q":"كَبِيرٌ 的阴性形式是什么？","a":"كَبِيرَةٌ"},{"q":"أَحْمَرُ 的阴性形式是什么？","a":"حَمْرَاءُ"},{"q":"الطَّالِبَةُ 的谓语「用功的」该怎么写？","a":"مُجْتَهِدَةٌ"},{"q":"「在大房间里」怎么说？","a":"فِي الْغُرْفَةِ الْكَبِيرَةِ"},{"q":"「我读了这本新书」怎么说？","a":"قَرَأْتُ الْكِتَابَ الْجَدِيدَ"},{"q":"为什么 الْكِتَابُ الْجَدِيدُ 是短语，الْكِتَابُ جَدِيدٌ 却是句子？","a":"前者的形容词带 الْ 作定语，后者的形容词不带 الْ 作谓语"}],"tips":["形容词一律后置，别按汉语习惯放到名词前面。","四项一致里最容易漏的是「确指」：الْكِتَابُ الْجَدِيدُ 两个词都要带 الْ。","形容词不带 الْ 又不修饰任何名词时，它就是谓语：الْكِتَابُ جَدِيدٌ 是句子，不是短语。","阴性主格写 ـَةٌ，鼻音符在上面；写成 ـَةً 就成了宾格，意思和格位都变了。","颜色词的阴性是 فَعْلَاء 型（أَحْمَرُ 变 حَمْرَاءُ），而且这类词一律不带鼻音符。","形容词紧贴谁就修饰谁，所以 بَابُ الْبَيْتِ الْجَدِيدِ 是「新房子的门」。"],"id":"ch3-s4"},{"title":"第十六节 复数","concepts":[{"title":"1. 这一节学完你能做什么","body":"学完这一节，你能把「一本书」说成「几本书」，并且能判断该用哪一种复数：规则阳性、规则阴性还是破碎复数。更要紧的是你会明白，为什么「这些书是新的」里形容词用的是阴性单数 جَدِيدَةٌ（jadīdatun），而不是阳性复数——这是阿拉伯语最反直觉、也最常被考的一条。\n阿拉伯语的复数（جَمْعٌ，jamʿun）分三类：规则阳性复数（جَمْعُ الْمُذَكَّرِ السَّالِمِ，jamʿu al-mudhakkari as-sālimi）、规则阴性复数（جَمْعُ الْمُؤَنَّثِ السَّالِمِ，jamʿu al-muʾannathi as-sālimi）、破碎复数（جَمْعُ التَّكْسِيرِ，jamʿu at-taksīri）。「规则」的意思是词尾加东西、词干不动；「破碎」的意思是词干内部被拆开重排。"},{"title":"2. 规则阳性复数：ـُونَ 与 ـِينَ","body":"以 مُعَلِّمٌ（muʿallimun，老师）为例：去掉词尾的鼻音符，加 ـُونَ 得 مُعَلِّمُونَ（muʿallimūna，老师们），这是主格；加 ـِينَ 得 مُعَلِّمِينَ（muʿallimīna，老师们），这是宾格和属格。\n这一类复数的最大特点是「格不同、形不同」：主格 -ūna，宾格属格 -īna，整个词尾换掉，不是只换最后一个元音。看三句就明白：\n- الْمُعَلِّمُونَ فِي الْمَدْرَسَةِ（al-muʿallimūna fī al-madrasati，老师们在学校里）——主格 -ūna，作起语\n- رَأَيْتُ الْمُعَلِّمِينَ（raʾaytu al-muʿallimīna，我看见了老师们）——宾格 -īna\n- مَعَ الْمُعَلِّمِينَ（maʿa al-muʿallimīna，和老师们一起）——属格 -īna，与宾格同形\n哪些词走这条路？主要是「指人的阳性派生名词」：مُعَلِّمٌ（muʿallimun，老师）、مُهَنْدِسٌ（muhandisun，工程师）、مُسَافِرٌ（musāfirun，旅客），以及形容词 مُجْتَهِدٌ（mujtahidun，用功的）。但别以为所有指人的词都自动这么变：طَالِبٌ（ṭālibun，学生）的常用复数是破碎的 طُلَّابٌ（ṭullābun，学生们），رَجُلٌ（rajulun，男人）是 رِجَالٌ（rijālun，男人们）。同一个词有时两种复数并存，比如 طَالِبُونَ（ṭālibūna）也能见到，但日常最常用的是 طُلَّابٌ。"},{"title":"3. 规则阴性复数：ـَات","body":"以 طَالِبَةٌ（ṭālibatun，女学生）为例，去掉 ة 加 ـَات：طَالِبَاتٌ（ṭālibātun，女学生们）。主格读 -ātun，属格读 -āti，宾格读 -ātin。\n关键差别在于：这一类复数的字形完全不变，格只体现在最后一个字母上的符号。写出来都是 ـَات，只有收尾不同：主格 الطَّالِبَاتُ（aṭ-ṭālibātu）、属格 مَعَ الطَّالِبَاتِ（maʿa aṭ-ṭālibāti）、宾格 رَأَيْتُ الطَّالِبَاتِ（raʾaytu aṭ-ṭālibāti）。\n注意宾格：规则阴性复数的宾格不用 -a，而是用 -i（不定指写 ـَاتٍ，读 -ātin）。这是阿拉伯语格系统里最有名的一处例外，考试最爱考；记的时候别问为什么，直接把「规则阴性复数 + 宾格 = -i」当成硬规则背下来。\n还有一类词也走这条路：以 ة 结尾的阴性名词大多如此，少数不以 ة 结尾的阴性词也一样，如 بِنْتٌ（bintun，女孩）→ بَنَاتٌ（banātun，女孩们）、أُخْتٌ（ukhtun，姐妹）→ أَخَوَاتٌ（akhawātun，姐妹们）。"},{"title":"4. 破碎复数：词形从里面被拆开","body":"جَمْعُ التَّكْسِيرِ（jamʿu at-taksīri）字面是「被打碎的复数」。它不往词尾加东西，而是改动词干内部的元音和字母顺序。下面这些是日常最常用的，先整体过一遍：\n- كِتَابٌ（kitābun，书）→ كُتُبٌ（kutubun，复数）\n- بَيْتٌ（baytun，房子）→ بُيُوتٌ（buyūtun，复数）\n- قَلَمٌ（qalamun，笔）→ أَقْلَامٌ（aqlāmun，复数）\n- بَابٌ（bābun，门）→ أَبْوَابٌ（abwābun，复数）\n- وَلَدٌ（waladun，男孩）→ أَوْلَادٌ（awlādun，复数）\n- رَجُلٌ（rajulun，男人）→ رِجَالٌ（rijālun，复数）\n- اِمْرَأَةٌ（imraʾatun，女人）→ نِسَاءٌ（nisāʾun，复数）\n- طَالِبٌ（ṭālibun，学生）→ طُلَّابٌ（ṭullābun，复数）\n- طَبِيبٌ（ṭabībun，医生）→ أَطِبَّاءُ（aṭibbāʾu，复数）\n- مَدْرَسَةٌ（madrasatun，学校）→ مَدَارِسُ（madārisu，复数）\n- مَدِينَةٌ（madīnatun，城市）→ مُدُنٌ（mudunun，复数）\n- يَوْمٌ（yawmun，天）→ أَيَّامٌ（ayyāmun，复数）\n- شَهْرٌ（shahrun，月）→ أَشْهُرٌ（ashurun，复数）\n- صَدِيقٌ（ṣadīqun，朋友）→ أَصْدِقَاءُ（aṣdiqāʾu，复数）\n- غُرْفَةٌ（ghurfatun，房间）→ غُرَفٌ（ghurafun，复数）\n- نَهْرٌ（nahrun，河）→ أَنْهَارٌ（anhārun，复数）\n这些复数没有统一规则，只能一个词一个词记。不过它们按「词型」（أَوْزَانٌ，awzānun）可以归堆：كُتُبٌ、مُدُنٌ 属 فُعُل 型；بُيُوتٌ、دُرُوسٌ 属 فُعُول 型；أَقْلَامٌ、أَبْوَابٌ、أَوْلَادٌ 属 أَفْعَال 型；رِجَالٌ、جِبَالٌ 属 فِعَال 型；مَدَارِسُ、مَكَاتِبُ 属 مَفَاعِل 型。\n归堆只帮助记忆，不能拿来推。看到单数不知道复数是什么样，看到复数也未必能还原单数，所以词汇表里一律把「单数／复数」成对给出，背的时候也成对背。"},{"title":"5. 复数与形容词一致：物用阴性单数，人按人数","body":"这一条是本节的重量级规则。复数分两类：理性名词（指人）的复数，形容词按复数处理；非理性名词（指物、抽象概念）的复数，形容词一律用阴性单数。\n先看物：الْكُتُبُ الْجَدِيدَةُ（al-kutubu al-jadīdatu，这些新书）。كُتُبٌ（kutubun，书，复数）明明不是阴性，形容词却用了阴性单数 جَدِيدَةٌ。谓语也一样：الْكُتُبُ جَدِيدَةٌ（al-kutubu jadīdatun，这些书是新的），形容词不能跟着名词变成阳性复数。\n再看人：الطُّلَّابُ الْمُجْتَهِدُونَ（aṭ-ṭullābu al-mujtahidūna，这些用功的男学生）用阳性复数，الطَّالِبَاتُ الْمُجْتَهِدَاتُ（aṭ-ṭālibātu al-mujtahidātu，这些用功的女学生）用阴性复数，人数和性别都要对上。\n为什么物要按阴性单数？阿拉伯语把「一堆没有生命的东西」看成一个整体，一个整体就是「它」，而「它」在语法上是阴性单数（هِيَ，hiya）。记法就一句：一堆东西 = 一个「它」。所以 الْبُيُوتُ كَبِيرَةٌ（al-buyūtu kabīratun，这些房子很大）、الدُّرُوسُ صَعْبَةٌ（ad-durūsu ṣaʿbatun，这些课很难）、الْغُرَفُ نَظِيفَةٌ（al-ghurafu naẓīfatun，这些房间很干净），谓语全是阴性单数。"},{"title":"6. 双数：只表示「两个」","body":"双数（الْمُثَنَّى，al-muthannā）是阿拉伯语的第三个数，只表示正好两个。词尾加 ـَانِ 是主格，加 ـَيْنِ 是宾格和属格：كِتَابٌ（kitābun，书）→ كِتَابَانِ（kitābāni，两本书）／كِتَابَيْنِ（kitābayni，两本书，宾格属格）。\n双数的时候形容词也用双数，不走「阴性单数」那一条：الْكِتَابَانِ الْجَدِيدَانِ（al-kitābāni al-jadīdāni，这两本新书）、الطَّالِبَانِ مُجْتَهِدَانِ（aṭ-ṭālibāni mujtahidāni，这两名学生很用功）。\n还有一个小变化：双数作正次时，词尾的 ن 要掉。كِتَابَا الطَّالِبِ（kitābā aṭ-ṭālibi，这名学生的两本书），不能写成 كِتَابَانِ الطَّالِبِ。这一点和规则阳性复数作正次时一样，都是「正次不能带 ن」。"}],"vocab":[{"ar":"مُعَلِّمٌ / مُعَلِّمُونَ","rom":"muʿallimun / muʿallimūna","zh":"老师（男）／老师们","a":"14d61216a07c"},{"ar":"مُهَنْدِسٌ / مُهَنْدِسُونَ","rom":"muhandisun / muhandisūna","zh":"工程师（男）／工程师们","a":"49fa37a0ba4a"},{"ar":"مُجْتَهِدٌ / مُجْتَهِدُونَ","rom":"mujtahidun / mujtahidūna","zh":"用功的／用功的（阳性复数）","a":"2402a104e02e"},{"ar":"مُسَافِرٌ / مُسَافِرُونَ","rom":"musāfirun / musāfirūna","zh":"旅客（男）／旅客们","a":"18eb5586050b"},{"ar":"طَالِبَةٌ / طَالِبَاتٌ","rom":"ṭālibatun / ṭālibātun","zh":"女学生／女学生们","a":"7b638c39ced7"},{"ar":"مُعَلِّمَةٌ / مُعَلِّمَاتٌ","rom":"muʿallimatun / muʿallimātun","zh":"女老师／女老师们","a":"c919981b8af1"},{"ar":"سَيَّارَةٌ / سَيَّارَاتٌ","rom":"sayyāratun / sayyārātun","zh":"汽车／汽车（复数）","a":"0abbad6a3302"},{"ar":"كَلِمَةٌ / كَلِمَاتٌ","rom":"kalimatun / kalimātun","zh":"词／词（复数）","a":"a06b8cc4b47a"},{"ar":"كِتَابٌ / كُتُبٌ","rom":"kitābun / kutubun","zh":"书／书（复数）","a":"0eb585133d92"},{"ar":"بَيْتٌ / بُيُوتٌ","rom":"baytun / buyūtun","zh":"房子／房子（复数）","a":"48ce78295533"},{"ar":"قَلَمٌ / أَقْلَامٌ","rom":"qalamun / aqlāmun","zh":"笔／笔（复数）","a":"7b44a6a2cd9c"},{"ar":"بَابٌ / أَبْوَابٌ","rom":"bābun / abwābun","zh":"门／门（复数）","a":"3cffb522d7d9"},{"ar":"وَلَدٌ / أَوْلَادٌ","rom":"waladun / awlādun","zh":"男孩／男孩们","a":"a8e013b29339"},{"ar":"رَجُلٌ / رِجَالٌ","rom":"rajulun / rijālun","zh":"男人／男人们","a":"80d0f90589c6"},{"ar":"اِمْرَأَةٌ / نِسَاءٌ","rom":"imraʾatun / nisāʾun","zh":"女人／女人们","a":"88c20b8e94a6"},{"ar":"طَالِبٌ / طُلَّابٌ","rom":"ṭālibun / ṭullābun","zh":"学生（男）／学生们","a":"945dee2f88c6"},{"ar":"طَبِيبٌ / أَطِبَّاءُ","rom":"ṭabībun / aṭibbāʾu","zh":"医生／医生们","a":"49ef05a5571d"},{"ar":"مَدْرَسَةٌ / مَدَارِسُ","rom":"madrasatun / madārisu","zh":"学校／学校（复数）","a":"ec5baf87e912"},{"ar":"مَدِينَةٌ / مُدُنٌ","rom":"madīnatun / mudunun","zh":"城市／城市（复数）","a":"ba8d3c44ab20"},{"ar":"يَوْمٌ / أَيَّامٌ","rom":"yawmun / ayyāmun","zh":"天／天（复数）","a":"591485369c94"},{"ar":"شَهْرٌ / أَشْهُرٌ","rom":"shahrun / ashurun","zh":"月／月（复数）","a":"dcecbac92a90"},{"ar":"صَدِيقٌ / أَصْدِقَاءُ","rom":"ṣadīqun / aṣdiqāʾu","zh":"朋友／朋友们","a":"df20c744ea38"},{"ar":"غُرْفَةٌ / غُرَفٌ","rom":"ghurfatun / ghurafun","zh":"房间／房间（复数）","a":"5b0bee62b454"},{"ar":"نَهْرٌ / أَنْهَارٌ","rom":"nahrun / anhārun","zh":"河／河（复数）","a":"df2aa04014a7"},{"ar":"سُوقٌ / أَسْوَاقٌ","rom":"sūqun / aswāqun","zh":"市场／市场（复数）","a":"275127a2aac9"},{"ar":"جَبَلٌ / جِبَالٌ","rom":"jabalun / jibālun","zh":"山／山（复数）","a":"c86c12e0a4e0"},{"ar":"بِنْتٌ / بَنَاتٌ","rom":"bintun / banātun","zh":"女孩／女孩们","a":"eeb3a2b0dce8"},{"ar":"أُخْتٌ / أَخَوَاتٌ","rom":"ukhtun / akhawātun","zh":"姐妹／姐妹们","a":"8a3fecdf221d"},{"ar":"دَرْسٌ / دُرُوسٌ","rom":"darsun / durūsun","zh":"课／课（复数）","a":"b677bbd4a4ee"},{"ar":"حَدِيقَةٌ / حَدَائِقُ","rom":"ḥadīqatun / ḥadāʾiqu","zh":"花园／花园（复数）","a":"7dec8edc6a67"},{"ar":"كَثِيرٌ / كَثِيرَةٌ","rom":"kathīrun / kathīratun","zh":"多的","a":"3bac363788ec"},{"ar":"قَلِيلٌ / قَلِيلَةٌ","rom":"qalīlun / qalīlatun","zh":"少的","a":"fa5757780cbb"},{"ar":"جَمْعٌ","rom":"jamʿun","zh":"复数（语法术语）","a":"ff01697ddd14"},{"ar":"مُفْرَدٌ","rom":"mufradun","zh":"单数（语法术语）","a":"11ef8fd87a11"},{"ar":"مُثَنَّى","rom":"muthannā","zh":"双数（语法术语）","a":"fbf9673fb68a"}],"examples":[{"ar":"الْمُعَلِّمُونَ فِي الْمَدْرَسَةِ.","rom":"al-muʿallimūna fī al-madrasati","zh":"老师们在学校里。","note":"规则阳性复数主格 -ūna，作起语","a":"365f07df3dac"},{"ar":"مَعَ الْمُعَلِّمِينَ.","rom":"maʿa al-muʿallimīna","zh":"和老师们一起（短语）。","note":"属格 -īna","a":"ae785a3c0e64"},{"ar":"رَأَيْتُ الْمُعَلِّمِينَ.","rom":"raʾaytu al-muʿallimīna","zh":"我看见了老师们。","note":"宾格也用 -īna","a":"e9db42704ed9"},{"ar":"الطَّالِبَاتُ فِي الْمَدْرَسَةِ.","rom":"aṭ-ṭālibātu fī al-madrasati","zh":"女学生们在学校里。","note":"规则阴性复数主格 -ātu","a":"ff6bbb374428"},{"ar":"مَعَ الطَّالِبَاتِ.","rom":"maʿa aṭ-ṭālibāti","zh":"和女学生们一起（短语）。","note":"属格 -āti","a":"93469f2ab3d7"},{"ar":"رَأَيْتُ الطَّالِبَاتِ.","rom":"raʾaytu aṭ-ṭālibāti","zh":"我看见了女学生们。","note":"宾格也用 -āti，不用 -a","a":"af392e57b6c4"},{"ar":"السَّيَّارَاتُ جَدِيدَةٌ.","rom":"as-sayyārātu jadīdatun","zh":"这些汽车是新的。","note":"物的复数配阴性单数谓语","a":"c4ac848e0ad5"},{"ar":"الْكُتُبُ الْجَدِيدَةُ.","rom":"al-kutubu al-jadīdatu","zh":"这些新书（短语）。","note":"物的复数配阴性单数定语","a":"d859f5e683cd"},{"ar":"الْبُيُوتُ الْكَبِيرَةُ.","rom":"al-buyūtu al-kabīratu","zh":"这些大房子（短语）。","note":"物的复数用阴性单数","a":"9da1b8a5ae5f"},{"ar":"الْكُتُبُ جَدِيدَةٌ.","rom":"al-kutubu jadīdatun","zh":"这些书是新的。","note":"谓语也用阴性单数","a":"cc70100acedd"},{"ar":"الْبُيُوتُ كَبِيرَةٌ.","rom":"al-buyūtu kabīratun","zh":"这些房子很大。","note":"同上","a":"afe971307d8b"},{"ar":"الطُّلَّابُ الْمُجْتَهِدُونَ.","rom":"aṭ-ṭullābu al-mujtahidūna","zh":"这些用功的男学生（短语）。","note":"指人的复数用阳性复数形容词","a":"124b6b722b37"},{"ar":"الطَّالِبَاتُ الْمُجْتَهِدَاتُ.","rom":"aṭ-ṭālibātu al-mujtahidātu","zh":"这些用功的女学生（短语）。","note":"指人的阴性复数用 -āt","a":"4207b213d2a8"},{"ar":"الطُّلَّابُ كَثِيرُونَ.","rom":"aṭ-ṭullābu kathīrūna","zh":"学生们很多。","note":"理性复数的谓语用阳性复数","a":"0fdc3b7dcb81"},{"ar":"الْكِتَابَانِ الْجَدِيدَانِ.","rom":"al-kitābāni al-jadīdāni","zh":"这两本新书（短语）。","note":"双数：名词和形容词都加 ـَانِ","a":"c9007da1b0a2"},{"ar":"الطَّالِبَانِ مُجْتَهِدَانِ.","rom":"aṭ-ṭālibāni mujtahidāni","zh":"这两名学生很用功。","note":"双数谓语","a":"16d9d138147f"},{"ar":"مَعَ الطَّالِبَيْنِ.","rom":"maʿa aṭ-ṭālibayni","zh":"和这两名学生一起（短语）。","note":"双数属格 -ayni","a":"c0ce71306b25"},{"ar":"كِتَابَا الطَّالِبِ.","rom":"kitābā aṭ-ṭālibi","zh":"这名学生的两本书（短语）。","note":"双数作正次，ن 掉了","a":"b5f29c3508f9"},{"ar":"الْأَوْلَادُ فِي الْحَدِيقَةِ.","rom":"al-awlādu fī al-ḥadīqati","zh":"男孩们在花园里。","note":"أَوْلَادٌ 是 وَلَدٌ 的破碎复数","a":"956234ac42c1"},{"ar":"النِّسَاءُ فِي السُّوقِ.","rom":"an-nisāʾu fī as-sūqi","zh":"女人们在市场里。","note":"اِمْرَأَةٌ 的复数是 نِسَاءٌ","a":"eb76a296ec59"},{"ar":"الْأَطِبَّاءُ فِي الْمَدِينَةِ.","rom":"al-aṭibbāʾu fī al-madīnati","zh":"医生们在这座城市里。","note":"أَطِبَّاءُ 是 طَبِيبٌ 的破碎复数","a":"bcb3ecfbb7c5"},{"ar":"أَيَّامُ الصَّيْفِ حَارَّةٌ.","rom":"ayyāmu aṣ-ṣayfi ḥārratun","zh":"夏天的日子很热。","note":"非理性复数作起语，谓语用阴性单数","a":"e3e7fddaab64"},{"ar":"الْغُرَفُ نَظِيفَةٌ.","rom":"al-ghurafu naẓīfatun","zh":"这些房间很干净。","note":"غُرْفَةٌ 的复数是 غُرَفٌ","a":"d94e27d876ec"},{"ar":"الدُّرُوسُ صَعْبَةٌ.","rom":"ad-durūsu ṣaʿbatun","zh":"这些课很难。","note":"دَرْسٌ 的复数是 دُرُوسٌ","a":"8b2fd07bb2ff"},{"ar":"الْبَنَاتُ فِي الْبَيْتِ.","rom":"al-banātu fī al-bayti","zh":"女孩们在家里。","note":"بِنْتٌ 的复数是 بَنَاتٌ","a":"043ed6723792"}],"drills":[{"q":"كِتَابٌ 的复数是什么？","a":"كُتُبٌ"},{"q":"بَيْتٌ 的复数是什么？","a":"بُيُوتٌ"},{"q":"مَدْرَسَةٌ 的复数是什么？","a":"مَدَارِسُ"},{"q":"اِمْرَأَةٌ 的复数是什么？","a":"نِسَاءٌ"},{"q":"规则阳性复数的主格词尾是什么？","a":"ـُونَ"},{"q":"规则阳性复数的宾格、属格词尾是什么？","a":"ـِينَ"},{"q":"规则阴性复数的主格词尾是什么？","a":"ـَاتٌ"},{"q":"「这些书是新的」怎么说？","a":"الْكُتُبُ جَدِيدَةٌ"},{"q":"「这些男学生很用功」怎么说？","a":"الطُّلَّابُ مُجْتَهِدُونَ"},{"q":"双数的主格词尾是什么？","a":"ـَانِ"},{"q":"双数的宾格、属格词尾是什么？","a":"ـَيْنِ"},{"q":"非理性名词的复数，形容词要用什么形式？","a":"阴性单数"}],"tips":["破碎复数没有统一规则，单数和复数要当成一对词来背，别指望从单数推出来。","物的复数一律按阴性单数处理：الْكُتُبُ جَدِيدَةٌ，不能跟着名词写成阳性复数。","规则阳性复数主格 -ūna、宾格属格 -īna，写的时候 ن 不能丢。","规则阴性复数的宾格也用 ـَاتٍ（读 -ātin），不用 -a，这是它唯一的特殊之处。","规则阳性复数作正次时，ن 要掉：مُعَلِّمُو الْمَدْرَسَةِ（muʿallimū al-madrasati，学校的老师们）。","双数只表示「两个」，三个以上才用复数；双数作正次时，ن 同样要掉。"],"id":"ch3-s5"}],"id":"ch3"},{"title":"第四章 动词与动词句","sections":[{"title":"第十七节 过去式变位","concepts":[{"title":"1. 这一节学完你能做什么","body":"学完这一节，你能说出「我写了」「他去了」「我们吃了」这类已经发生的事，也能一眼看出一个动词的主语是谁——因为阿拉伯语把「谁做的」直接写进动词的尾巴里。这一节还要建立一个比背变位更要紧的东西：词根意识。"},{"title":"2. 动词的核心是三母词根","body":"阿拉伯语的动词绝大多数都从一个三字母的「词根（جِذْرٌ，jidhrun）」长出来。ك-ت-ب 这三个字母表示「写」，往这个骨架里塞不同的元音、加不同的前后缀，就长出一整族词：كَتَبَ（kataba，他写了）、يَكْتُبُ（yaktubu，他写）、كَاتِبٌ（kātibun，作家）、كِتَابٌ（kitābun，书）、مَكْتَبٌ（maktabun，办公室、书桌）。\n词根只负责「意思的骨架」，元音和词型负责「语法身份」。所以学动词的第一步不是背一整串形式，而是先认词根。看到 مَكْتَبٌ 里有 k-t-b，就知道它跟「写、记录」有关；看到 كِتَابٌ 也是同一族。中文母语者容易把每个词当成独立的整体硬背，阿拉伯语这样学会很累，先认词根能省一半力气。"},{"title":"3. 过去式 = 词干 + 人称后缀","body":"过去式（الْمَاضِي，al-māḍī）的造法很整齐：拿过去式词干 كَتَبْ-，后面粘一个人称后缀，后缀只回答一个问题——谁做的。第一人称单数加 ـتُ（-tu），得到 كَتَبْتُ（katabtu，我写了）；第二人称阳性加 ـتَ（-ta），是 كَتَبْتَ（katabta，你写了）；阴性把同一个 ـتَ 换成 ـتِ（-ti），成了 كَتَبْتِ（katabti，你写了）。第一人称复数加 ـنَا（-nā）：كَتَبْنَا（katabnā，我们写了）。\n第三人称的尾巴是另外一套：阳性单数什么都不加，就是 كَتَبَ（kataba，他写了）；阴性加 ـتْ（-at），كَتَبَتْ（katabat，她写了）；阳性复数在词尾加 -ū，写成 كَتَبُوا（katabū，他们写了）；阴性复数加 ـنَ（-na），كَتَبْنَ（katabna，她们写了）。\n双数（正好两个人）用 ـَا（-ā）和 ـَتَا（-atā）：كَتَبَا（katabā，他俩写了）、كَتَبَتَا（katabatā，她俩写了）。这里已经能看出规律：辅音骨架 k-t-b 一动没动，变的全是尾巴。阿拉伯语动词变位，本质上是「换尾巴」。"},{"title":"4. 13 个人称一张表","body":"表里最后一行是尊称。阿拉伯语没有专门的「您」字，礼貌场合直接用复数「你们」（أَنْتُمْ，antum），或者用 حَضْرَتُكَ（ḥaḍratuka，阁下、您），动词形式跟第二人称阳性单数完全一样。另外补一个表里没列的形式：第二人称双数「你们俩」是 كَتَبْتُمَا（katabtumā），只比 كَتَبْتُمْ 多一个 ا，双数在阿拉伯语里是独立的「数」，后面会反复遇到。","tables":[{"header":["人称","阿拉伯语","转写","中文"],"rows":[["我（أَنَا）","كَتَبْتُ","katabtu","我写了"],["你（男，أَنْتَ）","كَتَبْتَ","katabta","你写了"],["你（女，أَنْتِ）","كَتَبْتِ","katabti","你写了"],["他（هُوَ）","كَتَبَ","kataba","他写了"],["她（هِيَ）","كَتَبَتْ","katabat","她写了"],["我们（نَحْنُ）","كَتَبْنَا","katabnā","我们写了"],["你们（男，أَنْتُمْ）","كَتَبْتُمْ","katabtum","你们写了"],["你们（女，أَنْتُنَّ）","كَتَبْتُنَّ","katabtunna","你们写了"],["他俩（هُمَا）","كَتَبَا","katabā","他俩写了"],["她俩（هُمَا）","كَتَبَتَا","katabatā","她俩写了"],["他们（هُمْ）","كَتَبُوا","katabū","他们写了"],["她们（هُنَّ）","كَتَبْنَ","katabna","她们写了"],["您（حَضْرَتُكَ）","كَتَبْتَ","katabta","您写了"]]}]},{"title":"5. 词典形与阴性形式","body":"查阿拉伯语词典，动词一律按「过去式第三人称阳性单数」排，也就是 هُوَ 的那个形式：كَتَبَ（kataba）、ذَهَبَ（dhahaba）、فَهِمَ（fahima）。这个形式不带任何人称后缀，是原形，也是背单词时要背的形式。看到 كَتَبْتُ 想查词典，要先把 ـتُ 去掉，还原成 كَتَبَ 再查。\n阴性单数只加 ـتْ：كَتَبَتْ（katabat，她写了）。这个 ـتْ 上的 سُكُون（sukūn，静音符号）一定要写出来，读的时候也不能再加元音，否则听起来像 كَتَبَتَ。"},{"title":"6. 动词句的语序：动词在前","body":"过去式最常出现在动词句（الْجُمْلَةُ الْفِعْلِيَّةُ，al-jumlatu al-fiʿliyyatu）里。阿拉伯语动词句的常规顺序是「动词 + 主语 + 宾语」，跟汉语的「主语 + 动词 + 宾语」正好相反：كَتَبَ أَحْمَدُ رِسَالَةً（kataba aḥmadu risālatan，艾哈迈德写了一封信）。\n主语用主格 -u，宾语用宾格 -an，规则和名词句一样，只是位置换了。还有一个必须记住的细节：动词跑到主语前面时，动词用单数，而且要与主语的性别一致——阳性用 كَتَبَ，阴性用 كَتَبَتْ。كَتَبَ الطُّلَّابُ الدَّرْسَ（kataba aṭ-ṭullābu ad-darsa，学生们写了这一课），不能说 كَتَبُوا الطُّلَّابُ；主语换成阴性复数就说 كَتَبَتِ الطَّالِبَاتُ（katabati aṭ-ṭālibātu，女学生们写了）。"}],"vocab":[{"ar":"كَتَبَ","rom":"kataba","zh":"写","a":"1a31c3cbb834"},{"ar":"قَرَأَ","rom":"qaraʾa","zh":"读","a":"6962f4cf6457"},{"ar":"ذَهَبَ","rom":"dhahaba","zh":"去","a":"440735301132"},{"ar":"جَلَسَ","rom":"jalasa","zh":"坐","a":"99f363151346"},{"ar":"أَكَلَ","rom":"akala","zh":"吃","a":"783cd38be9d8"},{"ar":"شَرِبَ","rom":"shariba","zh":"喝","a":"e5b226a6ba0b"},{"ar":"فَتَحَ","rom":"fataḥa","zh":"打开","a":"cefd56d1dba6"},{"ar":"أَخَذَ","rom":"akhadha","zh":"拿、取","a":"161735a9f641"},{"ar":"سَمِعَ","rom":"samiʿa","zh":"听","a":"698f9b8de727"},{"ar":"فَهِمَ","rom":"fahima","zh":"懂、明白","a":"9f50eaf32f77"},{"ar":"عَرَفَ","rom":"ʿarafa","zh":"认识、知道","a":"1db12710ab72"},{"ar":"سَأَلَ","rom":"saʾala","zh":"问","a":"336255ee83d6"},{"ar":"دَرَسَ","rom":"darasa","zh":"学习","a":"a534bf110d1a"},{"ar":"عَمِلَ","rom":"ʿamila","zh":"工作、做","a":"2073d9572934"},{"ar":"رَجَعَ","rom":"rajaʿa","zh":"回来","a":"3557af65d49c"},{"ar":"سَافَرَ","rom":"sāfara","zh":"旅行","a":"97153b5c2c85"},{"ar":"نَظَرَ","rom":"naẓara","zh":"看","a":"2eabb9ab58b6"},{"ar":"تَعَلَّمَ","rom":"taʿallama","zh":"学会","a":"51a0d82501b8"},{"ar":"كَتَبْتُ","rom":"katabtu","zh":"我写了","a":"c65e1c6ae87b"},{"ar":"كَتَبْتَ","rom":"katabta","zh":"你写了（男）","a":"524ad47ab25b"},{"ar":"كَتَبْتِ","rom":"katabti","zh":"你写了（女）","a":"8989ff6ed438"},{"ar":"كَتَبَتْ","rom":"katabat","zh":"她写了","a":"0f44a250fbed"},{"ar":"كَتَبْنَا","rom":"katabnā","zh":"我们写了","a":"692b4322d0ff"},{"ar":"كَتَبْتُمْ","rom":"katabtum","zh":"你们写了（男）","a":"af3bbc178459"},{"ar":"كَتَبْتُنَّ","rom":"katabtunna","zh":"你们写了（女）","a":"4e36f907cac8"},{"ar":"كَتَبُوا","rom":"katabū","zh":"他们写了","a":"ea3d23036943"},{"ar":"كَتَبْنَ","rom":"katabna","zh":"她们写了","a":"f799049d4893"},{"ar":"كَتَبَا","rom":"katabā","zh":"他俩写了","a":"d0fa7d37ff26"},{"ar":"كَتَبَتَا","rom":"katabatā","zh":"她俩写了","a":"e297e636daac"},{"ar":"جِذْرٌ","rom":"jidhrun","zh":"词根","a":"d0a6c1a5e56a"},{"ar":"فِعْلٌ","rom":"fiʿlun","zh":"动词","a":"92e6305d3978"},{"ar":"الْمَاضِي","rom":"al-māḍī","zh":"过去式","a":"3d4d60ec8c41"},{"ar":"فَاعِلٌ","rom":"fāʿilun","zh":"主语、动作的发出者","a":"82cd739ec851"},{"ar":"ضَمِيرٌ","rom":"ḍamīrun","zh":"代词","a":"a37ee5cbcebe"},{"ar":"الْغَائِبُ","rom":"al-ghāʾibu","zh":"第三人称","a":"43bf14211e1a"}],"examples":[{"ar":"كَتَبْتُ.","rom":"katabtu","zh":"我写了。","note":"第一人称单数后缀 ـتُ","a":"412c95d24ff1"},{"ar":"كَتَبَ.","rom":"kataba","zh":"他写了。","note":"第三人称阳性单数没有后缀","a":"6fa89e4bb5c5"},{"ar":"كَتَبَتْ.","rom":"katabat","zh":"她写了。","note":"阴性加 ـتْ","a":"c63993e88fad"},{"ar":"كَتَبُوا.","rom":"katabū","zh":"他们写了。","note":"阳性复数，词尾读 -ū","a":"ef12279211aa"},{"ar":"كَتَبْنَ.","rom":"katabna","zh":"她们写了。","note":"阴性复数 ـنَ","a":"59e48c3c7aa0"},{"ar":"كَتَبْنَا الْوَاجِبَ.","rom":"katabnā al-wājiba","zh":"我们写了作业。","note":"ـنَا 表示我们；宾语用宾格 -a","a":"37189ec6451f"},{"ar":"كَتَبْتُ رِسَالَةً.","rom":"katabtu risālatan","zh":"我写了一封信。","note":"宾语泛指，用宾格鼻音符 -an","a":"accb79386512"},{"ar":"كَتَبْتَ الدَّرْسَ.","rom":"katabta ad-darsa","zh":"你写了这一课。","note":"ـتَ 指男性；د 是太阳字母","a":"49d971e8c85d"},{"ar":"كَتَبْتِ الْجَوَابَ.","rom":"katabti al-jawāba","zh":"你写了答案。（对女性）","note":"ـتِ 的 kasra 是女性标志","a":"e084290f7b62"},{"ar":"كَتَبَ أَحْمَدُ رِسَالَةً.","rom":"kataba aḥmadu risālatan","zh":"艾哈迈德写了一封信。","note":"动词 + 主语主格 -u + 宾语宾格 -an","a":"b3646829933c"},{"ar":"كَتَبَتْ فَاطِمَةُ الرِّسَالَةَ.","rom":"katabat fāṭimatu ar-risālata","zh":"法蒂玛写了这封信。","note":"阴性动词配阴性主语","a":"e72a55ac8f9d"},{"ar":"كَتَبَ الطُّلَّابُ الدَّرْسَ.","rom":"kataba aṭ-ṭullābu ad-darsa","zh":"学生们写了这一课。","note":"主语是复数，动词仍用单数阳性","a":"9e14950ed57f"},{"ar":"كَتَبْتُنَّ الدَّرْسَ.","rom":"katabtunna ad-darsa","zh":"你们（女）写了这一课。","note":"ـتُنَّ 专指女性复数","a":"f3b074f21d3f"},{"ar":"كَتَبَا الرِّسَالَةَ.","rom":"katabā ar-risālata","zh":"他俩写了这封信。","note":"双数 ـَا","a":"b7e27bc77c42"},{"ar":"كَتَبَتَا الدَّرْسَ.","rom":"katabatā ad-darsa","zh":"她俩写了这一课。","note":"阴性双数 ـَتَا","a":"dcba214e2b77"},{"ar":"ذَهَبْتُ إِلَى الْمَدْرَسَةِ.","rom":"dhahabtu ilā al-madrasati","zh":"我去了学校。","note":"إِلَى 后面用属格 -i","a":"e74677054c0f"},{"ar":"جَلَسْنَا فِي الْغُرْفَةِ.","rom":"jalasnā fī al-ghurfati","zh":"我们坐在房间里。","note":"فِي 后面用属格","a":"6f4c96a53528"},{"ar":"شَرِبْتُ الْمَاءَ.","rom":"sharibtu al-māʾa","zh":"我喝了水。","note":"الْمَاء 作宾语用宾格 -a","a":"21357cd31dc7"},{"ar":"قَرَأْتُ الْكِتَابَ.","rom":"qaraʾtu al-kitāba","zh":"我读了这本书。","note":"词根第三个字母是 hamza，照样加后缀","a":"7f8ce82e083d"},{"ar":"فَتَحَ الطَّالِبُ الْبَابَ.","rom":"fataḥa aṭ-ṭālibu al-bāba","zh":"学生打开了门。","note":"动词 + 主语 + 宾语","a":"aad017cf1e63"},{"ar":"سَمِعْتُ صَوْتَهُ.","rom":"samiʿtu ṣawtahu","zh":"我听见了他的声音。","note":"正偏组合 + 代词后缀","a":"169296c5a464"},{"ar":"فَهِمْتُ الدَّرْسَ جَيِّدًا.","rom":"fahimtu ad-darsa jayyidan","zh":"我很好地理解了这一课。","note":"جَيِّدًا 作状语，用宾格","a":"ad42a9a6ab16"},{"ar":"سَافَرَ أَخِي إِلَى مِصْرَ.","rom":"sāfara akhī ilā miṣra","zh":"我兄弟去了埃及。","note":"مِصْرَ 不带鼻音符","a":"f704f78915ea"},{"ar":"رَجَعَ الطُّلَّابُ مِنَ الْمَدْرَسَةِ.","rom":"rajaʿa aṭ-ṭullābu mina al-madrasati","zh":"学生们从学校回来了。","note":"مِنْ 在冠词前读 مِنَ","a":"d2275bdb4669"},{"ar":"هَلْ كَتَبْتَ الْوَاجِبَ؟","rom":"hal katabta al-wājiba","zh":"你写作业了吗？","note":"هَلْ 加在过去式句首","a":"7869930c7790"},{"ar":"مَا كَتَبْتُ شَيْئًا.","rom":"mā katabtu shayʾan","zh":"我什么都没写。","note":"مَا 否定过去式","a":"2ade4330c946"}],"drills":[{"q":"「写」的过去式第三人称阳性单数是什么？","a":"كَتَبَ"},{"q":"「我写了」怎么说？","a":"كَتَبْتُ"},{"q":"「你写了」（对男性）怎么说？","a":"كَتَبْتَ"},{"q":"「她写了」怎么写？","a":"كَتَبَتْ"},{"q":"「我们写了」怎么说？","a":"كَتَبْنَا"},{"q":"「他们写了」怎么说？","a":"كَتَبُوا"},{"q":"「她们写了」怎么说？","a":"كَتَبْنَ"},{"q":"「你们（女）写了」怎么说？","a":"كَتَبْتُنَّ"},{"q":"「他俩写了」怎么说？","a":"كَتَبَا"},{"q":"查词典时看动词的哪个形式？","a":"过去式第三人称阳性单数（هُوَ）"},{"q":"كَتَبَ 的词根是哪三个字母？","a":"ك-ت-ب"},{"q":"「学生们写了这一课」怎么说？","a":"كَتَبَ الطُّلَّابُ الدَّرْسَ"}],"tips":["查词典只认第三人称阳性单数：كَتَبَ、ذَهَبَ、فَهِمَ，别的形式都是变出来的。","ـتُ、ـتَ、ـتِ 只差最后一个短元音，读错就换了人称，别把词尾吞掉。","阴性单数一定要写 سُكُون：كَتَبَتْ（katabat），写成 كَتَبَتَ 就错了。","主语是复数时动词仍用单数阳性：كَتَبَ الطُّلَّابُ，不说 كَتَبُوا الطُّلَّابُ。","「只加后缀、词根不变」说的是 كَتَبَ 这类三母健全动词；中间有 و 或 ي 的动词（如 قَالَ）会变形，后面再学。"],"id":"ch4-s1"},{"title":"第十八节 现在式变位","concepts":[{"title":"1. 这一节学完你能做什么","body":"学完这一节，你能说「我在写」「他每天去学校」「我们学阿拉伯语」这类现在发生、经常发生的事。现在式（الْمُضَارِعُ，al-muḍāriʿu）比过去式多一个零件：过去式只换尾巴，现在式连脑袋也要换。"},{"title":"2. 现在式是三件套：前缀 + 词干 + 后缀","body":"拿 كَتَبَ（kataba，他写了）来说，它的现在式是 يَكْتُبُ（yaktubu，他写）。这个形式由三段拼起来：开头 يَ 是前缀，中间的 كْتُب 是词干（词根 k-t-b 的骨架还在），末尾的 -u 是词尾。前缀管人称，后缀管数、性和阴阳，词干管意思。\n和过去式对照一下就很清楚：كَتَبَ 是「词干 + 零后缀」，يَكْتُبُ 是「前缀 + 词干 + 词尾」。所以背现在式不能只盯尾巴，要先看第一个字母。"},{"title":"3. 四个前缀记住人称","body":"现在式的前缀只有四个字母，背下来就抓住了一半：أَ 表示「我」，أَكْتُبُ（aktubu，我写）；نَ 表示「我们」，نَكْتُبُ（naktubu，我们写）；تَ 表示「你」和「她」，تَكْتُبُ（taktubu，你写、她写）；يَ 表示「他」，يَكْتُبُ（yaktubu，他写）。\n记忆法：按「我—我们—你—他」排成 أَ / نَ / تَ / يَ。تَ 一个人管一大片——全部第二人称（你男、你女、你俩、你们男、你们女），再加上第三人称阴性单数和双数，看着像偷懒，其实是阿拉伯语的老规矩——过去式里 ـتَ（你）和 ـتْ（她）也只差一个短元音，第二人称和阴性第三人称本来就贴得很近。"},{"title":"4. 13 个人称变位表","body":"表里有三对同形，必须靠上下文分辨：تَكْتُبُ 既是「你（男）写」也是「她写」；تَكْتُبَانِ 既是「她俩写」也是「你们俩写」；تَكْتُبُ 还是尊称「您写」。同形不可怕，阿拉伯语的习惯是主语一出现就分清了：تَكْتُبُ فَاطِمَةُ（taktubu fāṭimatu，法蒂玛在写）。\n词尾的变化规律也顺手记一下：阴性单数加 ـِينَ（-īna），阳性复数加 ـُونَ（-ūna），阴性复数加 ـْنَ（-na），双数加 ـَانِ（-āni）。剩下的形式词尾都是 -u。","tables":[{"header":["人称","阿拉伯语","转写","中文"],"rows":[["我（أَنَا）","أَكْتُبُ","aktubu","我写"],["你（男，أَنْتَ）","تَكْتُبُ","taktubu","你写"],["你（女，أَنْتِ）","تَكْتُبِينَ","taktubīna","你写"],["他（هُوَ）","يَكْتُبُ","yaktubu","他写"],["她（هِيَ）","تَكْتُبُ","taktubu","她写"],["我们（نَحْنُ）","نَكْتُبُ","naktubu","我们写"],["你们（男，أَنْتُمْ）","تَكْتُبُونَ","taktubūna","你们写"],["你们（女，أَنْتُنَّ）","تَكْتُبْنَ","taktubna","你们写"],["他俩（هُمَا）","يَكْتُبَانِ","yaktubāni","他俩写"],["她俩（هُمَا）","تَكْتُبَانِ","taktubāni","她俩写"],["他们（هُمْ）","يَكْتُبُونَ","yaktubūna","他们写"],["她们（هُنَّ）","يَكْتُبْنَ","yaktubna","她们写"],["您（حَضْرَتُكَ）","تَكْتُبُ","taktubu","您写"]]}]},{"title":"5. 现在式与过去式对照","body":"横着背比竖着背有效：كَتَبْتُ / أَكْتُبُ、كَتَبَ / يَكْتُبُ、كَتَبُوا / يَكْتُبُونَ。三组一起记，前缀和词尾的关系就自动浮出来了。","tables":[{"header":["人称","过去式","现在式","中文"],"rows":[["我","كَتَبْتُ","أَكْتُبُ","我写"],["你（男）","كَتَبْتَ","تَكْتُبُ","你写"],["你（女）","كَتَبْتِ","تَكْتُبِينَ","你写"],["他","كَتَبَ","يَكْتُبُ","他写"],["她","كَتَبَتْ","تَكْتُبُ","她写"],["我们","كَتَبْنَا","نَكْتُبُ","我们写"],["你们（男）","كَتَبْتُمْ","تَكْتُبُونَ","你们写"],["你们（女）","كَتَبْتُنَّ","تَكْتُبْنَ","你们写"],["他俩","كَتَبَا","يَكْتُبَانِ","他俩写"],["她俩","كَتَبَتَا","تَكْتُبَانِ","她俩写"],["他们","كَتَبُوا","يَكْتُبُونَ","他们写"],["她们","كَتَبْنَ","يَكْتُبْنَ","她们写"],["您","كَتَبْتَ","تَكْتُبُ","您写"]]}]},{"title":"6. 词尾 -u 是主格，但它会变","body":"现在式的词尾一般读 -u，语法上叫直陈式（مَرْفُوعٌ，marfūʿun），也就是主格。这个 -u 不是永远都在：前面加 لَمْ（lam，没有）表示否定过去时，词尾变成 سُكُون，لَمْ أَكْتُبْ（lam aktub，我没写）；前面加 أَنْ（an，要、去）时，词尾变成 -a，أَنْ تَكْتُبَ（an taktuba，你写）。这两条先记个印象，后面讲否定式和虚拟式时会展开。\n还有一点要提前说：现在式本身不区分「正在」和「经常」，也不排斥将来。想明确指将来，就在前面加 سَـ（sa-）或 سَوْفَ（sawfa）：سَأَكْتُبُ（sa-aktubu，我将要写）。"}],"vocab":[{"ar":"أَكْتُبُ","rom":"aktubu","zh":"我写","a":"36fd8390a2b6"},{"ar":"تَكْتُبُ","rom":"taktubu","zh":"你写、她写","a":"b0c36189a73d"},{"ar":"تَكْتُبِينَ","rom":"taktubīna","zh":"你写（女）","a":"257d55dc69ec"},{"ar":"يَكْتُبُ","rom":"yaktubu","zh":"他写","a":"8db9132c7988"},{"ar":"نَكْتُبُ","rom":"naktubu","zh":"我们写","a":"c76816a0a83f"},{"ar":"تَكْتُبُونَ","rom":"taktubūna","zh":"你们写（男）","a":"ddff4f063c53"},{"ar":"تَكْتُبْنَ","rom":"taktubna","zh":"你们写（女）","a":"b38e1ac4d243"},{"ar":"يَكْتُبَانِ","rom":"yaktubāni","zh":"他俩写","a":"63ca4d5c7cef"},{"ar":"يَكْتُبُونَ","rom":"yaktubūna","zh":"他们写","a":"aa4b95f853bf"},{"ar":"يَكْتُبْنَ","rom":"yaktubna","zh":"她们写","a":"877bf399c839"},{"ar":"يَذْهَبُ","rom":"yadhhabu","zh":"去","a":"780f745b45a3"},{"ar":"يَجْلِسُ","rom":"yajlisu","zh":"坐","a":"876b30bb6749"},{"ar":"يَأْكُلُ","rom":"yaʾkulu","zh":"吃","a":"512756fed6cf"},{"ar":"يَشْرَبُ","rom":"yashrabu","zh":"喝","a":"977242f922bd"},{"ar":"يَقْرَأُ","rom":"yaqraʾu","zh":"读","a":"c68e48c7c3d3"},{"ar":"يَفْتَحُ","rom":"yaftaḥu","zh":"打开","a":"d58525a77962"},{"ar":"يَفْهَمُ","rom":"yafhamu","zh":"懂","a":"0d4e65a6cdaa"},{"ar":"يَسْمَعُ","rom":"yasmaʿu","zh":"听","a":"c1f854329b3e"},{"ar":"يَعْمَلُ","rom":"yaʿmalu","zh":"工作、做","a":"7f8de03828df"},{"ar":"يَدْرُسُ","rom":"yadrusu","zh":"学习","a":"df96c73f87f4"},{"ar":"يَرْجِعُ","rom":"yarjiʿu","zh":"回来","a":"fe97fdc1619c"},{"ar":"يَتَعَلَّمُ","rom":"yataʿallamu","zh":"学会","a":"8ffe7ac55ba2"},{"ar":"يَنْظُرُ","rom":"yanẓuru","zh":"看","a":"d7de218f8196"},{"ar":"يَسْأَلُ","rom":"yasʾalu","zh":"问","a":"054b96c8abe6"},{"ar":"الْمُضَارِعُ","rom":"al-muḍāriʿu","zh":"现在式","a":"8125b507595f"},{"ar":"السَّابِقَةُ","rom":"as-sābiqatu","zh":"前缀","a":"4d2e38fb4958"},{"ar":"اللَّاحِقَةُ","rom":"al-lāḥiqatu","zh":"后缀","a":"a1be3bf6805a"},{"ar":"الْآنَ","rom":"al-āna","zh":"现在","a":"8cf9507b20f7"},{"ar":"كُلَّ يَوْمٍ","rom":"kulla yawmin","zh":"每天","a":"c327ef0660ee"},{"ar":"صَبَاحًا","rom":"ṣabāḥan","zh":"早上","a":"6961ebb80db1"},{"ar":"مَسَاءً","rom":"masāʾan","zh":"傍晚","a":"aaae3c2fa1a7"},{"ar":"غَدًا","rom":"ghadan","zh":"明天","a":"7268f632e353"}],"examples":[{"ar":"أَكْتُبُ.","rom":"aktubu","zh":"我写。","note":"前缀 أَ 表示第一人称单数","a":"3b2387f77f72"},{"ar":"تَكْتُبُ.","rom":"taktubu","zh":"你写。","note":"前缀 تَ 表示第二人称","a":"b7a622a1a1d2"},{"ar":"يَكْتُبُ.","rom":"yaktubu","zh":"他写。","note":"前缀 يَ 表示第三人称阳性","a":"62eb46a3faa6"},{"ar":"نَكْتُبُ.","rom":"naktubu","zh":"我们写。","note":"前缀 نَ 表示第一人称复数","a":"36405b580a49"},{"ar":"تَكْتُبِينَ.","rom":"taktubīna","zh":"你写。（对女性）","note":"阴性单数加 ـِينَ","a":"46667807a77a"},{"ar":"تَكْتُبْنَ.","rom":"taktubna","zh":"你们写。（对女性）","note":"阴性复数加 ـْنَ","a":"c967f7c20bbd"},{"ar":"يَكْتُبْنَ.","rom":"yaktubna","zh":"她们写。","note":"阴性复数也用 ـْنَ","a":"53bfab7f02a8"},{"ar":"أَكْتُبُ رِسَالَةً.","rom":"aktubu risālatan","zh":"我在写一封信。","note":"现在式可以表示正在做","a":"822dc74f8f29"},{"ar":"تَكْتُبُ الدَّرْسَ.","rom":"taktubu ad-darsa","zh":"你在写这一课。","note":"宾语确指，用宾格 -a","a":"df07cde70ae6"},{"ar":"يَكْتُبُ أَحْمَدُ رِسَالَةً.","rom":"yaktubu aḥmadu risālatan","zh":"艾哈迈德在写一封信。","note":"动词 + 主语 + 宾语","a":"0952ea71125f"},{"ar":"تَكْتُبُ فَاطِمَةُ الدَّرْسَ.","rom":"taktubu fāṭimatu ad-darsa","zh":"法蒂玛在写这一课。","note":"「她」用 تَ + 阴性主语","a":"a050a21c0ac0"},{"ar":"نَكْتُبُ الْوَاجِبَ مَعًا.","rom":"naktubu al-wājiba maʿan","zh":"我们一起写作业。","note":"نَ 表示我们","a":"8891ee85e2c5"},{"ar":"تَكْتُبُونَ الْوَاجِبَ.","rom":"taktubūna al-wājiba","zh":"你们在写作业。","note":"阳性复数 ـُونَ","a":"97f7cbab3550"},{"ar":"يَكْتُبَانِ الرِّسَالَةَ.","rom":"yaktubāni ar-risālata","zh":"他俩在写这封信。","note":"双数 ـَانِ","a":"f2e88ebdaed8"},{"ar":"تَكْتُبَانِ الدَّرْسَ.","rom":"taktubāni ad-darsa","zh":"她俩在写这一课。","note":"阴性双数只差前缀","a":"77a6c73318e9"},{"ar":"يَكْتُبُونَ الرِّسَالَةَ.","rom":"yaktubūna ar-risālata","zh":"他们在写这封信。","note":"阳性复数 ـُونَ","a":"9c56cd75fca9"},{"ar":"أَذْهَبُ إِلَى الْمَدْرَسَةِ كُلَّ يَوْمٍ.","rom":"adhhabu ilā al-madrasati kulla yawmin","zh":"我每天去学校。","note":"现在式表示习惯","a":"0fb7315ce203"},{"ar":"يَذْهَبُ أَبِي إِلَى الْعَمَلِ صَبَاحًا.","rom":"yadhhabu abī ilā al-ʿamali ṣabāḥan","zh":"我父亲早上去上班。","note":"صَبَاحًا 是时间状语","a":"1b9e5b2fcdfe"},{"ar":"نَجْلِسُ فِي الْغُرْفَةِ.","rom":"najlisu fī al-ghurfati","zh":"我们坐在房间里。","note":"فِي 后面用属格","a":"f82be136e822"},{"ar":"يَأْكُلُ الْأَوْلَادُ الْخُبْزَ.","rom":"yaʾkulu al-awlādu al-khubza","zh":"孩子们在吃面包。","note":"主语复数，动词仍用单数","a":"ba876c672354"},{"ar":"أَشْرَبُ الْمَاءَ كَثِيرًا.","rom":"ashrabu al-māʾa kathīran","zh":"我喝很多水。","note":"كَثِيرًا 作状语","a":"3d4022f0fa6a"},{"ar":"يَقْرَأُ الطَّالِبُ الْكِتَابَ.","rom":"yaqraʾu aṭ-ṭālibu al-kitāba","zh":"学生在读这本书。","note":"قَرَأَ 的词根第三个字母是 hamza","a":"a46e66a9f752"},{"ar":"هَلْ تَفْهَمُ الدَّرْسَ؟","rom":"hal tafhamu ad-darsa","zh":"你懂这一课吗？","note":"هَلْ + 现在式","a":"b5c5407bc5d3"},{"ar":"لَمْ أَكْتُبْ شَيْئًا.","rom":"lam aktub shayʾan","zh":"我什么都没写。","note":"لَمْ 后面词尾变 سُكُون","a":"793e930d7eff"},{"ar":"مَاذَا تَكْتُبُ الْآنَ؟","rom":"mādhā taktubu al-āna","zh":"你现在在写什么？","note":"疑问词 + 现在式","a":"e7679caf78be"},{"ar":"أَنْتَ تَكْتُبُ وَأَنَا أَقْرَأُ.","rom":"anta taktubu wa-anā aqraʾu","zh":"你写，我读。","note":"两个现在式并列","a":"f97d2038935e"},{"ar":"يَرْجِعُ الطُّلَّابُ مِنَ الْمَدْرَسَةِ مَسَاءً.","rom":"yarjiʿu aṭ-ṭullābu mina al-madrasati masāʾan","zh":"学生们傍晚从学校回来。","note":"时间状语放句末","a":"4dbe4ab860a2"},{"ar":"أَدْرُسُ الْعَرَبِيَّةَ كُلَّ يَوْمٍ.","rom":"adrusu al-ʿarabiyyata kulla yawmin","zh":"我每天学阿拉伯语。","note":"现在式 + 频率状语","a":"1081c6453207"}],"drills":[{"q":"「我写」怎么说？","a":"أَكْتُبُ"},{"q":"「他写」怎么说？","a":"يَكْتُبُ"},{"q":"「我们写」怎么说？","a":"نَكْتُبُ"},{"q":"「你写」（对女性）怎么说？","a":"تَكْتُبِينَ"},{"q":"「他们写」怎么说？","a":"يَكْتُبُونَ"},{"q":"「她们写」怎么说？","a":"يَكْتُبْنَ"},{"q":"「他俩写」怎么说？","a":"يَكْتُبَانِ"},{"q":"现在式里表示「我」的前缀是哪个？","a":"أَ"},{"q":"现在式里表示「我们」的前缀是哪个？","a":"نَ"},{"q":"现在式里 تَ 能表示哪几个人称？","a":"全部第二人称（你男、你女、你俩、你们男、你们女），加上第三人称阴性单数和双数"},{"q":"كَتَبَ 的现在式第三人称阳性单数是什么？","a":"يَكْتُبُ"},{"q":"لَمْ 后面的现在式词尾怎么读？","a":"读 سُكُون，如 لَمْ أَكْتُبْ"}],"tips":["先看第一个字母定人称，再看最后一个字母定数和性，两头都看才不会乱。","تَ 是三合一的：你（男）、你（女）、她，区别全在后缀上，主语一出现就分得清。","现在式词尾 -u 是主格；遇到 لَمْ 变 سُكُون（لَمْ يَكْتُبْ），遇到 أَنْ 变 -a（أَنْ يَكْتُبَ）。","阴性复数 ـْنَ 收 -na，阳性复数 ـُونَ 收 -ūna，两个尾巴长得像，别混。","现在式也守「复数主语 + 单数动词」的规矩：يَأْكُلُ الْأَوْلَادُ，不说 يَأْكُلُونَ الْأَوْلَادُ。"],"id":"ch4-s2"},{"title":"第十九节 命令式","concepts":[{"title":"1. 这一节学完你能做什么","body":"学完这一节，你能说「写！」「去学校！」「别在这儿坐」，也能把命令说得客气一点——用 مِنْ فَضْلِكَ（min faḍlika，请）或者 هَلْ يُمْكِنُكَ أَنْ…（hal yumkinuka an…，您能不能…）代替硬邦邦的命令。命令式（الْأَمْرُ，al-amru）只对「你」说话，形式比前两节少得多。"},{"title":"2. 命令式只对第二人称","body":"命令是「我对你说」，所以只有第二人称有命令式：你（男）、你（女）、你们俩、你们（男）、你们（女），再加上礼貌的「您」。第一人称「我」和第三人称「他」没有命令式——你不能命令自己，也不能命令一个不在场的第三者。这一点和汉语一样，汉语也不会说「我写！」来表示命令。"},{"title":"3. 三步造出命令式","body":"规则只有三步。第一步，取第二人称的现在式；第二步，去掉开头的前缀 تَ；第三步，看剩下的部分开头有没有辅音丛——如果第一个字母带着 سُكُون、没法直接起头，就在前面加一个连接 hamza（هَمْزَةُ الْوَصْلِ，hamzatu al-waṣli），比如 تَكْتُبُ → كْتُبْ → اُكْتُبْ、تَسْمَعُ → سْمَعْ → اِسْمَعْ；如果去掉前缀后词首本来就是带元音的字母，就直接说，不加 hamza，比如 يَأْكُلُ → كُلْ。\n以 تَكْتُبُ（taktubu，你写）为例：去掉 تَ 剩下 كْتُبْ，这是辅音开头的「光杆」，阿拉伯语不允许这样起头，于是加 hamza 变成 اُكْتُبْ（uktub，写！）。تَذْهَبُ（tadhhabu，你去）去掉 تَ 是 ذْهَبْ，加 hamza 成 اِذْهَبْ（idhhab，去！）。تَجْلِسُ（tajlisu，你坐）去掉 تَ 是 جْلِسْ，加 hamza 成 اِجْلِسْ（ijlis，坐！）。","tables":[{"header":["现在式（你）","去前缀","命令式","转写"],"rows":[["تَكْتُبُ","كْتُبْ","اُكْتُبْ","uktub"],["تَذْهَبُ","ذْهَبْ","اِذْهَبْ","idhhab"],["تَجْلِسُ","جْلِسْ","اِجْلِسْ","ijlis"],["تَفْتَحُ","فْتَحْ","اِفْتَحْ","iftaḥ"],["تَشْرَبُ","شْرَبْ","اِشْرَبْ","ishrab"],["تَدْرُسُ","دْرُسْ","اُدْرُسْ","udrus"],["تَنْظُرُ","نْظُرْ","اُنْظُرْ","unẓur"]]}]},{"title":"4. hamza 读 u 还是 i","body":"连接 hamza 的元音不是随便定的，它跟着词干中间那个元音走。词干中间是 u，hamza 就读 u：اُكْتُبْ（uktub）、اُدْرُسْ（udrus）、اُنْظُرْ（unẓur）。词干中间是 a 或 i，hamza 就读 i：اِذْهَبْ（idhhab）、اِجْلِسْ（ijlis）、اِفْتَحْ（iftaḥ）。\n记忆法：只有「胖元音」u 才配「胖 hamza」u，其余一律配细的 i。这一条要背，写错了虽然也能猜出意思，但读出来是错的，阿拉伯人一听就知道你没记牢。"},{"title":"5. 命令式的六个人称","body":"去掉前缀以后，第二人称的各种尾巴都原样保留：阴性单数的 ـِينَ 变成 ـِي（اُكْتُبِي），双数的 ـَانِ 变成 ـَا（اُكْتُبَا），阳性复数的 ـُونَ 变成 ـُوا（اُكْتُبُوا），阴性复数的 ـْنَ 不变（اُكْتُبْنَ）。尊称用复数形式 اُكْتُبُوا，和「你们写」同形。","tables":[{"header":["人称","阿拉伯语","转写","中文"],"rows":[["你（男）","اُكْتُبْ","uktub","你写！"],["你（女）","اُكْتُبِي","uktubī","你写！"],["你们俩","اُكْتُبَا","uktubā","你们俩写！"],["你们（男）","اُكْتُبُوا","uktubū","你们写！"],["你们（女）","اُكْتُبْنَ","uktubna","你们写！"],["您（尊称）","اُكْتُبُوا","uktubū","您写！"]]}]},{"title":"6. 禁止式与礼貌请求","body":"否定命令（禁止）不用命令式，而是 لَا 加第二人称现在式，而且词尾要读 سُكُون：لَا تَكْتُبْ（lā taktub，别写）、لَا تَذْهَبْ（lā tadhhab，别去）、لَا تَجْلِسْ（lā tajlis，别坐）。这里的 لَا 叫「禁止的 لَا」，跟普通否定的 لَا 不是一回事：لَا تَكْتُبُ（lā taktubu，你不写）是陈述事实，لَا تَكْتُبْ（lā taktub，别写）才是禁止，差别只在词尾一个元音。\n日常请人做事，阿拉伯语更常用客气的说法，不直接甩命令式。مِنْ فَضْلِكَ（min faḍlika，请、劳驾）后面接 أَنْ 加现在式：مِنْ فَضْلِكَ أَنْ تَكْتُبَ اسْمَكَ هُنَا（min faḍlika an taktuba ismaka hunā，请您把名字写在这儿）。同类的还有 هَلْ يُمْكِنُكَ أَنْ…（hal yumkinuka an…，您能不能…）和 أَرْجُو أَنْ…（arjū an…，请您…）。在办公室、商店、跟陌生人说话时，这几句几乎是默认选项，直接说 اُكْتُبْ 会显得像在使唤人。"}],"vocab":[{"ar":"اُكْتُبْ","rom":"uktub","zh":"你写！","a":"47dd2dfa2e63"},{"ar":"اُكْتُبِي","rom":"uktubī","zh":"你写！（对女性）","a":"ba9e31c0fa3d"},{"ar":"اُكْتُبُوا","rom":"uktubū","zh":"你们写！","a":"2b01f4b2544d"},{"ar":"اُكْتُبْنَ","rom":"uktubna","zh":"你们写！（对女性）","a":"af174aa73514"},{"ar":"اُكْتُبَا","rom":"uktubā","zh":"你们俩写！","a":"9f4b6848be90"},{"ar":"اِذْهَبْ","rom":"idhhab","zh":"去！","a":"e7d6fdf80f0e"},{"ar":"اِجْلِسْ","rom":"ijlis","zh":"坐！","a":"4d191a5ade18"},{"ar":"اِفْتَحْ","rom":"iftaḥ","zh":"打开！","a":"c96e74f8e364"},{"ar":"اِشْرَبْ","rom":"ishrab","zh":"喝！","a":"f3352bab2891"},{"ar":"اِقْرَأْ","rom":"iqraʾ","zh":"读！","a":"9b2fdb619ef4"},{"ar":"اِسْمَعْ","rom":"ismaʿ","zh":"听！","a":"4088df1480c2"},{"ar":"اِفْهَمْ","rom":"ifham","zh":"懂！","a":"d8d374e818f1"},{"ar":"اِعْمَلْ","rom":"iʿmal","zh":"做！、工作！","a":"bef9e373ff2a"},{"ar":"اُدْرُسْ","rom":"udrus","zh":"学习！","a":"9d064752ca08"},{"ar":"اِرْجِعْ","rom":"irjiʿ","zh":"回来！","a":"3acb312551b3"},{"ar":"اُنْظُرْ","rom":"unẓur","zh":"看！","a":"72949560ba5b"},{"ar":"لَا تَكْتُبْ","rom":"lā taktub","zh":"别写！","a":"9617d5c88a85"},{"ar":"لَا تَذْهَبْ","rom":"lā tadhhab","zh":"别去！","a":"df58958a762b"},{"ar":"لَا تَجْلِسْ","rom":"lā tajlis","zh":"别坐！","a":"2b1889ad2aba"},{"ar":"مِنْ فَضْلِكَ","rom":"min faḍlika","zh":"请、劳驾","a":"38991703b8fd"},{"ar":"أَرْجُو","rom":"arjū","zh":"我请求、劳驾","a":"d5f6bccb93d9"},{"ar":"لَوْ سَمَحْتَ","rom":"law samaḥta","zh":"如果您允许","a":"b0754fbd63cb"},{"ar":"هَلْ يُمْكِنُ","rom":"hal yumkin","zh":"能不能、可以吗","a":"08cb11a4873c"},{"ar":"الْأَمْرُ","rom":"al-amru","zh":"命令式","a":"0c81e237df1f"},{"ar":"هَمْزَةُ الْوَصْلِ","rom":"hamzatu al-waṣli","zh":"连接 hamza","a":"28cf2dd40962"},{"ar":"السَّابِقَةُ","rom":"as-sābiqatu","zh":"前缀","a":"4d2e38fb4958"},{"ar":"اسْمٌ","rom":"ismun","zh":"名字","a":"f44a34d2e01f"},{"ar":"وَاجِبٌ","rom":"wājibun","zh":"作业","a":"d5d25e10863d"},{"ar":"سَبُّورَةٌ","rom":"sabbūratun","zh":"黑板","a":"39102ff23b9a"},{"ar":"كُرْسِيٌّ","rom":"kursiyyun","zh":"椅子","a":"f8c06dec5141"},{"ar":"مَكْتَبٌ","rom":"maktabun","zh":"办公室、书桌","a":"9b5fb3903fdf"}],"examples":[{"ar":"اُكْتُبْ!","rom":"uktub","zh":"写！","note":"一个词就是一句话","a":"57ae45159061"},{"ar":"اُكْتُبْ رِسَالَةً.","rom":"uktub risālatan","zh":"写一封信。","note":"命令 + 宾语，宾格 -an","a":"c25612f7f0e7"},{"ar":"اُكْتُبِي الدَّرْسَ.","rom":"uktubī ad-darsa","zh":"你（女）写这一课。","note":"阴性命令式加 ـِي","a":"77888325bfe3"},{"ar":"اُكْتُبُوا الْوَاجِبَ.","rom":"uktubū al-wājiba","zh":"你们写作业。","note":"阳性复数 ـُوا","a":"64d10edf4a4d"},{"ar":"اُكْتُبْنَ الدَّرْسَ.","rom":"uktubna ad-darsa","zh":"你们（女）写这一课。","note":"阴性复数 ـْنَ","a":"65a66decef7b"},{"ar":"اِذْهَبْ إِلَى الْمَدْرَسَةِ.","rom":"idhhab ilā al-madrasati","zh":"去学校。","note":"hamza 读 i，词干元音是 a","a":"a717824fcf42"},{"ar":"اِجْلِسْ هُنَا.","rom":"ijlis hunā","zh":"坐这儿。","note":"词干元音 i，hamza 也读 i","a":"e79e11ac4a07"},{"ar":"اِفْتَحِ الْبَابَ.","rom":"iftaḥi al-bāba","zh":"把门打开。","note":"后接 الْ 时 سُكُون 读成 kasra","a":"b14c6ccf5238"},{"ar":"اِشْرَبِ الْمَاءَ.","rom":"ishrabi al-māʾa","zh":"喝水。","note":"同上，词尾 ـبْ 读成 -bi","a":"c58bcd21b6ec"},{"ar":"اِقْرَأِ الْكِتَابَ.","rom":"iqraʾi al-kitāba","zh":"读这本书。","note":"词根第三个字母是 hamza，去掉 تَ 后词首是 قْ 辅音丛，照样加连接 hamza","a":"139beb0fb119"},{"ar":"اِسْمَعْ جَيِّدًا.","rom":"ismaʿ jayyidan","zh":"好好听。","note":"جَيِّدًا 作状语","a":"f06d8a8dfc31"},{"ar":"اِفْهَمِ الدَّرْسَ.","rom":"ifhami ad-darsa","zh":"弄懂这一课。","note":"后接 الدَّرْس 读成 -mi d-","a":"f0d9558d1da9"},{"ar":"اُدْرُسْ كُلَّ يَوْمٍ.","rom":"udrus kulla yawmin","zh":"每天学习。","note":"词干元音 u，hamza 读 u","a":"9e5bcfc7f479"},{"ar":"اِرْجِعْ إِلَى الْبَيْتِ.","rom":"irjiʿ ilā al-bayti","zh":"回家。","note":"إِلَى 后面用属格","a":"d75b4c711e33"},{"ar":"اُنْظُرْ إِلَى السَّبُّورَةِ.","rom":"unẓur ilā as-sabbūrati","zh":"看黑板。","note":"词干元音 u，hamza 读 u","a":"cc3dce374c04"},{"ar":"لَا تَكْتُبْ هُنَا.","rom":"lā taktub hunā","zh":"别在这儿写。","note":"禁止的 لَا + 现在式，词尾 سُكُون","a":"2489b6074261"},{"ar":"لَا تَذْهَبْ وَحْدَكَ.","rom":"lā tadhhab waḥdaka","zh":"别一个人去。","note":"وَحْدَكَ 作状语","a":"c1332fad0575"},{"ar":"لَا تَجْلِسْ عَلَى الْكُرْسِيِّ.","rom":"lā tajlis ʿalā al-kursiyyi","zh":"别坐在椅子上。","note":"عَلَى 后面用属格","a":"4ff0330d0413"},{"ar":"مِنْ فَضْلِكَ أَنْ تَكْتُبَ اسْمَكَ هُنَا.","rom":"min faḍlika an taktuba ismaka hunā","zh":"请您把名字写在这儿。","note":"أَنْ 后面的现在式词尾读 -a","a":"2d91db9ced3a"},{"ar":"أَرْجُو أَنْ تَجْلِسَ.","rom":"arjū an tajlisa","zh":"请您坐下。","note":"أَرْجُو + أَنْ + 虚拟式","a":"40d02b101f02"},{"ar":"هَلْ يُمْكِنُكَ أَنْ تَفْتَحَ الْبَابَ؟","rom":"hal yumkinuka an taftaḥa al-bāba","zh":"你能开一下门吗？","note":"比命令式客气得多","a":"663b9db3573d"},{"ar":"لَوْ سَمَحْتَ، اُنْظُرْ إِلَى هَذَا.","rom":"law samaḥta, unẓur ilā hādhā","zh":"劳驾，看一下这个。","note":"لَوْ سَمَحْتَ 是客套话","a":"0505fa8f4523"},{"ar":"مِنْ فَضْلِكَ لَا تَجْلِسْ هُنَا.","rom":"min faḍlika lā tajlis hunā","zh":"请您别坐这儿。","note":"客套话 + 禁止式","a":"56d6b704817a"},{"ar":"اُكْتُبِ اسْمَكَ ثُمَّ اُكْتُبِ التَّارِيخَ.","rom":"uktubi ismaka thumma uktubi at-tārīkha","zh":"先写名字，再写日期。","note":"ثُمَّ 连接两个命令","a":"49ba5d88fe3e"},{"ar":"لَا تَنْسَ وَاجِبَكَ.","rom":"lā tansa wājibaka","zh":"别忘了你的作业。","note":"تَنْسَى 是缺尾动词，لَا 后面省掉词尾 alif","a":"a2a0c9eb24d5"}],"drills":[{"q":"تَكْتُبُ 的命令式（对你，男）怎么写？","a":"اُكْتُبْ"},{"q":"تَذْهَبُ 的命令式怎么写？","a":"اِذْهَبْ"},{"q":"تَجْلِسُ 的命令式怎么写？","a":"اِجْلِسْ"},{"q":"تَدْرُسُ 的命令式怎么写？","a":"اُدْرُسْ"},{"q":"连接 hamza 什么时候读 u？","a":"词干中间元音是 u 时（如 اُكْتُبْ、اُدْرُسْ）"},{"q":"「你们（男）写！」怎么说？","a":"اُكْتُبُوا"},{"q":"「你（女）写！」怎么说？","a":"اُكْتُبِي"},{"q":"「别写」怎么说？","a":"لَا تَكْتُبْ"},{"q":"「别去」怎么说？","a":"لَا تَذْهَبْ"},{"q":"「请」的客气说法（加在请求前）是什么？","a":"مِنْ فَضْلِكَ"},{"q":"命令式能对哪些人称发命令？","a":"只对第二人称（你、你们）"}],"tips":["命令式只对「你」说，第一、第三人称没有命令式。","连接 hamza 的读法跟词干元音走：u 配 اُ，a 和 i 配 اِ。","命令式后面接 الْ 开头的词，词尾的 سُكُون 要读成 kasra：اِفْتَحِ الْبَابَ。","لَا تَكْتُبُ（你不写）是陈述，لَا تَكْتُبْ（别写）才是禁止，只差词尾一个元音。","请人做事用 مِنْ فَضْلِكَ 或 هَلْ يُمْكِنُكَ أَنْ… 比直接命令客气得多。"],"id":"ch4-s3"},{"title":"第二十节 动词句","concepts":[{"title":"1. 这一节学完你能做什么","body":"学完这一节，你能说出「学生写了这一课」「男孩在喝牛奶」「老师问了那个学生」这样的完整句子，也能一眼看出句子里谁是主语、谁是宾语。阿拉伯语的句子只有两大类，上一章学的名词句是其中一类，这一节学另一类：动词句。分工很简单——说「谁做了什么」用动词句，说「谁是什么、怎么样」用名词句。"},{"title":"2. 两类句子：名词句和动词句","body":"名词句（جُمْلَةٌ اِسْمِيَّةٌ，jumlatun ismiyyatun）以名词开头，由起语和谓语两部分组成，中间不加「是」：الطَّالِبُ مُجْتَهِدٌ（aṭ-ṭālibu mujtahidun，这个学生很用功）。\n动词句（جُمْلَةٌ فِعْلِيَّةٌ，jumlatun fiʿliyyatun）以动词开头，动词后面跟主语，再跟宾语：كَتَبَ الطَّالِبُ الدَّرْسَ（kataba aṭ-ṭālibu ad-darsa，学生写了这一课）。\n两类句子的区别不在长短，而在**第一个词是什么词**。第一个词是名词，就是名词句；第一个词是动词，就是动词句。这个判断法很好用：看到一个句子，先看它头一个词。"},{"title":"3. 动词句的语序：动词永远在最前","body":"动词句的固定语序是「动词 + 主语 + 宾语」。汉语说「学生写了这一课」，主语打头；阿拉伯语反过来，动词打头：كَتَبَ الطَّالِبُ الدَّرْسَ（kataba aṭ-ṭālibu ad-darsa，学生写了这一课）。\n拆开看：كَتَبَ 是动词「写了」，الطَّالِبُ 是主语「学生」，الدَّرْسَ 是宾语「这一课」。三块按这个顺序排，不能颠倒。\n动词在最前面，是动词句的招牌。一旦主语跑到动词前面，句子就换了一副面孔，第 6 点会细说。\n还有一点：宾语不是必须的。像 ذَهَبَ（dhahaba，去了）这类不及物动词，后面直接跟介词短语，或者什么都不跟：ذَهَبَ أَحْمَدُ إِلَى الْمَدْرَسَةِ（dhahaba aḥmadu ilā al-madrasati，艾哈迈德去了学校）。这里的 إِلَى الْمَدْرَسَةِ 不是宾语，是介词短语，所以它用属格 -i，不是宾格 -a。"},{"title":"4. 主语和宾语：靠格区分，不靠位置","body":"主语（فَاعِلٌ，fāʿilun）用主格，词尾读 -u；宾语（مَفْعُولٌ بِهِ，mafʿūlun bihi）用宾格，词尾读 -a。\n拿 كَتَبَ الطَّالِبُ الدَّرْسَ 拆开看：الطَّالِبُ 读 aṭ-ṭālibu，尾巴是 -u，主格，所以是主语；الدَّرْسَ 读 ad-darsa，尾巴是 -a，宾格，所以是宾语。\n顺序上主语在宾语前面，但真正决定身份的是词尾，不是位置。这一点在主语和宾语都是「人」的时候特别要紧：\nسَأَلَ الْمُعَلِّمُ الطَّالِبَ（saʾala al-muʿallimu aṭ-ṭāliba，老师问了那个学生）\nسَأَلَ الطَّالِبُ الْمُعَلِّمَ（saʾala aṭ-ṭālibu al-muʿallima，学生问了老师）\n两个句子的词序一模一样，只换了两个词的词尾，意思就反过来了。所以读阿拉伯语句子，眼睛要盯着词尾那个小符号，别只看词。"},{"title":"5. 动词跟主语一致，主语常常省略","body":"动词里已经含着主语的信息，所以主语通常不写出来：كَتَبْتُ（katabtu，我写了）里的 ـتُ 就是「我」，不用再说 أَنَا。写了 أَنَا 也不出错，只是多一层强调，等于说「是我写的」。\n主语是第三人称时，动词的形式要跟着主语的性和数走。但有个和汉语很不一样的地方：主语是双数或复数时，动词仍然用单数形式，只有阴性才把前缀换成 تَـ。\n过去式是同一套逻辑：阳性单数 كَتَبَ，阴性单数 كَتَبَتْ，双数和阳性复数还是 كَتَبَ，阴性复数还是 كَتَبَتْ。也就是说，过去式只分阳性和阴性，不再分单数复数。","tables":[{"header":["主语类型","例子","动词形式","说明"],"rows":[["阳性单数","الطَّالِبُ","يَكْتُبُ","基本形"],["阴性单数","الطَّالِبَةُ","تَكْتُبُ","前缀换成 تَـ"],["阳性双数","الطَّالِبَانِ","يَكْتُبُ","动词仍用单数"],["阴性双数","الطَّالِبَتَانِ","تَكْتُبُ","前缀换成 تَـ"],["阳性复数","الطُّلَّابُ","يَكْتُبُ","动词仍用单数"],["阴性复数","الطَّالِبَاتُ","تَكْتُبُ","前缀换成 تَـ"]]}]},{"title":"6. 什么时候用动词句，什么时候用名词句","body":"分两条：\n叙述一个动作、一件发生的事，用动词句。ذَهَبَ أَحْمَدُ إِلَى الْمَدْرَسَةِ（dhahaba aḥmadu ilā al-madrasati，艾哈迈德去了学校）说的是「发生了什么事」。\n描述状态、身份、性质，用名词句。أَحْمَدُ طَالِبٌ（aḥmadu ṭālibun，艾哈迈德是学生）说的是「他是什么人」；الْكِتَابُ جَدِيدٌ（al-kitābu jadīdun，这本书是新的）说的是「它怎么样」。\n汉语习惯把主语放前面，所以初学者很容易造出 الطَّالِبُ كَتَبَ الدَّرْسَ 这种句子。这不算错，但它已经不是动词句，而是名词句：الطَّالِبُ 是起语，كَتَبَ الدَّرْسَ 是谓语，语感上像「学生啊，他写了这一课」，重点落在「学生」身上。想平铺直叙地说一件事，就把动词放最前面。"}],"vocab":[{"ar":"جُمْلَةٌ","rom":"jumlatun","zh":"句子","a":"fe5620b914cc"},{"ar":"جُمْلَةٌ اِسْمِيَّةٌ","rom":"jumlatun ismiyyatun","zh":"名词句","a":"31bd4d8788ef"},{"ar":"جُمْلَةٌ فِعْلِيَّةٌ","rom":"jumlatun fiʿliyyatun","zh":"动词句","a":"45e91a12cb1a"},{"ar":"فَاعِلٌ","rom":"fāʿilun","zh":"主语、动作的发出者","a":"82cd739ec851"},{"ar":"مَفْعُولٌ بِهِ","rom":"mafʿūlun bihi","zh":"宾语","a":"69ab41e08fff"},{"ar":"كَتَبَ","rom":"kataba","zh":"写（过去式）","a":"1a31c3cbb834"},{"ar":"يَكْتُبُ","rom":"yaktubu","zh":"写（现在式）","a":"8db9132c7988"},{"ar":"قَرَأَ","rom":"qaraʾa","zh":"读（过去式）","a":"6962f4cf6457"},{"ar":"يَقْرَأُ","rom":"yaqraʾu","zh":"读（现在式）","a":"c68e48c7c3d3"},{"ar":"ذَهَبَ","rom":"dhahaba","zh":"去（过去式）","a":"440735301132"},{"ar":"يَذْهَبُ","rom":"yadhhabu","zh":"去（现在式）","a":"780f745b45a3"},{"ar":"أَكَلَ","rom":"akala","zh":"吃（过去式）","a":"783cd38be9d8"},{"ar":"يَأْكُلُ","rom":"yaʾkulu","zh":"吃（现在式）","a":"512756fed6cf"},{"ar":"شَرِبَ","rom":"shariba","zh":"喝（过去式）","a":"e5b226a6ba0b"},{"ar":"يَشْرَبُ","rom":"yashrabu","zh":"喝（现在式）","a":"977242f922bd"},{"ar":"فَتَحَ","rom":"fataḥa","zh":"打开（过去式）","a":"cefd56d1dba6"},{"ar":"يَفْتَحُ","rom":"yaftaḥu","zh":"打开（现在式）","a":"d58525a77962"},{"ar":"دَرَسَ","rom":"darasa","zh":"学习（过去式）","a":"a534bf110d1a"},{"ar":"يَدْرُسُ","rom":"yadrusu","zh":"学习（现在式）","a":"df96c73f87f4"},{"ar":"سَأَلَ","rom":"saʾala","zh":"问（过去式）","a":"336255ee83d6"},{"ar":"يَسْأَلُ","rom":"yasʾalu","zh":"问（现在式）","a":"054b96c8abe6"},{"ar":"طَالِبٌ","rom":"ṭālibun","zh":"学生（男）","a":"bea7c61ac7f5"},{"ar":"طَالِبَةٌ","rom":"ṭālibatun","zh":"学生（女）","a":"f69923af1ab2"},{"ar":"مُعَلِّمٌ","rom":"muʿallimun","zh":"老师（男）","a":"d3c46805be2a"},{"ar":"دَرْسٌ","rom":"darsun","zh":"课、功课","a":"d13ac4ee73ac"},{"ar":"تُفَّاحَةٌ","rom":"tuffāḥatun","zh":"苹果","a":"dbed82b302bd"},{"ar":"حَلِيبٌ","rom":"ḥalībun","zh":"牛奶","a":"f9a794056d46"},{"ar":"خُبْزٌ","rom":"khubzun","zh":"面包","a":"96ab68e09cee"},{"ar":"مَاءٌ","rom":"māʾun","zh":"水","a":"8bc24c13a697"},{"ar":"بَابٌ","rom":"bābun","zh":"门","a":"b7831c1d1303"},{"ar":"قِصَّةٌ","rom":"qiṣṣatun","zh":"故事","a":"54f7ebee463d"},{"ar":"رِسَالَةٌ","rom":"risālatun","zh":"信、书信","a":"fb6922a7983f"},{"ar":"سُؤَالٌ","rom":"suʾālun","zh":"问题","a":"ae22ad648daf"},{"ar":"جَوَابٌ","rom":"jawābun","zh":"回答","a":"499366d4785d"},{"ar":"لُغَةٌ","rom":"lughatun","zh":"语言","a":"a5689680ac79"},{"ar":"رَجُلٌ","rom":"rajulun","zh":"男人","a":"44767a34bc25"}],"examples":[{"ar":"كَتَبَ الطَّالِبُ الدَّرْسَ.","rom":"kataba aṭ-ṭālibu ad-darsa","zh":"学生写了这一课。","note":"动词 + 主格主语 + 宾格宾语","a":"ee6b86d67e5e"},{"ar":"يَكْتُبُ الطَّالِبُ الدَّرْسَ.","rom":"yaktubu aṭ-ṭālibu ad-darsa","zh":"学生正在写这一课。","note":"现在式动词开头","a":"21d8940b75c0"},{"ar":"قَرَأَ الْوَلَدُ الْكِتَابَ.","rom":"qaraʾa al-waladu al-kitāba","zh":"男孩读了这本书。","note":"الْوَلَد 是月字母，读 al-","a":"3c5e1972a3ab"},{"ar":"يَقْرَأُ الطِّفْلُ الْقِصَّةَ.","rom":"yaqraʾu aṭ-ṭiflu al-qiṣṣata","zh":"孩子在读这个故事。","note":"主语宾语都带 الْ，靠 -u 和 -a 区分","a":"5b49ebac1590"},{"ar":"ذَهَبَ أَحْمَدُ إِلَى الْمَدْرَسَةِ.","rom":"dhahaba aḥmadu ilā al-madrasati","zh":"艾哈迈德去了学校。","note":"专有名词作主语也带 -u","a":"de2e8e51b477"},{"ar":"يَذْهَبُ الْمُعَلِّمُ إِلَى الْبَيْتِ.","rom":"yadhhabu al-muʿallimu ilā al-bayti","zh":"老师回家去。","note":"不及物动词没有宾语","a":"52941c3c536c"},{"ar":"أَكَلَ الطِّفْلُ التُّفَّاحَةَ.","rom":"akala aṭ-ṭiflu at-tuffāḥata","zh":"孩子吃了那个苹果。","note":"宾语是阴性名词，宾格仍是 -a","a":"15617ea8dbf8"},{"ar":"يَأْكُلُ الرَّجُلُ الْخُبْزَ.","rom":"yaʾkulu ar-rajulu al-khubza","zh":"男人在吃面包。","note":"ر 是太阳字母，读 ar-","a":"71fc8906fe53"},{"ar":"شَرِبَ الْوَلَدُ الْحَلِيبَ.","rom":"shariba al-waladu al-ḥalība","zh":"男孩喝了牛奶。","note":"主语在前宾语在后，身份由格决定","a":"0c2b3eb6734d"},{"ar":"يَشْرَبُ الطَّالِبُ الْمَاءَ.","rom":"yashrabu aṭ-ṭālibu al-māʾa","zh":"学生在喝水。","note":"الْمَاء 的 ء 不能省","a":"f59cf18506fb"},{"ar":"فَتَحَ الرَّجُلُ الْبَابَ.","rom":"fataḥa ar-rajulu al-bāba","zh":"男人打开了门。","note":"最典型的动词句","a":"51d5b8fe088a"},{"ar":"يَفْتَحُ الطَّالِبُ الْكِتَابَ.","rom":"yaftaḥu aṭ-ṭālibu al-kitāba","zh":"学生打开书。","note":"现在式可表习惯也可表现在","a":"cf00db4e0e5e"},{"ar":"سَأَلَ الْمُعَلِّمُ الطَّالِبَ.","rom":"saʾala al-muʿallimu aṭ-ṭāliba","zh":"老师问了那个学生。","note":"主语 -u，宾语 -a","a":"44eb441a9d1d"},{"ar":"سَأَلَ الطَّالِبُ الْمُعَلِّمَ.","rom":"saʾala aṭ-ṭālibu al-muʿallima","zh":"学生问了老师。","note":"词序不变，只换词尾，意思就反了","a":"6a0971e5dcfb"},{"ar":"فَهِمَ الطَّالِبُ السُّؤَالَ.","rom":"fahima aṭ-ṭālibu as-suʾāla","zh":"学生明白了这个问题。","note":"س 是太阳字母，读 as-","a":"115566b40ee3"},{"ar":"يَفْهَمُ الطَّالِبُ الْجَوَابَ.","rom":"yafhamu aṭ-ṭālibu al-jawāba","zh":"学生明白这个回答。","note":"现在式词尾是 -u","a":"b5dec52fa2a4"},{"ar":"دَرَسَ الطَّالِبُ اللُّغَةَ الْعَرَبِيَّةَ.","rom":"darasa aṭ-ṭālibu al-lughata al-ʿarabiyyata","zh":"学生学了阿拉伯语。","note":"形容词跟被修饰语同格","a":"542f35ae6714"},{"ar":"تَكْتُبُ الطَّالِبَةُ الرِّسَالَةَ.","rom":"taktubu aṭ-ṭālibatu ar-risālata","zh":"女学生在写信。","note":"阴性主语，现在式加 تَـ","a":"8a7d30a46ede"},{"ar":"كَتَبَتِ الطَّالِبَةُ الدَّرْسَ.","rom":"katabati aṭ-ṭālibatu ad-darsa","zh":"女学生写了这一课。","note":"过去式阴性加 ـتْ，接 الْ 读 ـتِ","a":"026d2a3c436b"},{"ar":"يَكْتُبُ الطُّلَّابُ الدَّرْسَ.","rom":"yaktubu aṭ-ṭullābu ad-darsa","zh":"学生们在写这一课。","note":"复数主语，动词仍用单数","a":"68411a2bb720"},{"ar":"كَتَبَ الطُّلَّابُ الدَّرْسَ.","rom":"kataba aṭ-ṭullābu ad-darsa","zh":"学生们写了这一课。","note":"过去式也不随复数变","a":"9e14950ed57f"},{"ar":"تَكْتُبُ الطَّالِبَاتُ الدَّرْسَ.","rom":"taktubu aṭ-ṭālibātu ad-darsa","zh":"女学生们在写这一课。","note":"阴性复数动词加 تَـ","a":"95fbb93569aa"},{"ar":"يَكْتُبُ الطَّالِبَانِ الدَّرْسَ.","rom":"yaktubu aṭ-ṭālibāni ad-darsa","zh":"两个男生在写这一课。","note":"双数主语，动词仍用单数","a":"b81330b4789f"},{"ar":"أَنَا أَكْتُبُ الدَّرْسَ.","rom":"anā aktubu ad-darsa","zh":"我在写这一课。","note":"第一人称现在式加 أَ","a":"63456fc35554"},{"ar":"هُوَ يَكْتُبُ الدَّرْسَ.","rom":"huwa yaktubu ad-darsa","zh":"他在写这一课。","note":"写出代词是为了强调","a":"01c0903573e3"},{"ar":"الطَّالِبُ يَكْتُبُ الدَّرْسَ.","rom":"aṭ-ṭālibu yaktubu ad-darsa","zh":"学生（他）在写这一课。","note":"主语提前，整句变成名词句","a":"b0fecd9727cc"},{"ar":"الْكِتَابُ جَدِيدٌ.","rom":"al-kitābu jadīdun","zh":"这本书是新的。","note":"描述状态用名词句，不加动词","a":"234f3c14dc49"}],"drills":[{"q":"动词句的基本语序是什么？","a":"动词 + 主语 + 宾语"},{"q":"主语用什么格，词尾读什么？","a":"主格，-u"},{"q":"宾语用什么格，词尾读什么？","a":"宾格，-a"},{"q":"「学生写了这一课」怎么说？","a":"كَتَبَ الطَّالِبُ الدَّرْسَ"},{"q":"「男孩在喝牛奶」怎么说？","a":"يَشْرَبُ الْوَلَدُ الْحَلِيبَ"},{"q":"「女学生在写信」怎么说？","a":"تَكْتُبُ الطَّالِبَةُ الرِّسَالَةَ"},{"q":"把 كَتَبَ الطَّالِبُ الدَّرْسَ 改成现在式","a":"يَكْتُبُ الطَّالِبُ الدَّرْسَ"},{"q":"把 يَقْرَأُ الْوَلَدُ الْكِتَابَ 改成过去式","a":"قَرَأَ الْوَلَدُ الْكِتَابَ"},{"q":"「这本书是新的」该用哪种句子？","a":"名词句：الْكِتَابُ جَدِيدٌ"},{"q":"الطُّلَّابُ 作主语时，动词用单数还是复数？","a":"单数：يَكْتُبُ الطُّلَّابُ"}],"tips":["动词句的动词必须站在最前面；主语一提前，句子就变成名词句了。","主语 -u、宾语 -a，两个词都带 الْ 时全靠这个尾巴区分，读的时候别吞掉。","过去式阴性是 ـتْ，后面接 الْ 要读 ـتِ：كَتَبَتِ الطَّالِبَةُ。","主语是双数或复数时，动词仍用单数形式，只有阴性主语才把前缀换成 تَـ。","说「谁做了什么」用动词句，说「谁是什么、怎么样」用名词句。"],"id":"ch4-s4"},{"title":"第二十一节 否定","concepts":[{"title":"1. 这一节学完你能做什么","body":"学完这一节，你能把已经学过的句子全部改成否定句：「学生没写这一课」「我不明白这个」「这本书不是新的」「他明天不会来」。阿拉伯语的否定不是一个词管到底，而是按时间和句型分工：过去、现在、将来、名词句，各用各的否定词。先记住这张分工表，比背十条规则有用。"},{"title":"2. 五个否定词，按时间和句型分工","body":"同一个意思「学生没写这一课」，用不同的否定词写出来是这样：\n看这张表，只要盯两件事：用哪个词、后面动词的尾巴变不变。مَا 和 لَا 不动词尾，لَنْ 把 -u 变成 -a，لَمْ 把 -u 变成静音。这三档变化是这一节的全部难点。","tables":[{"header":["否定词","管什么","后面动词的词尾","意思"],"rows":[["مَا","过去式","不变","没做"],["لَا","现在式","不变，仍是 -u","不做、没在做"],["لَنْ","将来","变成宾格 -a","不会做"],["لَمْ","书面语的过去","变成静音 -ْ","没做"],["لَيْسَ","名词句","谓语变宾格 -an","不是"]]},{"header":["时间","肯定句","否定句","用的词"],"rows":[["过去","كَتَبَ الطَّالِبُ الدَّرْسَ.","مَا كَتَبَ الطَّالِبُ الدَّرْسَ.","مَا"],["现在","يَكْتُبُ الطَّالِبُ الدَّرْسَ.","لَا يَكْتُبُ الطَّالِبُ الدَّرْسَ.","لَا"],["将来","يَكْتُبُ الطَّالِبُ الدَّرْسَ غَدًا.","لَنْ يَكْتُبَ الطَّالِبُ الدَّرْسَ غَدًا.","لَنْ"],["书面语过去","كَتَبَ الطَّالِبُ الدَّرْسَ.","لَمْ يَكْتُبِ الطَّالِبُ الدَّرْسَ.","لَمْ"],["名词句","الْكِتَابُ جَدِيدٌ.","لَيْسَ الْكِتَابُ جَدِيدًا.","لَيْسَ"]]}]},{"title":"3. مَا：否定过去式","body":"مَا（mā，不、没有）放在过去式动词前面，动词的形式一个字母都不用改：\nمَا كَتَبَ الطَّالِبُ الدَّرْسَ（mā kataba aṭ-ṭālibu ad-darsa，学生没有写这一课）\n这句和肯定的 كَتَبَ الطَّالِبُ الدَّرْسَ 只差最前面一个 مَا，主语的 -u、宾语的 -a 全都不动。这正是 مَا 的好处：它只加一个词，不碰句子里的任何东西。\n再看几个：مَا ذَهَبَ إِلَى الْمَدْرَسَةِ（mā dhahaba ilā al-madrasati，他没有去学校），主语省掉了，因为动词 ذَهَبَ 已经说明是「他」；مَا فَهِمْتُ السُّؤَالَ（mā fahimtu as-suʾāla，我没明白这个问题），ـتُ 说明是「我」。\n要提醒一点：مَا 只回答「这件事过去发生没发生」，不掺别的语气。想强调「从来没有」，要另外加 أَبَدًا（abadan，从来不）。"},{"title":"4. لَا：否定现在式","body":"لَا（lā，不）放在现在式动词前面，动词照旧用主格 -u，一个符号都不变：\nلَا أَفْهَمُ هَذَا（lā afhamu hādhā，我不明白这个）\n这里的 أَفْهَمُ 还是 -u 结尾，和肯定句一模一样。لَا 否定现在式，管的是「现在不做」「平时不做」这两层意思：لَا يَشْرَبُ الْوَلَدُ الْحَلِيبَ（lā yashrabu al-waladu al-ḥalība，男孩不喝牛奶）说的是习惯；لَا يَكْتُبُ الطَّالِبُ الدَّرْسَ（lā yaktubu aṭ-ṭālibu ad-darsa，学生没在写这一课）说的是此刻。\n顺便分清两个 لَا：一个是句首单独用的「不」，用来回答是非问句；一个是放在动词前的否定词。两者写法读音都一样，看位置就能判断。\n**最常见的一个错误**：拿 لَا 去否定过去式。لَا كَتَبَ 是错的，过去的事必须用 مَا كَتَبَ。反过来，用 مَا 否定现在式（مَا يَكْتُبُ）在口语里能听到，但书面语不推荐，规范写法是 لَا يَكْتُبُ。这两条记住，能避开初学者一半的否定错误。"},{"title":"5. لَنْ 和 لَمْ：一个管将来，一个管书面语的过去","body":"لَنْ（lan，不会）加现在式，动词词尾从 -u 变成 -a，也就是变宾格：\nلَنْ أَكْتُبَ الرِّسَالَةَ（lan aktuba ar-risālata，我不会写这封信）\n对比一下就看清了：أَكْتُبُ 是 -u，أَكْتُبَ 是 -a。لَنْ 的语气比 لَا 硬，是「绝不会、断然不会」，所以它后面这个词尾变化不是可选项，漏了就错。\nلَمْ（lam，没有）也加现在式，但动词词尾从 -u 变成静音，也就是收成 -ْ，意思却是过去否定：\nلَمْ أَفْهَمْ（lam afham，我没明白）\nأَفْهَمُ 变成 أَفْهَمْ，尾巴上的 -u 没了。لَمْ 是书面语里的标准过去否定，新闻、文章里到处是它；口语里更常用 مَا。两者的意思差不多，但 لَمْ 常常暗示「到现在还没做」，مَا 更中性。\n这里有个连读的坑：لَمْ 后面的动词收成静音以后，如果下一个词带 الْ，两个辅音撞在一起读不出来，要在动词尾巴上加一个 ـِ：لَمْ يَكْتُبِ الطَّالِبُ الدَّرْسَ（lam yaktubi aṭ-ṭālibu ad-darsa，学生没有写这一课）。写的时候这个 ـِ 也要标上。"},{"title":"6. لَيْسَ：否定名词句，也构成否定疑问","body":"名词句里没有动词，所以 مَا、لَا、لَنْ、لَمْ 都用不上，要用 لَيْسَ（laysa，不是）。لَيْسَ 本身按过去式的规则变位，后面的谓语要变宾格，也就是读 -an：\nلَيْسَ الْكِتَابُ جَدِيدًا（laysa al-kitābu jadīdan，这本书不是新的）\n原来的名词句是 الْكِتَابُ جَدِيدٌ，加了 لَيْسَ 以后，جَدِيدٌ 变成 جَدِيدًا。这个「谓语变宾格」的规矩和 لَنْ 让动词变 -a 是同一回事，都是「这个词管着后面那个词」。\n否定疑问在 لَيْسَ 前面加一个 أَ，就成了「难道不是…吗」：أَلَيْسَ الْكِتَابُ جَدِيدًا؟（alaysa al-kitābu jadīdan，这本书不是新的吗）。变位落在 لَيْسَ 上，所以「你难道不是学生吗」是 أَلَسْتَ طَالِبًا؟（alasta ṭāliban）。\n动词句的否定疑问用 أَلَا：أَلَا تَفْهَمُ؟（alā tafhamu，你不明白吗）。أَلَا 比 هَلْ 多一层「我以为你明白」的意外语气。","tables":[{"header":["人称","变位","转写","中文"],"rows":[["أَنَا","لَسْتُ","lastu","我不是"],["أَنْتَ","لَسْتَ","lasta","你不是（男）"],["أَنْتِ","لَسْتِ","lasti","你不是（女）"],["هُوَ","لَيْسَ","laysa","他不是"],["هِيَ","لَيْسَتْ","laysat","她不是"],["نَحْنُ","لَسْنَا","lasnā","我们不是"],["أَنْتُمْ","لَسْتُمْ","lastum","你们不是"],["هُمْ","لَيْسُوا","laysū","他们不是"]]}]}],"vocab":[{"ar":"مَا","rom":"mā","zh":"不、没有（否定过去式）","a":"cf093c097b3b"},{"ar":"لَا","rom":"lā","zh":"不（否定现在式）","a":"2e27e0c97265"},{"ar":"لَنْ","rom":"lan","zh":"不会（否定将来）","a":"19d863d79063"},{"ar":"لَمْ","rom":"lam","zh":"没有（书面语否定过去）","a":"8215202e4c96"},{"ar":"لَيْسَ","rom":"laysa","zh":"不是","a":"855fa25c17aa"},{"ar":"لَسْتُ","rom":"lastu","zh":"我不是","a":"cfa728c114ab"},{"ar":"لَسْتَ","rom":"lasta","zh":"你不是（男）","a":"41e10478e3a1"},{"ar":"لَيْسَتْ","rom":"laysat","zh":"她不是","a":"19c6e4e502dd"},{"ar":"لَسْنَا","rom":"lasnā","zh":"我们不是","a":"6f6774815da7"},{"ar":"لَيْسُوا","rom":"laysū","zh":"他们不是","a":"abb74527623e"},{"ar":"أَلَيْسَ","rom":"alaysa","zh":"难道不是…吗","a":"1fe9376f4a6b"},{"ar":"أَلَا","rom":"alā","zh":"难道不…吗","a":"f5cdf37ad656"},{"ar":"نَعَمْ","rom":"naʿam","zh":"是、对","a":"f7443118d6d8"},{"ar":"أَبَدًا","rom":"abadan","zh":"从来不、绝不","a":"328ea31dbfd4"},{"ar":"غَدًا","rom":"ghadan","zh":"明天","a":"7268f632e353"},{"ar":"أَمْسِ","rom":"amsi","zh":"昨天","a":"c94257c727e0"},{"ar":"الْيَوْمَ","rom":"al-yawma","zh":"今天","a":"d4424cd307b4"},{"ar":"شَيْءٌ","rom":"shayʾun","zh":"东西、事情","a":"faa12087e330"},{"ar":"أَحَدٌ","rom":"aḥadun","zh":"任何人","a":"9926aaf5bdf0"},{"ar":"صَحِيحٌ","rom":"ṣaḥīḥun","zh":"正确的","a":"2716c485047e"},{"ar":"خَطَأٌ","rom":"khaṭaʾun","zh":"错误","a":"bf9843764f80"},{"ar":"يَكْتُبُ","rom":"yaktubu","zh":"写（现在式）","a":"8db9132c7988"},{"ar":"يَذْهَبُ","rom":"yadhhabu","zh":"去（现在式）","a":"780f745b45a3"},{"ar":"يَشْرَبُ","rom":"yashrabu","zh":"喝（现在式）","a":"977242f922bd"},{"ar":"يَفْهَمُ","rom":"yafhamu","zh":"明白（现在式）","a":"0d4e65a6cdaa"},{"ar":"يَأْكُلُ","rom":"yaʾkulu","zh":"吃（现在式）","a":"512756fed6cf"},{"ar":"نَدْرُسُ","rom":"nadrusu","zh":"我们学习","a":"b2c122bdf392"},{"ar":"رِسَالَةٌ","rom":"risālatun","zh":"信、书信","a":"fb6922a7983f"},{"ar":"سُؤَالٌ","rom":"suʾālun","zh":"问题","a":"ae22ad648daf"},{"ar":"حَلِيبٌ","rom":"ḥalībun","zh":"牛奶","a":"f9a794056d46"},{"ar":"طَعَامٌ","rom":"ṭaʿāmun","zh":"食物、饭菜","a":"c0c6dea5f5c8"},{"ar":"مُعَلِّمٌ","rom":"muʿallimun","zh":"老师（男）","a":"d3c46805be2a"},{"ar":"طَالِبٌ","rom":"ṭālibun","zh":"学生（男）","a":"bea7c61ac7f5"},{"ar":"جَدِيدٌ","rom":"jadīdun","zh":"新的","a":"bc60168bb745"}],"examples":[{"ar":"مَا كَتَبَ الطَّالِبُ الدَّرْسَ.","rom":"mā kataba aṭ-ṭālibu ad-darsa","zh":"学生没有写这一课。","note":"مَا 加过去式，动词不变","a":"185d016fb24b"},{"ar":"مَا ذَهَبَ إِلَى الْمَدْرَسَةِ.","rom":"mā dhahaba ilā al-madrasati","zh":"他没有去学校。","note":"主语省略，动词已含「他」","a":"bd88338f9d69"},{"ar":"مَا فَهِمْتُ السُّؤَالَ.","rom":"mā fahimtu as-suʾāla","zh":"我没明白这个问题。","note":"ـتُ 表示「我」","a":"34689bb8eba3"},{"ar":"مَا شَرِبَ الْوَلَدُ الْحَلِيبَ.","rom":"mā shariba al-waladu al-ḥalība","zh":"男孩没喝牛奶。","note":"宾语仍是宾格 -a","a":"20e9c3bba255"},{"ar":"لَا أَفْهَمُ هَذَا.","rom":"lā afhamu hādhā","zh":"我不明白这个。","note":"لَا 加现在式，词尾仍是 -u","a":"776305d69ff9"},{"ar":"لَا يَكْتُبُ الطَّالِبُ الدَّرْسَ.","rom":"lā yaktubu aṭ-ṭālibu ad-darsa","zh":"学生没在写这一课。","note":"否定此刻正在做的事","a":"05a867c7751f"},{"ar":"لَا يَشْرَبُ الْوَلَدُ الْحَلِيبَ.","rom":"lā yashrabu al-waladu al-ḥalība","zh":"男孩不喝牛奶。","note":"否定习惯","a":"96bb04d9ec6b"},{"ar":"لَا نَذْهَبُ إِلَى الْمَدْرَسَةِ يَوْمَ الْجُمُعَةِ.","rom":"lā nadhhabu ilā al-madrasati yawma al-jumuʿati","zh":"我们星期五不去学校。","note":"时间状语用宾格","a":"2dbe85915d5d"},{"ar":"لَا أَشْرَبُ الْحَلِيبَ أَبَدًا.","rom":"lā ashrabu al-ḥalība abadan","zh":"我从来不喝牛奶。","note":"أَبَدًا 加强否定","a":"c5d9b9976e26"},{"ar":"لَنْ أَكْتُبَ الرِّسَالَةَ.","rom":"lan aktuba ar-risālata","zh":"我不会写这封信。","note":"لَنْ 后面动词变 -a","a":"61506b302678"},{"ar":"لَنْ يَذْهَبَ إِلَى الْمَدْرَسَةِ.","rom":"lan yadhhaba ilā al-madrasati","zh":"他不会去学校。","note":"يَذْهَبُ 变 يَذْهَبَ","a":"9f1f58f40596"},{"ar":"لَنْ نَفْهَمَ هَذَا.","rom":"lan nafhama hādhā","zh":"我们不会明白这个。","note":"نَفْهَمُ 变 نَفْهَمَ","a":"41e4b16d3ce5"},{"ar":"لَنْ يَشْرَبَ الْوَلَدُ الْحَلِيبَ.","rom":"lan yashraba al-waladu al-ḥalība","zh":"男孩不会喝牛奶。","note":"宾语仍是 -a","a":"90a45466f5ef"},{"ar":"لَمْ يَكْتُبِ الطَّالِبُ الدَّرْسَ.","rom":"lam yaktubi aṭ-ṭālibu ad-darsa","zh":"学生没有写这一课。","note":"静音遇到 الْ 要读 ـِ","a":"2b0f69988167"},{"ar":"لَمْ أَفْهَمْ شَيْئًا.","rom":"lam afham shayʾan","zh":"我什么都没明白。","note":"شَيْء 带 ـًا 作宾语","a":"a360d475341a"},{"ar":"لَمْ يَذْهَبْ أَحَدٌ إِلَى الْمَدْرَسَةِ.","rom":"lam yadhhab aḥadun ilā al-madrasati","zh":"没有人去学校。","note":"主语不受否定词影响，仍是 -un","a":"fa9f213da02b"},{"ar":"لَمْ يَأْكُلِ الطِّفْلُ الطَّعَامَ.","rom":"lam yaʾkuli aṭ-ṭiflu aṭ-ṭaʿāma","zh":"孩子没吃饭。","note":"同样的连读规则","a":"3f46f98eb70c"},{"ar":"لَيْسَ الْكِتَابُ جَدِيدًا.","rom":"laysa al-kitābu jadīdan","zh":"这本书不是新的。","note":"谓语变宾格 -an","a":"be16dd047d1c"},{"ar":"لَيْسَ الطَّالِبُ مُعَلِّمًا.","rom":"laysa aṭ-ṭālibu muʿalliman","zh":"这个学生不是老师。","note":"لَيْسَ 加主格主语加宾格谓语","a":"cf210ae3ed2d"},{"ar":"لَسْتُ طَالِبًا.","rom":"lastu ṭāliban","zh":"我不是学生。","note":"لَيْسَ 随人称变 لَسْتُ","a":"a56a2e1b061c"},{"ar":"لَيْسَتِ الطَّالِبَةُ مُعَلِّمَةً.","rom":"laysati aṭ-ṭālibatu muʿallimatan","zh":"这个女学生不是老师。","note":"لَيْسَتْ 接 الْ 读 لَيْسَتِ","a":"e93203a1a48f"},{"ar":"لَسْنَا فِي الْبَيْتِ.","rom":"lasnā fī al-bayti","zh":"我们不在家。","note":"谓语是介词短语时不变格","a":"b8703244284a"},{"ar":"أَلَيْسَ الْكِتَابُ جَدِيدًا؟","rom":"alaysa al-kitābu jadīdan","zh":"这本书不是新的吗？","note":"أَ 加 لَيْسَ 构成反问","a":"f8eb9522540e"},{"ar":"أَلَسْتَ طَالِبًا؟","rom":"alasta ṭāliban","zh":"你难道不是学生吗？","note":"变位落在 لَيْسَ 上","a":"732b24f80125"},{"ar":"أَلَا تَفْهَمُ؟","rom":"alā tafhamu","zh":"你不明白吗？","note":"أَلَا 加现在式","a":"da6ef19de20d"},{"ar":"أَلَا تَشْرَبُ الْحَلِيبَ؟","rom":"alā tashrabu al-ḥalība","zh":"你不喝牛奶吗？","note":"语气比 هَلْ 更意外","a":"7556a8301a46"},{"ar":"لَا، أَنَا لَسْتُ طَالِبًا.","rom":"lā, anā lastu ṭāliban","zh":"不，我不是学生。","note":"句首的 لَا 是「不」","a":"1323ba195cd5"},{"ar":"نَعَمْ، أَنَا أَفْهَمُ.","rom":"naʿam, anā afhamu","zh":"是，我明白。","note":"نَعَمْ 用于肯定回答","a":"1e985834e030"}],"drills":[{"q":"否定过去式用哪个词？","a":"مَا"},{"q":"否定现在式用哪个词？","a":"لَا"},{"q":"否定将来用哪个词，后面动词什么词尾？","a":"لَنْ，宾格 -a"},{"q":"书面语否定过去、后面动词读静音的是哪个词？","a":"لَمْ"},{"q":"否定名词句用哪个词？","a":"لَيْسَ"},{"q":"把 كَتَبَ الطَّالِبُ الدَّرْسَ 改成否定句","a":"مَا كَتَبَ الطَّالِبُ الدَّرْسَ"},{"q":"把 يَذْهَبُ إِلَى الْمَدْرَسَةِ 改成将来否定","a":"لَنْ يَذْهَبَ إِلَى الْمَدْرَسَةِ"},{"q":"把 الْكِتَابُ جَدِيدٌ 改成否定句","a":"لَيْسَ الْكِتَابُ جَدِيدًا"},{"q":"「我不是学生」怎么说？","a":"لَسْتُ طَالِبًا"},{"q":"「你不明白吗？」用 أَلَا 怎么说？","a":"أَلَا تَفْهَمُ؟"}],"tips":["别用 لَا 否定过去：لَا كَتَبَ 是错的，过去要用 مَا كَتَبَ。","书面语里也别用 مَا 否定现在（口语可以），规范写法是 لَا يَكْتُبُ。","لَنْ 后面的动词一定要变 -a：لَنْ يَذْهَبَ，不是 لَنْ يَذْهَبُ。","لَمْ 后面的动词收静音；遇到后面的 الْ 要补一个 ـِ 才读得出来：لَمْ يَكْتُبِ الطَّالِبُ。","لَيْسَ 后面的谓语是名词时用 -an（جَدِيدًا），是介词短语时不变（لَسْنَا فِي الْبَيْتِ）。"],"id":"ch4-s5"},{"title":"第二十二节 كَانَ 与将来时","concepts":[{"title":"1. 这一节学完你能做什么","body":"学完这一节，你能把名词句搬到过去（「这本书以前是新的」），能说出「我明天会写这封信」「他将来会当老师」，还能说「我那时候正在图书馆学习」。三个工具分工明确：كَانَ 管过去，سَوْفَ 和 سَـ 管将来，كَانَ 加现在式管「过去的进行和过去的打算」。"},{"title":"2. كَانَ：把名词句整个搬到过去","body":"名词句 الْكِتَابُ جَدِيدٌ（al-kitābu jadīdun，这本书是新的）说的是现在。要说是过去，就在前面加 كَانَ（kāna，曾经是），但谓语要跟着变：جَدِيدٌ 变成 جَدِيدًا。\nكَانَ الْكِتَابُ جَدِيدًا（kāna al-kitābu jadīdan，这本书以前是新的）\n只加了一个词、改了一个符号，整句就从现在挪到了过去。原因在于 كَانَ 的脾气：它是「残缺动词」（فِعْلٌ نَاقِصٌ，fiʿlun nāqiṣun），自己不能独立表达一个完整的意思，必须靠一个主语和一个谓语把话补完。它管的主语用主格，叫「كَانَ 的主语」（اِسْمُ كَانَ，ismu kāna）；它管的谓语用宾格，叫「كَانَ 的谓语」（خَبَرُ كَانَ，khabaru kāna）。\n再体会几组：كَانَ الْبَيْتُ كَبِيرًا（kāna al-baytu kabīran，这房子以前很大）、كَانَ الطَّالِبُ مُجْتَهِدًا（kāna aṭ-ṭālibu mujtahidan，这个学生以前很用功）。谓语不管是名词还是形容词，只要跟在 كَانَ 后面，一律变 -an。\n要小心的是：谓语如果本来就是一个介词短语，就没有格可变。كُنَّا فِي الْبَيْتِ（kunnā fī al-bayti，我们那时在家）里，فِي الْبَيْتِ 保持原样，不能改成 فِي الْبَيْتَ。"},{"title":"3. كَانَ 的变位","body":"كَانَ 按过去式的规则变位，只是它中间的 ا 会让词形缩短，所以第一人称不是 كَانْتُ，而是 كُنْتُ。\n规律很清楚：第三人称保留 كَانَ- 的样子（阳性单数 كَانَ、阴性单数 كَانَتْ、阳性双数 كَانَا、阴性双数 كَانَتَا、阳性复数 كَانُوا），第一、二人称一律用 كُنْـ 开头，第三人称阴性复数则是 كُنَّ；后面都接和过去式一样的后缀。\n例句：كُنْتُ طَالِبًا（kuntu ṭāliban，我从前是学生）、كَانُوا طُلَّابًا（kānū ṭullāban，他们以前是学生）。注意 كَانُوا 后面跟复数谓语时，谓语还是宾格 طُلَّابًا。","tables":[{"header":["人称","变位","转写","中文"],"rows":[["أَنَا","كُنْتُ","kuntu","我曾经是"],["أَنْتَ","كُنْتَ","kunta","你曾经是（男）"],["أَنْتِ","كُنْتِ","kunti","你曾经是（女）"],["هُوَ","كَانَ","kāna","他曾经是"],["هِيَ","كَانَتْ","kānat","她曾经是"],["نَحْنُ","كُنَّا","kunnā","我们曾经是"],["أَنْتُمْ","كُنْتُمْ","kuntum","你们曾经是"],["هُمْ","كَانُوا","kānū","他们曾经是"]]}]},{"title":"4. 将来时：سَوْفَ 和 سَـ","body":"阿拉伯语没有专门的将来式动词，将来靠两个小词加现在式来表达，两种写法意思一样：\n第一种是 سَوْفَ（sawfa，将要），它是一个独立的词，后面空一格再接动词，语气偏「较远的将来」，也更正式：سَوْفَ أَكْتُبُ الرِّسَالَةَ（sawfa aktubu ar-risālata，我将会写这封信）。\n第二种是 سَـ（sa-，将要），它是一个前缀，必须紧贴动词写，中间不能空格，语气偏「较近的将来」，日常用得多：سَأَكْتُبُ الرِّسَالَةَ（saʾaktubu ar-risālata，我会写这封信）。\n两种写法后面，动词都保持现在式、保持主格 -u。这一点和第 21 节的 لَنْ 正好相反：لَنْ 后面变 -a，سَوْفَ 和 سَـ 后面不变。记住这个对照，时态和语气就不会混：\n还有个细节：سَـ 碰到 أَ 开头的人称，会写成 سَأَ，三个符号挤在一起，比如 سَأَكْتُبُ、سَأَذْهَبُ。别把它拆开写成 سَ أَكْتُبُ。\nكَانَ 本身也能放到将来：سَوْفَ يَكُونُ مُعَلِّمًا（sawfa yakūnu muʿalliman，他将来会当老师）。这里 يَكُونُ 是 كَانَ 的现在式，后面的谓语照样是宾格 مُعَلِّمًا。","tables":[{"header":["说法","例句","动词词尾"],"rows":[["将来（正式）","سَوْفَ يَذْهَبُ","-u"],["将来（日常）","سَيَذْهَبُ","-u"],["将来否定","لَنْ يَذْهَبَ","-a"]]}]},{"title":"5. 过去进行与过去将来：كَانَ 加现在式","body":"كَانَ 后面跟一个现在式动词句，表示「那时正在做」或者「那时打算做」：\nكَانَ يَكْتُبُ الدَّرْسَ（kāna yaktubu ad-darsa，他那时正在写这一课）\nكُنْتُ أَدْرُسُ فِي الْمَكْتَبَةِ（kuntu adrusu fī al-maktabati，我那时在图书馆学习）\n这时候 كَانَ 后面跟的不是名词谓语，而是一整个动词句，所以没有「变宾格」的问题，动词照常保持主格 -u。意思有两个，靠上下文分辨：一是过去正在进行，二是过去计划中的事（「那时打算去」）。\n这个结构在叙事里出现频率极高。读故事、读新闻，看到 كَانَ 后面紧跟一个现在式动词，基本就是「当时正在」的意思。"},{"title":"6. 残缺动词一家：كَانَ、لَيْسَ、أَصْبَحَ","body":"كَانَ 不是一个人。لَيْسَ（不是）、أَصْبَحَ（成了）、صَارَ（变成）、ظَلَّ（仍然是）都是同一类，统称「残缺动词」（الْأَفْعَالُ النَّاقِصَةُ，al-afʿālu an-nāqiṣatu）。\n它们的共同点只有两条，记住这两条就够用：第一，它们自己不带完整的动作意思，只是给后面的名词句加一层「时间、否定、变化」；第二，它们后面的谓语都要变宾格。\n- كَانَ：过去是。كَانَ الْبَيْتُ كَبِيرًا。\n- لَيْسَ：不是。لَيْسَ الْبَيْتُ كَبِيرًا。\n- أَصْبَحَ：成了、变成。أَصْبَحَ الطَّالِبُ مُعَلِّمًا（aṣbaḥa aṭ-ṭālibu muʿalliman，这个学生成了老师）。\n- صَارَ：变成。صَارَ الْمَاءُ ثَلْجًا（ṣāra al-māʾu thaljan，水变成了冰）。\n- ظَلَّ：仍然是。ظَلَّ الطَّالِبُ فِي الْبَيْتِ（ẓalla aṭ-ṭālibu fī al-bayti，这个学生仍然在家里）。\n一句话总结：这五个词后面，名词谓语用 -an，介词短语不变。"}],"vocab":[{"ar":"كَانَ","rom":"kāna","zh":"曾经是、过去是","a":"3f58fa51cfca"},{"ar":"كَانَتْ","rom":"kānat","zh":"她曾经是","a":"8d34663542d9"},{"ar":"كُنْتُ","rom":"kuntu","zh":"我曾经是","a":"5725a556ff52"},{"ar":"كُنْتَ","rom":"kunta","zh":"你曾经是（男）","a":"b28d1a0cc4ce"},{"ar":"كُنْتِ","rom":"kunti","zh":"你曾经是（女）","a":"69d7c9dfe666"},{"ar":"كُنَّا","rom":"kunnā","zh":"我们曾经是","a":"bb528eeb6302"},{"ar":"كُنْتُمْ","rom":"kuntum","zh":"你们曾经是","a":"38bf59d73b2e"},{"ar":"كَانُوا","rom":"kānū","zh":"他们曾经是","a":"18385b5213a3"},{"ar":"يَكُونُ","rom":"yakūnu","zh":"是（现在式）","a":"0eff727d50e4"},{"ar":"سَوْفَ","rom":"sawfa","zh":"将要（独立词）","a":"c440a5cd0ba1"},{"ar":"سَـ","rom":"sa-","zh":"将要（前缀，紧贴动词）","a":"3435ea12d98f"},{"ar":"أَصْبَحَ","rom":"aṣbaḥa","zh":"变成、成了","a":"e80ef8e42c48"},{"ar":"صَارَ","rom":"ṣāra","zh":"变成","a":"7b27e3141577"},{"ar":"ظَلَّ","rom":"ẓalla","zh":"仍然是","a":"154f5aaa17f9"},{"ar":"لَيْسَ","rom":"laysa","zh":"不是","a":"855fa25c17aa"},{"ar":"غَدًا","rom":"ghadan","zh":"明天","a":"7268f632e353"},{"ar":"الْيَوْمَ","rom":"al-yawma","zh":"今天","a":"d4424cd307b4"},{"ar":"أَمْسِ","rom":"amsi","zh":"昨天","a":"c94257c727e0"},{"ar":"مُجْتَهِدٌ","rom":"mujtahidun","zh":"用功的","a":"10a9e9bd54f1"},{"ar":"كَبِيرٌ","rom":"kabīrun","zh":"大的","a":"1fabde614f66"},{"ar":"صَغِيرٌ","rom":"ṣaghīrun","zh":"小的","a":"2353820d7b0e"},{"ar":"جَدِيدٌ","rom":"jadīdun","zh":"新的","a":"bc60168bb745"},{"ar":"رِسَالَةٌ","rom":"risālatun","zh":"信、书信","a":"fb6922a7983f"},{"ar":"مَكْتَبَةٌ","rom":"maktabatun","zh":"图书馆","a":"93620b1195f5"},{"ar":"طَعَامٌ","rom":"ṭaʿāmun","zh":"食物、饭菜","a":"c0c6dea5f5c8"},{"ar":"مُعَلِّمٌ","rom":"muʿallimun","zh":"老师（男）","a":"d3c46805be2a"},{"ar":"طَالِبٌ","rom":"ṭālibun","zh":"学生（男）","a":"bea7c61ac7f5"},{"ar":"يَكْتُبُ","rom":"yaktubu","zh":"写（现在式）","a":"8db9132c7988"},{"ar":"يَذْهَبُ","rom":"yadhhabu","zh":"去（现在式）","a":"780f745b45a3"},{"ar":"يَدْرُسُ","rom":"yadrusu","zh":"学习（现在式）","a":"df96c73f87f4"},{"ar":"يَلْعَبُ","rom":"yalʿabu","zh":"玩（现在式）","a":"9af62f574d28"},{"ar":"يَطْبُخُ","rom":"yaṭbukhu","zh":"做饭（现在式）","a":"85aa10996347"}],"examples":[{"ar":"كَانَ الْبَيْتُ كَبِيرًا.","rom":"kāna al-baytu kabīran","zh":"这房子以前很大。","note":"كَانَ 加主格主语加宾格谓语","a":"3a56b5ad3b82"},{"ar":"كَانَ الطَّالِبُ مُجْتَهِدًا.","rom":"kāna aṭ-ṭālibu mujtahidan","zh":"这个学生以前很用功。","note":"谓语是形容词也用 -an","a":"6b49321d9326"},{"ar":"كَانَتِ الطَّالِبَةُ صَغِيرَةً.","rom":"kānati aṭ-ṭālibatu ṣaghīratan","zh":"这个女学生那时还小。","note":"كَانَتْ 接 الْ 读 كَانَتِ","a":"a71ab3684a2e"},{"ar":"كُنْتُ طَالِبًا.","rom":"kuntu ṭāliban","zh":"我从前是学生。","note":"第一人称是 كُنْتُ","a":"957cb6a1d6a1"},{"ar":"كُنْتُمْ طُلَّابًا.","rom":"kuntum ṭullāban","zh":"你们以前是学生。","note":"ـتُمْ 表示你们","a":"188e81691e63"},{"ar":"كُنَّا فِي الْبَيْتِ.","rom":"kunnā fī al-bayti","zh":"我们那时在家。","note":"谓语是介词短语，不变格","a":"157afc8a77ba"},{"ar":"كَانُوا طُلَّابًا.","rom":"kānū ṭullāban","zh":"他们以前是学生。","note":"复数谓语 طُلَّابًا 也是宾格","a":"a5639ca031d5"},{"ar":"سَوْفَ أَكْتُبُ الرِّسَالَةَ.","rom":"sawfa aktubu ar-risālata","zh":"我将会写这封信。","note":"سَوْفَ 独立写，动词保持 -u","a":"89165517d3bc"},{"ar":"سَأَكْتُبُ الرِّسَالَةَ.","rom":"saʾaktubu ar-risālata","zh":"我会写这封信。","note":"سَـ 紧贴动词，不能空格","a":"f5869aafa8fc"},{"ar":"سَوْفَ يَذْهَبُ إِلَى الْمَدْرَسَةِ.","rom":"sawfa yadhhabu ilā al-madrasati","zh":"他将会去学校。","note":"将来时动词仍是现在式","a":"8877c44c18d3"},{"ar":"سَيَذْهَبُ إِلَى الْمَدْرَسَةِ.","rom":"sayadhhabu ilā al-madrasati","zh":"他会去学校。","note":"两种写法意思相同","a":"18b358848a7d"},{"ar":"سَوْفَ نَدْرُسُ اللُّغَةَ الْعَرَبِيَّةَ.","rom":"sawfa nadrusu al-lughata al-ʿarabiyyata","zh":"我们将会学阿拉伯语。","note":"نَـ 表示我们","a":"90d72c3f4609"},{"ar":"سَنَدْرُسُ اللُّغَةَ الْعَرَبِيَّةَ.","rom":"sanadrusu al-lughata al-ʿarabiyyata","zh":"我们会学阿拉伯语。","note":"سَـ 加 نَـ","a":"6de6753caeab"},{"ar":"سَوْفَ يَكُونُ مُعَلِّمًا.","rom":"sawfa yakūnu muʿalliman","zh":"他将来会当老师。","note":"يَكُونُ 是 كَانَ 的现在式","a":"52f8a81a3ba4"},{"ar":"سَيَشْرَبُ الْوَلَدُ الْحَلِيبَ.","rom":"sayashrabu al-waladu al-ḥalība","zh":"男孩会喝牛奶。","note":"主语在动词后","a":"eb9ccff0cc39"},{"ar":"غَدًا سَأَذْهَبُ إِلَى الْمَكْتَبَةِ.","rom":"ghadan saʾadhhabu ilā al-maktabati","zh":"明天我要去图书馆。","note":"时间词放句首很常见","a":"e22bd3af83b4"},{"ar":"كَانَ يَكْتُبُ الدَّرْسَ.","rom":"kāna yaktubu ad-darsa","zh":"他那时正在写这一课。","note":"كَانَ 加现在式等于过去进行","a":"00a0bed987e2"},{"ar":"كُنْتُ أَدْرُسُ فِي الْمَكْتَبَةِ.","rom":"kuntu adrusu fī al-maktabati","zh":"我那时在图书馆学习。","note":"现在式保持 -u","a":"8d66cc0072cf"},{"ar":"كَانَتْ تَطْبُخُ الطَّعَامَ.","rom":"kānat taṭbukhu aṭ-ṭaʿāma","zh":"她那时在做饭。","note":"阴性动词加 تَـ","a":"819a304dde6f"},{"ar":"كَانُوا يَلْعَبُونَ.","rom":"kānū yalʿabūna","zh":"他们那时在玩。","note":"复数动词用 ـُونَ","a":"ecce21a7750d"},{"ar":"أَصْبَحَ الطَّالِبُ مُعَلِّمًا.","rom":"aṣbaḥa aṭ-ṭālibu muʿalliman","zh":"这个学生成了老师。","note":"أَصْبَحَ 也让谓语变 -an","a":"55f975bc4f32"},{"ar":"صَارَ الْمَاءُ ثَلْجًا.","rom":"ṣāra al-māʾu thaljan","zh":"水变成了冰。","note":"صَارَ 表示变化","a":"7a48fcec5bd5"},{"ar":"ظَلَّ الطَّالِبُ فِي الْبَيْتِ.","rom":"ẓalla aṭ-ṭālibu fī al-bayti","zh":"这个学生仍然在家里。","note":"谓语是介词短语，不变格","a":"87485ba3cbe9"},{"ar":"الْكِتَابُ جَدِيدٌ.","rom":"al-kitābu jadīdun","zh":"这本书是新的。","note":"现在时用名词句","a":"234f3c14dc49"},{"ar":"كَانَ الْكِتَابُ جَدِيدًا.","rom":"kāna al-kitābu jadīdan","zh":"这本书以前是新的。","note":"加 كَانَ 搬到过去，谓语变 -an","a":"771c58516cd0"},{"ar":"سَوْفَ يَكُونُ الْكِتَابُ جَدِيدًا.","rom":"sawfa yakūnu al-kitābu jadīdan","zh":"这本书将来会是新的。","note":"يَكُونُ 后面谓语仍是 -an","a":"e436631b31f9"}],"drills":[{"q":"把名词句搬到过去用哪个词？","a":"كَانَ"},{"q":"كَانَ 后面的谓语用什么格？","a":"宾格，词尾 -a 或 -an"},{"q":"「这本书以前是新的」怎么说？","a":"كَانَ الْكِتَابُ جَدِيدًا"},{"q":"كَانَ 的第一人称单数怎么变？","a":"كُنْتُ"},{"q":"「她曾经是学生」怎么说？","a":"كَانَتْ طَالِبَةً"},{"q":"表示将来有哪两种写法？","a":"سَوْفَ 加现在式、سَـ 加现在式"},{"q":"「我会写这封信」用 سَـ 怎么说？","a":"سَأَكْتُبُ الرِّسَالَةَ"},{"q":"「他那时正在写这一课」怎么说？","a":"كَانَ يَكْتُبُ الدَّرْسَ"},{"q":"「这个学生成了老师」怎么说？","a":"أَصْبَحَ الطَّالِبُ مُعَلِّمًا"},{"q":"كَانَ 后面接现在式动词时，动词用什么词尾？","a":"主格 -u，不变宾格"}],"tips":["كَانَ 后面是名词谓语时用宾格（جَدِيدًا），是介词短语时不变（كُنَّا فِي الْبَيْتِ）。","كَانَ 中间是 ا，所以第一人称是 كُنْتُ，不是 كَانْتُ。","سَـ 是前缀，必须紧贴动词写；سَوْفَ 是独立的词，后面要空格。","将来时后面的动词仍是主格 -u，别和 لَنْ 后面的 -a 搞混。","كَانَ 加现在式表示「那时正在」或「那时打算」，不是将来。"],"id":"ch4-s6"}],"id":"ch4"},{"title":"第五章 数字、时间与场景","sections":[{"title":"第二十三节 数字 1–100 与数词规则","concepts":[{"title":"1. 这一节学完你能做什么","body":"学完这一节，你能从 1 数到 100，能说「三本书」「五个学生」「二十支笔」「一百个人」，也能听懂别人报的人数、价格和门牌号。更要紧的是你会弄明白阿拉伯语数词最出名的一条规矩：数「三」到「十」的时候，数词要和被数的名词「唱反调」。\n阿拉伯语的数词（الْأَعْدَادُ，al-aʿdādu）分阳性和阴性两套。用哪一套，不看数的是人还是东西，只看被数名词的性是阳还是阴。下面从 1 开始，一层一层往上搭。"},{"title":"2. 1–10：一个数字，两副面孔","body":"先看全表。中间两列是阳性读法和阴性读法，最后一列的转写用斜杠分成两半，斜杠前配阳性、斜杠后配阴性。\n3 到 10 的两套很好认：阴性形式就是把阳性形式的 ة 摘掉，词尾只留一个短音——ثَلَاثَةٌ 变 ثَلَاثٌ，خَمْسَةٌ 变 خَمْسٌ，عَشَرَةٌ 变 عَشْرٌ。只有 8 稍微例外：阴性写成 ثَمَانٍ（thamānin），词尾是一个鼻音符，不写 alif。\n1 和 2 也成对，但用法特殊，第 5 点单独说。","tables":[{"header":["数字","阳性读法","阴性读法","转写"],"rows":[["1","وَاحِدٌ","وَاحِدَةٌ","wāḥidun / wāḥidatun"],["2","اِثْنَانِ","اِثْنَتَانِ","ithnāni / ithnatāni"],["3","ثَلَاثَةٌ","ثَلَاثٌ","thalāthatun / thalāthun"],["4","أَرْبَعَةٌ","أَرْبَعٌ","arbaʿatun / arbaʿun"],["5","خَمْسَةٌ","خَمْسٌ","khamsatun / khamsun"],["6","سِتَّةٌ","سِتٌّ","sittatun / sittun"],["7","سَبْعَةٌ","سَبْعٌ","sabʿatun / sabʿun"],["8","ثَمَانِيَةٌ","ثَمَانٍ","thamāniyatun / thamānin"],["9","تِسْعَةٌ","تِسْعٌ","tisʿatun / tisʿun"],["10","عَشَرَةٌ","عَشْرٌ","ʿasharatun / ʿashrun"]]}]},{"title":"3. 11–19：个位加「十」","body":"11 到 19 是把个位和「十」拼在一起：个位在前，عَشَرَ（ʿashara，阳性）或 عَشْرَةَ（ʿashrata，阴性）在后。11 和 13 到 19 属于「两部分都定在开口符上」的结构，不管这个数词在句子里当什么，尾巴都读 -a，不随成分变。\n12 有两副面孔，正好一阳一阴：阳性 اِثْنَا عَشَرَ（ithnā ʿashara），阴性 اِثْنَتَا عَشْرَةَ（ithnatā ʿashrata）。11 的两个形式也不是从 وَاحِدٌ 变来的：阳性 أَحَدَ عَشَرَ（aḥada ʿashara），阴性 إِحْدَى عَشْرَةَ（iḥdā ʿashrata），这两个得单独记。还有一点：12 的前半截像双数一样跟着格走，宾格和属格要写成 اِثْنَيْ عَشَرَ（ithnay ʿashara）和 اِثْنَتَيْ عَشْرَةَ（ithnatay ʿashrata）；11 和 13 到 19 没有这个变化，尾巴永远不动。\n13 到 19 的个位那一截照样要「唱反调」：数阳性名词用带 ة 的形式，ثَلَاثَةَ عَشَرَ رَجُلًا（thalāthata ʿashara rajulan，十三个男人）；数阴性名词用不带 ة 的形式，ثَلَاثَ عَشْرَةَ امْرَأَةً（thalātha ʿashrata imraʾatan，十三个女人）。后面的「十」不参与，永远跟着个位走。11 和 12 不唱反调，跟着名词同性：أَحَدَ عَشَرَ طَالِبًا（aḥada ʿashara ṭāliban，十一个男学生）、إِحْدَى عَشْرَةَ طَالِبَةً（iḥdā ʿashrata ṭālibatan，十一个女学生）。","tables":[{"header":["数字","阳性读法","阴性读法","转写"],"rows":[["11","أَحَدَ عَشَرَ","إِحْدَى عَشْرَةَ","aḥada ʿashara / iḥdā ʿashrata"],["12","اِثْنَا عَشَرَ","اِثْنَتَا عَشْرَةَ","ithnā ʿashara / ithnatā ʿashrata"],["13","ثَلَاثَةَ عَشَرَ","ثَلَاثَ عَشْرَةَ","thalāthata ʿashara / thalātha ʿashrata"],["14","أَرْبَعَةَ عَشَرَ","أَرْبَعَ عَشْرَةَ","arbaʿata ʿashara / arbaʿa ʿashrata"],["15","خَمْسَةَ عَشَرَ","خَمْسَ عَشْرَةَ","khamsata ʿashara / khamsa ʿashrata"],["16","سِتَّةَ عَشَرَ","سِتَّ عَشْرَةَ","sittata ʿashara / sitta ʿashrata"],["17","سَبْعَةَ عَشَرَ","سَبْعَ عَشْرَةَ","sabʿata ʿashara / sabʿa ʿashrata"],["18","ثَمَانِيَةَ عَشَرَ","ثَمَانِيَ عَشْرَةَ","thamāniyata ʿashara / thamāniya ʿashrata"],["19","تِسْعَةَ عَشَرَ","تِسْعَ عَشْرَةَ","tisʿata ʿashara / tisʿa ʿashrata"]]}]},{"title":"4. 20–100：整十与连写","body":"整十有一个特别好认的形状：全部以 ـُونَ 收尾，和第十六节学的规则阳性复数一个模子。所以它们跟规则阳性复数一样变格——主格 ـُونَ，宾格和属格 ـِينَ（عِشْرُونَ / عِشْرِينَ）——既不随名词的性变，也不管数的是人还是东西。主格的位置见得最多，但别以为它永远长这样：رَأَيْتُ عِشْرِينَ كِتَابًا（raʾaytu ʿishrīna kitāban，我看见了二十本书）、بِعِشْرِينَ رَجُلًا（bi-ʿishrīna rajulan，用二十个人），这两处都读 -īn。\n100 是单独的一个词 مِائَةٌ（miʾatun），不是「十乘十」拼出来的。要数两百，就用它的双数 مِائَتَا（miʾatā），后面接属格单数：مِائَتَا صَفْحَةٍ（miʾatā ṣafḥatin，两百页）。\n21 到 99 是把个位、连词 وَ、整十拼起来，顺序和汉语正好相反。汉语说「二十一」，阿拉伯语说「一和二十」：\n连词 وَ 就是「和」，要贴着后面的整十写。个位那一截按 1–9 自己的规矩来：1、2 跟名词同性，3–9 跟名词反性；整十那一截永远不动。","tables":[{"header":["数字","阿拉伯语","转写"],"rows":[["20","عِشْرُونَ","ʿishrūna"],["30","ثَلَاثُونَ","thalāthūna"],["40","أَرْبَعُونَ","arbaʿūna"],["50","خَمْسُونَ","khamsūna"],["60","سِتُّونَ","sittūna"],["70","سَبْعُونَ","sabʿūna"],["80","ثَمَانُونَ","thamānūna"],["90","تِسْعُونَ","tisʿūna"],["100","مِائَةٌ","miʾatun"]]},{"header":["数字","阿拉伯语","转写"],"rows":[["21","وَاحِدٌ وَعِشْرُونَ","wāḥidun wa-ʿishrūna"],["22","اِثْنَانِ وَعِشْرُونَ","ithnāni wa-ʿishrūna"],["23","ثَلَاثَةٌ وَعِشْرُونَ","thalāthatun wa-ʿishrūna"],["35","خَمْسَةٌ وَثَلَاثُونَ","khamsatun wa-thalāthūna"],["48","ثَمَانِيَةٌ وَأَرْبَعُونَ","thamāniyatun wa-arbaʿūna"],["99","تِسْعَةٌ وَتِسْعُونَ","tisʿatun wa-tisʿūna"]]}]},{"title":"5. 反性规则：3–10 跟名词唱反调","body":"这是本节的核心，也是阿拉伯语数词最反直觉的一条。规则一句话：3 到 10 的数词，性要和被数名词**相反**——数阳性名词，用带 ة 的阴性形式；数阴性名词，用不带 ة 的阳性形式。\n记法：把数词当成一面镜子，名词是男的，镜子里照出来就是女的。拿不准该用哪个形式时，先问「名词是阳是阴」，再把答案反过来。\n这条规矩在实用层面讲不出什么道理，语言学家也只能追到古代塞姆语里 ة 的另一种用法。对学习者来说，把它当成「照镜子」的规矩记住就行，别去找逻辑。\n1 和 2 不遵循这一条。1 直接跟在名词后面，性跟着名词走：كِتَابٌ وَاحِدٌ（kitābun wāḥidun，一本书）、طَالِبَةٌ وَاحِدَةٌ（ṭālibatun wāḥidatun，一个女学生）。2 干脆不用数词，直接把名词变成双数：كِتَابَانِ（kitābāni，两本书）、طَالِبَتَانِ（ṭālibatāni，两个女学生）。只有在强调「是两个、不是三个」的时候，才会把 اِثْنَانِ 说出来。","tables":[{"header":["被数名词","名词的性","数词","短语","中文"],"rows":[["كُتُبٌ（书，复数）","阳性","ثَلَاثَةٌ（阴性形）","ثَلَاثَةُ كُتُبٍ","三本书"],["طَالِبَاتٌ（女学生，复数）","阴性","ثَلَاثٌ（阳性形）","ثَلَاثُ طَالِبَاتٍ","三个女学生"],["طُلَّابٌ（男学生，复数）","阳性","خَمْسَةٌ（阴性形）","خَمْسَةُ طُلَّابٍ","五个男学生"],["سَيَّارَاتٌ（汽车，复数）","阴性","أَرْبَعٌ（阳性形）","أَرْبَعُ سَيَّارَاتٍ","四辆汽车"],["أَقْلَامٌ（笔，复数）","阳性","سِتَّةٌ（阴性形）","سِتَّةُ أَقْلَامٍ","六支笔"],["غُرَفٌ（房间，复数）","阴性","تِسْعٌ（阳性形）","تِسْعُ غُرَفٍ","九个房间"]]}]},{"title":"6. 数词后面的名词：复数和格","body":"数词定了，后面的名词还得跟着改形状。规则分三段，看这张表：\n3 到 10 后面是**属格复数**，所以 ثَلَاثَةُ كُتُبٍ 的 كُتُبٍ 读 kutubin，尾巴是 -in，不能读成 -un。11 以上换成单数：11 到 99 的尾巴读 -an（宾格，语法上叫区分语 تَمْيِيزٌ，tamyīzun），100 的尾巴读 -in（属格）。\n一句话概括：数词后面的名词按数词所属的段位决定形态，不跟着数词的格走：3–10 用属格复数，11–99 用宾格单数（所以这一段数词变格时，名词也不跟它同格），100 用属格单数。判断的时候先看数词落在哪一段，再看名词该用复数还是单数、该收哪个尾巴。\n名词确指时也一样，只是不带鼻音符：ثَلَاثَةُ الْكُتُبِ（thalāthatu al-kutubi，这三本书），الْكُتُبِ 仍然是属格复数。","tables":[{"header":["数词","名词的数","名词词尾","例子"],"rows":[["1","单数","跟名词自己的格走","كِتَابٌ وَاحِدٌ（一本书）"],["2","双数","主格 ـَانِ，宾格属格 ـَيْنِ","كِتَابَانِ（两本书）"],["3–10","复数","属格 -in","ثَلَاثَةُ كُتُبٍ（三本书）"],["11–99","单数","宾格 -an","عِشْرُونَ كِتَابًا（二十本书）"],["100","单数","属格 -in","مِائَةُ كِتَابٍ（一百本书）"]]}]}],"vocab":[{"ar":"وَاحِدٌ","rom":"wāḥidun","zh":"一","a":"3cdce2f89a8f"},{"ar":"اِثْنَانِ","rom":"ithnāni","zh":"二","a":"5fde2b247957"},{"ar":"ثَلَاثَةٌ","rom":"thalāthatun","zh":"三","a":"8811b3146c16"},{"ar":"أَرْبَعَةٌ","rom":"arbaʿatun","zh":"四","a":"1cafda6cb276"},{"ar":"خَمْسَةٌ","rom":"khamsatun","zh":"五","a":"d94c5fce4178"},{"ar":"سِتَّةٌ","rom":"sittatun","zh":"六","a":"4fd8c9c48b61"},{"ar":"سَبْعَةٌ","rom":"sabʿatun","zh":"七","a":"5ca324e6f3da"},{"ar":"ثَمَانِيَةٌ","rom":"thamāniyatun","zh":"八","a":"76e3a2134a8f"},{"ar":"تِسْعَةٌ","rom":"tisʿatun","zh":"九","a":"7b876c5b3b55"},{"ar":"عَشَرَةٌ","rom":"ʿasharatun","zh":"十","a":"f4eaff663c2e"},{"ar":"أَحَدَ عَشَرَ","rom":"aḥada ʿashara","zh":"十一","a":"ff17771995e5"},{"ar":"اِثْنَا عَشَرَ","rom":"ithnā ʿashara","zh":"十二","a":"ee201c6753a7"},{"ar":"عِشْرُونَ","rom":"ʿishrūna","zh":"二十","a":"89d6d230cbc6"},{"ar":"ثَلَاثُونَ","rom":"thalāthūna","zh":"三十","a":"f56a0d74711f"},{"ar":"خَمْسُونَ","rom":"khamsūna","zh":"五十","a":"87c876f04ed5"},{"ar":"مِائَةٌ","rom":"miʾatun","zh":"百","a":"89291a819164"},{"ar":"رَقْمٌ","rom":"raqmun","zh":"数字、号码","a":"38990720f3e9"},{"ar":"عَدَدٌ","rom":"ʿadadun","zh":"数目","a":"cc7a9421ddf9"},{"ar":"كَمْ","rom":"kam","zh":"多少（疑问数词）","a":"8da01b1313b1"},{"ar":"كِتَابٌ","rom":"kitābun","zh":"书","a":"edbacf7ab47c"},{"ar":"قَلَمٌ","rom":"qalamun","zh":"笔","a":"c5cd3bad9c06"},{"ar":"طَالِبٌ","rom":"ṭālibun","zh":"学生（男）","a":"bea7c61ac7f5"},{"ar":"طَالِبَةٌ","rom":"ṭālibatun","zh":"学生（女）","a":"f69923af1ab2"},{"ar":"وَلَدٌ","rom":"waladun","zh":"男孩","a":"ef7a497be3d4"},{"ar":"بِنْتٌ","rom":"bintun","zh":"女孩","a":"db9e49cfe2a2"},{"ar":"رَجُلٌ","rom":"rajulun","zh":"男人","a":"44767a34bc25"},{"ar":"اِمْرَأَةٌ","rom":"imraʾatun","zh":"女人","a":"9615543e5098"},{"ar":"كُرْسِيٌّ","rom":"kursiyyun","zh":"椅子","a":"f8c06dec5141"},{"ar":"طَاوِلَةٌ","rom":"ṭāwilatun","zh":"桌子","a":"6676a860f540"},{"ar":"غُرْفَةٌ","rom":"ghurfatun","zh":"房间","a":"56cee0873c82"},{"ar":"سَيَّارَةٌ","rom":"sayyāratun","zh":"汽车","a":"e5f13dbd9c85"},{"ar":"تُفَّاحَةٌ","rom":"tuffāḥatun","zh":"苹果","a":"dbed82b302bd"},{"ar":"بَابٌ","rom":"bābun","zh":"门","a":"b7831c1d1303"},{"ar":"صَدِيقٌ","rom":"ṣadīqun","zh":"朋友","a":"204b61c6d156"},{"ar":"سَاعَةٌ","rom":"sāʿatun","zh":"小时、钟表","a":"ac9b3059e0fc"},{"ar":"يَوْمٌ","rom":"yawmun","zh":"天","a":"031c241145e1"},{"ar":"شَهْرٌ","rom":"shahrun","zh":"月","a":"5c4e49a44635"},{"ar":"سَنَةٌ","rom":"sanatun","zh":"年","a":"4e8d2cf348bd"}],"examples":[{"ar":"عِنْدِي كِتَابٌ وَاحِدٌ.","rom":"ʿindī kitābun wāḥidun","zh":"我有一本书。","note":"1 放在名词后面，性跟着名词","a":"3862c8fa820c"},{"ar":"عِنْدِي كِتَابَانِ.","rom":"ʿindī kitābāni","zh":"我有两本书。","note":"2 直接用双数，不用数词","a":"722df85973f4"},{"ar":"فِي الْفَصْلِ ثَلَاثَةُ طُلَّابٍ.","rom":"fī al-faṣli thalāthatu ṭullābin","zh":"教室里有三个男学生。","note":"阳性名词配阴性数词，名词属格复数","a":"464b8e15ea43"},{"ar":"فِي الْفَصْلِ ثَلَاثُ طَالِبَاتٍ.","rom":"fī al-faṣli thalāthu ṭālibātin","zh":"教室里有三个女学生。","note":"阴性名词配阳性数词","a":"c7eee6194d43"},{"ar":"عِنْدِي خَمْسَةُ كُتُبٍ.","rom":"ʿindī khamsatu kutubin","zh":"我有五本书。","note":"名词用属格复数 -in","a":"7b345191f106"},{"ar":"فِي الْغُرْفَةِ سِتَّةُ أَقْلَامٍ.","rom":"fī al-ghurfati sittatu aqlāmin","zh":"房间里有六支笔。","note":"反性：阳性名词加阴性数词","a":"14629694b8ca"},{"ar":"فِي الْبَيْتِ تِسْعُ غُرَفٍ.","rom":"fī al-bayti tisʿu ghurafin","zh":"房子里有九个房间。","note":"阴性名词加阳性数词 تِسْع","a":"6104b2ae8a3c"},{"ar":"عِنْدِي أَرْبَعُ سَيَّارَاتٍ.","rom":"ʿindī arbaʿu sayyārātin","zh":"我有四辆车。","note":"数词不带 ة，名词属格复数","a":"7da2bd6efc88"},{"ar":"فِي الْمَكْتَبِ عَشَرَةُ رِجَالٍ.","rom":"fī al-maktabi ʿasharatu rijālin","zh":"办公室里有十个男人。","note":"10 也遵循反性规则","a":"ae3ebc0add15"},{"ar":"فِي الْبَيْتِ عَشْرُ نِسَاءٍ.","rom":"fī al-bayti ʿashru nisāʾin","zh":"家里有十个女人。","note":"阴性名词用阳性形 عَشْر","a":"a69ffbffcfff"},{"ar":"فِي الْفَصْلِ أَحَدَ عَشَرَ طَالِبًا.","rom":"fī al-faṣli aḥada ʿashara ṭāliban","zh":"教室里有十一个男学生。","note":"11 后面名词用单数宾格","a":"a881723b6c01"},{"ar":"عِنْدِي اِثْنَا عَشَرَ قَلَمًا.","rom":"ʿindī ithnā ʿashara qalaman","zh":"我有十二支笔。","note":"12 的阳性形式 اِثْنَا عَشَرَ","a":"04ac8d9aa93a"},{"ar":"عِنْدَهَا اِثْنَتَا عَشْرَةَ سَاعَةً.","rom":"ʿindahā ithnatā ʿashrata sāʿatan","zh":"她有十二块表。","note":"12 的阴性形式 اِثْنَتَا عَشْرَةَ","a":"8e6abccdd28f"},{"ar":"فِي الْمَكْتَبَةِ عِشْرُونَ كِتَابًا.","rom":"fī al-maktabati ʿishrūna kitāban","zh":"图书馆里有二十本书。","note":"整十不变性，名词单数宾格","a":"7a46646fa0a3"},{"ar":"عِنْدِي ثَلَاثَةٌ وَعِشْرُونَ كِتَابًا.","rom":"ʿindī thalāthatun wa-ʿishrūna kitāban","zh":"我有二十三本书。","note":"个位加 وَ 加整十","a":"4d647f039cef"},{"ar":"فِي الْمَدْرَسَةِ مِائَةُ طَالِبٍ.","rom":"fī al-madrasati miʾatu ṭālibin","zh":"学校有一百名学生。","note":"100 后面名词用单数属格","a":"be42eefea54c"},{"ar":"فِي الْأُسْبُوعِ سَبْعَةُ أَيَّامٍ.","rom":"fī al-usbūʿi sabʿatu ayyāmin","zh":"一个星期有七天。","note":"阳性名词 أَيَّام 配阴性数词","a":"e9f0493fb310"},{"ar":"فِي السَّنَةِ اِثْنَا عَشَرَ شَهْرًا.","rom":"fī as-sanati ithnā ʿashara shahran","zh":"一年有十二个月。","note":"12 加单数宾格","a":"10c675cc6536"},{"ar":"عُمْرِي عِشْرُونَ سَنَةً.","rom":"ʿumrī ʿishrūna sanatan","zh":"我二十岁。","note":"年龄用「年」的单数宾格","a":"330a962fb243"},{"ar":"كَمْ كِتَابًا عِنْدَكَ؟","rom":"kam kitāban ʿindaka","zh":"你有多少本书？","note":"كَمْ 后面名词用单数宾格","a":"f26e543b8f7d"},{"ar":"كَمْ طَالِبًا فِي الْفَصْلِ؟","rom":"kam ṭāliban fī al-faṣli","zh":"教室里有多少个学生？","note":"同上，问数目","a":"026d40ac3cec"},{"ar":"الرَّقْمُ ثَلَاثَةٌ.","rom":"ar-raqmu thalāthatun","zh":"号码是三。","note":"名词句，谓语用主格","a":"c8575e8b4ddb"},{"ar":"ثَلَاثَةُ الْكُتُبِ جَدِيدَةٌ.","rom":"thalāthatu al-kutubi jadīdatun","zh":"这三本书是新的。","note":"名词确指，谓语用阴性单数","a":"648c88fb0d1c"},{"ar":"عِنْدِي تِسْعَةُ أَصْدِقَاءَ.","rom":"ʿindī tisʿatu aṣdiqāʾa","zh":"我有九个朋友。","note":"أَصْدِقَاء 属格不读 -i 而读 -a","a":"41a5c68bf4e2"}],"drills":[{"q":"「三」的阳性读法怎么写？","a":"ثَلَاثَةٌ"},{"q":"「五」的阴性读法怎么写？","a":"خَمْسٌ"},{"q":"「八」的阴性读法怎么写？","a":"ثَمَانٍ"},{"q":"12 的两种写法分别是什么？","a":"اِثْنَا عَشَرَ / اِثْنَتَا عَشْرَةَ"},{"q":"20 怎么说？","a":"عِشْرُونَ"},{"q":"21 怎么说？","a":"وَاحِدٌ وَعِشْرُونَ"},{"q":"100 怎么说？","a":"مِائَةٌ"},{"q":"「三本书」怎么说？","a":"ثَلَاثَةُ كُتُبٍ"},{"q":"「三个女学生」怎么说？","a":"ثَلَاثُ طَالِبَاتٍ"},{"q":"3 到 10 后面的名词用什么数、什么格？","a":"复数、属格"},{"q":"11 到 99 后面的名词用什么数、什么格？","a":"单数、宾格"},{"q":"「我有二十本书」怎么说？","a":"عِنْدِي عِشْرُونَ كِتَابًا"}],"tips":["3 到 10 的数词和名词「唱反调」：阳性名词配阴性数词，阴性名词配阳性数词。","1 放在名词后面，2 直接用双数，别造 اِثْنَانِ كِتَابٌ 这种说法。","整十按规则阳性复数变格（主格 -ūn、宾格属格 -īn），但不随名词的性变，也不管数的是人还是东西。","21 以上是「个位 + وَ + 整十」，汉语的「二十一」要倒过来说成「一和二十」。","11 到 99 后面的名词是单数宾格 -an：عِشْرُونَ كِتَابًا，别写成 كِتَابٍ。","ثَمَانٍ 的阴性形不写 alif，词尾就是一个鼻音符，别写成 ثَمَانِيَةٌ。"],"id":"ch5-s1"},{"title":"第二十四节 时间与日期","concepts":[{"title":"1. 这一节学完你能做什么","body":"学完这一节，你能问「今天星期几」「现在几点」「今天几号」，也能张口就答；能背出七天和十二个月的名称，能把钟点说到「三点半」「差一刻五点」，还能说出自己的生日、上课时间和一天的作息。\n时间和日期是阿拉伯语里最「背了就能用」的一块：词本身不难，难的是几个固定搭配——钟点用阴性序数词、月份按不完整变格读 -a、مِنْ 后面接冠词时要读 مِنَ。这一节把这些一次收齐。"},{"title":"2. 星期：七天各叫什么","body":"阿拉伯语的星期名从「日」排到「六」：星期日是一周的第一天，星期五叫 الْجُمُعَةُ（本义是「聚集」，即主麻日），星期六 السَّبْتُ 和希伯来语的安息日同源。\n问「今天星期几」最常用的是 مَا الْيَوْمُ؟（mā al-yawmu）。回答是名词句，起语是 الْيَوْمُ，谓语是星期名，两边都带冠词：الْيَوْمُ الْأَحَدُ（al-yawmu al-aḥadu，今天是星期天）。\n星期一是个小例外。الِاثْنَيْنِ 是「双数」形状的词（本义「第二个」），直接摆在 الْيَوْمُ 后面不像形容词，习惯上说成 الْيَوْمُ يَوْمُ الِاثْنَيْنِ（al-yawmu yawmu al-ithnayni），中间补一个 يَوْمُ 做成正偏组合。","tables":[{"header":["星期","阿拉伯语","转写"],"rows":[["星期日","الْأَحَدُ","al-aḥadu"],["星期一","الِاثْنَيْنِ","al-ithnayni"],["星期二","الثُّلَاثَاءُ","ath-thulāthāʾu"],["星期三","الْأَرْبِعَاءُ","al-arbiʿāʾu"],["星期四","الْخَمِيسُ","al-khamīsu"],["星期五","الْجُمُعَةُ","al-jumuʿatu"],["星期六","السَّبْتُ","as-sabtu"]]}]},{"title":"3. 月份：十二个月怎么叫","body":"公历月份在阿拉伯世界有两套叫法。一套是音译，来自拉丁语和英语，埃及、海湾和北非多用；另一套是本地名，黎巴嫩、叙利亚、约旦、巴勒斯坦多用，比如一月叫 كَانُونُ الثَّانِي、二月叫 شُبَاطُ、三月叫 آذَارُ。这一节学音译那套，本地名那套见到认得出来就行。\n这十二个词都是外来专名，语法上按「不完整变格」处理：作属格时词尾读 -a，也不带鼻音符——مِنْ شَهْرِ يَنَايِرَ（min shahri yanāyira，在一月），不读 yanāyiri，也不读 yanāyirin。\n说「在某月」用 فِي شَهْرِ …，也可以直接 فِي 加月份：فِي شَهْرِ مَارِسَ（fī shahri mārisa，在三月）。","tables":[{"header":["月份","阿拉伯语","转写"],"rows":[["1 月","يَنَايِرُ","yanāyiru"],["2 月","فِبْرَايِرُ","fibrāyiru"],["3 月","مَارِسُ","mārisu"],["4 月","أَبْرِيلُ","abrīlu"],["5 月","مَايُو","māyū"],["6 月","يُونْيُو","yūnyū"],["7 月","يُولْيُو","yūlyū"],["8 月","أَغُسْطُسُ","aghusṭusu"],["9 月","سِبْتِمْبِرُ","sibtimbiru"],["10 月","أُكْتُوبِرُ","uktūbiru"],["11 月","نُوفِمْبِرُ","nūfimbiru"],["12 月","دِيسِمْبِرُ","dīsimbiru"]]}]},{"title":"4. 钟点：现在几点","body":"问时间最常用的是 كَمِ السَّاعَةُ؟（kami as-sāʿatu，现在几点？）。注意 كَمْ 在这里读 كَمِ，带 kasra：后面紧跟着 السَّاعَةُ 的冠词，两个静音不能碰头。\n回答也是名词句：起语是 السَّاعَةُ，谓语是序数词。钟点一律用阴性序数词，因为 سَاعَةٌ 是阴性名词：السَّاعَةُ الثَّالِثَةُ（as-sāʿatu ath-thālithatu，三点），不能说 الثَّالِثُ。\n「半」和「刻」用连词 وَ 挂上去，词尾跟着 السَّاعَةُ 走主格 -u；「差」用 إِلَّا，后面的名词读宾格：إِلَّا رُبْعًا、إِلَّا خَمْسَ دَقَائِقَ。\n说「在几点做某事」用介词 فِي 加属格，说「从几点到几点」用 مِنْ … إِلَى …：\nمِنْ 后面接冠词时要读 مِنَ：مِنَ السَّاعَةِ，因为 مِنْ 的静音和后面的冠词会撞车。","tables":[{"header":["说法","阿拉伯语","转写"],"rows":[["三点","السَّاعَةُ الثَّالِثَةُ","as-sāʿatu ath-thālithatu"],["三点半","السَّاعَةُ الثَّالِثَةُ وَالنِّصْفُ","as-sāʿatu ath-thālithatu wa-n-niṣfu"],["三点一刻","السَّاعَةُ الثَّالِثَةُ وَالرُّبْعُ","as-sāʿatu ath-thālithatu wa-r-rubʿu"],["差一刻三点","السَّاعَةُ الثَّالِثَةُ إِلَّا رُبْعًا","as-sāʿatu ath-thālithatu illā rubʿan"],["差五分三点","السَّاعَةُ الثَّالِثَةُ إِلَّا خَمْسَ دَقَائِقَ","as-sāʿatu ath-thālithatu illā khamsa daqāʾiqa"]]},{"header":["介词","意思","例子","转写"],"rows":[["فِي","在（某时）","فِي السَّاعَةِ السَّابِعَةِ","fī as-sāʿati as-sābiʿati"],["مِنْ … إِلَى …","从……到……","مِنَ السَّاعَةِ الثَّامِنَةِ إِلَى الْعَاشِرَةِ","mina as-sāʿati ath-thāminati ilā al-ʿāshirati"]]}]},{"title":"5. 日期：几月几号","body":"问日期用 مَا التَّارِيخُ الْيَوْمَ؟（mā at-tārīkhu al-yawma，今天几号？）。الْيَوْمَ 是时间副词，读宾格 -a，不带冠词，也不带鼻音符。也可以说 مَا تَارِيخُ الْيَوْمِ؟（mā tārīkhu al-yawmi），把「今天的日期」做成正偏组合。\n回答的格式是「日 + مِنْ + 月」：الْيَوْمُ الثَّانِي عَشَرَ مِنْ يَنَايِرَ（al-yawmu ath-thānī ʿashara min yanāyira，一月十二日），也可以说 التَّارِيخُ الثَّانِي عَشَرَ مِنْ يَنَايِرَ。\n「日」用序数词，不用基数词：一号是 الْأَوَّلُ（al-awwalu），二号是 الثَّانِي（ath-thānī），不是 وَاحِدٌ 和 اِثْنَانِ。十二号是 الثَّانِي عَشَرَ，个位和「十」的搭配跟上一节学的一样。\n星期和日期可以连着说：الْيَوْمُ الْأَحَدُ، الثَّانِي عَشَرَ مِنْ يَنَايِرَ（今天是星期天，一月十二日）。"},{"title":"6. 「几天」「几点」：كَمْ 的两个用法","body":"كَمْ 既问「多少」，也问「几点」：كَمِ السَّاعَةُ؟ 是「几点」，كَمْ يَوْمًا فِي الْأُسْبُوعِ؟ 是「一周有几天」。\n问数目时，كَمْ 后面的名词用单数宾格，尾巴带 -an：كَمْ يَوْمًا、كَمْ سَاعَةً、كَمْ كِتَابًا。这和上一节数词后面接单数宾格是同一条规矩。"}],"vocab":[{"ar":"الْأَحَدُ","rom":"al-aḥadu","zh":"星期日","a":"787fc5d8c173"},{"ar":"الِاثْنَيْنِ","rom":"al-ithnayni","zh":"星期一","a":"8b65a79b16cb"},{"ar":"الثُّلَاثَاءُ","rom":"ath-thulāthāʾu","zh":"星期二","a":"0b77b0d3d1c7"},{"ar":"الْأَرْبِعَاءُ","rom":"al-arbiʿāʾu","zh":"星期三","a":"1a813a7c7667"},{"ar":"الْخَمِيسُ","rom":"al-khamīsu","zh":"星期四","a":"5d4554a3bd35"},{"ar":"الْجُمُعَةُ","rom":"al-jumuʿatu","zh":"星期五","a":"ae925e7e200b"},{"ar":"السَّبْتُ","rom":"as-sabtu","zh":"星期六","a":"9bdd8bb94c9d"},{"ar":"يَنَايِرُ","rom":"yanāyiru","zh":"一月","a":"90cfbf297ffe"},{"ar":"فِبْرَايِرُ","rom":"fibrāyiru","zh":"二月","a":"8a0917f16da5"},{"ar":"مَارِسُ","rom":"mārisu","zh":"三月","a":"86b0a61de50d"},{"ar":"أَبْرِيلُ","rom":"abrīlu","zh":"四月","a":"8e6cbe64a98b"},{"ar":"مَايُو","rom":"māyū","zh":"五月","a":"18325eaf3979"},{"ar":"يُونْيُو","rom":"yūnyū","zh":"六月","a":"5c074688cd03"},{"ar":"يُولْيُو","rom":"yūlyū","zh":"七月","a":"ac952d0201c6"},{"ar":"أَغُسْطُسُ","rom":"aghusṭusu","zh":"八月","a":"4825343e0879"},{"ar":"سِبْتِمْبِرُ","rom":"sibtimbiru","zh":"九月","a":"60fcc24660e3"},{"ar":"أُكْتُوبِرُ","rom":"uktūbiru","zh":"十月","a":"262f8fb1c5af"},{"ar":"نُوفِمْبِرُ","rom":"nūfimbiru","zh":"十一月","a":"af9716abd93d"},{"ar":"دِيسِمْبِرُ","rom":"dīsimbiru","zh":"十二月","a":"b8349666b68b"},{"ar":"الْيَوْمَ","rom":"al-yawma","zh":"今天","a":"d4424cd307b4"},{"ar":"أَمْسِ","rom":"amsi","zh":"昨天","a":"c94257c727e0"},{"ar":"غَدًا","rom":"ghadan","zh":"明天","a":"7268f632e353"},{"ar":"الْآنَ","rom":"al-āna","zh":"现在","a":"8cf9507b20f7"},{"ar":"السَّاعَةُ","rom":"as-sāʿatu","zh":"钟点、小时","a":"7752d015a38b"},{"ar":"الدَّقِيقَةُ","rom":"ad-daqīqatu","zh":"分钟","a":"bd4263fb5f3a"},{"ar":"النِّصْفُ","rom":"an-niṣfu","zh":"一半","a":"105ef9ba165e"},{"ar":"الرُّبْعُ","rom":"ar-rubʿu","zh":"四分之一、一刻","a":"4bc85c826835"},{"ar":"التَّارِيخُ","rom":"at-tārīkhu","zh":"日期","a":"d6b3bfc6f8ef"},{"ar":"الْأُسْبُوعُ","rom":"al-usbūʿu","zh":"星期、周","a":"2e75973ca7f1"},{"ar":"الشَّهْرُ","rom":"ash-shahru","zh":"月","a":"82babb263410"},{"ar":"السَّنَةُ","rom":"as-sanatu","zh":"年","a":"9d5166711cbf"},{"ar":"مَتَى","rom":"matā","zh":"什么时候","a":"c7d7cb8280b6"},{"ar":"كَمْ","rom":"kam","zh":"多少、几点","a":"8da01b1313b1"},{"ar":"إِلَّا","rom":"illā","zh":"除了、差","a":"33a07b8d2b81"},{"ar":"صَبَاحًا","rom":"ṣabāḥan","zh":"在上午","a":"6961ebb80db1"},{"ar":"مَسَاءً","rom":"masāʾan","zh":"在晚上","a":"aaae3c2fa1a7"}],"examples":[{"ar":"مَا الْيَوْمُ؟","rom":"mā al-yawmu","zh":"今天星期几？","note":"疑问词作谓语，前置","a":"c4883a793515"},{"ar":"الْيَوْمُ الْأَحَدُ.","rom":"al-yawmu al-aḥadu","zh":"今天是星期天。","note":"名词句，起语谓语都带冠词","a":"5fdb8aa01b75"},{"ar":"الْيَوْمُ يَوْمُ الِاثْنَيْنِ.","rom":"al-yawmu yawmu al-ithnayni","zh":"今天是星期一。","note":"谓语用正偏组合","a":"ee3d0de900da"},{"ar":"غَدًا الْجُمُعَةُ.","rom":"ghadan al-jumuʿatu","zh":"明天是星期五。","note":"时间副词放句首","a":"19582ac7675b"},{"ar":"كَمِ السَّاعَةُ؟","rom":"kami as-sāʿatu","zh":"现在几点？","note":"كَمْ 读 كَمِ，避免两个静音","a":"cfa3b554055e"},{"ar":"السَّاعَةُ الثَّالِثَةُ.","rom":"as-sāʿatu ath-thālithatu","zh":"三点。","note":"钟点用阴性序数词","a":"cefedfa5e339"},{"ar":"السَّاعَةُ الثَّالِثَةُ وَالنِّصْفُ.","rom":"as-sāʿatu ath-thālithatu wa-n-niṣfu","zh":"三点半。","note":"وَ 连接，النِّصْفُ 读主格","a":"1b86f18c04b2"},{"ar":"السَّاعَةُ الرَّابِعَةُ وَالرُّبْعُ.","rom":"as-sāʿatu ar-rābiʿatu wa-r-rubʿu","zh":"四点一刻。","note":"同上，序数词跟着 سَاعَةٌ 变阴性","a":"d522fb15c367"},{"ar":"السَّاعَةُ الْخَامِسَةُ إِلَّا رُبْعًا.","rom":"as-sāʿatu al-khāmisatu illā rubʿan","zh":"差一刻五点。","note":"إِلَّا 后面的名词用宾格","a":"80e09b8def8a"},{"ar":"السَّاعَةُ الْعَاشِرَةُ إِلَّا خَمْسَ دَقَائِقَ.","rom":"as-sāʿatu al-ʿāshiratu illā khamsa daqāʾiqa","zh":"差五分十点。","note":"5 与 دَقَائِقَ 反性，دَقَائِقَ 不完整变格","a":"6cc0ca26c79e"},{"ar":"أَذْهَبُ إِلَى الْمَدْرَسَةِ فِي السَّاعَةِ السَّابِعَةِ.","rom":"adhhabu ilā al-madrasati fī as-sāʿati as-sābiʿati","zh":"我七点去学校。","note":"فِي + 属格表示时间","a":"29e0261fe744"},{"ar":"أَدْرُسُ مِنَ السَّاعَةِ الثَّامِنَةِ إِلَى الْعَاشِرَةِ.","rom":"adrusu mina as-sāʿati ath-thāminati ilā al-ʿāshirati","zh":"我从八点学到十点。","note":"مِنْ…إِلَى…，مِنْ 读 مِنَ","a":"b7c42648eb1e"},{"ar":"مَا التَّارِيخُ الْيَوْمَ؟","rom":"mā at-tārīkhu al-yawma","zh":"今天几号？","note":"الْيَوْمَ 是宾格时间副词","a":"e0eee6483b32"},{"ar":"التَّارِيخُ الثَّانِي عَشَرَ مِنْ يَنَايِرَ.","rom":"at-tārīkhu ath-thānī ʿashara min yanāyira","zh":"一月十二日。","note":"月份属格读 -a，不带鼻音符","a":"9f9fd1677ba7"},{"ar":"الْيَوْمُ الْأَوَّلُ مِنْ مَارِسَ.","rom":"al-yawmu al-awwalu min mārisa","zh":"三月一日。","note":"日期用序数词，不用基数词","a":"9a020f359454"},{"ar":"عِيدُ مِيلَادِي فِي شَهْرِ أَبْرِيلَ.","rom":"ʿīdu mīlādī fī shahri abrīla","zh":"我的生日在四月。","note":"月份作属格，正偏组合","a":"5b239f7370e7"},{"ar":"كَمْ يَوْمًا فِي الْأُسْبُوعِ؟","rom":"kam yawman fī al-usbūʿi","zh":"一周有几天？","note":"كَمْ 后面用单数宾格","a":"9999d66a1fba"},{"ar":"فِي الْأُسْبُوعِ سَبْعَةُ أَيَّامٍ.","rom":"fī al-usbūʿi sabʿatu ayyāmin","zh":"一周有七天。","note":"反性：阳性名词配阴性数词","a":"e9f0493fb310"},{"ar":"كَمْ سَاعَةً تَدْرُسُ كُلَّ يَوْمٍ؟","rom":"kam sāʿatan tadrusu kulla yawmin","zh":"你每天学几个小时？","note":"كَمْ + 单数宾格，كُلَّ يَوْمٍ 属格","a":"f40f6f14482b"},{"ar":"أَدْرُسُ سَاعَتَيْنِ كُلَّ يَوْمٍ.","rom":"adrusu sāʿatayni kulla yawmin","zh":"我每天学两个小时。","note":"双数宾格作时间状语","a":"dd96aa129b78"},{"ar":"أَمْسِ دَرَسْتُ فِي الْمَكْتَبَةِ.","rom":"amsi darastu fī al-maktabati","zh":"昨天我在图书馆学习。","note":"أَمْسِ 词尾固定读 -i","a":"103fc515ca7f"},{"ar":"الْيَوْمُ الْأَحَدُ، الثَّانِي عَشَرَ مِنْ يَنَايِرَ.","rom":"al-yawmu al-aḥadu, ath-thānī ʿashara min yanāyira","zh":"今天是星期天，一月十二日。","note":"星期与日期连着说","a":"1bd6bbd10ba8"},{"ar":"الصَّبَاحُ جَمِيلٌ.","rom":"aṣ-ṣabāḥu jamīlun","zh":"早晨很美。","note":"名词句，谓语是形容词","a":"a0b8e9ceb4c7"},{"ar":"أَعْمَلُ صَبَاحًا وَأَدْرُسُ مَسَاءً.","rom":"aʿmalu ṣabāḥan wa-adrusu masāʾan","zh":"我上午工作，晚上学习。","note":"صَبَاحًا、مَسَاءً 是宾格时间副词","a":"0d03ef6b6f99"}],"drills":[{"q":"「星期日」怎么说？","a":"الْأَحَدُ"},{"q":"「星期三」怎么说？","a":"الْأَرْبِعَاءُ"},{"q":"「今天星期几？」怎么说？","a":"مَا الْيَوْمُ؟"},{"q":"「现在几点？」怎么说？","a":"كَمِ السَّاعَةُ؟"},{"q":"「三点半」怎么说？","a":"السَّاعَةُ الثَّالِثَةُ وَالنِّصْفُ"},{"q":"「差一刻五点」怎么说？","a":"السَّاعَةُ الْخَامِسَةُ إِلَّا رُبْعًا"},{"q":"「一月」怎么说？","a":"يَنَايِرُ"},{"q":"「一月十二日」怎么说？","a":"الثَّانِي عَشَرَ مِنْ يَنَايِرَ"},{"q":"「从八点到十点」怎么说？","a":"مِنَ السَّاعَةِ الثَّامِنَةِ إِلَى الْعَاشِرَةِ"},{"q":"كَمْ 问数目时，后面的名词用什么形式？","a":"单数宾格，词尾带 -an"},{"q":"「我每天学两个小时」怎么说？","a":"أَدْرُسُ سَاعَتَيْنِ كُلَّ يَوْمٍ"},{"q":"「今天几号？」怎么说？","a":"مَا التَّارِيخُ الْيَوْمَ؟"}],"tips":["كَمْ السَّاعَةُ 的 كَمْ 要读 كَمِ，带 kasra：后面紧跟着冠词，两个静音不能碰头。","月份名是外来专名，按不完整变格处理：属格读 -a，不带鼻音符，مِنْ شَهْرِ يَنَايِرَ，不读 -i。","钟点用阴性序数词，因为 سَاعَةٌ 是阴性：السَّاعَةُ الثَّالِثَةُ，不说 الثَّالِثُ。","إِلَّا 后面的名词读宾格：إِلَّا رُبْعًا、إِلَّا خَمْسَ دَقَائِقَ。","أَمْسِ 表示「昨天」时词尾固定读 -i，不随句子成分变。","日期里的「日」用序数词：一号是 الْأَوَّلُ，不是 وَاحِدٌ。"],"id":"ch5-s2"},{"title":"第二十五节 日常场景","concepts":[{"title":"1. 这一节学完你能做什么","body":"学完这一节，你能在一天里最常遇到的五个场合开口：见面打招呼、介绍自己、点餐买东西、问路、求助。前面二十四节攒下的语法零件，到这里第一次全部装成能说出口的整句。\n你会发现一件让人松一口气的事：真正开口时最常用的句子都很短，三个词、四个词，没有长定语，也没有从句。阿拉伯人听你说话，先看的是你敢不敢开口，不是你每一个格位准不准。所以这一节的学习方法和前面不同——别分析，先背整句，背到不用想就能说出来。\n这一节没有新语法。所有句子都由你已经学过的四样东西拼成：一个名词、一个动词、一个介词短语、一个代词后缀。真正的新东西只有一批「客套话」，它们不讲语法道理，是整块记、整块用的。"},{"title":"2. 问候与寒暄：三句话打开一场对话","body":"阿拉伯语的问候有一套固定问答，像汉语的「吃了吗」——问的人不真要答案，答的人也只用固定句式。\n最通用的一句是 السَّلَامُ عَلَيْكُمْ（as-salāmu ʿalaykum，愿平安在你们上）。字面是「平安在你们上」，不分男女、不分人数、不分早晚，正式场合和熟人之间都能用。回答固定是 وَعَلَيْكُمُ السَّلَامُ（wa-ʿalaykumu as-salāmu，也愿平安在你们上）。注意顺序：先「和」，再「在你们上」，最后才是「平安」，一个字都不能挪。\n早上和晚上各有专门的说法，而且问与答是两个不同的词：问 صَبَاحُ الْخَيْرِ（ṣabāḥu al-khayr，早上好），答 صَبَاحُ النُّورِ（ṣabāḥu an-nūr，早上好）；问 مَسَاءُ الْخَيْرِ（masāʾu al-khayr，晚上好），答 مَسَاءُ النُّورِ（masāʾu an-nūr，晚上好）。为什么答句换成「光明」？因为对方已经说了「吉庆」，你再重复一遍就成了回声，换成「光明」是「愿你的早晨有光」。记住这个对子：问「吉庆」，答「光明」。\n问候过后接一句 كَيْفَ حَالُكَ؟（kayfa ḥāluka，你好吗）。这句里藏着一个你早就学过的结构：حَالُ 是正次，ـكَ 是偏次，合起来是「你的状况」。所以对女的说 كَيْفَ حَالُكِ؟（kayfa ḥāluki），对一群人说 كَيْفَ حَالُكُمْ（kayfa ḥālukum）——变的只是最后那个后缀。回答用 أَنَا بِخَيْرٍ، شُكْرًا（anā bi-khayrin, shukran，我很好，谢谢）：بِخَيْرٍ 是介词短语直接当谓语，前面不加动词，这正是名词句的老规矩。\n道别有大小两种：إِلَى اللِّقَاءِ（ilā al-liqāʾi，再见）字面是「到相见时」，中性、通用；مَعَ السَّلَامَةِ（maʿa as-salāmati，再见）字面是「与平安同在」，送人出门、挂电话时用，语气更暖。\n**关键词**：السَّلَامُ عَلَيْكُمْ（你好）、صَبَاحُ الْخَيْرِ（早上好）、كَيْفَ حَالُكَ（你好吗）、إِلَى اللِّقَاءِ（再见）。\n顺便看一眼 اللِّقَاءِ 的写法：الْ 后面接一个 ل 开头的词，两个 ل 合成一个带叠音的 ل，所以写成 اللِّقَاءِ，读 al-liqāʾi。同样的道理，اللُّغَة（语言）也是这么写的——这不是例外，是冠词遇到 ل 时的固定写法。","tables":[{"header":["阿拉伯语","转写","中文","说明"],"rows":[["السَّلَامُ عَلَيْكُمْ.","as-salāmu ʿalaykum","你好。","最通用的问候，正式、随意都能用"],["وَعَلَيْكُمُ السَّلَامُ.","wa-ʿalaykumu as-salāmu","也愿平安在你上。","固定回答，语序不能颠倒"],["صَبَاحُ الْخَيْرِ.","ṣabāḥu al-khayr","早上好。","字面「早上的吉庆」"],["صَبَاحُ النُّورِ.","ṣabāḥu an-nūr","早上好。","固定回答，字面「早上的光明」"],["كَيْفَ حَالُكَ؟","kayfa ḥāluka","你好吗？","حَال 正次，ـكَ 偏次"],["أَنَا بِخَيْرٍ، شُكْرًا.","anā bi-khayrin, shukran","我很好，谢谢。","介词短语作谓语"],["وَأَنْتَ؟","wa-anta","你呢？","一个代词就够"],["إِلَى اللِّقَاءِ.","ilā al-liqāʾi","再见。","字面「到相见时」"],["مَعَ السَّلَامَةِ.","maʿa as-salāmati","再见。","送人时用，字面「与平安同在」"]]}]},{"title":"3. 自我介绍：把「我是谁」说清楚","body":"自我介绍只需要三句话：我叫什么、我从哪儿来、我做什么。\nاِسْمِي（ismī，我的名字）是 اِسْم（名字）加 ـِي（我的）。问句是 مَا اسْمُكَ؟（mā ismuka，你叫什么名字？）——注意用 مَا，不用 كَيْفَ；汉语说「你叫什么」，英语说 what is your name，阿拉伯语问的也是「什么」。اسْمُ 用主格，因为它是这句话的起语。\n第二句 أَنَا مِنَ الصِّينِ（anā mina aṣ-ṣīni，我来自中国）。مِنْ 后面接属格，所以 الصِّينِ 读 -i。这里还有个连读细节：مِنْ 的 ن 收静音，后面紧跟 الْ，两个辅音撞在一起读不出来，要补一个短元音读成 مِنَ，写出来也要加 ـَ。这条「静音遇 الْ 补短元音」的规矩，第二十一节讲 لَمْ 时已经见过一次，这里是第二次——说明它不是特例，是阿拉伯语的普遍习惯。\n第三句说身份，用名词句：أَنَا طَالِبٌ فِي الْجَامِعَةِ（anā ṭālibun fī al-jāmiʿati，我是大学生）。说自己做什么，用第一人称现在式：أَعْمَلُ فِي شَرِكَةٍ（aʿmalu fī sharikatin，我在一家公司工作）、أَتَعَلَّمُ الْعَرَبِيَّةَ（ataʿallamu al-ʿarabiyyata，我学阿拉伯语）。这两句里，شَرِكَةٍ 是泛指属格 -in，الْعَرَبِيَّةَ 是确指宾格 -a，各按各的成分走。\n最后一句 تَشَرَّفْنَا（tasharrafnā，幸会）字面是「我们荣幸了」，是过去式第一人称复数，但意思跟「我们」无关，纯粹是客套。这种句子不要拆开分析，整块背下来。\n顺便说一句人名：阿拉伯语里中国人名按读音转写，李写作 لِي，明写作 مِينْغ，所以「我叫李明」就是 اِسْمِي لِي مِينْغ。你自己的名字也可以这样拼，第一次见面时写给别人看，比念十遍管用。\n**关键词**：اِسْمِي（我叫）、أَنَا مِنْ（我来自）、أَعْمَلُ（我工作）、أَتَعَلَّمُ（我学习）、تَشَرَّفْنَا（幸会）。","tables":[{"header":["阿拉伯语","转写","中文","说明"],"rows":[["مَا اسْمُكَ؟","mā ismuka","你叫什么名字？","مَا 问「什么」，اسْم 主格"],["اِسْمِي لِي مِينْغ.","ismī lī mīng","我叫李明。","ـِي 表示「我的」"],["أَنَا مِنَ الصِّينِ.","anā mina aṣ-ṣīni","我来自中国。","مِنْ 加属格；ص 是太阳字母"],["أَنَا طَالِبٌ فِي الْجَامِعَةِ.","anā ṭālibun fī al-jāmiʿati","我是大学生。","名词句，谓语 -un"],["أَتَعَلَّمُ الْعَرَبِيَّةَ.","ataʿallamu al-ʿarabiyyata","我学阿拉伯语。","第一人称现在式，宾语宾格"],["أَعْمَلُ فِي شَرِكَةٍ.","aʿmalu fī sharikatin","我在一家公司工作。","泛指属格 -in"],["تَشَرَّفْنَا.","tasharrafnā","幸会。","固定客套，不按字面理解"],["أَهْلًا وَسَهْلًا.","ahlan wa-sahlan","欢迎。","字面「家人和容易」"]]}]},{"title":"4. 点餐与购物：أُرِيدُ 加宾格，一句话点完","body":"أُرِيدُ（urīdu，我想要）是点餐的万能动词。它后面直接跟宾格：أُرِيدُ قَهْوَةً（urīdu qahwatan，我要一杯咖啡）。注意 قَهْوَةً 的尾巴是 ـً，不是 ـٌ，因为它是宾语。初学者最常见的错就是漏掉这个鼻音符，说成 أُرِيدُ قَهْوَةٌ，听起来像「我要，一杯咖啡」两个不相干的词。\nمِنْ فَضْلِكَ（min faḍlika，请、劳驾）放在句尾，字面是「从你的恩惠里」，等于汉语的「麻烦您」。它不改变句子里任何词的格，加不加都行，但加上礼貌得多。\n问价钱有两个说法：بِكَمْ هَذَا؟（bi-kam hādhā，这个多少钱？）和 كَمِ الثَّمَنُ؟（kami ath-thamanu，价格是多少？）。第二个要特别注意：كَمْ 本来收静音，后面紧跟带 الْ 的 الثَّمَنُ，两个静音相撞，要给 كَمْ 补一个 ـِ，写成 كَمِ。这和 مِنَ الصِّينِ 是同一条规则——阿拉伯语不允许两个辅音直接碰头。\n在店里还会听到 هَلْ عِنْدَكَ…؟（hal ʿindaka，你这儿有…吗？）。عِنْدَ 是「在…那里」，引申为「有」：عِنْدِي كِتَابٌ（ʿindī kitābun，我有一本书）。注意「有」的句子在阿拉伯语里仍是名词句，不用去找一个相当于 have 的动词。\n结账说 الْحِسَابُ مِنْ فَضْلِكَ（al-ḥisābu min faḍlika，请结账）；递东西、请人先走说 تَفَضَّلْ（tafaḍḍal，请）。\n**关键词**：أُرِيدُ（我要）、بِكَمْ（多少钱）、الثَّمَنُ（价格）、الْحِسَابُ（账单）、مِنْ فَضْلِكَ（麻烦您）。","tables":[{"header":["阿拉伯语","转写","中文","说明"],"rows":[["أُرِيدُ قَهْوَةً مِنْ فَضْلِكَ.","urīdu qahwatan min faḍlika","请给我一杯咖啡。","أُرِيدُ 后面用宾格 -an"],["بِكَمْ هَذَا؟","bi-kam hādhā","这个多少钱？","كَمْ 前加 بِـ 问价钱"],["كَمِ الثَّمَنُ؟","kami ath-thamanu","价格是多少？","كَمْ 接 الْ 读 كَمِ"],["أَعْطِنِي مَاءً مِنْ فَضْلِكَ.","aʿṭinī māʾan min faḍlika","请给我水。","命令式加代词后缀 ـنِي"],["هَذَا غَالٍ جِدًّا.","hādhā ghālin jiddan","这个太贵了。","جِدًّا 是宾格状语"],["هَلْ عِنْدَكَ شَايٌ؟","hal ʿindaka shāyun","你这儿有茶吗？","عِنْدَ 表示「有」"],["الْحِسَابُ مِنْ فَضْلِكَ.","al-ḥisābu min faḍlika","请结账。","名词句，谓语是介词短语"],["تَفَضَّلْ.","tafaḍḍal","请。","递东西时的万能词"]]}]},{"title":"5. 问路：三个方位词走遍一座城","body":"问「在哪儿」用 أَيْنَ（ayna），后面直接跟你要找的东西，那个东西用主格：أَيْنَ الْمَحَطَّةُ؟（ayna al-maḥaṭṭatu，车站在哪儿？）。为什么是主格？因为这句话本质上是名词句：الْمَحَطَّةُ 是起语，أَيْنَ 占了谓语的位置。汉语的「车站在哪儿」结构其实一样，只是阿拉伯语把疑问词提到了最前面。\n问「怎么去」用 كَيْفَ أَذْهَبُ إِلَى…؟（kayfa adhhabu ilā…，我怎么去…？）。إِلَى 后面一律属格：إِلَى الْمَطَارِ（ilā al-maṭāri，去机场）、إِلَى الْفُنْدُقِ（ilā al-funduqi，去旅馆）。\n方位只要三个词就够用：عَلَى الْيَمِينِ（ʿalā al-yamīni，在右边）、عَلَى الْيَسَارِ（ʿalā al-yasāri，在左边）、إِلَى الْأَمَامِ（ilā al-amāmi，往前）。三个都是介词短语，介词后面的名词用属格 -i，这个尾巴别吞掉。\n指路的人常直接用命令式：اِذْهَبْ（idhhab，你走）。命令式的规矩第四章讲过——从第二人称现在式 تَذْهَبُ 去掉前缀 تَـ，词尾收静音，就是 اِذْهَبْ。\n远近是一对形容词：قَرِيبٌ（qarībun，近的）、بَعِيدٌ（baʿīdun，远的）。它们要跟被修饰的名词一致，所以问车站远不远，要说 هَلْ هِيَ بَعِيدَةٌ؟（hal hiya baʿīdatun，它远吗？）——الْمَحَطَّة 是阴性，形容词也要变阴性。\n**关键词**：أَيْنَ（在哪儿）、كَيْفَ أَذْهَبُ إِلَى（怎么去）、عَلَى الْيَمِينِ（右边）、عَلَى الْيَسَارِ（左边）、قَرِيبٌ（近）。","tables":[{"header":["阿拉伯语","转写","中文","说明"],"rows":[["عَفْوًا، أَيْنَ الْمَحَطَّةُ؟","ʿafwan, ayna al-maḥaṭṭatu","劳驾，车站在哪儿？","أَيْنَ 后面的名词用主格"],["اِذْهَبْ إِلَى الْأَمَامِ ثُمَّ عَلَى الْيَمِينِ.","idhhab ilā al-amāmi thumma ʿalā al-yamīni","一直往前，然后往右。","命令式加两个方位短语"],["هَلْ هِيَ بَعِيدَةٌ؟","hal hiya baʿīdatun","它远吗？","形容词跟 الْمَحَطَّة 变阴性"],["لَا، هِيَ قَرِيبَةٌ جِدًّا.","lā, hiya qarībatun jiddan","不，很近。","لَا 用于否定回答"],["كَيْفَ أَذْهَبُ إِلَى الْمَطَارِ؟","kayfa adhhabu ilā al-maṭāri","我怎么去机场？","إِلَى 后面属格 -i"],["هُوَ عَلَى الْيَسَارِ.","huwa ʿalā al-yasāri","它在左边。","عَلَى 后面属格"],["شُكْرًا جَزِيلًا.","shukran jazīlan","非常感谢。","جَزِيلًا 宾格加强语气"]]}]},{"title":"6. 求助与礼貌：不会说的时候怎么办","body":"开口之前先说 عَفْوًا（ʿafwan，劳驾、对不起）。这个词有两个身份：撞到人、打断别人时是「对不起」，别人道谢时回答「不客气」也是它。一个词管两头，记住场景就行。\n听不懂就说 لَا أَفْهَمُ（lā afhamu，我不懂）。想请人重复，说 أَعِدْ مِنْ فَضْلِكَ（aʿid min faḍlika，请再说一遍）。أَعِدْ 是 أَعَادَ（aʿāda，重复）的命令式，属于「病弱动词」，词形不规则，先整块记住，别去推。\n问对方会不会说某种语言，用 هَلْ تَتَكَلَّمُ…؟（hal tatakallamu…，你说…吗？）：هَلْ تَتَكَلَّمُ الْإِنْجِلِيزِيَّةَ؟（hal tatakallamu al-injlīziyyata，你说英语吗？）。تَتَكَلَّمُ 里有叠音，读的时候要在 ك 上停一下。\n问一个词的意思，用 مَا مَعْنَى…؟（mā maʿnā…，…是什么意思？）：مَا مَعْنَى هَذِهِ الْكَلِمَةِ؟（mā maʿnā hādhihi al-kalimati，这个词是什么意思？）。注意 هَذِهِ 后面的名词用属格，因为 هَذِهِ 和后面的名词构成正偏关系。\n最后提醒一个方言的坑：埃及人常说 مَعْلِيش（maʿlīsh，没关系），黎凡特人另有说法，这些都不是标准语。标准语里「没关系」就是 لَا بَأْسَ（lā baʾsa）。初学阶段一律用标准语，等底子稳了再去听方言。\n把这几段连起来，一个上午是这样过的：进教室说 السَّلَامُ عَلَيْكُمْ，同学回 وَعَلَيْكُمُ السَّلَامُ；老师问 كَيْفَ حَالُكَ，你答 أَنَا بِخَيْرٍ، شُكْرًا；下课去食堂说 أُرِيدُ قَهْوَةً مِنْ فَضْلِكَ；找不到图书馆就问 أَيْنَ الْمَكْتَبَةُ؟；听不懂就说 أَعِدْ مِنْ فَضْلِكَ；离开时说 إِلَى اللِّقَاءِ。六句话，一个上午。\n**关键词**：عَفْوًا（劳驾、不客气）、لَا أَفْهَمُ（我不懂）、أَعِدْ（再说一遍）、مَا مَعْنَى（什么意思）、لَا بَأْسَ（没关系）。","tables":[{"header":["阿拉伯语","转写","中文","说明"],"rows":[["عَفْوًا، لَا أَفْهَمُ.","ʿafwan, lā afhamu","抱歉，我不懂。","لَا 否定现在式"],["أَعِدْ مِنْ فَضْلِكَ.","aʿid min faḍlika","请再说一遍。","أَعَادَ 的命令式"],["هَلْ تَتَكَلَّمُ الْإِنْجِلِيزِيَّةَ؟","hal tatakallamu al-injlīziyyata","你说英语吗？","هَلْ 加现在式"],["مَا مَعْنَى هَذِهِ الْكَلِمَةِ؟","mā maʿnā hādhihi al-kalimati","这个词是什么意思？","هَذِهِ 后面的名词用属格"],["كَيْفَ تَقُولُ هَذَا بِالْعَرَبِيَّةِ؟","kayfa taqūlu hādhā bi-al-ʿarabiyyati","这个用阿拉伯语怎么说？","بِـ 表示「用某种语言」"],["أَنَا آسِفٌ.","anā āsifun","对不起。","男用 آسِفٌ，女用 آسِفَةٌ"],["لَا بَأْسَ.","lā baʾsa","没关系。","固定说法，不按字面拆"],["مَعَ السَّلَامَةِ.","maʿa as-salāmati","再见。","道别收尾"]]}]}],"vocab":[{"ar":"السَّلَامُ عَلَيْكُمْ","rom":"as-salāmu ʿalaykum","zh":"你好、愿平安在你上","a":"cebd0016693c"},{"ar":"وَعَلَيْكُمُ السَّلَامُ","rom":"wa-ʿalaykumu as-salāmu","zh":"也愿你平安（回答）","a":"6bc35c189cd0"},{"ar":"صَبَاحُ الْخَيْرِ","rom":"ṣabāḥu al-khayr","zh":"早上好","a":"44446d8e6a9d"},{"ar":"صَبَاحُ النُّورِ","rom":"ṣabāḥu an-nūr","zh":"早上好（回答）","a":"11e83a54358d"},{"ar":"مَسَاءُ الْخَيْرِ","rom":"masāʾu al-khayr","zh":"晚上好","a":"7ac7294313e0"},{"ar":"مَسَاءُ النُّورِ","rom":"masāʾu an-nūr","zh":"晚上好（回答）","a":"5713f8f8d9c2"},{"ar":"كَيْفَ حَالُكَ","rom":"kayfa ḥāluka","zh":"你好吗","a":"251f7e1e65e0"},{"ar":"بِخَيْرٍ","rom":"bi-khayrin","zh":"很好","a":"e75cf5735b6d"},{"ar":"إِلَى اللِّقَاءِ","rom":"ilā al-liqāʾi","zh":"再见","a":"a5d8c794ca29"},{"ar":"مَعَ السَّلَامَةِ","rom":"maʿa as-salāmati","zh":"再见、一路平安","a":"300912ab1d2f"},{"ar":"أَهْلًا وَسَهْلًا","rom":"ahlan wa-sahlan","zh":"欢迎","a":"c7a61b51bcf1"},{"ar":"تَشَرَّفْنَا","rom":"tasharrafnā","zh":"幸会","a":"dd34895b69e4"},{"ar":"اِسْمٌ","rom":"ismun","zh":"名字","a":"8fd9878719ae"},{"ar":"شَرِكَةٌ","rom":"sharikatun","zh":"公司","a":"cef21cc5fb89"},{"ar":"أَعْمَلُ","rom":"aʿmalu","zh":"我工作","a":"12dfa6ed8556"},{"ar":"أَتَعَلَّمُ","rom":"ataʿallamu","zh":"我学习","a":"e9a877117f51"},{"ar":"أُرِيدُ","rom":"urīdu","zh":"我想要","a":"b5d4a1054e91"},{"ar":"مِنْ فَضْلِكَ","rom":"min faḍlika","zh":"请、劳驾","a":"38991703b8fd"},{"ar":"كَمْ","rom":"kam","zh":"多少","a":"8da01b1313b1"},{"ar":"ثَمَنٌ","rom":"thamanun","zh":"价格","a":"7fe659965a52"},{"ar":"غَالٍ","rom":"ghālin","zh":"贵的","a":"2d1a1b533ebd"},{"ar":"رَخِيصٌ","rom":"rakhīṣun","zh":"便宜的","a":"085510d514f2"},{"ar":"أَعْطِنِي","rom":"aʿṭinī","zh":"给我","a":"205992205162"},{"ar":"عِنْدَ","rom":"ʿinda","zh":"在…那里、有","a":"7e2f9771fde6"},{"ar":"حِسَابٌ","rom":"ḥisābun","zh":"账单","a":"b988a692aee1"},{"ar":"تَفَضَّلْ","rom":"tafaḍḍal","zh":"请（递东西）","a":"7542b900af2e"},{"ar":"مَحَطَّةٌ","rom":"maḥaṭṭatun","zh":"车站","a":"763bce79de2f"},{"ar":"مَطَارٌ","rom":"maṭārun","zh":"机场","a":"242b2c06b41b"},{"ar":"فُنْدُقٌ","rom":"funduqun","zh":"旅馆","a":"a4cfa534d966"},{"ar":"مَكْتَبَةٌ","rom":"maktabatun","zh":"图书馆","a":"93620b1195f5"},{"ar":"يَمِينٌ","rom":"yamīnun","zh":"右边","a":"61459aae2d90"},{"ar":"يَسَارٌ","rom":"yasārun","zh":"左边","a":"e65e21a73e20"},{"ar":"أَمَامٌ","rom":"amāmun","zh":"前面","a":"16f2ffbe1512"},{"ar":"قَرِيبٌ","rom":"qarībun","zh":"近的","a":"2557e9764f77"},{"ar":"بَعِيدٌ","rom":"baʿīdun","zh":"远的","a":"b27f06451a07"},{"ar":"عَفْوًا","rom":"ʿafwan","zh":"对不起、不客气","a":"ea3cf19eb849"},{"ar":"آسِفٌ","rom":"āsifun","zh":"抱歉的","a":"094d616ac062"},{"ar":"أَعِدْ","rom":"aʿid","zh":"请再说一遍","a":"cefc96c2840d"},{"ar":"مَعْنًى","rom":"maʿnan","zh":"意思","a":"c8d86abfc959"},{"ar":"كَلِمَةٌ","rom":"kalimatun","zh":"词","a":"740e3cb4d6a6"}],"examples":[{"ar":"صَبَاحُ الْخَيْرِ.","rom":"ṣabāḥu al-khayr","zh":"早上好。","note":"名词句，谓语省掉","a":"581b6c0f6511"},{"ar":"صَبَاحُ النُّورِ.","rom":"ṣabāḥu an-nūr","zh":"早上好。","note":"固定回答，不能说 الْخَيْر","a":"cf4a6217c40a"},{"ar":"كَيْفَ حَالُكَ؟","rom":"kayfa ḥāluka","zh":"你好吗？","note":"حَال 正次，ـكَ 偏次","a":"0605021321aa"},{"ar":"أَنَا بِخَيْرٍ، شُكْرًا.","rom":"anā bi-khayrin, shukran","zh":"我很好，谢谢。","note":"介词短语作谓语","a":"144ce8928cfb"},{"ar":"إِلَى اللِّقَاءِ.","rom":"ilā al-liqāʾi","zh":"再见。","note":"إِلَى 后面属格","a":"c3a87f332cc1"},{"ar":"مَا اسْمُكَ؟","rom":"mā ismuka","zh":"你叫什么名字？","note":"مَا 问名称，اسْم 主格","a":"73ae15973f10"},{"ar":"اِسْمِي لِي مِينْغ.","rom":"ismī lī mīng","zh":"我叫李明。","note":"ـِي 是所有格后缀","a":"c51243cd08d1"},{"ar":"أَنَا مِنَ الصِّينِ.","rom":"anā mina aṣ-ṣīni","zh":"我来自中国。","note":"مِنْ 遇 الْ 读 مِنَ，属格 -i","a":"e22b31d1605c"},{"ar":"أَتَعَلَّمُ الْعَرَبِيَّةَ.","rom":"ataʿallamu al-ʿarabiyyata","zh":"我学阿拉伯语。","note":"宾语宾格 -a","a":"e3afb549a27b"},{"ar":"أَعْمَلُ فِي شَرِكَةٍ.","rom":"aʿmalu fī sharikatin","zh":"我在一家公司工作。","note":"泛指属格 -in","a":"84847c068100"},{"ar":"تَشَرَّفْنَا.","rom":"tasharrafnā","zh":"幸会。","note":"固定客套，整块记","a":"99bb8a6e7996"},{"ar":"أُرِيدُ قَهْوَةً مِنْ فَضْلِكَ.","rom":"urīdu qahwatan min faḍlika","zh":"请给我一杯咖啡。","note":"أُرِيدُ 加宾格鼻音符","a":"0cdfb133fc02"},{"ar":"بِكَمْ هَذَا؟","rom":"bi-kam hādhā","zh":"这个多少钱？","note":"كَمْ 前加 بِـ 问价","a":"a0ccf8a2cfda"},{"ar":"كَمِ الثَّمَنُ؟","rom":"kami ath-thamanu","zh":"价格是多少？","note":"كَمْ 接 الْ 要读 كَمِ","a":"f5ac11b0788c"},{"ar":"أَعْطِنِي مَاءً مِنْ فَضْلِكَ.","rom":"aʿṭinī māʾan min faḍlika","zh":"请给我水。","note":"命令式加 ـنِي","a":"ef368f5475a2"},{"ar":"هَذَا غَالٍ جِدًّا.","rom":"hādhā ghālin jiddan","zh":"这个太贵了。","note":"جِدًّا 是宾格状语","a":"23079bb2b1f9"},{"ar":"الْحِسَابُ مِنْ فَضْلِكَ.","rom":"al-ḥisābu min faḍlika","zh":"请结账。","note":"名词句，谓语是介词短语","a":"087cce53a5cd"},{"ar":"عَفْوًا، أَيْنَ الْمَحَطَّةُ؟","rom":"ʿafwan, ayna al-maḥaṭṭatu","zh":"劳驾，车站在哪儿？","note":"أَيْنَ 后面的名词用主格","a":"fa8843d00c1f"},{"ar":"اِذْهَبْ إِلَى الْأَمَامِ ثُمَّ عَلَى الْيَمِينِ.","rom":"idhhab ilā al-amāmi thumma ʿalā al-yamīni","zh":"一直往前，然后往右。","note":"命令式加方位短语","a":"f1fe91ea2385"},{"ar":"هَلْ هِيَ بَعِيدَةٌ؟","rom":"hal hiya baʿīdatun","zh":"它远吗？","note":"形容词跟名词一致","a":"5aad6b76264d"},{"ar":"لَا، هِيَ قَرِيبَةٌ جِدًّا.","rom":"lā, hiya qarībatun jiddan","zh":"不，很近。","note":"لَا 用于否定回答","a":"9ca5851f90d6"},{"ar":"كَيْفَ أَذْهَبُ إِلَى الْمَطَارِ؟","rom":"kayfa adhhabu ilā al-maṭāri","zh":"我怎么去机场？","note":"إِلَى 后面属格 -i","a":"1ca628b4bd16"},{"ar":"لَا أَفْهَمُ.","rom":"lā afhamu","zh":"我不懂。","note":"لَا 否定现在式","a":"70b5ac851e74"},{"ar":"أَعِدْ مِنْ فَضْلِكَ.","rom":"aʿid min faḍlika","zh":"请再说一遍。","note":"أَعَادَ 的命令式","a":"6376c0075270"},{"ar":"هَلْ تَتَكَلَّمُ الْإِنْجِلِيزِيَّةَ؟","rom":"hal tatakallamu al-injlīziyyata","zh":"你说英语吗？","note":"هَلْ 加现在式","a":"188d04ddc19e"},{"ar":"مَا مَعْنَى هَذِهِ الْكَلِمَةِ؟","rom":"mā maʿnā hādhihi al-kalimati","zh":"这个词是什么意思？","note":"هَذِهِ 后面的名词用属格","a":"c69102ca0295"},{"ar":"كَيْفَ تَقُولُ هَذَا بِالْعَرَبِيَّةِ؟","rom":"kayfa taqūlu hādhā bi-al-ʿarabiyyati","zh":"这个用阿拉伯语怎么说？","note":"بِـ 表示「用某种语言」","a":"2751b69dbeba"},{"ar":"أَنَا آسِفٌ.","rom":"anā āsifun","zh":"对不起。","note":"男用 آسِفٌ，女用 آسِفَةٌ","a":"bc1753210107"},{"ar":"لَا بَأْسَ.","rom":"lā baʾsa","zh":"没关系。","note":"固定说法，别按字面拆","a":"01350aad7e35"}],"drills":[{"q":"「你好」最通用的说法是什么？","a":"السَّلَامُ عَلَيْكُمْ"},{"q":"صَبَاحُ الْخَيْرِ 的固定回答是什么？","a":"صَبَاحُ النُّورِ"},{"q":"「你叫什么名字？」怎么说？","a":"مَا اسْمُكَ؟"},{"q":"「我来自中国」怎么说？","a":"أَنَا مِنَ الصِّينِ"},{"q":"「这个多少钱？」怎么说？","a":"بِكَمْ هَذَا؟"},{"q":"「请结账」怎么说？","a":"الْحِسَابُ مِنْ فَضْلِكَ"},{"q":"「车站在哪儿？」怎么说？","a":"أَيْنَ الْمَحَطَّةُ؟"},{"q":"「往右」怎么说？","a":"عَلَى الْيَمِينِ"},{"q":"「我不懂，请再说一遍」怎么说？","a":"لَا أَفْهَمُ، أَعِدْ مِنْ فَضْلِكَ"},{"q":"「你说英语吗？」怎么说？","a":"هَلْ تَتَكَلَّمُ الْإِنْجِلِيزِيَّةَ؟"},{"q":"别人说 شُكْرًا，你怎么回？","a":"عَفْوًا"}],"tips":["السَّلَامُ عَلَيْكُمْ 的回答必须带 وَـ：وَعَلَيْكُمُ السَّلَامُ，只说 السَّلَامُ 是半句话。","صَبَاحُ الْخَيْرِ 的固定回答是 صَبَاحُ النُّورِ，重复问句反而像回声。","كَيْفَ حَالُكَ 的 ـكَ 随对方变：男 ـكَ，女 ـكِ，一群人 ـكُمْ。","点餐用 أُرِيدُ 加宾格（قَهْوَةً），别漏掉 ـً，也别在中间加 مِنْ。","مَعْلِيش 是埃及方言，标准语里「没关系」说 لَا بَأْسَ，「对不起」说 عَفْوًا。"],"id":"ch5-s3"},{"title":"第二十六节 阅读短文与综合复习","concepts":[{"title":"1. 这一节学完你能做什么","body":"学完这一节，你能独立读完一篇一百多词的阿拉伯语短文，能认出里面每一个格、每一个动词形式，也能把全书十二个核心语法点一口气说清楚。这是全书的最后一节，也是唯一一节「以读为主」的课：前面二十五节是拆零件，这一节是把零件装回去，看看整台机器转起来是什么样子。\n短文题目是 يَوْمِيَّاتُ طَالِبٍ（yawmiyyātun ṭālibin，一个学生的日记）。主人公是一个在开罗学阿拉伯语的中国学生，写的是他从起床到睡觉的一天。全文分成四段，每段后面跟中文翻译和语法提示。读的时候先别查词，一口气读完整段，能懂三成就算成功；第二遍再逐句抠。"},{"title":"2. 短文（一）：六点起床","body":"第一段从「我是谁」写起：三句话交代身份、名字、专业，然后进入一天的流程。这段的动词全部是第一人称单数，前缀都是 أَـ。\nأَنَا طَالِبٌ صِينِيٌّ. اِسْمِي لِي مِينْغ، وَأَنَا أَتَعَلَّمُ اللُّغَةَ الْعَرَبِيَّةَ فِي الْجَامِعَةِ. أَسْتَيْقِظُ كُلَّ يَوْمٍ فِي السَّاعَةِ السَّادِسَةِ صَبَاحًا. أَغْسِلُ وَجْهِي ثُمَّ أَتَنَاوَلُ فُطُورِي مَعَ أُسْرَتِي. آكُلُ خُبْزًا وَبَيْضًا وَأَشْرَبُ كُوبًا مِنَ الْحَلِيبِ. أَخْرُجُ مِنَ الْبَيْتِ فِي السَّاعَةِ السَّابِعَةِ وَأَذْهَبُ إِلَى الْجَامِعَةِ بِالْحَافِلَةِ.\n**中文**：我是一个中国学生。我叫李明，在大学里学阿拉伯语。我每天六点起床。我洗脸，然后和家人一起吃早饭。我吃面包和鸡蛋，喝一杯牛奶。七点出门，坐公交车去大学。\n**名词句**：开头两句都没有「是」；谓语 طَالِبٌ 带 -un，形容词 صِينِيٌّ 跟它一样是阳性单数主格。\n**动词句**：后面全是动词句，动词清一色第一人称单数：أَسْتَيْقِظُ（起床）、أَغْسِلُ（洗）、أَتَنَاوَلُ（吃）、آكُلُ（吃）、أَشْرَبُ（喝）、أَخْرُجُ（出去）、أَذْهَبُ（去）。主语「我」都含在动词里，不必另写 أَنَا。\n**时间状语**：كُلَّ يَوْمٍ、صَبَاحًا 是宾格，فِي السَّاعَةِ السَّادِسَةِ 是介词短语加属格。同一个「几点」，两条路都通。\n**连读**：مِنَ الْبَيْتِ 的 مِنَ 是因为 مِنْ 的静音碰上 الْ，两个辅音不能直接连读，要补一个短元音。"},{"title":"3. 短文（二）：在课堂上","body":"第二段写上课。注意这一段里的 نَقْرَأُ、نَكْتُبُ、نَتَكَلَّمُ 都以 نَـ 开头——阿拉伯语的动词自带主语，说「我们读」只要一个词。\nفِي الْجَامِعَةِ أَدْرُسُ الْعَرَبِيَّةَ وَالْإِنْجِلِيزِيَّةَ وَالتَّارِيخَ. أُحِبُّ حِصَّةَ الْعَرَبِيَّةِ كَثِيرًا. الْمُعَلِّمُ طَيِّبٌ وَالْأَسْئِلَةُ سَهْلَةٌ. نَقْرَأُ النُّصُوصَ وَنَكْتُبُ التَّمَارِينَ وَنَتَكَلَّمُ مَعَ زُمَلَائِنَا. أَحْيَانًا لَا أَفْهَمُ كَلِمَةً جَدِيدَةً، فَأَسْأَلُ الْمُعَلِّمَ، وَيَشْرَحُهَا لِي.\n**中文**：在大学里我学阿拉伯语、英语和历史。我很喜欢阿拉伯语课。老师很和气，问题也不难。我们读课文、写练习，和同学用阿拉伯语交谈。有时候我不懂一个新词，就问老师，他讲给我听。\n**并列宾语**：أَدْرُسُ 后面挂三个并列宾语：الْعَرَبِيَّةَ、الْإِنْجِلِيزِيَّةَ、التَّارِيخَ，全部宾格 -a。\n**名词句**：الْمُعَلِّمُ طَيِّبٌ وَالْأَسْئِلَةُ سَهْلَةٌ 是两个名词句并列。الْأَسْئِلَةُ 是「非理性复数」（指物的复数），谓语用阴性单数 سَهْلَةٌ，不用 سَهْلَةٌ 的复数形式。\n**第一人称复数**：نَقْرَأُ、نَكْتُبُ、نَتَكَلَّمُ 都是第一人称复数，主语「我们」含在动词里。\n**状语与否定**：أَحْيَانًا 是宾格状语，放句首；لَا أَفْهَمُ 是否定现在式。\n**代词回指**：وَيَشْرَحُهَا لِي 里的 ـهَا 回指 كَلِمَة，这种代词后缀回指前面的名词，是阿拉伯语最常用的衔接手段。"},{"title":"4. 短文（三）：午饭与下午","body":"第三段写午饭和下午的学习。这一段开始出现复合数词和正偏组合套正偏组合，是全书语法密度最高的一段。\nفِي السَّاعَةِ الثَّانِيَةَ عَشْرَةَ أَذْهَبُ إِلَى مَطْعَمِ الْجَامِعَةِ مَعَ صَدِيقِي عُمَر. نَأْكُلُ أَرُزًّا وَلَحْمًا وَسَلَطَةً. بَعْدَ الْغَدَاءِ أَعُودُ إِلَى الْبَيْتِ وَأَسْتَرِيحُ نِصْفَ سَاعَةٍ. ثُمَّ أَجْلِسُ إِلَى الْمَكْتَبِ وَأُرَاجِعُ الدَّرْسَ الْجَدِيدَ. أَكْتُبُ الْكَلِمَاتِ فِي دَفْتَرٍ صَغِيرٍ وَأَقْرَأُهَا بِصَوْتٍ عَالٍ.\n**中文**：十二点，我和朋友欧麦尔去大学食堂。我们吃米饭、肉和沙拉。午饭后我回家休息半小时。然后我坐到书桌前复习新课。我把单词写在一个小本子上，大声读出来。\n**复合数词**：السَّاعَةِ الثَّانِيَةَ عَشْرَةَ 里，十一到十九是复合数词，两部分连写成一个词块，第二部分保持开口符，不随前面的格变。\n**正偏组合**：مَطْعَمِ الْجَامِعَةِ 里正次 مَطْعَمِ 不带 الْ、不带鼻音符，偏次 الْجَامِعَةِ 用属格。\n**时间状语**：نِصْفَ سَاعَةٍ 是宾格时间状语，سَاعَةٍ 是它的偏次，用属格 -in。\n**非理性复数**：الْكَلِمَاتِ 宾格和属格同形，都读 -i，只有主格才是 -u。\n**形容词一致**：بِصَوْتٍ عَالٍ 两个词都属格，形容词 عَالٍ 跟着被修饰语走。"},{"title":"5. 短文（四）：晚上与睡觉","body":"第四段收尾：晚上看新闻、睡觉，最后一句把整篇日记合上。这段里出现了将来时，也出现了不带鼻音符的专有名词。\nفِي الْمَسَاءِ أَشْرَبُ الشَّايَ مَعَ أُسْرَتِي وَأُشَاهِدُ الْأَخْبَارَ بِالْعَرَبِيَّةِ. أُحِبُّ هَذَا الْوَقْتَ. أَسْمَعُ فِيهِ كَلِمَاتٍ كَثِيرَةً أَعْرِفُهَا. أَنَامُ فِي السَّاعَةِ الْعَاشِرَةِ. سَأَزُورُ مِصْرَ بَعْدَ سَنَةٍ وَأَتَكَلَّمُ مَعَ النَّاسِ هُنَاكَ. هَذِهِ يَوْمِيَّاتِي، وَأَنَا سَعِيدٌ بِهَا.\n**中文**：晚上我和家人喝茶，看阿拉伯语新闻。我喜欢这段时间。我能听到很多我认识的词。我十点睡觉。一年后我要去埃及，在那里和当地人说话。这就是我的日记，我为此感到高兴。\n**破碎复数**：الْأَخْبَارَ 是 أَخْبَار 的破碎复数，宾格用 -a，不带额外的鼻音。\n**动词句作定语**：كَلِمَاتٍ كَثِيرَةً أَعْرِفُهَا 里，形容词 كَثِيرَةً 跟 كَلِمَاتٍ 一致，后面的 أَعْرِفُهَا 是一个动词句作定语，等于「我认识的那些词」。\n**将来时**：سَأَزُورُ 是 سَـ 加现在式，表示将来；مِصْرَ 属于「禁用变格名词」，宾格只读 -a，不加鼻音符。\n**名词句**：هَذِهِ يَوْمِيَّاتِي 里，هَذِهِ 是起语，يَوْمِيَّاتِي 是谓语，代词后缀 ـِي 说明「我的」。"},{"title":"6. 全书语法总复习：12 个核心点","body":"这本书讲了二十六节，真正的语法骨架只有十二根。下面这张表，每一行都是一句话能说清的规则加一个例子。建议合上书，先自己默一遍规则，再对照表格查漏；能默出十行，这门课的语法就算过关了。\n这十二行里，最值钱的是「三个格」和「形容词一致」两行。它们不背也能读，但一开口就露馅；反过来，把这两行练成条件反射，你的阿拉伯语听起来就「像个学过的人」了。","tables":[{"header":["语法点","一句话规则","例子"],"rows":[["名词句","起语加谓语，中间不加「是」；泛指谓语带 -un","الْكِتَابُ جَدِيدٌ（al-kitābu jadīdun，这本书是新的）"],["确指冠词","الْ 表确指；月字母读 al-，太阳字母同化并叠音","الشَّمْسُ（ash-shamsu，太阳）"],["三个格","主格 -u、宾格 -a、属格 -i；先看成分再定尾巴","قَرَأْتُ الْكِتَابَ（qaraʾtu al-kitāba，我读了这本书）"],["正偏组合","正次不带 الْ、不带鼻音符；偏次用属格","بَابُ الْبَيْتِ（bābu al-bayti，房子的门）"],["形容词一致","性、数、格、确指四项都跟被修饰语一致","طَالِبٌ مُجْتَهِدٌ（ṭālibun mujtahidun，用功的学生）"],["复数","规则复数 -ūna、-īna、-āt；破碎复数只能一个个背","الطُّلَّابُ（aṭ-ṭullābu，学生们）"],["过去式","人称信息在后缀上：ـتُ ـتَ ـتْ ـنَا ـتُمْ ـُوا","كَتَبْتُ（katabtu，我写了）"],["现在式","人称信息在前缀上：أَ نَ تَ يَ，词尾 -u","أَكْتُبُ（aktubu，我写）"],["命令式","第二人称现在式去掉前缀，词尾收静音","اُكْتُبْ（uktub，你写吧）"],["否定","过去 مَا、现在 لَا、将来 لَنْ、名词句 لَيْسَ","لَا أَفْهَمُ（lā afhamu，我不明白）"],["疑问","疑问词放句首；是非问句在句首加 هَلْ","هَلْ أَنْتَ طَالِبٌ؟（hal anta ṭālibun，你是学生吗？）"],["将来时","سَـ 或 سَوْفَ 加现在式","سَأَذْهَبُ غَدًا（sa-adhhabu ghadan，我明天去）"]]}]},{"title":"7. 学完这本书之后怎么继续","body":"这本书给你的是地基，不是房子。接下来最怕两件事：一是停下来，二是从此只读不听说。给你五个方向，每天加起来一小时就够。\n关于听：半岛电视台（الْجَزِيرَة，al-jazīra）和 BBC 阿拉伯语都有新闻，语速快，第一遍能听出「这是新闻」就算成功。听的时候别暂停查词，让耳朵先习惯节奏。\n关于读：从儿童读物和短新闻入手，别一上来啃小说。阿拉伯语的书报通常不标音，这是最大的坎——所以你迟早要学会看没有标音的文字。方法是先读带标音的版本建立语感，再读同一篇的无标音版对照。\n关于标音这根拐杖：它帮你起步，但不能拄一辈子。建议每读一段，先带标音读三遍，再用手遮住标音读一遍，读错的地方回头看一眼。两三周之后，你会发现很多词的读音已经长在脑子里了。\n关于说：找不到阿拉伯语母语者也没关系，先自言自语。把这一节的短文改成你自己的版本——几点起床、吃什么、学什么——每天说一遍，一周之后它就是你自己的话了。","tables":[{"header":["方向","具体做法","每天多久"],"rows":[["听","先听慢速新闻，再听正常语速；不求全懂，抓关键词和人名地名","15 分钟"],["读","一周读一篇带标音的短文，读完合上复述三句","20 分钟"],["说","找语言伙伴，或对着手机录音，再回听自己的发音","10 分钟"],["写","用当天学的五个词写三句话日记","10 分钟"],["复习","用学习台的「复习」页过到期卡片，错题优先","10 分钟"]]}]},{"title":"8. 结语","body":"二十六节走到这里，你从「一个字母都不认识」变成了「能读、能写、能开口说几句」。回头看，最难的其实是开头那两周：字母的四种形态、从右往左写、那些汉语里没有的喉音和咽音。你已经把它们走过来了，剩下的路只会越走越顺。\n语言不是知识，是习惯。这本书能给你规则，给不了习惯；习惯只能靠每天那二十分钟。哪怕今天只读了三句话、只听了一分钟新闻，也比「等有空了再系统学」强。\n最后送你一句阿拉伯人常说的祝贺：أَلْفُ مَبْرُوكٍ（alfu mabrūkin，恭喜，字面「一千个祝福」）。带着这本书里的句子去说，说错了也没关系——阿拉伯人听到外国人讲自己的语言，第一反应永远是高兴，而不是挑你的格位。"}],"vocab":[{"ar":"يَوْمِيَّاتٌ","rom":"yawmiyyātun","zh":"日记","a":"31feae7640eb"},{"ar":"صِينِيٌّ","rom":"ṣīniyyun","zh":"中国的","a":"57a3f7ceaab2"},{"ar":"أَسْتَيْقِظُ","rom":"astayqiẓu","zh":"我醒来、起床","a":"b170173991df"},{"ar":"أَغْسِلُ","rom":"aghsilu","zh":"我洗","a":"a950264b548b"},{"ar":"وَجْهٌ","rom":"wajhun","zh":"脸","a":"22e84e03bdcb"},{"ar":"فُطُورٌ","rom":"fuṭūrun","zh":"早饭","a":"bf8d8ba8a365"},{"ar":"بَيْضٌ","rom":"bayḍun","zh":"蛋","a":"9a744f63f235"},{"ar":"كُوبٌ","rom":"kūbun","zh":"杯子、一杯","a":"27c2e186a135"},{"ar":"حَافِلَةٌ","rom":"ḥāfilatun","zh":"公共汽车","a":"d79fd0842899"},{"ar":"أَخْرُجُ","rom":"akhruju","zh":"我出去","a":"107a74bf08c2"},{"ar":"أَدْرُسُ","rom":"adrusu","zh":"我学习","a":"0c481b7af3ad"},{"ar":"تَارِيخٌ","rom":"tārīkhun","zh":"历史","a":"31ed12e7a788"},{"ar":"حِصَّةٌ","rom":"ḥiṣṣatun","zh":"课、课时","a":"0847281076f7"},{"ar":"سَهْلٌ","rom":"sahlun","zh":"容易的","a":"334c67bf62ed"},{"ar":"نَصٌّ","rom":"naṣṣun","zh":"课文、文本","a":"b83d9a60b5f5"},{"ar":"تَمْرِينٌ","rom":"tamrīnun","zh":"练习","a":"2249dbd85bee"},{"ar":"زَمِيلٌ","rom":"zamīlun","zh":"同学、同事","a":"c578863d98fd"},{"ar":"أَحْيَانًا","rom":"aḥyānan","zh":"有时候","a":"b32bae5a98d3"},{"ar":"يَشْرَحُ","rom":"yashraḥu","zh":"讲解、解释","a":"80760f3db4b3"},{"ar":"مَطْعَمٌ","rom":"maṭʿamun","zh":"食堂、饭馆","a":"dad00cffec5c"},{"ar":"صَدِيقٌ","rom":"ṣadīqun","zh":"朋友","a":"204b61c6d156"},{"ar":"أَرُزٌّ","rom":"aruzzun","zh":"米、米饭","a":"b1a8c8044bcf"},{"ar":"لَحْمٌ","rom":"laḥmun","zh":"肉","a":"d2450a0fa763"},{"ar":"سَلَطَةٌ","rom":"salaṭatun","zh":"沙拉","a":"ab09b6ba5a02"},{"ar":"غَدَاءٌ","rom":"ghadāʾun","zh":"午饭","a":"e5666997d18b"},{"ar":"أَسْتَرِيحُ","rom":"astarīḥu","zh":"我休息","a":"50f9b6dbe9a6"},{"ar":"نِصْفٌ","rom":"niṣfun","zh":"一半","a":"3ccf41481b1e"},{"ar":"مَكْتَبٌ","rom":"maktabun","zh":"书桌、办公室","a":"9b5fb3903fdf"},{"ar":"أُرَاجِعُ","rom":"urājiʿu","zh":"我复习","a":"8f451b0d261d"},{"ar":"دَفْتَرٌ","rom":"daftarun","zh":"本子、笔记本","a":"cf38915bbf53"},{"ar":"صَوْتٌ","rom":"ṣawtun","zh":"声音","a":"f7fbc93cb7ac"},{"ar":"عَالٍ","rom":"ʿālin","zh":"高的、大声的","a":"f3465782c674"},{"ar":"أُشَاهِدُ","rom":"ushāhidu","zh":"我观看","a":"5ed2f60a7324"},{"ar":"أَخْبَارٌ","rom":"akhbārun","zh":"新闻","a":"8295f076229a"},{"ar":"أَنَامُ","rom":"anāmu","zh":"我睡觉","a":"1459365a81c2"},{"ar":"سَعِيدٌ","rom":"saʿīdun","zh":"高兴的","a":"c58c9a3f4ab7"}],"examples":[{"ar":"أَنَا طَالِبٌ صِينِيٌّ.","rom":"anā ṭālibun ṣīniyyun","zh":"我是一个中国学生。","note":"名词句，形容词跟名词同格","a":"003f143f812e"},{"ar":"اِسْمِي لِي مِينْغ.","rom":"ismī lī mīng","zh":"我叫李明。","note":"ـِي 表示「我的」","a":"c51243cd08d1"},{"ar":"أَتَعَلَّمُ اللُّغَةَ الْعَرَبِيَّةَ فِي الْجَامِعَةِ.","rom":"ataʿallamu al-lughata al-ʿarabiyyata fī al-jāmiʿati","zh":"我在大学里学阿拉伯语。","note":"宾语和形容词都用宾格","a":"37795a20a644"},{"ar":"أَسْتَيْقِظُ كُلَّ يَوْمٍ فِي السَّاعَةِ السَّادِسَةِ.","rom":"astayqiẓu kulla yawmin fī as-sāʿati as-sādisati","zh":"我每天六点起床。","note":"كُلَّ يَوْمٍ 宾格时间状语","a":"a30ab7b27e40"},{"ar":"أَغْسِلُ وَجْهِي ثُمَّ أَتَنَاوَلُ فُطُورِي.","rom":"aghsilu wajhī thumma atanāwalu fuṭūrī","zh":"我洗脸，然后吃早饭。","note":"两个后缀都指「我的」","a":"b8bb1f80acc0"},{"ar":"آكُلُ خُبْزًا وَبَيْضًا وَأَشْرَبُ كُوبًا مِنَ الْحَلِيبِ.","rom":"ākulu khubzan wa-bayḍan wa-ashrabu kūban mina al-ḥalībi","zh":"我吃面包和鸡蛋，喝一杯牛奶。","note":"三个宾语都是 -an","a":"61c31659ef7c"},{"ar":"أَذْهَبُ إِلَى الْجَامِعَةِ بِالْحَافِلَةِ.","rom":"adhhabu ilā al-jāmiʿati bi-al-ḥāfilati","zh":"我坐公交车去大学。","note":"إِلَى 接属格，بِـ 表工具","a":"2e3bc81b8c51"},{"ar":"أَدْرُسُ الْعَرَبِيَّةَ وَالْإِنْجِلِيزِيَّةَ وَالتَّارِيخَ.","rom":"adrusu al-ʿarabiyyata wa-al-injlīziyyata wa-at-tārīkha","zh":"我学阿拉伯语、英语和历史。","note":"并列宾语都用宾格","a":"5b4d00928233"},{"ar":"أُحِبُّ حِصَّةَ الْعَرَبِيَّةِ كَثِيرًا.","rom":"uḥibbu ḥiṣṣata al-ʿarabiyyati kathīran","zh":"我很喜欢阿拉伯语课。","note":"正偏组合作宾语","a":"09c0469d9a60"},{"ar":"الْمُعَلِّمُ طَيِّبٌ وَالْأَسْئِلَةُ سَهْلَةٌ.","rom":"al-muʿallimu ṭayyibun wa-al-asʾilatu sahlatun","zh":"老师很和气，问题也不难。","note":"非理性复数谓语用阴性单数","a":"e2897d95d0d7"},{"ar":"نَقْرَأُ النُّصُوصَ وَنَكْتُبُ التَّمَارِينَ.","rom":"naqraʾu an-nuṣūṣa wa-naktubu at-tamārīna","zh":"我们读课文，写练习。","note":"第一人称复数，主语含在动词里","a":"8bc9552e51c3"},{"ar":"أَحْيَانًا لَا أَفْهَمُ كَلِمَةً جَدِيدَةً.","rom":"aḥyānan lā afhamu kalimatan jadīdatan","zh":"有时候我不懂一个新词。","note":"لَا 否定现在式","a":"43143e0fee7c"},{"ar":"أَسْأَلُ الْمُعَلِّمَ وَيَشْرَحُهَا لِي.","rom":"asʾalu al-muʿallima wa-yashraḥuhā lī","zh":"我问老师，他讲给我听。","note":"ـهَا 回指 كَلِمَة","a":"c393cd784adc"},{"ar":"أَذْهَبُ إِلَى مَطْعَمِ الْجَامِعَةِ مَعَ صَدِيقِي.","rom":"adhhabu ilā maṭʿami al-jāmiʿati maʿa ṣadīqī","zh":"我和朋友去大学食堂。","note":"正偏组合里套正偏组合","a":"9de0e7fc0206"},{"ar":"نَأْكُلُ أَرُزًّا وَلَحْمًا وَسَلَطَةً.","rom":"naʾkulu aruzzan wa-laḥman wa-salaṭatan","zh":"我们吃米饭、肉和沙拉。","note":"三个宾语都是 -an","a":"257e1fd6126b"},{"ar":"بَعْدَ الْغَدَاءِ أَسْتَرِيحُ نِصْفَ سَاعَةٍ.","rom":"baʿda al-ghadāʾi astarīḥu niṣfa sāʿatin","zh":"午饭后我休息半小时。","note":"نِصْفَ 宾格，سَاعَةٍ 属格","a":"eaf2aca6b4f6"},{"ar":"أَجْلِسُ إِلَى الْمَكْتَبِ وَأُرَاجِعُ الدَّرْسَ الْجَدِيدَ.","rom":"ajlisu ilā al-maktabi wa-urājiʿu ad-darsa al-jadīda","zh":"我坐到书桌前复习新课。","note":"形容词跟宾语同格","a":"0674bc3cd8f1"},{"ar":"أَكْتُبُ الْكَلِمَاتِ فِي دَفْتَرٍ صَغِيرٍ.","rom":"aktubu al-kalimāti fī daftarin ṣaghīrin","zh":"我把单词写在一个小本子上。","note":"非理性复数宾格用 ـِ","a":"9751b0fd3cab"},{"ar":"أَقْرَأُ الْكَلِمَاتِ بِصَوْتٍ عَالٍ.","rom":"aqraʾu al-kalimāti bi-ṣawtin ʿālin","zh":"我大声读这些单词。","note":"بِـ 加属格","a":"8c3311055032"},{"ar":"أُشَاهِدُ الْأَخْبَارَ بِالْعَرَبِيَّةِ.","rom":"ushāhidu al-akhbāra bi-al-ʿarabiyyati","zh":"我看阿拉伯语新闻。","note":"الْأَخْبَار 是破碎复数","a":"939a5311c293"},{"ar":"أَسْمَعُ كَلِمَاتٍ كَثِيرَةً أَعْرِفُهَا.","rom":"asmaʿu kalimātin kathīratan aʿrifuhā","zh":"我听到很多我认识的词。","note":"形容词加动词句作定语","a":"1d73a0c65f26"},{"ar":"أَنَامُ فِي السَّاعَةِ الْعَاشِرَةِ.","rom":"anāmu fī as-sāʿati al-ʿāshirati","zh":"我十点睡觉。","note":"فِي 加属格表时间","a":"08f56f259435"},{"ar":"سَأَزُورُ مِصْرَ بَعْدَ سَنَةٍ.","rom":"sa-azūru miṣra baʿda sanatin","zh":"一年后我要去埃及。","note":"سَـ 加现在式；مِصْرَ 不带鼻音","a":"d60b1460df47"},{"ar":"هَذِهِ يَوْمِيَّاتِي.","rom":"hādhihi yawmiyyātī","zh":"这是我的日记。","note":"هَذِهِ 起语，谓语带 ـِي","a":"0ecfc7b08197"},{"ar":"هَلْ أَنْتَ طَالِبٌ؟","rom":"hal anta ṭālibun","zh":"你是学生吗？","note":"هَلْ 加名词句","a":"72ff8474d360"},{"ar":"لَا أَفْهَمُ، أَعِدْ مِنْ فَضْلِكَ.","rom":"lā afhamu, aʿid min faḍlika","zh":"我不懂，请再说一遍。","note":"否定现在式加命令式","a":"4cb71b1ef1b0"},{"ar":"سَأَذْهَبُ غَدًا.","rom":"sa-adhhabu ghadan","zh":"我明天去。","note":"سَـ 表将来","a":"62e74eed344b"},{"ar":"الطُّلَّابُ فِي الْفَصْلِ.","rom":"aṭ-ṭullābu fī al-faṣli","zh":"学生们在教室里。","note":"复数起语加介词短语谓语","a":"3880c1a45ef1"}],"drills":[{"q":"يَوْمِيَّاتٌ 是什么意思？","a":"日记"},{"q":"短文里的 أَسْتَيْقِظُ 是第几人称？","a":"第一人称单数"},{"q":"「我七点出门」怎么说？","a":"أَخْرُجُ فِي السَّاعَةِ السَّابِعَةِ"},{"q":"「我在大学里学阿拉伯语」怎么说？","a":"أَتَعَلَّمُ الْعَرَبِيَّةَ فِي الْجَامِعَةِ"},{"q":"名词句的两个成分叫什么？","a":"起语和谓语"},{"q":"太阳字母前面的 الْ 怎么读？","a":"同化并叠音，如 الشَّمْس 读 ash-shams"},{"q":"三个格分别读什么？","a":"主格 -u、宾格 -a、属格 -i"},{"q":"正偏组合里的偏次用什么格？","a":"属格"},{"q":"过去式和现在式的人称信息靠什么表示？","a":"过去式靠后缀，现在式靠前缀"},{"q":"命令式怎么构成？","a":"第二人称现在式去掉前缀，词尾收静音"},{"q":"将来时怎么构成？","a":"سَـ 或 سَوْفَ 加现在式"},{"q":"否定名词句用哪个词？","a":"لَيْسَ"}],"tips":["读短文先找骨架：动词句看动词，名词句看起语和谓语，名词和介词短语只是填进去的血肉。","标音是拐杖，别拄太久：带标音读三遍，再遮住标音读一遍，读错的回头看一眼。","遇到生词先猜再看：从上下文和词根推，猜错也比立刻查词典记得牢。","复述比翻译有用：读完一段用三句话说出大意，比逐句翻译更练脑子。","每天二十分钟胜过周末三小时，语言是靠频率长的，不是靠时长。"],"id":"ch5-s4"}],"id":"ch5"}],"plan":[{"title":"第 1 周 · 认识阿拉伯语和字母（一）","name":"认识阿拉伯语和字母（一）","sections":["ch1-s1","ch1-s2","ch1-s3"],"goals":["搞清书写方向（右起）、连写规则、一个字母的四种形态","学会 ا ب ت ث ن ي 六个字母和三个短元音符号","每天跟读 10 分钟，先把「بَ بِ بُ」这种拼读练顺","本周不要碰语法，只练字形和发音"]},{"title":"第 2 周 · 字母（二）和长元音","name":"字母（二）和长元音","sections":["ch1-s4","ch1-s5","ch1-s6"],"goals":["学完剩下的 22 个字母，重点攻 ع غ ق ح خ 这几个中文里没有的音","分清强调音 ص ض ط ظ 与普通音 س د ت ذ 的对立","长元音 ā ī ū、叠音符 شَدَّة、鼻音符 تَنْوِين、冠词 الْ 的读法","目标：看到任何标音的阿语词都能读出来"]},{"title":"第 3 周 · 名词句","name":"名词句","sections":["ch2-s1","ch2-s2"],"goals":["阿拉伯语最简单也最常用的句型：起语 + 谓语，没有「是」","名词分阴阳性，ة 结尾一般是阴性","指示代词 هذا هذه ذلك تلك 的搭配","开始用「这 + 名词」造句"]},{"title":"第 4 周 · 确指与代词","name":"确指与代词","sections":["ch2-s3","ch2-s4"],"goals":["冠词 الْ 与鼻音符的分工：确指 / 泛指","太阳字母与月亮字母：为什么 الشمس 读 ash-shams","12 个人称代词 + 所有格后缀（كتابي / كتابك / كتابه）","练到能说「我的书」「他的老师」"]},{"title":"第 5 周 · 疑问句与三个格","name":"疑问句与三个格","sections":["ch2-s5","ch3-s1"],"goals":["疑问词：ما من أين كيف متى لماذا كم，以及 هل","阿拉伯语疑问词必须放句首","名词的三个格：主格 -u、宾格 -a、属格 -i","三格就是三种鼻音符，别怕，本质很简单"]},{"title":"第 6 周 · 介词与正偏组合","name":"介词与正偏组合","sections":["ch3-s2","ch3-s3"],"goals":["常用介词 في من إلى على عن مع عند ل ب，介词后面接属格","正偏组合（الإضافة）：كتاب الطالب「学生的书」","偏次（مضاف إليه）永远属格，而且不能再带 ال 或鼻音符","这一周开始能说「在教室里」「学校的老师」"]},{"title":"第 7 周 · 形容词与复数","name":"形容词与复数","sections":["ch3-s4","ch3-s5"],"goals":["形容词要和被修饰语在性、数、格、确指上四项一致","规则复数：阳性 -ون / -ين，阴性 -ات","非规则复数（جمع التكسير）先混个脸熟，不要求全背","把前面所有名词都换成复数练一遍"]},{"title":"第 8 周 · 动词（一）","name":"动词（一）","sections":["ch4-s1","ch4-s2"],"goals":["阿拉伯语动词的三母词根（جذر）概念，词根决定意思","过去式（الماضي）变位：-تُ -تَ -تِ -نا -تُمْ -وا","现在式（المضارع）变位：前缀 أ ن ت ي + 后缀","重点：现在式和过去式的主语信息都长在动词身上"]},{"title":"第 9 周 · 动词（二）","name":"动词（二）","sections":["ch4-s3","ch4-s4"],"goals":["命令式（الأمر）：从第二人称现在式去掉 ت 再加 همزة","动词句（الجملة الفعلية）：动词 + 主语 + 宾语","宾语是宾格（-a / -an）","开始用完整动词句描述日常动作"]},{"title":"第 10 周 · 否定与时态","name":"否定与时态","sections":["ch4-s5","ch4-s6"],"goals":["过去否定 ما，现在否定 لا，未来否定 لن + 现在式","لم + 现在式（جزم）也是过去否定，语感更书面","كان 与将来 سوف / سَـ 的用法","把前面所有句子改写成否定句和将来句"]},{"title":"第 11 周 · 数字与时间","name":"数字与时间","sections":["ch5-s1","ch5-s2"],"goals":["数字 1–100；数词 3–10 与名词的「反性」规则","星期、月份、钟点怎么说","这一周的词汇量最大，靠复习卡片来记","练：说出今天的日期和时间"]},{"title":"第 12 周 · 场景与总复习","name":"场景与总复习","sections":["ch5-s3","ch5-s4"],"goals":["日常场景：问候、自我介绍、点餐、问路","读一篇短文，把 12 周的语法点全部串起来","把错题本刷一遍，重点看非规则复数和动词变位","尝试不带标音读一段阿语新闻标题"]}]};
